INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FH7C1pOgiiZ', 1, '{"title":"伤寒杂病论序(张机序)","description":"<p>       论曰：余每览越人入虢之诊，望齐侯之色，未尝不慨然叹其才秀也。怪当今居世之士，曾不留神医药，精究方术，上以疗君亲之疾，下以救贫贱之厄，中以保身长全，以养其生，但竞逐荣势，企踵权豪，孜孜汲汲，惟名利是务，崇饰其末，忽弃其本，华其外，而悴其内，皮之不存，毛将安附焉。卒然遭邪风之气，婴非常之疾，患及祸至，而方震栗，降志屈节，钦望巫祝，告穷归天，束手受败，賫百年之寿命，持至贵之重器，委付凡医，恣其所措，咄嗟呜呼！厥身已毙，神明消灭，变为异物，幽潜重泉，徒为啼泣，痛夫！举世昏迷，莫能觉悟，不惜其命，若是轻生，彼何荣势之足云哉！而进不能爱人知人，退不能爱身知己，遇灾值祸，身居厄地，蒙蒙昧昧，憃若游魂。哀乎！趋势之士，驰竞浮华，不固根本，忘躯徇物，危若冰谷，至于是也。余宗族素多，向余二百，建安纪元以来，犹未十稔，其死亡者，三分有二，伤寒十居其七。感往昔之沦丧，伤横夭之莫救，乃勤求古训，博采众方，撰用《$m{素问}》、《$m{九卷}》、《$m{八十一难}》、《$m{阴阳大论}》、《$m{胎胪药录}》，并平脉辨证，为《$m{伤寒杂病论}》合十六卷，虽未能尽愈诸病，庶可以见病知源，若能寻余所集，思过半矣。夫天布五行，以运万类，人禀五常，以有五脏，经络府俞，阴阳会通，玄冥幽微，变化难极，自非才高识妙，岂能探其理致哉！上古有$n{神农、黄帝、歧伯、伯高、雷公、少俞、少师、仲文}，中世有$m{长桑、扁鹊，汉有公乘阳庆及仓公}，下此以往，未之闻也。观今之医，不念思求经旨，以演其所知，各承家技，终始顺旧，省疾问病，务在口给。相对须臾，便处汤药，按寸不及尺，握手不及足，人迎趺阳，三部不参，动数发息，不满五十，短期未知决诊，九候曾无仿佛，明堂阙庭，尽不见察，所谓窥管而已。夫欲视死别生，实为难矣。</p>\n<p></p>\n<p>      孔子云：生而知之者上，学则亚之，多闻博识，知之次也。余宿尚方术，请事斯语。</p>\n<p></p>\n<p> 汉长沙太守南阳张机序</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010001,"no":1}}', '2024-12-06T07:19:13.000Z', '2024-12-06T07:19:13.000Z', '2024-12-06T07:19:13.000Z', '论曰：余每览越人入虢之诊，望齐侯之色，未尝不慨然叹其才秀也。怪当今居世之士，曾不留神医药，精究方术，上以疗君亲之疾，下以救贫贱之厄，中以保身长全，以养其生，但竞逐荣势，企踵权豪，孜孜汲汲，惟名利是务，崇饰其末，忽弃其本，华其外，而悴其内，皮之不存，毛将安附焉。卒然遭邪风之气，婴非常之疾，患及祸至，而方震栗，降志屈节，钦望巫祝，告穷归天，束手受败，賫百年之寿命，持至贵之重器，委付凡医，恣其所措，咄嗟呜呼！厥身已毙，神明消灭，变为异物，幽潜重泉，徒为啼泣，痛夫！举世昏迷，莫能觉悟，不惜其命，若是轻生，彼何荣势之足云哉！而进不能爱人知人，退不能爱身知己，遇灾值祸，身居厄地，蒙蒙昧昧，憃若游魂。哀乎！趋势之士，驰竞浮华，不固根本，忘躯徇物，危若冰谷，至于是也。余宗族素多，向余二百，建安纪元以来，犹未十稔，其死亡者，三分有二，伤寒十居其七。感往昔之沦丧，伤横夭之莫救，乃勤求古训，博采众方，撰用《$m{素问}》、《$m{九卷}》、《$m{八十一难}》、《$m{阴阳大论}》、《$m{胎胪药录}》，并平脉辨证，为《$m{伤寒杂病论}》合十六卷，虽未能尽愈诸病，庶可以见病知源，若能寻余所集，思过半矣。夫天布五行，以运万类，人禀五常，以有五脏，经络府俞，阴阳会通，玄冥幽微，变化难极，自非才高识妙，岂能探其理致哉！上古有$n{神农、黄帝、歧伯、伯高、雷公、少俞、少师、仲文}，中世有$m{长桑、扁鹊，汉有公乘阳庆及仓公}，下此以往，未之闻也。观今之医，不念思求经旨，以演其所知，各承家技，终始顺旧，省疾问病，务在口给。相对须臾，便处汤药，按寸不及尺，握手不及足，人迎趺阳，三部不参，动数发息，不满五十，短期未知决诊，九候曾无仿佛，明堂阙庭，尽不见察，所谓窥管而已。夫欲视死别生，实为难矣。 孔子云：生而知之者上，学则亚之，多闻博识，知之次也。余宿尚方术，请事斯语。 汉长沙太守南阳张机序', '2024-12-06T07:19:13.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oGwKvnSkJP1', 1, '{"title":"伤寒杂病论序(桂林左德序)","description":"<p>        余闻吾师$n{张绍祖}先生之言曰：“吾家伤寒一书，相传共有一十三稿，每成一稿，传抄殆遍城邑，兹所存者为第十二稿，余者或为族人所秘，或付劫灰，不外是矣；叔和所得相传为第七次稿，与吾所脏者较，其间阙如固多，编次亦不相类，或为叔和所篡乱，或疑为宋人所增删，聚讼纷如，各执其说；然考晋时尚无刊本，犹是传抄，唐末宋初始易传抄为刊刻，遂称易简，以此言之，则坊间所刊者，不但非汉时之原稿，恐亦非叔和之原稿也。</p>\n<p></p>\n<p>       ”余聆训之下，始亦疑之，及读至伤寒例一卷，见其于可汗不可汗，可吐不可吐，可下不可下法，尽载其中，于六经已具之条为并不重引，法律谨严，始知坊间所刻之辨可汗不可汗，可吐不可吐，可下不可下，以及发汗 吐下后各卷，盖后人以读书之法，错杂其间，而未计及编书之法固不如是也，不然孔氏之徒，问仁者众，问政者繁，何不各类其类，而惮烦若此耶!吾师讳学正，自言为仲氏四十六世孙，自晋以后迁徙不一，其高祖复初公，自岭南复迁原籍，寄居光州，遂聚族焉。</p>\n<p>       吾师虽承家学，不以医名，亦不轻出此书以三示人，余得之受业者，殆有天焉。</p>\n<p>      余宿好方术，得针灸之学于永川邓师宪章公，后随侍先严游宦岭南，与吾师同寅，朝夕相过从，见余手执宋本伤寒论，笑问曰：“亦嗜此乎？”时余年仅弱冠，答曰：“非敢云嗜，尚未得其要领，正寻绎耳。”师曰：“子既好学，复知针灸，可以读伤寒论矣，吾有世传抄本伤寒杂病论十六卷，向不示人，得人不传，恐成坠绪。”遂历言此书颠末，及吾师家世滔滔不倦。先严促余曰：“速下拜。”于是即席拜之，得师事焉。今罗生哲初为吾邑知名人士，从习针灸历有年所，颇能好余之所好，余亦以所得者尽授之，余不负吾师，罗生亦必不负余，故特序其原起，罗生其志之，罗生其勉之。</p>\n<p></p>\n<p>       光绪二十年岁次甲午三月桂林左盛德序</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010002,"no":2}}', '2024-12-06T07:21:45.000Z', '2024-12-06T07:21:45.000Z', '2024-12-06T07:21:45.000Z', '余闻吾师$n{张绍祖}先生之言曰：“吾家伤寒一书，相传共有一十三稿，每成一稿，传抄殆遍城邑，兹所存者为第十二稿，余者或为族人所秘，或付劫灰，不外是矣；叔和所得相传为第七次稿，与吾所脏者较，其间阙如固多，编次亦不相类，或为叔和所篡乱，或疑为宋人所增删，聚讼纷如，各执其说；然考晋时尚无刊本，犹是传抄，唐末宋初始易传抄为刊刻，遂称易简，以此言之，则坊间所刊者，不但非汉时之原稿，恐亦非叔和之原稿也。 ”余聆训之下，始亦疑之，及读至伤寒例一卷，见其于可汗不可汗，可吐不可吐，可下不可下法，尽载其中，于六经已具之条为并不重引，法律谨严，始知坊间所刻之辨可汗不可汗，可吐不可吐，可下不可下，以及发汗 吐下后各卷，盖后人以读书之法，错杂其间，而未计及编书之法固不如是也，不然孔氏之徒，问仁者众，问政者繁，何不各类其类，而惮烦若此耶!吾师讳学正，自言为仲氏四十六世孙，自晋以后迁徙不一，其高祖复初公，自岭南复迁原籍，寄居光州，遂聚族焉。 吾师虽承家学，不以医名，亦不轻出此书以三示人，余得之受业者，殆有天焉。 余宿好方术，得针灸之学于永川邓师宪章公，后随侍先严游宦岭南，与吾师同寅，朝夕相过从，见余手执宋本伤寒论，笑问曰：“亦嗜此乎？”时余年仅弱冠，答曰：“非敢云嗜，尚未得其要领，正寻绎耳。”师曰：“子既好学，复知针灸，可以读伤寒论矣，吾有世传抄本伤寒杂病论十六卷，向不示人，得人不传，恐成坠绪。”遂历言此书颠末，及吾师家世滔滔不倦。先严促余曰：“速下拜。”于是即席拜之，得师事焉。今罗生哲初为吾邑知名人士，从习针灸历有年所，颇能好余之所好，余亦以所得者尽授之，余不负吾师，罗生亦必不负余，故特序其原起，罗生其志之，罗生其勉之。 光绪二十年岁次甲午三月桂林左盛德序', '2024-12-06T07:21:45.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TYCTSYUPQh5', 1, '{"title":"平脉法第一","description":"<p>1、问曰：脉何以知气血脏腑之诊也？</p>\n<p> </p>\n<p>    师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。气独胜者，则脉强；血独盛者，则脉滑；气偏衰者，则脉微；血偏衰者，则脉涩；气血和者，则脉缓；气血平者，则脉平；气血乱者，则脉乱；气血脱者，则脉绝；阳迫气血，则脉数；阴阻气血，则脉迟；若感于邪，气血扰动，脉随变化，变化无穷，气血使之；病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。</p><p>2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。</p>\n<p></p>\n<p>       师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。</p>\n<p></p><p>3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。</p><p>4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。</p><p>5、问曰：经说，脉有三菽、六菽重者，何谓也？</p>\n<p></p>\n<p>     师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。</p><p>6、问曰：东方肝脉，其形何似？</p>\n<p>      师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。</p><p>7、南方心脉，其形何似？</p>\n<p> </p>\n<p>      师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。</p><p>8、西方肺脉，其形何似？</p>\n<p></p>\n<p>      师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。</p><p>9、北方肾脉其形何似？</p>\n<p></p>\n<p>     师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。</p><p>10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。</p><p>11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。</p><p>12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。</p>\n<p></p>\n<p>        师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。</p><p>13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。</p><p>14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。</p><p>15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。</p><p>16、色白者，病在肺与大肠；假令身色白，明堂色微黑者，生；赤者，死；黄赤者，半死半生也。</p><p>17、色黑者，病在肾与膀胱；假令身色黑，明堂色微青者，生；黄者，死；黄赤者，半死半生也。</p><p>18、阙庭脉色青而沉细，推之不移者，病在肝；青而浮大，推之随转者，病在胆。</p><p>19、阙庭脉色赤而沉细，推之参差不齐者，病在心；赤而横弋，推之愈赤者，病在小肠。</p><p>20、阙庭脉色黄，推之如水停留者，病在脾；如水急流者，病在胃。</p><p>21、阙庭脉色青白，推之久不还者，病在肺；推之即至者，病在大肠。</p><p>22、阙庭脉色青黑直下睛明，推之不变者，病在肾；推之即至者，病在膀胱。</p><p>23、明堂阙庭色不见，推之色青紫者，病在中焦有积；推之明于水者，病在上焦有饮；推之黑赤参差者，病在下焦有寒热。</p><p>24、问曰：色有内外，何以别之？师曰：一望而知者，谓之外；在明堂阙庭，推而见之者，谓之内。</p><p>25、病暴至者，先形于色，不见于脉；病久发者，先见于脉，不形于色；病入于脏，无余证者，见于脉，不形于色；病痼疾者，见于脉，不形于色也。</p><p>26、问曰：色有生死，何谓也？</p>\n<p></p>\n<p>       师曰：假令色黄如蟹腹者，生；如枳实者，死；有气则生，无气则死，余色仿此。</p><p>27、师曰：人秉五常，有五脏，五脏发五声，宫、商、角、征、羽是也；五声在人，各具一体；假令人本声角变商声者，为金克木，至秋当死；变宫、征、羽皆病，以本声不可变故也。</p>\n<p> </p>\n<p>       人本声宫变角声者，为本克土，至春当死；变商、征、羽皆病。 </p>\n<p></p>\n<p>       人本声商变征声者，为火克金，至夏当死；变宫、角、羽皆病。</p>\n<p></p>\n<p>       人本声征变羽声者，为水克火，至冬当死；变角、宫、商皆病。</p>\n<p></p>\n<p>       人本声羽变宫声者，为土克水，至长夏当死；变角、商、征皆病。</p>\n<p></p>\n<p>       以上所言，皆人不病而声先病者，初变可治，变成难瘳；词声之妙，差在毫厘，本不易晓，若病至发声则易知也。</p><p>28、师曰：持脉，病人欠者，无病也。脉之，呻者，病也。言迟者，风也。摇头言者，里痛也。行迟者，表强也。坐而伏者，短气也。坐而下一脚者，腰痛也。里实护腹，如怀卵物者，心痛也。</p><p>29、病人长叹声，出高入卑者，病在上焦；出卑入高者，病在下焦；出入急促者，病在中焦有痛处；声唧唧而叹者，身体疼痛；问之不欲语，语先泪下者，必有忧郁；问之不语，泪下不止者，必有隐衷；问之不语，数问之而微笑者，必有隐疾。</p><p>30、实则谵语，虚则郑声；假令言出声卑者，为气虚；言出声高者，为气实；欲言手按胸中者，胸中满痛；欲言手按腹者，腹中满痛；欲言声不出者，咽中肿痛。</p><p>31、师曰：脉病人不病，名曰行尸，以无王气，卒眩仆，不识人者，短命则死。人病脉不病，名曰内虚，以少谷神，虽困无苦。</p><p>32、师曰：脉，肥人责浮，瘦人责沉。肥人当沉，今反浮；瘦人当浮，今反沉，故责之。</p><p>33、师曰：呼吸者，脉之头也。初持脉来疾去迟，此出疾入迟，名曰内虚外实也。初持脉，来迟去疾，此出迟入疾，名曰内实外虚也。</p><p>34、寸口卫气盛，名曰高；荣气盛，名曰章；高章相搏，名曰纲。卫气弱，名曰惵；荣气弱，名曰卑；惵卑相搏，名曰损。卫气和，名曰缓；荣气和，名曰迟；迟缓相搏，名曰沉。</p><p>35、阳脉浮大而濡，阴脉浮大而濡，阴脉与阳脉同等者，名曰缓也。</p><p>36、问曰：二月得毛浮脉，何以处言至秋当死。</p>\n<p></p>\n<p>       师曰：二月之时，脉当濡弱，反得毛浮者，故知至秋死。二月肝用事，肝属木，脉应濡弱，反得毛浮者，是肺脉也。肺属金，金来克木，故知至秋死。他皆仿此。</p><p>37、师曰：立夏得洪大脉是其本位。其人病身体苦疼重者，须发其汗。若明日身不疼不重者，不须发汗。若汗濈濈自出者，明日便解矣。何以言之？立夏脉洪大是其时脉，故使然也。四时仿此。</p><p>38、问曰：凡病欲知何时得，何时愈，何以知之？</p>\n<p></p>\n<p>       师曰：假令夜半得病者，明日日中愈；日中得病者，夜半愈。何以言之？日中得病，夜半愈者，以阳得阴则解也。夜半得病，明日日中愈者，以阴得阳则解也。</p><p>39、问曰：脉病欲知愈未愈者，何以别之？</p>\n<p>     </p>\n<p>      答曰：寸口、关上、尺中三处，大、小、浮、沉、迟、数同等，虽有寒热不解者，此脉阴阳为和平，虽剧当愈。师曰：寸脉下不至关，为阳绝；尺脉上不至关，为阴绝。此皆不治，决死也。若计其余命生死之期，期以月节克之也。</p><p>40、脉浮者在前，其病在表；浮者在后，其病在里；假令濡而上鱼际者，宗气泄也；孤而下尺中者，精不脏也；若乍高乍卑，乍升乍坠，为难治。</p><p>41、寸口脉缓而迟，缓则阳气长，其色鲜，其颜光，其声商，毛发长；迟则阴气盛，骨髓生，血满，肌肉紧薄鲜鞕。阴阳相抱，荣卫俱行，刚柔相得，名曰强也。</p><p>42、寸口脉浮为在表，沉为在里，数为在腑，迟为在脏。假令脉迟，此为在脏也。</p><p>43、寸口脉浮而紧，浮则为风，紧则为寒。风则伤卫，寒则伤荣。荣卫俱病，骨节烦疼，当发其汗也。</p><p>44、寸口脉浮而数，浮为风，数为热，风为虚，虚为寒，风虚相搏，则洒淅恶寒也。</p><p>45、问曰：病有洒淅恶寒而复发热者何也？</p>\n<p></p>\n<p>       师曰：阴脉不足，阳往从之；阳脉不足，阴往乘之也。何谓阳脉不足？师曰：假令寸口脉微，名曰阳不足，阴气上入阳中，则洒淅恶寒也，何谓阴不足？师曰：假令尺脉弱，名曰阴不足，阳气下陷入阴中，则发热也。阴脉弱者，则血虚。血虚则筋急也。其脉涩者，荣气微也。其脉浮而汗出如流珠者，卫气衰也。荣气微者，加烧针，则血留不行，更发热而躁烦也。</p><p>46、寸口脉阴阳俱紧者，法当清邪中于上焦，浊邪中于下焦。清邪中于上，名曰洁也；浊邪中于下，名曰浑也，阴中于邪，必内栗也，表气微虚，里气不守，故使邪中于阴也。阳中于邪，必发热、头痛、项强、颈挛、腰痛、胫酸，所谓阳中雾露之气，故曰清邪中上。浊邪中下，阴气为栗，足膝逆冷，便溺妄出，表气微虚，里气微急，三焦相混，内外不通，上焦怫郁，脏气相熏，口烂食断也。中焦不治，胃气上冲，脾气不转，胃中为浊，荣卫不通，血凝不流。若胃气前通者，小便赤黄，与热相搏，因热作使，游于经络，出入脏腑，热气所过，则为痈脓。若阴气前通者，阳气厥微，阴无所使，客气内入，嚏而出之，声嗢咽塞，寒厥相追，为热所拥，血凝自下，状如豚肝，阴阳俱厥，脾气弧弱，五液注下，下焦不阖，清便下重，令便数难，脐筑湫痛，命将难全。</p><p>47、寸口脉阴阳俱紧者，口中气出，唇口干燥，蜷卧足冷，鼻中涕出，舌上胎滑，勿妄治也。到七日以来，其人微发热，手足温者，此为欲解；或到八日以上，反大发热者，此为难治。设使恶寒者，必欲呕也；腹内痛者，必欲利也。</p><p>48、寸口脉阴阳俱紧，至于吐利，其脉独不解，紧去人安，此为欲解。若脉迟至六七日，不欲食，此为晚发，水停故也，为未解；食自可者，为欲解。</p><p>49、寸口脉浮而大，有热，心下反鞕，属脏者攻之，不令发汗。属腑者不令溲数。溲数则大便鞕，汗多则热甚，脉迟者尚未可攻也。</p><p>50、问曰：病有战而汗出，因得解者，何也？</p>\n<p></p>\n<p>       师曰：脉浮而紧，按之反芤，此为本虚，故当战而汗出也。其人本虚，是以发战。以脉浮紧，故当汗出而解也。若脉浮数，按之不芤，此人本不虚；若欲自解，但汗出耳，不发战也。</p><p>51、问曰：病有不战而汗出解者何也？师曰：脉大而浮数，故不战汗出而解也。</p><p>52、问曰：病有不战不汗出而解者，何也？</p>\n<p></p>\n<p>       答曰：其脉自微，此以曾发汗、若吐、若下、若亡血，以内无津液，此阴阳自和，必自愈，故不战不汗出而解也。</p><p>53、问曰：伤寒三日，脉浮数而微，病人身凉和者，何也？</p>\n<p></p>\n<p>        师曰：此为欲解也。解以夜半。浮而解者，濈然汗出也；数而解者，必能食也；微而解者，必大汗出也。</p><p>54、脉浮而迟，面热赤而战惕者，六七日当汗出而解。反发热者差迟。迟为无阳，不能作汗，其身必痒也。</p><p>55、病六七日，手足三部脉皆至，大烦而口噤不能言，其人躁扰者，未欲解也。若脉和，其人不烦，目重，睑内际黄者，此欲解也。</p><p>56、师曰：伏气之病，以意候之，今月之内，欲知伏气。假令旧有伏气，当须脉之。若脉微弱者，当喉中痛似伤，非喉痹也，病人云实咽中痛。虽尔，今复宜下之。</p><p>57、师曰：病家人请云病人苦发热，身体疼，病人自卧，师到，诊其脉，沉而迟者，知其瘥也；何以知之？凡表有病者，脉当浮大，今反沉迟故知愈也；假令病人云腹内卒痛，病人自坐，师到，脉之，浮而大者，知其瘥也；凡里有病者，脉当沉细，今反浮大，故知愈也。</p><p>58、师曰：病家人来请云，病人发热，烦极。明日师到，病人向壁卧，此热已去也。设令脉不和，处言已愈。设令向壁卧，闻师到，不惊起而盼视，若三言三止，脉之，咽唾者，此诈病也。设令脉自和，处言此病大重，当须服吐下药，针灸数十百处，乃愈。</p><p>59、问曰：脉有灾怪，何谓也？师曰：假令人病，脉得太阳，与形证相应，因为作汤。比还送汤如食顷，病人乃大吐，若下利，腹中痛。</p>\n<p>     </p>\n<p>        师曰：我前来不见此证，今乃变异，是名灾怪。又问曰：何缘得此吐利？师曰：或有旧时服药，今乃发作，故名灾怪耳。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010003,"no":3}}', '2024-12-06T07:22:22.000Z', '2024-12-06T07:22:22.000Z', '2024-12-06T07:22:22.000Z', '1、问曰：脉何以知气血脏腑之诊也？ 师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。气独胜者，则脉强；血独盛者，则脉滑；气偏衰者，则脉微；血偏衰者，则脉涩；气血和者，则脉缓；气血平者，则脉平；气血乱者，则脉乱；气血脱者，则脉绝；阳迫气血，则脉数；阴阻气血，则脉迟；若感于邪，气血扰动，脉随变化，变化无穷，气血使之；病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。 2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。 师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。 3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。 4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。 5、问曰：经说，脉有三菽、六菽重者，何谓也？ 师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。 6、问曰：东方肝脉，其形何似？ 师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。 7、南方心脉，其形何似？ 师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。 8、西方肺脉，其形何似？ 师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。 9、北方肾脉其形何似？ 师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。 10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。 11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。 12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。 师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。 13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。 14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。 15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。 16、色白者，病在肺与大肠；假令身色白，明堂色微黑者，生；赤者，死；黄赤者，半死半生也。 17、色黑者，病在肾与膀胱；假令身色黑，明堂色微青者，生；黄者，死；黄赤者，半死半生也。 18、阙庭脉色青而沉细，推之不移者，病在肝；青而浮大，推之随转者，病在胆。 19、阙庭脉色赤而沉细，推之参差不齐者，病在心；赤而横弋，推之愈赤者，病在小肠。 20、阙庭脉色黄，推之如水停留者，病在脾；如水急流者，病在胃。 21、阙庭脉色青白，推之久不还者，病在肺；推之即至者，病在大肠。 22、阙庭脉色青黑直下睛明，推之不变者，病在肾；推之即至者，病在膀胱。 23、明堂阙庭色不见，推之色青紫者，病在中焦有积；推之明于水者，病在上焦有饮；推之黑赤参差者，病在下焦有寒热。 24、问曰：色有内外，何以别之？师曰：一望而知者，谓之外；在明堂阙庭，推而见之者，谓之内。 25、病暴至者，先形于色，不见于脉；病久发者，先见于脉，不形于色；病入于脏，无余证者，见于脉，不形于色；病痼疾者，见于脉，不形于色也。 26、问曰：色有生死，何谓也？ 师曰：假令色黄如蟹腹者，生；如枳实者，死；有气则生，无气则死，余色仿此。 27、师曰：人秉五常，有五脏，五脏发五声，宫、商、角、征、羽是也；五声在人，各具一体；假令人本声角变商声者，为金克木，至秋当死；变宫、征、羽皆病，以本声不可变故也。 人本声宫变角声者，为本克土，至春当死；变商、征、羽皆病。 人本声商变征声者，为火克金，至夏当死；变宫、角、羽皆病。 人本声征变羽声者，为水克火，至冬当死；变角、宫、商皆病。 人本声羽变宫声者，为土克水，至长夏当死；变角、商、征皆病。 以上所言，皆人不病而声先病者，初变可治，变成难瘳；词声之妙，差在毫厘，本不易晓，若病至发声则易知也。 28、师曰：持脉，病人欠者，无病也。脉之，呻者，病也。言迟者，风也。摇头言者，里痛也。行迟者，表强也。坐而伏者，短气也。坐而下一脚者，腰痛也。里实护腹，如怀卵物者，心痛也。 29、病人长叹声，出高入卑者，病在上焦；出卑入高者，病在下焦；出入急促者，病在中焦有痛处；声唧唧而叹者，身体疼痛；问之不欲语，语先泪下者，必有忧郁；问之不语，泪下不止者，必有隐衷；问之不语，数问之而微笑者，必有隐疾。 30、实则谵语，虚则郑声；假令言出声卑者，为气虚；言出声高者，为气实；欲言手按胸中者，胸中满痛；欲言手按腹者，腹中满痛；欲言声不出者，咽中肿痛。 31、师曰：脉病人不病，名曰行尸，以无王气，卒眩仆，不识人者，短命则死。人病脉不病，名曰内虚，以少谷神，虽困无苦。 32、师曰：脉，肥人责浮，瘦人责沉。肥人当沉，今反浮；瘦人当浮，今反沉，故责之。 33、师曰：呼吸者，脉之头也。初持脉来疾去迟，此出疾入迟，名曰内虚外实也。初持脉，来迟去疾，此出迟入疾，名曰内实外虚也。 34、寸口卫气盛，名曰高；荣气盛，名曰章；高章相搏，名曰纲。卫气弱，名曰惵；荣气弱，名曰卑；惵卑相搏，名曰损。卫气和，名曰缓；荣气和，名曰迟；迟缓相搏，名曰沉。 35、阳脉浮大而濡，阴脉浮大而濡，阴脉与阳脉同等者，名曰缓也。 36、问曰：二月得毛浮脉，何以处言至秋当死。 师曰：二月之时，脉当濡弱，反得毛浮者，故知至秋死。二月肝用事，肝属木，脉应濡弱，反得毛浮者，是肺脉也。肺属金，金来克木，故知至秋死。他皆仿此。 37、师曰：立夏得洪大脉是其本位。其人病身体苦疼重者，须发其汗。若明日身不疼不重者，不须发汗。若汗濈濈自出者，明日便解矣。何以言之？立夏脉洪大是其时脉，故使然也。四时仿此。 38、问曰：凡病欲知何时得，何时愈，何以知之？ 师曰：假令夜半得病者，明日日中愈；日中得病者，夜半愈。何以言之？日中得病，夜半愈者，以阳得阴则解也。夜半得病，明日日中愈者，以阴得阳则解也。 39、问曰：脉病欲知愈未愈者，何以别之？ 答曰：寸口、关上、尺中三处，大、小、浮、沉、迟、数同等，虽有寒热不解者，此脉阴阳为和平，虽剧当愈。师曰：寸脉下不至关，为阳绝；尺脉上不至关，为阴绝。此皆不治，决死也。若计其余命生死之期，期以月节克之也。 40、脉浮者在前，其病在表；浮者在后，其病在里；假令濡而上鱼际者，宗气泄也；孤而下尺中者，精不脏也；若乍高乍卑，乍升乍坠，为难治。 41、寸口脉缓而迟，缓则阳气长，其色鲜，其颜光，其声商，毛发长；迟则阴气盛，骨髓生，血满，肌肉紧薄鲜鞕。阴阳相抱，荣卫俱行，刚柔相得，名曰强也。 42、寸口脉浮为在表，沉为在里，数为在腑，迟为在脏。假令脉迟，此为在脏也。 43、寸口脉浮而紧，浮则为风，紧则为寒。风则伤卫，寒则伤荣。荣卫俱病，骨节烦疼，当发其汗也。 44、寸口脉浮而数，浮为风，数为热，风为虚，虚为寒，风虚相搏，则洒淅恶寒也。 45、问曰：病有洒淅恶寒而复发热者何也？ 师曰：阴脉不足，阳往从之；阳脉不足，阴往乘之也。何谓阳脉不足？师曰：假令寸口脉微，名曰阳不足，阴气上入阳中，则洒淅恶寒也，何谓阴不足？师曰：假令尺脉弱，名曰阴不足，阳气下陷入阴中，则发热也。阴脉弱者，则血虚。血虚则筋急也。其脉涩者，荣气微也。其脉浮而汗出如流珠者，卫气衰也。荣气微者，加烧针，则血留不行，更发热而躁烦也。 46、寸口脉阴阳俱紧者，法当清邪中于上焦，浊邪中于下焦。清邪中于上，名曰洁也；浊邪中于下，名曰浑也，阴中于邪，必内栗也，表气微虚，里气不守，故使邪中于阴也。阳中于邪，必发热、头痛、项强、颈挛、腰痛、胫酸，所谓阳中雾露之气，故曰清邪中上。浊邪中下，阴气为栗，足膝逆冷，便溺妄出，表气微虚，里气微急，三焦相混，内外不通，上焦怫郁，脏气相熏，口烂食断也。中焦不治，胃气上冲，脾气不转，胃中为浊，荣卫不通，血凝不流。若胃气前通者，小便赤黄，与热相搏，因热作使，游于经络，出入脏腑，热气所过，则为痈脓。若阴气前通者，阳气厥微，阴无所使，客气内入，嚏而出之，声嗢咽塞，寒厥相追，为热所拥，血凝自下，状如豚肝，阴阳俱厥，脾气弧弱，五液注下，下焦不阖，清便下重，令便数难，脐筑湫痛，命将难全。 47、寸口脉阴阳俱紧者，口中气出，唇口干燥，蜷卧足冷，鼻中涕出，舌上胎滑，勿妄治也。到七日以来，其人微发热，手足温者，此为欲解；或到八日以上，反大发热者，此为难治。设使恶寒者，必欲呕也；腹内痛者，必欲利也。 48、寸口脉阴阳俱紧，至于吐利，其脉独不解，紧去人安，此为欲解。若脉迟至六七日，不欲食，此为晚发，水停故也，为未解；食自可者，为欲解。 49、寸口脉浮而大，有热，心下反鞕，属脏者攻之，不令发汗。属腑者不令溲数。溲数则大便鞕，汗多则热甚，脉迟者尚未可攻也。 50、问曰：病有战而汗出，因得解者，何也？ 师曰：脉浮而紧，按之反芤，此为本虚，故当战而汗出也。其人本虚，是以发战。以脉浮紧，故当汗出而解也。若脉浮数，按之不芤，此人本不虚；若欲自解，但汗出耳，不发战也。 51、问曰：病有不战而汗出解者何也？师曰：脉大而浮数，故不战汗出而解也。 52、问曰：病有不战不汗出而解者，何也？ 答曰：其脉自微，此以曾发汗、若吐、若下、若亡血，以内无津液，此阴阳自和，必自愈，故不战不汗出而解也。 53、问曰：伤寒三日，脉浮数而微，病人身凉和者，何也？ 师曰：此为欲解也。解以夜半。浮而解者，濈然汗出也；数而解者，必能食也；微而解者，必大汗出也。 54、脉浮而迟，面热赤而战惕者，六七日当汗出而解。反发热者差迟。迟为无阳，不能作汗，其身必痒也。 55、病六七日，手足三部脉皆至，大烦而口噤不能言，其人躁扰者，未欲解也。若脉和，其人不烦，目重，睑内际黄者，此欲解也。 56、师曰：伏气之病，以意候之，今月之内，欲知伏气。假令旧有伏气，当须脉之。若脉微弱者，当喉中痛似伤，非喉痹也，病人云实咽中痛。虽尔，今复宜下之。 57、师曰：病家人请云病人苦发热，身体疼，病人自卧，师到，诊其脉，沉而迟者，知其瘥也；何以知之？凡表有病者，脉当浮大，今反沉迟故知愈也；假令病人云腹内卒痛，病人自坐，师到，脉之，浮而大者，知其瘥也；凡里有病者，脉当沉细，今反浮大，故知愈也。 58、师曰：病家人来请云，病人发热，烦极。明日师到，病人向壁卧，此热已去也。设令脉不和，处言已愈。设令向壁卧，闻师到，不惊起而盼视，若三言三止，脉之，咽唾者，此诈病也。设令脉自和，处言此病大重，当须服吐下药，针灸数十百处，乃愈。 59、问曰：脉有灾怪，何谓也？师曰：假令人病，脉得太阳，与形证相应，因为作汤。比还送汤如食顷，病人乃大吐，若下利，腹中痛。 师曰：我前来不见此证，今乃变异，是名灾怪。又问曰：何缘得此吐利？师曰：或有旧时服药，今乃发作，故名灾怪耳。', '2024-12-06T07:22:22.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Okv1nb20qyT', 1, '{"title":"平脉法第二","description":"<p>1、问曰：脉何以知气血脏腑之诊也？</p>\n<p></p>\n<p>      师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。</p>\n<p></p>\n<p>      气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。</p>\n<p></p>\n<p>      气独胜者，则脉强；血独盛者，则脉滑；</p>\n<p></p>\n<p>      气偏衰者，则脉微；血偏衰者，则脉涩；</p>\n<p></p>\n<p>     气血和者，则脉缓；气血平者，则脉平；</p>\n<p></p>\n<p>     气血乱者，则脉乱；气血脱者，则脉绝；</p>\n<p></p>\n<p>     阳迫气血，则脉数；阴阻气血，则脉迟；</p>\n<p></p>\n<p>    若感于邪，气血扰动，脉随变化，变化无穷，气血使之；</p>\n<p></p>\n<p>    病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。</p><p>2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。</p>\n<p> </p>\n<p>        师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。</p><p>3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。</p><p>4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。</p><p>5、问曰：经说，脉有三菽、六菽重者，何谓也？</p>\n<p></p>\n<p>      师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。</p><p>6、问曰：东方肝脉，其形何似？</p>\n<p></p>\n<p>      师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。</p><p>7、南方心脉，其形何似？</p>\n<p></p>\n<p>     师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。</p><p>8、西方肺脉，其形何似？</p>\n<p></p>\n<p>      师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。</p><p>9、北方肾脉其形何似？</p>\n<p></p>\n<p>      师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。</p><p>10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。</p><p>11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。</p><p>12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。</p>\n<p></p>\n<p>        师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。</p><p>13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。</p><p>14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。</p><p>15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。</p><p>16、色白者，病在肺与大肠；假令身色白，明堂色微黑者，生；赤者，死；黄赤者，半死半生也。</p><p>17、色黑者，病在肾与膀胱；假令身色黑，明堂色微青者，生；黄者，死；黄赤者，半死半生也。</p><p>18、阙庭脉色青而沉细，推之不移者，病在肝；青而浮大，推之随转者，病在胆。</p><p>19、阙庭脉色赤而沉细，推之参差不齐者，病在心；赤而横弋，推之愈赤者，病在小肠。</p><p>20、阙庭脉色黄，推之如水停留者，病在脾；如水急流者，病在胃。</p><p>21、阙庭脉色青白，推之久不还者，病在肺；推之即至者，病在大肠。</p><p>22、阙庭脉色青黑直下睛明，推之不变者，病在肾；推之即至者，病在膀胱。</p><p>23、明堂阙庭色不见，推之色青紫者，病在中焦有积；推之明于水者，病在上焦有饮；推之黑赤参差者，病在下焦有寒热。</p><p>24、问曰：色有内外，何以别之？</p>\n<p></p>\n<p>       师曰：一望而知者，谓之外；在明堂阙庭，推而见之者，谓之内。</p><p>25、病暴至者，先形于色，不见于脉；病久发者，先见于脉，不形于色；病入于脏，无余证者，见于脉，不形于色；病痼疾者，见于脉，不形于色也。</p><p>26、问曰：色有生死，何谓也？</p>\n<p>           </p>\n<p>       师曰：假令色黄如蟹腹者，生；如枳实者，死；有气则生，无气则死，余色仿此。</p><p>27、师曰：人秉五常，有五脏，五脏发五声，宫、商、角、征、羽是也；五声在人，各具一体；假令人本声角变商声者，为金克木，至秋当死；变宫、征、羽皆病，以本声不可变故也。</p><p>28、人本声宫变角声者，为本克土，至春当死；变商、征、羽皆病。</p><p>29、人本声商变征声者，为火克金，至夏当死；变宫、角、羽皆病。</p><p>30、人本声征变羽声者，为水克火，至冬当死；变角、宫、商皆病。</p><p>31、人本声羽变宫声者，为土克水，至长夏当死；变角、商、征皆病。</p><p>32、问曰：脉有阴阳，何谓也？</p>\n<p></p>\n<p>        师曰：凡脉大、浮、数、动、滑，此名阳也；凡脉沉、涩、迟、弦、微，此名阴也，凡阴病见阳脉者生，阳病见阴脉者死。</p><p>33、阴阳相搏名曰动，阳动则汗出，阴动则发热，形冷恶寒者，此三焦伤也。若脉数见于关上，上下无头尾如豆大，厥厥然动摇者，名曰动也。脉来缓，时一止复来者，名曰结。脉来数，时一止复来者，名曰促。脉阳盛则促，阴盛则结，此皆病脉。又脉来动而中止，更来小数，中有还者反动，名曰结阴也；脉来动而中止，不能自还，因而复动者，名曰代阴也；得此脉者，必难治。脉阴阳俱促，当病血，为实；阴阳俱结，当亡血，为虚；假令促上寸口者，当吐血，或衄；下尺中者，当下血；若乍促乍结为难治。脉数者，久数不止，止则邪结，正气不能复，却结于脏；故邪气浮之，与皮毛相得脉数者，不可下，下之，必烦利不止。</p><p>34、问曰：脉有阳结阴结者，何以别之？师曰：其脉浮而数，能食，不大便者，此为实，名曰阳结也，期十七日当剧。其脉沉而迟，不能食，身体重，大便反鞕，名曰阴结也。期十四日当剧。</p><p>35、脉蔼蔼，如车盖者，名曰阳结也。</p><p>36、脉累累，如循长竿者，名曰阴结也。</p><p>37、脉瞥瞥，如羹上肥者，阳气微也。</p><p>38、脉萦萦，如蜘蛛丝者，阴气衰也。</p><p>39、脉绵绵，如泻漆之绝者，亡其血也。</p><p>40、问曰：脉有残贼，何谓也？</p>\n<p></p>\n<p>      师曰：脉有弦、紧、浮、滑、沉、涩，此六脉，名曰残贼，能为诸脉作病也。</p><p>41、问曰：脉有相乘、有纵、有横、有逆、有顺，何也？师曰：水行乘火，金行乘木，名曰纵；火行乘水，木行乘金，名曰横；水行乘金，火行乘木，名曰逆；金行乘水，木行乘火，名曰顺也。</p><p>42、问曰：濡弱何以反适十一头？</p>\n<p></p>\n<p>        师曰：五脏六腑相乘故令十一。</p><p>43、脉阴阳俱弦，无寒热，为病饮。在浮部，饮在皮肤；在中部，饮在经络；在沉部，饮在肌肉；若寸口弦，饮在上焦；关上弦，饮在中焦；尺中弦，饮在下焦。</p><p>44、脉弦而紧者，名曰革也。弦者状如弓弦，按之不移也。紧者如转索无常也。</p><p>45、脉弦而大，弦则为减，大则为芤。减则为寒，芤则为虚。寒虚相搏，此名为革。妇人则半产、漏下，男子则亡血、失精。</p><p>46、问曰：曾为人所难，紧脉从何而来？</p>\n<p></p>\n<p>        师曰：假令亡汗、若吐，以肺里寒，故令脉紧也。假令咳者，坐饮冷水，故令脉紧也。假令下利，以胃中虚冷，故令脉紧也。</p><p>47、寸口脉浮而紧，医反下之，此为大逆。浮则无血，紧则为寒，寒气相搏，则为肠鸣，医乃不知，而反饮冷水，令汗不出，水得寒气，冷必相搏，其人即饐。</p><p>48、寸口脉微，尺脉紧，其人虚损多汗，知阴常在，绝不见阳也。</p><p>49、寸口脉浮而大，浮为风虚，大为气强，风气相搏，必成隐疹，身体为痒。痒者名曰泄风，久久为痂癞。</p><p>50、寸口脉浮而大，浮为虚，大为实；在尺为关，在寸为格；关则不得小便，格则吐逆。</p><p>51、寸口脉微而涩，微者卫气不行，涩者荣气不逮。荣卫不能相将，三焦无所仰，身体痹不仁。荣气不足，则烦疼，口难言；卫气虚者，则恶寒数欠。三焦不归其部，上焦不归者，噫而酢吞；中焦不归者，不能消谷引食；下焦不归者，则遗溲。</p><p>52、寸口脉微而涩，微者卫气衰，涩者荣气不足。卫气衰则面色黄；荣气不足则面色青。荣为根，卫为叶。荣卫俱微，则根叶枯槁，而寒栗咳逆，唾腥吐涎沫也。</p><p>53、寸口脉微而缓，微者卫气疏，疏则其肤空；缓者胃气实，实则谷消而水化也。谷入于胃，脉道乃行，水入于经，其血乃成。荣盛则其肤必疏，三焦绝经，名曰血崩。</p><p>54、寸口脉弱而缓，弱者阳气不足，缓者胃气有余，噫而吞酸，食卒不下，气填于膈上也。</p><p>55、寸口脉弱而迟，弱者卫气微，迟者荣中寒；荣为血，血寒则发热；卫为气，气微者心内饥，饥而虚满不能食也。</p><p>56、寸口脉弱而涩，尺中浮大，无外证者，为病属内伤。</p><p>57、寸口脉弱而涩，尺中濡弱者，男子病失精，女子病赤白带下。</p><p>58、寸口脉洪数，按之弦急者，当发瘾疹；假令脉浮数，按之反平者，为外毒；脉数大，按之弦直者，为内毒，宜升之，令其外出也；误攻则内陷，内陷则死。</p><p>59、寸口脉洪数，按之急滑者，当发痈脓；发热者，暴出；无热者，久久必至也。</p><p>60、寸口脉浮滑，按之弦急者，当发内痈；咳嗽胸中痛为肺痈，当吐脓血；腹中掣痛为肠痈，当便脓血。</p><p>61、寸口脉大而涩，时一弦，无寒热，此为浸淫疮所致也；若加细数者，为难治。</p><p>62、趺阳脉紧而浮，浮为气，紧为寒。浮为腹满，紧为绞痛。浮紧相搏，肠鸣而转，转即气动，隔气乃下。少阴脉不出，其阴肿大而虚也。</p><p>63、趺阳脉微而紧，紧则为寒，微则为虚，微紧相搏，则为短气。</p><p>64、趺阳脉大而紧者，当即下利，为难治。</p><p>65、趺阳脉浮，浮则为虚，浮虚相搏，故令气饐，言胃气虚竭也；此为医咎，责虚取实，守空迫血；脉滑则为哕，脉浮鼻中燥者，必衄也。</p><p>66、趺阳脉迟而缓，胃气如经也。趺阳脉浮而数，浮则伤胃，数则动脾，此非本病，医特下之所为也。荣卫内陷，其数先微，脉反但浮，其人必大便鞕，气噫不除。何以言之？本以数脉动脾，其数先微，故知脾气不治，大便鞕，气噫不除。今脉反浮，其数改微，邪气独留，心中则饥，邪热不杀谷，潮热发渴，数脉当迟，缓病者则饥。数脉不时，则生恶疮也。</p><p>67、趺阳脉浮而涩，少阴脉如经者，其病在脾，法当下利。何以知之？若脉浮大者，气实血虚也。今趺阳脉浮而涩，故知脾气不足，胃气虚也。以少阴脉弦，而沉才见，此为调脉，故称如经也。若反滑而数者，故知当屎脓也。</p><p>68、趺阳脉浮而芤，浮者胃气虚，芤者荣气伤，其身体瘦，肌肉甲错，浮芤相搏，宗气衰微，四属断绝也。</p><p>69、趺阳脉浮而大，浮为气实，大为血虚；血虚为无阴，孤阳独下阴部者，小便当赤而难，胞中当虚；今小便利，而大汗出，法应胃家当微；今反更实，津液四射，荣竭血尽，干烦而不眠，血薄肉消而成暴液；医复以毒药攻其胃，此为重虚，客阳去有期，必下如淤泥而死。</p><p>70、问曰：翕奄沉名曰滑，何谓也？</p>\n<p></p>\n<p>        师曰：沉为纯阴，翕为正阳，阴阳和合，故令脉滑。关尺自平。</p><p>71、趺阳脉微沉，食饮自平；少阴脉微滑，滑者紧之浮名也，此为阴实，其人必股内汗出，阴下湿也。</p><p>72、趺阳脉浮而滑，浮为阳，滑为实，阳实相搏，其脉数疾，卫气失度，浮滑之脉数疾，发热汗出者，此为不治。</p><p>73、趺阳脉滑而紧，滑者胃气实，紧者脾气强。持实击强，痛还自伤，以手把刃，坐作疮也。</p><p>74、趺阳脉沉而微，沉为实，数消谷；紧者，病难治。</p><p>75、趺阳脉伏而涩，伏则吐逆，水谷不化，涩则食不得入，名曰关格。</p><p>76、师曰：病人脉微而涩者，此为医所病也。大发其汗，又数大下之，其人亡血，病当恶寒，后乃发热，无休止时，夏月盛热，欲着复衣，冬月盛寒，欲裸其身，所以然者，阳微则恶寒，阴弱则发热，此医发其汗，使阳气微，又大下之：令阴气弱，五月之时，阳气在表，胃中虚冷，以阳气内微，不能胜冷，故欲着复衣；十一月之时，阳气在里，胃中烦热，以阴气内弱，不能胜热，故欲裸其身。又阴脉迟涩，故知血亡也。</p><p>77、少阴脉弱而涩，弱者微烦，涩者厥逆。</p><p>78、趺阳脉不出，脾不上下，身冷肤鞕。</p><p>79、少阴脉不至，肾气微，少精血，奔气促迫，上入胸隔，宗气反聚，血结心下，阳气退下，热归阴股，与阴相动，令身不仁，此为尸厥。当刺期门、巨阙。</p><p>80、妊娠脉弦数而细，少腹痛，手心热，此为热结胞中，不先其时治之，必有产难。</p><p>81、产后脉洪数，按之弦急，此为浊未下；若浊已下而脉如故者，此为魂脱，为难治。</p><p>82、诸脉浮数，当发热而洒淅恶寒，若有痛处，饮食如常者，畜积有脓也。</p><p>83、问曰：人恐怖者，其脉何状？</p>\n<p></p>\n<p>     师曰：脉形如循丝累累然，其面白脱色也。</p><p>84、问曰：人不饮，其脉何类？</p>\n<p></p>\n<p>       师曰：脉自涩，唇口干燥也。</p><p>85、问曰：人愧者，其脉何类？</p>\n<p></p>\n<p>       师曰：脉浮而面色乍白乍赤也。</p><p>86、师曰：寸口诸微亡阳，诸濡亡血，诸弱发热，诸紧为寒。诸乘寒者则为厥，郁冒不仁，以胃无谷气，脾涩不通，口急不能言，战而栗也。</p><p>87、师曰：发热则脉躁，恶寒则脉静，脉随证转者，为病疟。</p><p>88、师曰：伤寒，咳逆上气，其脉散者死，为其形损故也。</p><p>89、师曰：脉乍大乍小，乍静乍乱，见人惊恐者，为祟发于胆，气竭故也。</p><p>90、师曰：人脉皆无病，暴发重病，不省人事者，为厉鬼，治之以祝由，能言者可治，不言者死。</p><p>91、师曰：脉浮而洪，身汗如油，喘而不休，水浆不下，形体不仁，乍静乍乱，此为命绝也。又未知何脏先受其灾。若汗出发润，喘不休者，此为肺先绝也。阳反独留，形体如烟熏，直视摇头者，此为心绝也。唇吻反青，四肢掣习者，此为肝绝也。环口黧黑，油汗发黄者，此为脾绝也。溲便遗失，狂言，目反直视者，此为肾绝也。又未知何脏阴阳前绝。若阳气前绝，阴气后竭者，其人死身色必青；阴气前绝，阳气后竭者，其人死，身色必赤，腋下温，心下热也。</p><p>92、奇经八脉不系于十二经，别有自行道路。其为病总于阴阳，其治法属十二经。假令督脉为病，脊背强，隐隐痛，脉当微浮而急，按之涩，治属太阳。</p><p>93、任脉为病，其内结痛疝瘕，脉当沉而结，治属太阴。</p><p>94、冲脉为病，气上逆而里急，脉当浮虚而数，治属太阴。</p><p>95、带脉为病，苦腹痛，腰间冷痛，脉当沉而细，治属少阴。</p><p>96、阳跷为病，中于侧，气行于外，脉当弦急，按之缓，治属少阳。</p><p>97、阴跷为病，中于侧，气行于内，脉当浮缓，按之微急而弦，治属厥阴。</p><p>98、阳维与诸阳会，其为病在脉外，发寒热，脉当浮而虚，治属气分。</p><p>99、阴维与诸阴交，其为病在脉中，心中痛，手心热，脉当弦而涩，治属血分。</p><p>100、阳维维于阳，阴维维于阴，为气血之别，使不拘于一经也。</p><p>101、奇经八脉之病，由各经受邪，久久移传，或劳伤所致，非暴发也。</p><p>102、问曰：八脉内伤何以别之？</p>\n<p></p>\n<p>         师曰：督脉伤，柔柔不欲伸，不能久立，立则隐隐而胀；任脉伤，小便多，其色白浊；冲脉伤，时咳不休，有声无物，劳则；地喘；带脉伤，回身一周冷；阳跷伤，则身左不仁；阴跷伤，则身右不仁；阳维伤，则畏寒甚，皮常湿；阴维伤，则畏热甚，皮常枯。</p><p>103、问曰：八脉内伤其脉何似？</p>\n<p> </p>\n<p>        师曰：督脉伤，尺脉大而涩；任脉伤，关脉大而涩；冲脉伤，寸脉短而涩；带脉伤，脉沉迟而结；阳跷伤，脉时大而弦；阴跷伤，脉时细时弦；阳维伤，脉时缓时弦；阴维伤，脉时紧时涩。问曰：其治奈何？师曰：督脉伤，当补髓；任脉伤，当补精；冲脉伤，当补气；带脉伤，当补肾；阳跷伤，则益胆；阴跷伤，则补肝；阴维伤，则调卫；阴维伤，则养荣。</p><p>104、问曰：其处方奈何？</p>\n<p></p>\n<p>         师曰：相体虚实，察病轻重，采取方法，权衡用之，则无失也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010004,"no":4}}', '2024-12-06T07:22:40.000Z', '2024-12-06T07:22:40.000Z', '2024-12-06T07:22:40.000Z', '1、问曰：脉何以知气血脏腑之诊也？ 师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。 气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。 气独胜者，则脉强；血独盛者，则脉滑； 气偏衰者，则脉微；血偏衰者，则脉涩； 气血和者，则脉缓；气血平者，则脉平； 气血乱者，则脉乱；气血脱者，则脉绝； 阳迫气血，则脉数；阴阻气血，则脉迟； 若感于邪，气血扰动，脉随变化，变化无穷，气血使之； 病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。 2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。 师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。 3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。 4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。 5、问曰：经说，脉有三菽、六菽重者，何谓也？ 师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。 6、问曰：东方肝脉，其形何似？ 师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。 7、南方心脉，其形何似？ 师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。 8、西方肺脉，其形何似？ 师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。 9、北方肾脉其形何似？ 师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。 10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。 11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。 12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。 师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。 13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。 14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。 15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。 16、色白者，病在肺与大肠；假令身色白，明堂色微黑者，生；赤者，死；黄赤者，半死半生也。 17、色黑者，病在肾与膀胱；假令身色黑，明堂色微青者，生；黄者，死；黄赤者，半死半生也。 18、阙庭脉色青而沉细，推之不移者，病在肝；青而浮大，推之随转者，病在胆。 19、阙庭脉色赤而沉细，推之参差不齐者，病在心；赤而横弋，推之愈赤者，病在小肠。 20、阙庭脉色黄，推之如水停留者，病在脾；如水急流者，病在胃。 21、阙庭脉色青白，推之久不还者，病在肺；推之即至者，病在大肠。 22、阙庭脉色青黑直下睛明，推之不变者，病在肾；推之即至者，病在膀胱。 23、明堂阙庭色不见，推之色青紫者，病在中焦有积；推之明于水者，病在上焦有饮；推之黑赤参差者，病在下焦有寒热。 24、问曰：色有内外，何以别之？ 师曰：一望而知者，谓之外；在明堂阙庭，推而见之者，谓之内。 25、病暴至者，先形于色，不见于脉；病久发者，先见于脉，不形于色；病入于脏，无余证者，见于脉，不形于色；病痼疾者，见于脉，不形于色也。 26、问曰：色有生死，何谓也？ 师曰：假令色黄如蟹腹者，生；如枳实者，死；有气则生，无气则死，余色仿此。 27、师曰：人秉五常，有五脏，五脏发五声，宫、商、角、征、羽是也；五声在人，各具一体；假令人本声角变商声者，为金克木，至秋当死；变宫、征、羽皆病，以本声不可变故也。 28、人本声宫变角声者，为本克土，至春当死；变商、征、羽皆病。 29、人本声商变征声者，为火克金，至夏当死；变宫、角、羽皆病。 30、人本声征变羽声者，为水克火，至冬当死；变角、宫、商皆病。 31、人本声羽变宫声者，为土克水，至长夏当死；变角、商、征皆病。 32、问曰：脉有阴阳，何谓也？ 师曰：凡脉大、浮、数、动、滑，此名阳也；凡脉沉、涩、迟、弦、微，此名阴也，凡阴病见阳脉者生，阳病见阴脉者死。 33、阴阳相搏名曰动，阳动则汗出，阴动则发热，形冷恶寒者，此三焦伤也。若脉数见于关上，上下无头尾如豆大，厥厥然动摇者，名曰动也。脉来缓，时一止复来者，名曰结。脉来数，时一止复来者，名曰促。脉阳盛则促，阴盛则结，此皆病脉。又脉来动而中止，更来小数，中有还者反动，名曰结阴也；脉来动而中止，不能自还，因而复动者，名曰代阴也；得此脉者，必难治。脉阴阳俱促，当病血，为实；阴阳俱结，当亡血，为虚；假令促上寸口者，当吐血，或衄；下尺中者，当下血；若乍促乍结为难治。脉数者，久数不止，止则邪结，正气不能复，却结于脏；故邪气浮之，与皮毛相得脉数者，不可下，下之，必烦利不止。 34、问曰：脉有阳结阴结者，何以别之？师曰：其脉浮而数，能食，不大便者，此为实，名曰阳结也，期十七日当剧。其脉沉而迟，不能食，身体重，大便反鞕，名曰阴结也。期十四日当剧。 35、脉蔼蔼，如车盖者，名曰阳结也。 36、脉累累，如循长竿者，名曰阴结也。 37、脉瞥瞥，如羹上肥者，阳气微也。 38、脉萦萦，如蜘蛛丝者，阴气衰也。 39、脉绵绵，如泻漆之绝者，亡其血也。 40、问曰：脉有残贼，何谓也？ 师曰：脉有弦、紧、浮、滑、沉、涩，此六脉，名曰残贼，能为诸脉作病也。 41、问曰：脉有相乘、有纵、有横、有逆、有顺，何也？师曰：水行乘火，金行乘木，名曰纵；火行乘水，木行乘金，名曰横；水行乘金，火行乘木，名曰逆；金行乘水，木行乘火，名曰顺也。 42、问曰：濡弱何以反适十一头？ 师曰：五脏六腑相乘故令十一。 43、脉阴阳俱弦，无寒热，为病饮。在浮部，饮在皮肤；在中部，饮在经络；在沉部，饮在肌肉；若寸口弦，饮在上焦；关上弦，饮在中焦；尺中弦，饮在下焦。 44、脉弦而紧者，名曰革也。弦者状如弓弦，按之不移也。紧者如转索无常也。 45、脉弦而大，弦则为减，大则为芤。减则为寒，芤则为虚。寒虚相搏，此名为革。妇人则半产、漏下，男子则亡血、失精。 46、问曰：曾为人所难，紧脉从何而来？ 师曰：假令亡汗、若吐，以肺里寒，故令脉紧也。假令咳者，坐饮冷水，故令脉紧也。假令下利，以胃中虚冷，故令脉紧也。 47、寸口脉浮而紧，医反下之，此为大逆。浮则无血，紧则为寒，寒气相搏，则为肠鸣，医乃不知，而反饮冷水，令汗不出，水得寒气，冷必相搏，其人即饐。 48、寸口脉微，尺脉紧，其人虚损多汗，知阴常在，绝不见阳也。 49、寸口脉浮而大，浮为风虚，大为气强，风气相搏，必成隐疹，身体为痒。痒者名曰泄风，久久为痂癞。 50、寸口脉浮而大，浮为虚，大为实；在尺为关，在寸为格；关则不得小便，格则吐逆。 51、寸口脉微而涩，微者卫气不行，涩者荣气不逮。荣卫不能相将，三焦无所仰，身体痹不仁。荣气不足，则烦疼，口难言；卫气虚者，则恶寒数欠。三焦不归其部，上焦不归者，噫而酢吞；中焦不归者，不能消谷引食；下焦不归者，则遗溲。 52、寸口脉微而涩，微者卫气衰，涩者荣气不足。卫气衰则面色黄；荣气不足则面色青。荣为根，卫为叶。荣卫俱微，则根叶枯槁，而寒栗咳逆，唾腥吐涎沫也。 53、寸口脉微而缓，微者卫气疏，疏则其肤空；缓者胃气实，实则谷消而水化也。谷入于胃，脉道乃行，水入于经，其血乃成。荣盛则其肤必疏，三焦绝经，名曰血崩。 54、寸口脉弱而缓，弱者阳气不足，缓者胃气有余，噫而吞酸，食卒不下，气填于膈上也。 55、寸口脉弱而迟，弱者卫气微，迟者荣中寒；荣为血，血寒则发热；卫为气，气微者心内饥，饥而虚满不能食也。 56、寸口脉弱而涩，尺中浮大，无外证者，为病属内伤。 57、寸口脉弱而涩，尺中濡弱者，男子病失精，女子病赤白带下。 58、寸口脉洪数，按之弦急者，当发瘾疹；假令脉浮数，按之反平者，为外毒；脉数大，按之弦直者，为内毒，宜升之，令其外出也；误攻则内陷，内陷则死。 59、寸口脉洪数，按之急滑者，当发痈脓；发热者，暴出；无热者，久久必至也。 60、寸口脉浮滑，按之弦急者，当发内痈；咳嗽胸中痛为肺痈，当吐脓血；腹中掣痛为肠痈，当便脓血。 61、寸口脉大而涩，时一弦，无寒热，此为浸淫疮所致也；若加细数者，为难治。 62、趺阳脉紧而浮，浮为气，紧为寒。浮为腹满，紧为绞痛。浮紧相搏，肠鸣而转，转即气动，隔气乃下。少阴脉不出，其阴肿大而虚也。 63、趺阳脉微而紧，紧则为寒，微则为虚，微紧相搏，则为短气。 64、趺阳脉大而紧者，当即下利，为难治。 65、趺阳脉浮，浮则为虚，浮虚相搏，故令气饐，言胃气虚竭也；此为医咎，责虚取实，守空迫血；脉滑则为哕，脉浮鼻中燥者，必衄也。 66、趺阳脉迟而缓，胃气如经也。趺阳脉浮而数，浮则伤胃，数则动脾，此非本病，医特下之所为也。荣卫内陷，其数先微，脉反但浮，其人必大便鞕，气噫不除。何以言之？本以数脉动脾，其数先微，故知脾气不治，大便鞕，气噫不除。今脉反浮，其数改微，邪气独留，心中则饥，邪热不杀谷，潮热发渴，数脉当迟，缓病者则饥。数脉不时，则生恶疮也。 67、趺阳脉浮而涩，少阴脉如经者，其病在脾，法当下利。何以知之？若脉浮大者，气实血虚也。今趺阳脉浮而涩，故知脾气不足，胃气虚也。以少阴脉弦，而沉才见，此为调脉，故称如经也。若反滑而数者，故知当屎脓也。 68、趺阳脉浮而芤，浮者胃气虚，芤者荣气伤，其身体瘦，肌肉甲错，浮芤相搏，宗气衰微，四属断绝也。 69、趺阳脉浮而大，浮为气实，大为血虚；血虚为无阴，孤阳独下阴部者，小便当赤而难，胞中当虚；今小便利，而大汗出，法应胃家当微；今反更实，津液四射，荣竭血尽，干烦而不眠，血薄肉消而成暴液；医复以毒药攻其胃，此为重虚，客阳去有期，必下如淤泥而死。 70、问曰：翕奄沉名曰滑，何谓也？ 师曰：沉为纯阴，翕为正阳，阴阳和合，故令脉滑。关尺自平。 71、趺阳脉微沉，食饮自平；少阴脉微滑，滑者紧之浮名也，此为阴实，其人必股内汗出，阴下湿也。 72、趺阳脉浮而滑，浮为阳，滑为实，阳实相搏，其脉数疾，卫气失度，浮滑之脉数疾，发热汗出者，此为不治。 73、趺阳脉滑而紧，滑者胃气实，紧者脾气强。持实击强，痛还自伤，以手把刃，坐作疮也。 74、趺阳脉沉而微，沉为实，数消谷；紧者，病难治。 75、趺阳脉伏而涩，伏则吐逆，水谷不化，涩则食不得入，名曰关格。 76、师曰：病人脉微而涩者，此为医所病也。大发其汗，又数大下之，其人亡血，病当恶寒，后乃发热，无休止时，夏月盛热，欲着复衣，冬月盛寒，欲裸其身，所以然者，阳微则恶寒，阴弱则发热，此医发其汗，使阳气微，又大下之：令阴气弱，五月之时，阳气在表，胃中虚冷，以阳气内微，不能胜冷，故欲着复衣；十一月之时，阳气在里，胃中烦热，以阴气内弱，不能胜热，故欲裸其身。又阴脉迟涩，故知血亡也。 77、少阴脉弱而涩，弱者微烦，涩者厥逆。 78、趺阳脉不出，脾不上下，身冷肤鞕。 79、少阴脉不至，肾气微，少精血，奔气促迫，上入胸隔，宗气反聚，血结心下，阳气退下，热归阴股，与阴相动，令身不仁，此为尸厥。当刺期门、巨阙。 80、妊娠脉弦数而细，少腹痛，手心热，此为热结胞中，不先其时治之，必有产难。 81、产后脉洪数，按之弦急，此为浊未下；若浊已下而脉如故者，此为魂脱，为难治。 82、诸脉浮数，当发热而洒淅恶寒，若有痛处，饮食如常者，畜积有脓也。 83、问曰：人恐怖者，其脉何状？ 师曰：脉形如循丝累累然，其面白脱色也。 84、问曰：人不饮，其脉何类？ 师曰：脉自涩，唇口干燥也。 85、问曰：人愧者，其脉何类？ 师曰：脉浮而面色乍白乍赤也。 86、师曰：寸口诸微亡阳，诸濡亡血，诸弱发热，诸紧为寒。诸乘寒者则为厥，郁冒不仁，以胃无谷气，脾涩不通，口急不能言，战而栗也。 87、师曰：发热则脉躁，恶寒则脉静，脉随证转者，为病疟。 88、师曰：伤寒，咳逆上气，其脉散者死，为其形损故也。 89、师曰：脉乍大乍小，乍静乍乱，见人惊恐者，为祟发于胆，气竭故也。 90、师曰：人脉皆无病，暴发重病，不省人事者，为厉鬼，治之以祝由，能言者可治，不言者死。 91、师曰：脉浮而洪，身汗如油，喘而不休，水浆不下，形体不仁，乍静乍乱，此为命绝也。又未知何脏先受其灾。若汗出发润，喘不休者，此为肺先绝也。阳反独留，形体如烟熏，直视摇头者，此为心绝也。唇吻反青，四肢掣习者，此为肝绝也。环口黧黑，油汗发黄者，此为脾绝也。溲便遗失，狂言，目反直视者，此为肾绝也。又未知何脏阴阳前绝。若阳气前绝，阴气后竭者，其人死身色必青；阴气前绝，阳气后竭者，其人死，身色必赤，腋下温，心下热也。 92、奇经八脉不系于十二经，别有自行道路。其为病总于阴阳，其治法属十二经。假令督脉为病，脊背强，隐隐痛，脉当微浮而急，按之涩，治属太阳。 93、任脉为病，其内结痛疝瘕，脉当沉而结，治属太阴。 94、冲脉为病，气上逆而里急，脉当浮虚而数，治属太阴。 95、带脉为病，苦腹痛，腰间冷痛，脉当沉而细，治属少阴。 96、阳跷为病，中于侧，气行于外，脉当弦急，按之缓，治属少阳。 97、阴跷为病，中于侧，气行于内，脉当浮缓，按之微急而弦，治属厥阴。 98、阳维与诸阳会，其为病在脉外，发寒热，脉当浮而虚，治属气分。 99、阴维与诸阴交，其为病在脉中，心中痛，手心热，脉当弦而涩，治属血分。 100、阳维维于阳，阴维维于阴，为气血之别，使不拘于一经也。 101、奇经八脉之病，由各经受邪，久久移传，或劳伤所致，非暴发也。 102、问曰：八脉内伤何以别之？ 师曰：督脉伤，柔柔不欲伸，不能久立，立则隐隐而胀；任脉伤，小便多，其色白浊；冲脉伤，时咳不休，有声无物，劳则；地喘；带脉伤，回身一周冷；阳跷伤，则身左不仁；阴跷伤，则身右不仁；阳维伤，则畏寒甚，皮常湿；阴维伤，则畏热甚，皮常枯。 103、问曰：八脉内伤其脉何似？ 师曰：督脉伤，尺脉大而涩；任脉伤，关脉大而涩；冲脉伤，寸脉短而涩；带脉伤，脉沉迟而结；阳跷伤，脉时大而弦；阴跷伤，脉时细时弦；阳维伤，脉时缓时弦；阴维伤，脉时紧时涩。问曰：其治奈何？师曰：督脉伤，当补髓；任脉伤，当补精；冲脉伤，当补气；带脉伤，当补肾；阳跷伤，则益胆；阴跷伤，则补肝；阴维伤，则调卫；阴维伤，则养荣。 104、问曰：其处方奈何？ 师曰：相体虚实，察病轻重，采取方法，权衡用之，则无失也。', '2024-12-06T07:22:40.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I8vjThKe1JN', 1, '{"title":"六气主客第三","description":"<p>1、问曰：六气主客何以别之？师曰：厥阴生少阴，少阴生少阳，少阳生太阴，太阴生阳明，阳明生太阳，太阳复生厥阴，周而复始，久久不变，年复一年，此名主气；厥阴生少阴，少阴生太阴，太阴生少阳，少阳生阳明，阳明生太阳，复生厥阴，周而复始，此名客气。</p><p>2、问曰：其始终奈何？</p>\n<p></p>\n<p>      师曰：初气始于大寒，二气始于春分，三气始于小满，四气始于大暑，五气始于秋分，终气始于小雪，仍终于大寒，主客相同，其差各三十度也。</p><p>3、问曰：司天在泉奈何？</p>\n<p></p>\n<p>    师曰：此客气也。假如子午之年，少阴司天，阳明则为在泉，太阳为初气，厥阴为二气，司天为三气，太阴为四气，少阳为五气，在泉为终气；卯酉之年，阳明司天，少阴在泉，则初气太阴，二气少阳，三气阳明，四气太阳，五气厥阴，终气少阴；戌辰之年，太阳司天，太阴在泉；丑未之年，太阴司天，太阳在泉；寅申之年，少阳司天，厥阴在泉；巳亥之年，厥阴司天，少阳在泉；其余各气，以例推之。</p><p>4、问曰：其为病也何如？</p>\n<p></p>\n<p>     师曰：亦有主客之分也；</p>\n<p></p>\n<p>    假如厥阴司天，主胜，则胸胁痛，舌难以言；客胜，则耳鸣，掉眩，甚则咳逆。</p>\n<p></p>\n<p>   少阴司天，主胜，则心热，烦躁，胁痛支满；客胜，则鼽嚏，颈项强，肩背瞀热，头痛，少气，发热，耳聋，目暝，甚则跗肿，血溢，疮，喑，喘咳。</p>\n<p></p>\n<p>   太阴司天，主胜，则胸腹满，食已而瞀；客胜，则首、面、跗肿，呼吸气喘。</p>\n<p></p>\n<p>   少阳司天，主胜，则胸满，咳逆，仰息，甚则有血，手热；客胜，则丹疹外发，及为丹熛，疮疡，呕逆，喉痹，头痛，嗌踵，耳聋，血溢，内为瘛疭。</p>\n<p></p>\n<p>   阳明司天，主胜，则清复内余，咳，衄，嗌塞，心膈中热，咳不止而白血出者死，金居少阳之位，客不胜主也。</p>\n<p></p>\n<p>   太阳司天，主胜，则喉嗌中鸣；客胜，则胸中不利，出清涕，感寒则咳也。</p>\n<p></p>\n<p>   厥阴主在泉，主胜，则筋骨徭并，腰腹时痛；客胜，则关节不利，内为痉强，外为不便。</p>\n<p></p>\n<p>  少阴在泉，主胜，则厥气上行，心痛发热，膈中众痹皆作，发于胠胁，魄汗不藏，四逆而起；客胜，则腰痛，尻、股、膝、髀、腨、胻、足病瞀热以酸，跗肿不能久立，溲便变。</p>\n<p></p>\n<p>   太阴在泉，主胜，则寒气逆满，食饮不下，甚则为疝；客胜，则足痿下肿，便溲不时，湿客下焦，发而濡泄，及为阴肿，隐曲之疾。</p>\n<p></p>\n<p>   少阳在泉，主胜，则热反上行，而客于心，心痛发热，格中而呕；客胜，则腰腹痛，而反恶寒，甚则下白溺白。</p>\n<p></p>\n<p>   阳明在泉，主胜，则腰重，腹痛，少腹生寒，下为鹜溏，寒厥于肠，上冲胸中，甚则喘满，不能久立；客胜，则清气动下，小腹坚满，而数便泄。</p>\n<p></p>\n<p>   太阳在泉，以水居水位，无所胜也。</p><p>5、问曰：其胜复何如？</p>\n<p></p>\n<p>      师曰：有胜必有复，无胜则无复也；</p>\n<p></p>\n<p>      厥阴之胜，则病耳鸣，头眩，愦愦欲吐，胃膈如寒，胠胁气并，化而为热，小便黄赤，胃脘当心而痛，上及两胁，肠鸣，飧泄，少腹痛，注下赤白，甚则呕吐，膈不通；其复也，则少腹坚满，里急暴痛，厥心痛，汗发，呕吐，饮食不入，入而复出，筋骨掉眩清厥，甚则入脾，食痹而吐。</p>\n<p></p>\n<p>     少阴之胜，则病心下热，善饥，脐下气动，气游三焦，呕吐，躁烦，腹满而痛，溏泄赤沃；其复也，则燠热内作，烦躁，鼽嚏，少腹绞痛，嗌燥，气动于左上行于右，咳则皮肤痛，暴喑，心痛，郁冒不知人，洒淅恶寒振栗，谵妄，寒已而热，渴而欲饮，少气，骨痿，膈肠不便，外为浮肿，哕噫，痱疹，疮疡，痈疽，痤痔，甚则入肺，咳而鼻渊。</p>\n<p></p>\n<p>     太阴之胜，则火气内郁，疮疡于中，流散于外，病在胠胁甚则心痛热格，头痛，喉痹，项强，又或湿气内郁，寒迫下焦，少腹满，腰椎痛强，注泄，足下湿，头重，跗肿，足胫肿，饮发于中，跗肿于上；其复也，则体重，中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声，头项痛重，掉瘛尤甚，呕而密默，唾吐清液，甚则入肾，窃泄无度。</p>\n<p></p>\n<p>       少阳之胜，则病热客于胃，心烦而痛，目赤呕酸，善饥，耳痛，溺赤，善惊谵妄，暴热消烁，少腹痛，下沃赤白；其复也，枯燥，烦热，惊瘛，咳，衄，心热，烦躁，便数，憎风，厥气上行，面如浮埃，目乃瞤瘛，火气内发，上为口糜，呕逆，血溢，血泄，发而为疟，恶寒鼓栗，寒极反热，嗌络焦槁，渴饮水浆，色变黄赤，少气肺痿，化而为水，传为跗肿，甚则入肺，咳而血泄。</p>\n<p></p>\n<p>       阳明之胜，则清发于中，左胠胁痛，溏泄，内为嗌塞，外发颓疝，胸中不便，嗌而咳；其复也，则病生胠胁，气归于左，善太息，甚则心痛痞满，腹胀而泄，呕苦，咳哕烦心，病在膈中，甚则入肝，惊骇筋挛。</p>\n<p></p>\n<p>       太阳之胜，则病痔疟，发寒，厥人胃，则内生心痛，阴中乃疡，隐曲不利，亘引阴股筋肉拘苛，血脉凝泣，络满血变，或为血泄，皮肤否肿，腹满时减，热反上行，头项囟顶脑户中痛，目如脱，寒入下焦，则传为濡泄；其复也，则心胃生寒，胸膈不利，心痛痞满，头痛，善悲，时发眩仆，食减，腰椎反痛，屈伸不便，少腹控睪引腰脊上冲心，唾出清水，及为哕噫，甚则入心，善忘，善悲，寒复内余，则腰尻痛，屈伸不利，股胫足膝中痛。</p>\n<p></p>\n<p>      此六气为病，须谨识之，而弗失也。</p><p>6、师曰：子知六气，不知五运，未尽其道，今为子言，假如太阳司天，而运当甲己，夫甲己土运也，太阳寒水也，土能克水，太阳不能正其位也；又如厥阴司天，而逢乙庚金运；少阴少阳司天，而逢丙辛水运；太阴司天，而逢丁壬木运；阳明司天，而逢戊癸火运，其例同也。</p><p>7、问曰：其治法奈何？</p>\n<p></p>\n<p>     师曰：风寒暑湿燥热各随其气，有假者反之，甚者从之，微者逆之，采取方法，慎毋乱也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010005,"no":5}}', '2024-12-06T07:23:07.000Z', '2024-12-06T07:23:07.000Z', '2024-12-06T07:23:07.000Z', '1、问曰：六气主客何以别之？师曰：厥阴生少阴，少阴生少阳，少阳生太阴，太阴生阳明，阳明生太阳，太阳复生厥阴，周而复始，久久不变，年复一年，此名主气；厥阴生少阴，少阴生太阴，太阴生少阳，少阳生阳明，阳明生太阳，复生厥阴，周而复始，此名客气。 2、问曰：其始终奈何？ 师曰：初气始于大寒，二气始于春分，三气始于小满，四气始于大暑，五气始于秋分，终气始于小雪，仍终于大寒，主客相同，其差各三十度也。 3、问曰：司天在泉奈何？ 师曰：此客气也。假如子午之年，少阴司天，阳明则为在泉，太阳为初气，厥阴为二气，司天为三气，太阴为四气，少阳为五气，在泉为终气；卯酉之年，阳明司天，少阴在泉，则初气太阴，二气少阳，三气阳明，四气太阳，五气厥阴，终气少阴；戌辰之年，太阳司天，太阴在泉；丑未之年，太阴司天，太阳在泉；寅申之年，少阳司天，厥阴在泉；巳亥之年，厥阴司天，少阳在泉；其余各气，以例推之。 4、问曰：其为病也何如？ 师曰：亦有主客之分也； 假如厥阴司天，主胜，则胸胁痛，舌难以言；客胜，则耳鸣，掉眩，甚则咳逆。 少阴司天，主胜，则心热，烦躁，胁痛支满；客胜，则鼽嚏，颈项强，肩背瞀热，头痛，少气，发热，耳聋，目暝，甚则跗肿，血溢，疮，喑，喘咳。 太阴司天，主胜，则胸腹满，食已而瞀；客胜，则首、面、跗肿，呼吸气喘。 少阳司天，主胜，则胸满，咳逆，仰息，甚则有血，手热；客胜，则丹疹外发，及为丹熛，疮疡，呕逆，喉痹，头痛，嗌踵，耳聋，血溢，内为瘛疭。 阳明司天，主胜，则清复内余，咳，衄，嗌塞，心膈中热，咳不止而白血出者死，金居少阳之位，客不胜主也。 太阳司天，主胜，则喉嗌中鸣；客胜，则胸中不利，出清涕，感寒则咳也。 厥阴主在泉，主胜，则筋骨徭并，腰腹时痛；客胜，则关节不利，内为痉强，外为不便。 少阴在泉，主胜，则厥气上行，心痛发热，膈中众痹皆作，发于胠胁，魄汗不藏，四逆而起；客胜，则腰痛，尻、股、膝、髀、腨、胻、足病瞀热以酸，跗肿不能久立，溲便变。 太阴在泉，主胜，则寒气逆满，食饮不下，甚则为疝；客胜，则足痿下肿，便溲不时，湿客下焦，发而濡泄，及为阴肿，隐曲之疾。 少阳在泉，主胜，则热反上行，而客于心，心痛发热，格中而呕；客胜，则腰腹痛，而反恶寒，甚则下白溺白。 阳明在泉，主胜，则腰重，腹痛，少腹生寒，下为鹜溏，寒厥于肠，上冲胸中，甚则喘满，不能久立；客胜，则清气动下，小腹坚满，而数便泄。 太阳在泉，以水居水位，无所胜也。 5、问曰：其胜复何如？ 师曰：有胜必有复，无胜则无复也； 厥阴之胜，则病耳鸣，头眩，愦愦欲吐，胃膈如寒，胠胁气并，化而为热，小便黄赤，胃脘当心而痛，上及两胁，肠鸣，飧泄，少腹痛，注下赤白，甚则呕吐，膈不通；其复也，则少腹坚满，里急暴痛，厥心痛，汗发，呕吐，饮食不入，入而复出，筋骨掉眩清厥，甚则入脾，食痹而吐。 少阴之胜，则病心下热，善饥，脐下气动，气游三焦，呕吐，躁烦，腹满而痛，溏泄赤沃；其复也，则燠热内作，烦躁，鼽嚏，少腹绞痛，嗌燥，气动于左上行于右，咳则皮肤痛，暴喑，心痛，郁冒不知人，洒淅恶寒振栗，谵妄，寒已而热，渴而欲饮，少气，骨痿，膈肠不便，外为浮肿，哕噫，痱疹，疮疡，痈疽，痤痔，甚则入肺，咳而鼻渊。 太阴之胜，则火气内郁，疮疡于中，流散于外，病在胠胁甚则心痛热格，头痛，喉痹，项强，又或湿气内郁，寒迫下焦，少腹满，腰椎痛强，注泄，足下湿，头重，跗肿，足胫肿，饮发于中，跗肿于上；其复也，则体重，中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声，头项痛重，掉瘛尤甚，呕而密默，唾吐清液，甚则入肾，窃泄无度。 少阳之胜，则病热客于胃，心烦而痛，目赤呕酸，善饥，耳痛，溺赤，善惊谵妄，暴热消烁，少腹痛，下沃赤白；其复也，枯燥，烦热，惊瘛，咳，衄，心热，烦躁，便数，憎风，厥气上行，面如浮埃，目乃瞤瘛，火气内发，上为口糜，呕逆，血溢，血泄，发而为疟，恶寒鼓栗，寒极反热，嗌络焦槁，渴饮水浆，色变黄赤，少气肺痿，化而为水，传为跗肿，甚则入肺，咳而血泄。 阳明之胜，则清发于中，左胠胁痛，溏泄，内为嗌塞，外发颓疝，胸中不便，嗌而咳；其复也，则病生胠胁，气归于左，善太息，甚则心痛痞满，腹胀而泄，呕苦，咳哕烦心，病在膈中，甚则入肝，惊骇筋挛。 太阳之胜，则病痔疟，发寒，厥人胃，则内生心痛，阴中乃疡，隐曲不利，亘引阴股筋肉拘苛，血脉凝泣，络满血变，或为血泄，皮肤否肿，腹满时减，热反上行，头项囟顶脑户中痛，目如脱，寒入下焦，则传为濡泄；其复也，则心胃生寒，胸膈不利，心痛痞满，头痛，善悲，时发眩仆，食减，腰椎反痛，屈伸不便，少腹控睪引腰脊上冲心，唾出清水，及为哕噫，甚则入心，善忘，善悲，寒复内余，则腰尻痛，屈伸不利，股胫足膝中痛。 此六气为病，须谨识之，而弗失也。 6、师曰：子知六气，不知五运，未尽其道，今为子言，假如太阳司天，而运当甲己，夫甲己土运也，太阳寒水也，土能克水，太阳不能正其位也；又如厥阴司天，而逢乙庚金运；少阴少阳司天，而逢丙辛水运；太阴司天，而逢丁壬木运；阳明司天，而逢戊癸火运，其例同也。 7、问曰：其治法奈何？ 师曰：风寒暑湿燥热各随其气，有假者反之，甚者从之，微者逆之，采取方法，慎毋乱也。', '2024-12-06T07:23:07.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s3kQvWS3zkF', 1, '{"title":"伤寒例第四","description":"<p>1、</p>\n<p>四时八节二十四节气七十二候决病法：</p>\n<p>立春正月节斗指艮，雨水正月中斗指寅。</p>\n<p>惊蛰二月节斗指甲，春分二月中斗指卯。</p>\n<p>清明三月节斗指乙，谷雨三月中斗指辰。</p>\n<p>立夏四月节斗指巽，小满四月中斗指巳。</p>\n<p>芒种五月节斗指丙，夏至五月中斗指午。</p>\n<p>小暑六月节斗指丁，大暑六月中斗指未。</p>\n<p>立秋七月节斗指坤，处暑七月中斗指申。</p>\n<p>白露八月节斗指庚，秋分八月中斗指酉。</p>\n<p>寒露九月节斗指辛，霜降九月中斗指戌。</p>\n<p>立冬十月节斗指干，小雪十月中斗指亥。</p>\n<p>大雪十一月节斗指壬，冬至十一月中斗指子。</p>\n<p>小寒十二月节斗指癸，大寒十二月中斗指丑。</p><p>2、二十四节气，节有十二，中气有十二，五日为一候，气亦同，合有七十二候，决病生死，此须洞解也。</p><p>3、阴阳大论云：春气温和，夏气暑热，秋气清凉，冬气冰冽，此则四时正气之序也。</p>\n<p></p>\n<p>    冬时严寒，万类深藏，君子周密，则不伤于寒。触冒之者，则名伤寒耳。其伤于四时之气，皆能为病。以伤寒为病者，以其最盛杀厉之气也。中而即病者，名曰伤寒；不即病，寒毒藏于肌肤，至春变为温病，至夏变为暑病。</p>\n<p>   暑病者，热极重于温也。是以辛苦之人，春夏多温热者，皆由冬时触寒所致，非时行之气也。凡时行者，春时应暖而反大寒；夏时应热而反大凉；秋时应凉而反大热；冬时应寒而反大温。此非其时而有其气，是以一岁之中，长幼之病多相似者，此则时行之气也。夫欲候知四时正气为病，及时行疫气之法，皆当按斗历占之。</p>\n<p>    九月霜降节后，宜渐寒，向冬大寒，至正月雨水节后宜解也。所以谓之雨水者，以冰雪解而为雨水故也。</p>\n<p>    至惊蛰二月节后，气渐和暖，向夏大热，至秋便凉。</p>\n<p>    从霜降以后，至春分以前，凡有触冒霜露，体中寒即病者，谓之伤寒也。</p>\n<p>    九月十月寒气尚微，为病则轻；十一月十二月寒冽已严，为病则重；正月二月寒渐将解，为病亦轻。此以冬时不调，适有伤寒之人即为病也。其冬有非节之暖者，名曰冬温。</p>\n<p>    冬温之毒，与伤寒大异，冬温复有先后，更相重沓，亦有轻重，为治不同，证如后章。</p>\n<p>    从立春节后，其中无暴大寒，又不冰雪；而有人壮热为病者，此属春时阳气，发其冬时伏寒，变为温病。</p>\n<p>    从春分以后，至秋分节前，天有暴寒者，皆为时行寒疫也。三月四月或有暴寒，其时阳气尚弱，为寒所折，病热犹轻；五月六月阳气已盛，为寒所折，病热则重；七月八月，阳气已衰，为寒所折，病热亦微。其病与温相似，但治有殊耳。</p>\n<p></p>\n<p>   十五日得一气，于四时之中，一时有六气，四六名为二十四气。然气候亦有应至仍不至，或有未应至而至者，或有至而太过者，皆成病气也。但天地动静，阴阳鼓击者，各正一气耳。是以彼春之暖，为夏之暑；彼秋之忿，为冬之怒。是故冬至之后，一阳爻升，一阴爻降也。</p>\n<p>    夏至之后，一阳气下，一阴气上也。斯则冬夏二至，阴阳合也；春秋二分，阴阳离也。阴阳交易，人变病焉。此君子春夏养阳，秋冬养阴，顺天地之刚柔也。小人触冒，必婴暴疹。须知毒烈之气，留在何经，必发何病，详而取之。是以春伤于风，夏必飧泄；夏伤于暑，秋必病疟；秋伤于湿，冬必咳嗽；</p>\n<p>   冬伤于寒，春必病温。此必然之道，可不审明之。伤寒之病，逐日浅深，以施方治。</p>\n<p></p>\n<p>   今世人伤寒，或始不早治，或治不对病，或日数久淹，困乃告医。医人又不依次第而治之，则不中病。皆宜临时消息制方，无不效也。</p>\n<p></p><p>4、又土地温凉，高下不同；物性刚柔，餐［注：桂本餐字为飧，似误］居亦异。是故黄帝兴四方之问，岐伯举四治之能，以训后贤，开其未悟。临病之工，宜须两审也。</p><p>5、凡伤于寒，传经则为病热，热虽甚，不死。若两感于寒而病者，多死。尺寸俱浮者，太阳受病也，当一二日发。以其脉上连风府，故头项痛，腰脊强。</p><p>6、尺寸俱长者，阳明受病也，当二三日发。以其脉侠鼻、络于目，故身热、汗出、目疼、鼻干、不得卧。</p><p>7、尺寸俱弦者，少阳受病也，当三四日发。以其脉循胁络于耳，故胸胁痛而耳聋。此三经受病，未入于腑者，皆可汗而已。</p><p>8、尺寸俱沉濡者，太阴受病也，当四五日发。以其脉布胃中，络于嗌，故腹满而嗌干。</p><p>9、尺寸俱沉细者，少阴受病也，当五六日发。以其脉贯肾，络于肺，系舌本，故口燥舌干而渴。</p><p>10、尺寸俱弦微者，厥阴受病也，当六七日发。以其脉循阴器、络于肝，故烦满而囊缩。此三经受病，己入于腑者，皆可下而已。</p><p>11、伤寒传经在太阳，脉浮而急数，发热，无汗，烦躁，宜$f{麻黄汤}。</p><p>12、传阳明，脉大而数，发热，汗出，口渴舌燥，宜$f{白虎汤}，不差与$n{承气汤}--$f{大承气汤}--$f{小承气汤}--$f{调胃承气汤}。</p><p>13、传少阳，脉弦而急，口苦，咽干，头晕，目眩，往来寒热，热多寒少，宜$f{小柴胡汤}，不差与$f{大柴胡汤}。</p><p>14、传太阴，脉濡而大，发热，下利，口渴，腹中急痛，宜$f{茯苓白术厚朴石膏黄芩甘草汤}。</p><p>15、传少阴，脉沉细而数，手足时厥时热，咽中痛，小便难，宜$f{附子细辛黄连黄芩汤}。</p><p>16、传厥阴，脉沉弦而急，发热时悚，心烦呕逆，宜$f{桂枝当归汤}，吐蛔者，宜$f{乌梅丸}。</p><p>17、以上皆传经脉证并治之正法也。若入腑及脏为传经变病，治列后条。</p><p>18、若两感于寒者，一日太阳受之，即与少阴俱病，则头痛、口干、烦满而渴，脉时浮时沉，时数时细，$f{大青龙汤加附子}主之。</p><p>19、二日阳明受之，即与太阴俱病，则腹满身热、不欲食、谵语，脉时高时卑，时强时弱，宜$f{大黄石膏茯苓白术枳实甘草汤}</p><p>20、三日少阳受之，即与厥阴俱病，则耳聋，囊缩而厥，水浆不入，脉乍弦乍急，乍细乍散，宜$f{当归附子汤}主之。</p><p>21、以上皆传经变病，多不可治，不知人者，六日死。若三阴三阳、五脏六腑皆受病，则荣卫不行，脏腑不通而死矣。所谓两感于寒不免于死者，其在斯乎!其在斯乎!</p><p>22、若不加异气者，至七日太阳病衰，头痛少愈也；八日阳明病衰，身热少歇也；九日少阳病衰，耳聋微闻也；十日太阴病衰，腹减如故，则思饮食；十一日少阴病衰，渴止舌干，已而嚏；十二日厥阴病衰，囊纵，少腹微下，大气皆去，病人精神爽慧也。若过十三日以上不间，尺寸陷者，大危。若更感异气，变为他病者，当依坏病证法而治之。若脉阴阳俱盛，重感于寒者，变成温疟。阳脉浮滑，阴脉濡弱，更伤于风者，变为风温。阳脉洪数，阴脉实大，更遇温热者，变为温毒。温毒，病之最重者也。阳脉濡弱，阴脉弦紧，更遇温气者，变为温疫。以此冬伤于寒，发为温病，脉之变证，方治如说。</p><p>23、凡人有疾，不时即治，隐忍冀差，以成痼疾。小儿女子，益以滋甚。时气不和，便当早言，寻其邪由，及在腠理，以时治之，罕有不愈者。患人忍之，数日乃说，邪气入脏，则难为制。</p><p>24、凡作汤药，不可避晨夕，觉病须臾，即宜便治，不等早晚，则易愈矣。如或差迟，病即传变，虽欲除治，必难为力。服药不如方法，纵意违师，不须治之。</p><p>25、凡伤寒之病，多从风寒得之。始表中风寒，入里则不消矣。未有温覆当而不消散者。不在证治，拟欲攻之，犹当先解表，乃可下之。若表未解，而内不消，必非大满，犹有寒热，则不可下。若表已解，而内不消，大满大实，腹坚，中有燥屎，自可除下之。虽四五日，数下之，不能为祸也。若不宜下，而便攻之，则内虚热入，协热遂利，烦躁诸变，不可胜数，轻者困笃，重者必死矣。</p><p>26、夫阳盛阴虚，汗之则死，下之则愈；阳虚阴盛，汗之则愈，下之则死。如是，则神丹安可以误发，甘遂何可以妄攻？虚盛之治，相背千里，吉凶之机，应若影响，岂容易哉!况桂枝下咽，阳盛即毙；承气入胃，阴盛以亡，死生之要，在乎须臾，视身之尽，不暇计日。此阴阳虚实之交错，其候至微；发汗吐下之相反，其祸至速，而医术浅狭，懵然不知病源，为治乃误，使病者殒殁，自谓其分，至令冤魂塞于冥路，死尸盈于旷野，仁者鉴此，岂不痛欤！</p><p>27、凡两感病俱作，治有先后，发表攻里，本自不同，而执迷用意者，乃云神丹甘遂合而饮之，且解其表，又除其里，言巧似是，其理实违。夫智者之举错也，常审以慎；愚者之动作也，必果而速。安危之变，岂可诡哉！世上之士，但务彼翕习之荣，而莫见此倾危之败，惟明者居然，能护其本，近取诸身，夫何远焉。</p><p>28、凡发汗，温暖汤药，其方虽言日三服，若病剧不解，当促其间，可半日中尽三服。若与病相阻，即使有所觉，病重病者一日一夜，当晬时观之，如服一剂，病证犹在，故当复作本汤服之。至有不能汗出，服三剂乃解；若汗不出者，死病也。</p><p>29、凡得时气病，至五六日，而渴欲饮水，饮不能多，不当与也，何者？以腹中热尚少，不能消之，便更与人作病也。至七八日，大渴欲饮水者，犹当依证而与之。与之时常令不足，勿极意也。言能饮一斗，与五升。若饮而腹满，小便不利，若喘若哕。不可与之也。忽然大汗出，是为自愈也。</p><p>30、凡得病反能饮水，此为欲愈之病。其不晓病者，但闻病饮水者自愈，小渴者乃强与饮之，因成其祸，不可复数也。</p><p>31、凡得病厥，脉动数，服汤更迟；脉浮大减小；初躁后静，此皆愈证也。</p><p>32、凡治温病，可刺五十九穴。又身之穴，三百六十有五，其三十穴灸之有害；七十九穴刺之为灾，并中髓也。</p><p>33、脉四损，三日死。平人一息，病人脉一至，名曰四损。脉五损，一日死。平人二息，病人脉一至，名曰五损。脉六损，一时死。平人三息，病人脉一至，名曰六损。</p><p>34、四损，经气绝；五损，腑气绝；六损，脏气绝。真气不行于经曰经气绝；不行于腑，曰腑气绝；不行于脏，曰脏气绝；经气绝，则四肢不举；腑气绝，则不省人事；脏气绝，则一身尽冷。</p><p>35、脉盛身寒，得之伤寒；脉虚身热，得之伤暑。脉阴阳俱盛，大汗出，下之不解者死。脉阴阳俱虚，热不止者死。脉至乍数乍疏者死。脉至如转索，按之不易者其日死。谵言妄语，身微热，脉浮大，手足温者生。逆冷，脉沉细者，不过一日死矣。此以前是伤寒热病证候也。</p><p>36、脉濡而弱，弱反在关，濡反在巅，微反在上，涩反在下。微则阳气不足，涩则无血。阳气反微，中风汗出而反躁烦。涩则无血，厥而且寒。阳厥发汗，躁不得眠。阳微则不可下，下之则心下痞鞕。</p><p>37、动气在右，不可发汗，发汗则衄而渴，心苦烦，饮水即吐。</p><p>38、动气在左，不可发汗，发汗则头眩，汗不止，则筋惕肉〖目闰〗。</p><p>39、动气在上，不可发汗，发汗则气上冲止于心下。</p><p>40、动气在下，不可发汗，发汗则无汗可发，心中大烦，骨节疼痛，目眩恶寒，食则吐谷，气不得前。</p><p>41、咽中闭塞，不可发汗，发汗则吐血，气欲欲绝，手足厥冷，欲得蜷卧，不能自温。</p><p>42、诸脉得数动微弱者，不可发汗，发汗则大便难，腹中干，胃燥而烦，其形相象，根本异源。</p><p>43、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，不可发汗，发汗则寒栗，不能自还。咳而发汗，其咳必剧，数吐涎沫，咽中必干，小便不利，心中饥烦，晬时而发，其形似疟，有寒无热，虚而寒栗，蜷而苦满，腹中复坚，命将难全。</p><p>44、厥逆脉紧，不可发汗，发汗声乱、咽嘶、舌萎、声不得前。</p><p>45、诸逆发汗，病微者难差，剧者必死。</p><p>46、凡发汗，欲令遍身漐漐微似汗，不可令如水流漓。若病不解，当重发汗；若汗多者，不得重发汗，亡阳故也。。</p><p>47、凡服汤发汗，中病便止，不必尽剂。</p><p>48、凡用吐汤，中病便止，不必尽剂。。</p><p>49、诸四逆厥者，不可吐之；虚家亦然。</p><p>50、凡病胸上诸实，胸中郁郁而痛，不能食，欲使人按之，而反有涎唾，下利十余行，其脉反涩，寸口脉微滑，此可吐之，吐之利则止。</p><p>51、宿食在上脘者，当吐之。</p><p>52、动气在右，不可下之，下之则津液内竭，咽燥、鼻干、头眩、心悸也。</p><p>53、动气在左，不可下之。下之则腹内拘急，食饮不下，动气更剧。虽有身热，卧则欲蜷。</p><p>54、动气在上，不可下之。下之则掌中热烦，身上浮冷，热汗自泄，欲得水自灌。</p><p>55、动气在下，不可下之。下之则腹胀满，卒起头眩，食则下利清谷，心下痞。</p><p>56、咽中闭寒，不可下之。下之则上轻下重，水浆不下，卧则欲蜷，身急痛，下利日数十行。</p><p>57、诸外实者，不可下之。下之则发微热，若亡脉厥者，当脐握热。</p><p>58、诸虚者，不可下之。下之则大渴，求水者易愈，恶水者剧。</p><p>59、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，虚者不可下也。微弦为咳，咳则吐涎，下之则咳止，而利因不休，利不休则胸中如虫啮，粥入则出，小便不利，两胁拘急，喘息为难，颈背相引，臂则不仁，极寒反汗出，身冷若冰，眼睛不慧，语言不休，而谷气多入，此为除中，口虽欲言，舌不得前。</p><p>60、脉濡而紧，濡则卫气微，紧则荣中寒。阳微卫中风，发热而恶寒；荣紧胃气冷，微呕心内烦。医谓有大热，解肌而发汗，亡阳虚烦躁，心下苦痞坚。表里俱虚竭，卒起而头眩。客热在皮肤，怅怏不得眠。不知胃气冷，紧寒在关元。技巧无所施，汲水灌其身。客热应时罢，栗栗而振寒。重被而复之，汗出而冒巅。体惕而又振，小便为微难。寒气因水发，清谷不容闲。呕变反肠出，颠倒不得安。手足为微逆，身冷而内烦。迟欲从后救，安可复追还。</p><p>61、脉浮而紧，浮则为风，紧则为寒；风则伤卫，寒则伤荣；荣卫俱病，骨节烦疼；当发其汗，而不可下也。。</p><p>62、脉浮而大，心下反鞕，有热，属脏者，攻之，不令发汗；属腑者，不令溲数。溲数则大便鞕，汗多则越甚，脉迟者，尚未可攻也。。</p><p>63、伤寒，脉阴阳俱紧，恶寒发热，则脉欲厥。厥者，脉初来大，渐渐小，更来渐大，是其候也。如此者恶寒，甚者，翕翕汗出，喉中痛；若热多者，目赤脉多，睛不慧，医复发之，咽中则伤；若复下之，则两目闭，寒多便清谷，热多便脓血；若熏之，则身发黄；若熨之，则咽燥。若小便利者，可救之；小便难者，危殆也。</p><p>64、伤寒发热，口中勃勃气出，头痛，目黄，衄不可制，阴阳俱虚，贪水者必呕，恶水者厥。若下之，则咽中生疮；假令手足温者，必下重便脓血。头痛目黄者，下之则目闭。贪水者，下之则脉厥，其声嘤嘤，咽喉塞，汗之则战栗；恶水者，下之则里冷，不嗜食，大便完谷出，汗之则口中伤，舌上白胎，烦躁，脉反数，不大便，六七日后必便血，小便不利也。</p><p>65、凡服下汤，得利便止，不必尽剂。此以前是汗吐下三法之大要也。若能于此例之外，更神而明之，斯道其庶几乎？</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010006,"no":6}}', '2024-12-06T07:23:24.000Z', '2024-12-06T07:23:24.000Z', '2024-12-06T07:23:24.000Z', '1、 四时八节二十四节气七十二候决病法： 立春正月节斗指艮，雨水正月中斗指寅。 惊蛰二月节斗指甲，春分二月中斗指卯。 清明三月节斗指乙，谷雨三月中斗指辰。 立夏四月节斗指巽，小满四月中斗指巳。 芒种五月节斗指丙，夏至五月中斗指午。 小暑六月节斗指丁，大暑六月中斗指未。 立秋七月节斗指坤，处暑七月中斗指申。 白露八月节斗指庚，秋分八月中斗指酉。 寒露九月节斗指辛，霜降九月中斗指戌。 立冬十月节斗指干，小雪十月中斗指亥。 大雪十一月节斗指壬，冬至十一月中斗指子。 小寒十二月节斗指癸，大寒十二月中斗指丑。 2、二十四节气，节有十二，中气有十二，五日为一候，气亦同，合有七十二候，决病生死，此须洞解也。 3、阴阳大论云：春气温和，夏气暑热，秋气清凉，冬气冰冽，此则四时正气之序也。 冬时严寒，万类深藏，君子周密，则不伤于寒。触冒之者，则名伤寒耳。其伤于四时之气，皆能为病。以伤寒为病者，以其最盛杀厉之气也。中而即病者，名曰伤寒；不即病，寒毒藏于肌肤，至春变为温病，至夏变为暑病。 暑病者，热极重于温也。是以辛苦之人，春夏多温热者，皆由冬时触寒所致，非时行之气也。凡时行者，春时应暖而反大寒；夏时应热而反大凉；秋时应凉而反大热；冬时应寒而反大温。此非其时而有其气，是以一岁之中，长幼之病多相似者，此则时行之气也。夫欲候知四时正气为病，及时行疫气之法，皆当按斗历占之。 九月霜降节后，宜渐寒，向冬大寒，至正月雨水节后宜解也。所以谓之雨水者，以冰雪解而为雨水故也。 至惊蛰二月节后，气渐和暖，向夏大热，至秋便凉。 从霜降以后，至春分以前，凡有触冒霜露，体中寒即病者，谓之伤寒也。 九月十月寒气尚微，为病则轻；十一月十二月寒冽已严，为病则重；正月二月寒渐将解，为病亦轻。此以冬时不调，适有伤寒之人即为病也。其冬有非节之暖者，名曰冬温。 冬温之毒，与伤寒大异，冬温复有先后，更相重沓，亦有轻重，为治不同，证如后章。 从立春节后，其中无暴大寒，又不冰雪；而有人壮热为病者，此属春时阳气，发其冬时伏寒，变为温病。 从春分以后，至秋分节前，天有暴寒者，皆为时行寒疫也。三月四月或有暴寒，其时阳气尚弱，为寒所折，病热犹轻；五月六月阳气已盛，为寒所折，病热则重；七月八月，阳气已衰，为寒所折，病热亦微。其病与温相似，但治有殊耳。 十五日得一气，于四时之中，一时有六气，四六名为二十四气。然气候亦有应至仍不至，或有未应至而至者，或有至而太过者，皆成病气也。但天地动静，阴阳鼓击者，各正一气耳。是以彼春之暖，为夏之暑；彼秋之忿，为冬之怒。是故冬至之后，一阳爻升，一阴爻降也。 夏至之后，一阳气下，一阴气上也。斯则冬夏二至，阴阳合也；春秋二分，阴阳离也。阴阳交易，人变病焉。此君子春夏养阳，秋冬养阴，顺天地之刚柔也。小人触冒，必婴暴疹。须知毒烈之气，留在何经，必发何病，详而取之。是以春伤于风，夏必飧泄；夏伤于暑，秋必病疟；秋伤于湿，冬必咳嗽； 冬伤于寒，春必病温。此必然之道，可不审明之。伤寒之病，逐日浅深，以施方治。 今世人伤寒，或始不早治，或治不对病，或日数久淹，困乃告医。医人又不依次第而治之，则不中病。皆宜临时消息制方，无不效也。 4、又土地温凉，高下不同；物性刚柔，餐［注：桂本餐字为飧，似误］居亦异。是故黄帝兴四方之问，岐伯举四治之能，以训后贤，开其未悟。临病之工，宜须两审也。 5、凡伤于寒，传经则为病热，热虽甚，不死。若两感于寒而病者，多死。尺寸俱浮者，太阳受病也，当一二日发。以其脉上连风府，故头项痛，腰脊强。 6、尺寸俱长者，阳明受病也，当二三日发。以其脉侠鼻、络于目，故身热、汗出、目疼、鼻干、不得卧。 7、尺寸俱弦者，少阳受病也，当三四日发。以其脉循胁络于耳，故胸胁痛而耳聋。此三经受病，未入于腑者，皆可汗而已。 8、尺寸俱沉濡者，太阴受病也，当四五日发。以其脉布胃中，络于嗌，故腹满而嗌干。 9、尺寸俱沉细者，少阴受病也，当五六日发。以其脉贯肾，络于肺，系舌本，故口燥舌干而渴。 10、尺寸俱弦微者，厥阴受病也，当六七日发。以其脉循阴器、络于肝，故烦满而囊缩。此三经受病，己入于腑者，皆可下而已。 11、伤寒传经在太阳，脉浮而急数，发热，无汗，烦躁，宜$f{麻黄汤}。 12、传阳明，脉大而数，发热，汗出，口渴舌燥，宜$f{白虎汤}，不差与$n{承气汤}--$f{大承气汤}--$f{小承气汤}--$f{调胃承气汤}。 13、传少阳，脉弦而急，口苦，咽干，头晕，目眩，往来寒热，热多寒少，宜$f{小柴胡汤}，不差与$f{大柴胡汤}。 14、传太阴，脉濡而大，发热，下利，口渴，腹中急痛，宜$f{茯苓白术厚朴石膏黄芩甘草汤}。 15、传少阴，脉沉细而数，手足时厥时热，咽中痛，小便难，宜$f{附子细辛黄连黄芩汤}。 16、传厥阴，脉沉弦而急，发热时悚，心烦呕逆，宜$f{桂枝当归汤}，吐蛔者，宜$f{乌梅丸}。 17、以上皆传经脉证并治之正法也。若入腑及脏为传经变病，治列后条。 18、若两感于寒者，一日太阳受之，即与少阴俱病，则头痛、口干、烦满而渴，脉时浮时沉，时数时细，$f{大青龙汤加附子}主之。 19、二日阳明受之，即与太阴俱病，则腹满身热、不欲食、谵语，脉时高时卑，时强时弱，宜$f{大黄石膏茯苓白术枳实甘草汤} 20、三日少阳受之，即与厥阴俱病，则耳聋，囊缩而厥，水浆不入，脉乍弦乍急，乍细乍散，宜$f{当归附子汤}主之。 21、以上皆传经变病，多不可治，不知人者，六日死。若三阴三阳、五脏六腑皆受病，则荣卫不行，脏腑不通而死矣。所谓两感于寒不免于死者，其在斯乎!其在斯乎! 22、若不加异气者，至七日太阳病衰，头痛少愈也；八日阳明病衰，身热少歇也；九日少阳病衰，耳聋微闻也；十日太阴病衰，腹减如故，则思饮食；十一日少阴病衰，渴止舌干，已而嚏；十二日厥阴病衰，囊纵，少腹微下，大气皆去，病人精神爽慧也。若过十三日以上不间，尺寸陷者，大危。若更感异气，变为他病者，当依坏病证法而治之。若脉阴阳俱盛，重感于寒者，变成温疟。阳脉浮滑，阴脉濡弱，更伤于风者，变为风温。阳脉洪数，阴脉实大，更遇温热者，变为温毒。温毒，病之最重者也。阳脉濡弱，阴脉弦紧，更遇温气者，变为温疫。以此冬伤于寒，发为温病，脉之变证，方治如说。 23、凡人有疾，不时即治，隐忍冀差，以成痼疾。小儿女子，益以滋甚。时气不和，便当早言，寻其邪由，及在腠理，以时治之，罕有不愈者。患人忍之，数日乃说，邪气入脏，则难为制。 24、凡作汤药，不可避晨夕，觉病须臾，即宜便治，不等早晚，则易愈矣。如或差迟，病即传变，虽欲除治，必难为力。服药不如方法，纵意违师，不须治之。 25、凡伤寒之病，多从风寒得之。始表中风寒，入里则不消矣。未有温覆当而不消散者。不在证治，拟欲攻之，犹当先解表，乃可下之。若表未解，而内不消，必非大满，犹有寒热，则不可下。若表已解，而内不消，大满大实，腹坚，中有燥屎，自可除下之。虽四五日，数下之，不能为祸也。若不宜下，而便攻之，则内虚热入，协热遂利，烦躁诸变，不可胜数，轻者困笃，重者必死矣。 26、夫阳盛阴虚，汗之则死，下之则愈；阳虚阴盛，汗之则愈，下之则死。如是，则神丹安可以误发，甘遂何可以妄攻？虚盛之治，相背千里，吉凶之机，应若影响，岂容易哉!况桂枝下咽，阳盛即毙；承气入胃，阴盛以亡，死生之要，在乎须臾，视身之尽，不暇计日。此阴阳虚实之交错，其候至微；发汗吐下之相反，其祸至速，而医术浅狭，懵然不知病源，为治乃误，使病者殒殁，自谓其分，至令冤魂塞于冥路，死尸盈于旷野，仁者鉴此，岂不痛欤！ 27、凡两感病俱作，治有先后，发表攻里，本自不同，而执迷用意者，乃云神丹甘遂合而饮之，且解其表，又除其里，言巧似是，其理实违。夫智者之举错也，常审以慎；愚者之动作也，必果而速。安危之变，岂可诡哉！世上之士，但务彼翕习之荣，而莫见此倾危之败，惟明者居然，能护其本，近取诸身，夫何远焉。 28、凡发汗，温暖汤药，其方虽言日三服，若病剧不解，当促其间，可半日中尽三服。若与病相阻，即使有所觉，病重病者一日一夜，当晬时观之，如服一剂，病证犹在，故当复作本汤服之。至有不能汗出，服三剂乃解；若汗不出者，死病也。 29、凡得时气病，至五六日，而渴欲饮水，饮不能多，不当与也，何者？以腹中热尚少，不能消之，便更与人作病也。至七八日，大渴欲饮水者，犹当依证而与之。与之时常令不足，勿极意也。言能饮一斗，与五升。若饮而腹满，小便不利，若喘若哕。不可与之也。忽然大汗出，是为自愈也。 30、凡得病反能饮水，此为欲愈之病。其不晓病者，但闻病饮水者自愈，小渴者乃强与饮之，因成其祸，不可复数也。 31、凡得病厥，脉动数，服汤更迟；脉浮大减小；初躁后静，此皆愈证也。 32、凡治温病，可刺五十九穴。又身之穴，三百六十有五，其三十穴灸之有害；七十九穴刺之为灾，并中髓也。 33、脉四损，三日死。平人一息，病人脉一至，名曰四损。脉五损，一日死。平人二息，病人脉一至，名曰五损。脉六损，一时死。平人三息，病人脉一至，名曰六损。 34、四损，经气绝；五损，腑气绝；六损，脏气绝。真气不行于经曰经气绝；不行于腑，曰腑气绝；不行于脏，曰脏气绝；经气绝，则四肢不举；腑气绝，则不省人事；脏气绝，则一身尽冷。 35、脉盛身寒，得之伤寒；脉虚身热，得之伤暑。脉阴阳俱盛，大汗出，下之不解者死。脉阴阳俱虚，热不止者死。脉至乍数乍疏者死。脉至如转索，按之不易者其日死。谵言妄语，身微热，脉浮大，手足温者生。逆冷，脉沉细者，不过一日死矣。此以前是伤寒热病证候也。 36、脉濡而弱，弱反在关，濡反在巅，微反在上，涩反在下。微则阳气不足，涩则无血。阳气反微，中风汗出而反躁烦。涩则无血，厥而且寒。阳厥发汗，躁不得眠。阳微则不可下，下之则心下痞鞕。 37、动气在右，不可发汗，发汗则衄而渴，心苦烦，饮水即吐。 38、动气在左，不可发汗，发汗则头眩，汗不止，则筋惕肉〖目闰〗。 39、动气在上，不可发汗，发汗则气上冲止于心下。 40、动气在下，不可发汗，发汗则无汗可发，心中大烦，骨节疼痛，目眩恶寒，食则吐谷，气不得前。 41、咽中闭塞，不可发汗，发汗则吐血，气欲欲绝，手足厥冷，欲得蜷卧，不能自温。 42、诸脉得数动微弱者，不可发汗，发汗则大便难，腹中干，胃燥而烦，其形相象，根本异源。 43、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，不可发汗，发汗则寒栗，不能自还。咳而发汗，其咳必剧，数吐涎沫，咽中必干，小便不利，心中饥烦，晬时而发，其形似疟，有寒无热，虚而寒栗，蜷而苦满，腹中复坚，命将难全。 44、厥逆脉紧，不可发汗，发汗声乱、咽嘶、舌萎、声不得前。 45、诸逆发汗，病微者难差，剧者必死。 46、凡发汗，欲令遍身漐漐微似汗，不可令如水流漓。若病不解，当重发汗；若汗多者，不得重发汗，亡阳故也。。 47、凡服汤发汗，中病便止，不必尽剂。 48、凡用吐汤，中病便止，不必尽剂。。 49、诸四逆厥者，不可吐之；虚家亦然。 50、凡病胸上诸实，胸中郁郁而痛，不能食，欲使人按之，而反有涎唾，下利十余行，其脉反涩，寸口脉微滑，此可吐之，吐之利则止。 51、宿食在上脘者，当吐之。 52、动气在右，不可下之，下之则津液内竭，咽燥、鼻干、头眩、心悸也。 53、动气在左，不可下之。下之则腹内拘急，食饮不下，动气更剧。虽有身热，卧则欲蜷。 54、动气在上，不可下之。下之则掌中热烦，身上浮冷，热汗自泄，欲得水自灌。 55、动气在下，不可下之。下之则腹胀满，卒起头眩，食则下利清谷，心下痞。 56、咽中闭寒，不可下之。下之则上轻下重，水浆不下，卧则欲蜷，身急痛，下利日数十行。 57、诸外实者，不可下之。下之则发微热，若亡脉厥者，当脐握热。 58、诸虚者，不可下之。下之则大渴，求水者易愈，恶水者剧。 59、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，虚者不可下也。微弦为咳，咳则吐涎，下之则咳止，而利因不休，利不休则胸中如虫啮，粥入则出，小便不利，两胁拘急，喘息为难，颈背相引，臂则不仁，极寒反汗出，身冷若冰，眼睛不慧，语言不休，而谷气多入，此为除中，口虽欲言，舌不得前。 60、脉濡而紧，濡则卫气微，紧则荣中寒。阳微卫中风，发热而恶寒；荣紧胃气冷，微呕心内烦。医谓有大热，解肌而发汗，亡阳虚烦躁，心下苦痞坚。表里俱虚竭，卒起而头眩。客热在皮肤，怅怏不得眠。不知胃气冷，紧寒在关元。技巧无所施，汲水灌其身。客热应时罢，栗栗而振寒。重被而复之，汗出而冒巅。体惕而又振，小便为微难。寒气因水发，清谷不容闲。呕变反肠出，颠倒不得安。手足为微逆，身冷而内烦。迟欲从后救，安可复追还。 61、脉浮而紧，浮则为风，紧则为寒；风则伤卫，寒则伤荣；荣卫俱病，骨节烦疼；当发其汗，而不可下也。。 62、脉浮而大，心下反鞕，有热，属脏者，攻之，不令发汗；属腑者，不令溲数。溲数则大便鞕，汗多则越甚，脉迟者，尚未可攻也。。 63、伤寒，脉阴阳俱紧，恶寒发热，则脉欲厥。厥者，脉初来大，渐渐小，更来渐大，是其候也。如此者恶寒，甚者，翕翕汗出，喉中痛；若热多者，目赤脉多，睛不慧，医复发之，咽中则伤；若复下之，则两目闭，寒多便清谷，热多便脓血；若熏之，则身发黄；若熨之，则咽燥。若小便利者，可救之；小便难者，危殆也。 64、伤寒发热，口中勃勃气出，头痛，目黄，衄不可制，阴阳俱虚，贪水者必呕，恶水者厥。若下之，则咽中生疮；假令手足温者，必下重便脓血。头痛目黄者，下之则目闭。贪水者，下之则脉厥，其声嘤嘤，咽喉塞，汗之则战栗；恶水者，下之则里冷，不嗜食，大便完谷出，汗之则口中伤，舌上白胎，烦躁，脉反数，不大便，六七日后必便血，小便不利也。 65、凡服下汤，得利便止，不必尽剂。此以前是汗吐下三法之大要也。若能于此例之外，更神而明之，斯道其庶几乎？', '2024-12-06T07:23:24.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1a2qOGIxrHw', 1, '{"title":"杂病例第五","description":"<p>1、问曰：上工治未病，何也？</p>\n<p> </p>\n<p>      师曰：夫治未病者，见肝之病，知肝传脾，当先实脾，四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。夫肝之病，补用酸，助用焦苦，益用甘味之药调之。酸入肝，焦苦入心，甘入脾。脾能伤肾，肾气微弱，则水不行；水不行，则心火气盛，心火气盛则伤肺；肺被伤，则金气不行；金气不行，则肝气盛，肝必自愈。此治肝补脾之要妙也。肝虚则用此法，实则不可用之。经曰：勿虚虚，勿实实，补不足，损有余，是其义也。余脏准此。</p><p>2、夫人禀五常，因风气而生长，风气虽能生万物，亦能害万物，如水能浮舟，亦能覆舟。若五脏元真通畅，人即安和。客气邪风，中人多死。千般疢难，不越三条；</p>\n<p></p>\n<p>       一者，经络受邪，入于脏腑，为内所因也；</p>\n<p>      二者，四肢九窍，血脉相传，壅塞不通，为外皮肤所中也；</p>\n<p>      三者，房室、金刃、虫兽所伤。以此详之，病由都尽。若人能养慎，不令邪风干杵经络，适中经络，未流传脏腑，即医治之，四肢才觉重滞，即导引、吐纳、针灸、膏摩，勿令九窍闭塞；更能无犯王法、禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遗形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处，为血气所注；理者，是皮肤脏腑之纹理也。</p><p>3、问曰：病人有气色见于面部，愿闻其说。</p>\n<p></p>\n<p>      师曰：鼻头色青，腹中痛，苦冷者死。鼻头色微黑者，有水气；色黄者，胸上有寒；色白者，亡血也。设微赤非时者死。其目正圆者痉，不治。又色青为痛，色黑为劳，色赤为风，色黄者便难，色鲜明者有留饮。</p><p>4、师曰：语声寂寂然喜惊呼者，骨节间病；语声喑喑然不彻者，心膈间病；语声啾啾然细而长者，头中病。</p><p>5、师曰：息摇肩者，心中坚，息引胸中上气者，咳；息张口短气者，肺痿唾沫。</p><p>6、师曰：吸而微数者，其病在中焦，实也，当下之即愈，虚者不治。在上焦者，其吸促，在下焦者，其吸远，此皆难治。呼吸动摇振振者，不可治也。</p><p>7、师曰：寸口脉动者，因其旺时而动，假令肝旺色青，四时各随其色。肝色青而反白，非其时也，色脉非时，法皆当病。</p><p>8、问曰：有未至而至，有至而不至，有至而不去，有至而太过，何谓也？师曰：冬至之后，甲子夜半少阳起，少阳之时，阳始生，天得温和。以未得甲子，天因温和，此末至而至也；以得甲子，而天犹未温和，此为至而不至也；以得甲子，而天大寒不解，此为至而不去也；以得甲子，而天温如盛夏五六月时，此为至而太过也。</p><p>9、问曰：经云：“厥阳独行”，何谓也？</p>\n<p></p>\n<p>     师曰：此为有阳无阴，故称厥阳。</p><p>10、问曰：寸脉沉大而滑，沉则为实，滑则为气，实气相搏，血气入脏即死，入腑即愈，此为卒厥，何谓也？</p>\n<p></p>\n<p>        师曰：唇口青，身冷，为入藏，即死；身和，自汗出，为入腑，即愈。</p><p>11、问曰：脉脱，入藏即死，入府即愈，何谓也？</p>\n<p></p>\n<p>        师曰：非为一病，百病皆然。譬如浸淫疮，从口流向四肢者可治，从四肢流来入口者不可治；病在外者可治，入里者即死。</p><p>12、问曰：阳病十八何谓也？师曰：头项痛腰脊臂脚掣痛。阴病十八，何谓也？</p>\n<p></p>\n<p>        师曰：咳上气喘哕咽痛肠鸣胀满心痛拘急。脏病三十六，腑病三十六，合为一百八病；此外五劳、七伤、六极、妇人三十六病，不在其中。清邪居上，浊邪居下，大邪中表，小邪中里，谷饪之邪，从口入者，宿食也。</p><p>13、问曰：病有急当救里救表者，何谓也？</p>\n<p></p>\n<p>       师曰：病，医下之，续得下利清谷不止，身体疼痛者，急当救里；后身疼痛，清便自调者，急当救表也。</p><p>14、夫病痼疾加以卒病，当先治其卒病，后乃治其痼疾也。</p><p>15、师曰：五藏病各有所得者愈，五藏病各有所恶，各随其所不喜为病。如病者素不喜食，而反暴思之，必发热也。</p><p>16、夫病在诸脏，欲攻，当随其所得而攻之，如渴者，与猪苓汤。余仿此。</p><p>17、夫病者手足寒，上气脚缩，此六腑之气绝于外也。下利不禁，手足不仁者，此五脏之气绝于内也。内外气绝者，死不治。</p><p>18、师曰：热在上焦者，因咳为肺痿；热在中焦者，为腹坚；热在下焦者，则尿血，或为淋秘不通。大肠有寒者，多鹜溏；有热者，便肠垢。小肠有寒者，其人下重便脓血；有热者，必痔。</p><p>19、问曰：三焦竭，何谓也？师曰：上焦受中焦之气，中焦未和，不能消谷，故上焦竭者，必善噫；下焦承中焦之气，中气未和，谷气不行，故下焦竭者，必遗溺失便。</p><p>20、问曰：病有积、有聚、有谷气，何谓也？</p>\n<p></p>\n<p>     师曰：积者，藏病也，终不移处；聚者，腑病也，发作有时，展转移痛，谷气者，胁下痛，按之则愈，愈而复发，为馨气。</p>\n<p></p>\n<p>     诸积之脉，沉细附骨在寸口，积在胸中；</p>\n<p></p>\n<p>     微出寸口，积在喉中；</p>\n<p>     在关者，积在脐旁；</p>\n<p>     上关上，积在心下；</p>\n<p>     微出下关，积在少腹。</p>\n<p>     在尺中，积在气冲；</p>\n<p>     脉出左，积在左；</p>\n<p>     脉出右，积在右；</p>\n<p>     脉左右俱出，积在中央；各以其部处之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010007,"no":7}}', '2024-12-06T07:23:39.000Z', '2024-12-06T07:23:39.000Z', '2024-12-06T07:23:39.000Z', '1、问曰：上工治未病，何也？ 师曰：夫治未病者，见肝之病，知肝传脾，当先实脾，四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。夫肝之病，补用酸，助用焦苦，益用甘味之药调之。酸入肝，焦苦入心，甘入脾。脾能伤肾，肾气微弱，则水不行；水不行，则心火气盛，心火气盛则伤肺；肺被伤，则金气不行；金气不行，则肝气盛，肝必自愈。此治肝补脾之要妙也。肝虚则用此法，实则不可用之。经曰：勿虚虚，勿实实，补不足，损有余，是其义也。余脏准此。 2、夫人禀五常，因风气而生长，风气虽能生万物，亦能害万物，如水能浮舟，亦能覆舟。若五脏元真通畅，人即安和。客气邪风，中人多死。千般疢难，不越三条； 一者，经络受邪，入于脏腑，为内所因也； 二者，四肢九窍，血脉相传，壅塞不通，为外皮肤所中也； 三者，房室、金刃、虫兽所伤。以此详之，病由都尽。若人能养慎，不令邪风干杵经络，适中经络，未流传脏腑，即医治之，四肢才觉重滞，即导引、吐纳、针灸、膏摩，勿令九窍闭塞；更能无犯王法、禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遗形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处，为血气所注；理者，是皮肤脏腑之纹理也。 3、问曰：病人有气色见于面部，愿闻其说。 师曰：鼻头色青，腹中痛，苦冷者死。鼻头色微黑者，有水气；色黄者，胸上有寒；色白者，亡血也。设微赤非时者死。其目正圆者痉，不治。又色青为痛，色黑为劳，色赤为风，色黄者便难，色鲜明者有留饮。 4、师曰：语声寂寂然喜惊呼者，骨节间病；语声喑喑然不彻者，心膈间病；语声啾啾然细而长者，头中病。 5、师曰：息摇肩者，心中坚，息引胸中上气者，咳；息张口短气者，肺痿唾沫。 6、师曰：吸而微数者，其病在中焦，实也，当下之即愈，虚者不治。在上焦者，其吸促，在下焦者，其吸远，此皆难治。呼吸动摇振振者，不可治也。 7、师曰：寸口脉动者，因其旺时而动，假令肝旺色青，四时各随其色。肝色青而反白，非其时也，色脉非时，法皆当病。 8、问曰：有未至而至，有至而不至，有至而不去，有至而太过，何谓也？师曰：冬至之后，甲子夜半少阳起，少阳之时，阳始生，天得温和。以未得甲子，天因温和，此末至而至也；以得甲子，而天犹未温和，此为至而不至也；以得甲子，而天大寒不解，此为至而不去也；以得甲子，而天温如盛夏五六月时，此为至而太过也。 9、问曰：经云：“厥阳独行”，何谓也？ 师曰：此为有阳无阴，故称厥阳。 10、问曰：寸脉沉大而滑，沉则为实，滑则为气，实气相搏，血气入脏即死，入腑即愈，此为卒厥，何谓也？ 师曰：唇口青，身冷，为入藏，即死；身和，自汗出，为入腑，即愈。 11、问曰：脉脱，入藏即死，入府即愈，何谓也？ 师曰：非为一病，百病皆然。譬如浸淫疮，从口流向四肢者可治，从四肢流来入口者不可治；病在外者可治，入里者即死。 12、问曰：阳病十八何谓也？师曰：头项痛腰脊臂脚掣痛。阴病十八，何谓也？ 师曰：咳上气喘哕咽痛肠鸣胀满心痛拘急。脏病三十六，腑病三十六，合为一百八病；此外五劳、七伤、六极、妇人三十六病，不在其中。清邪居上，浊邪居下，大邪中表，小邪中里，谷饪之邪，从口入者，宿食也。 13、问曰：病有急当救里救表者，何谓也？ 师曰：病，医下之，续得下利清谷不止，身体疼痛者，急当救里；后身疼痛，清便自调者，急当救表也。 14、夫病痼疾加以卒病，当先治其卒病，后乃治其痼疾也。 15、师曰：五藏病各有所得者愈，五藏病各有所恶，各随其所不喜为病。如病者素不喜食，而反暴思之，必发热也。 16、夫病在诸脏，欲攻，当随其所得而攻之，如渴者，与猪苓汤。余仿此。 17、夫病者手足寒，上气脚缩，此六腑之气绝于外也。下利不禁，手足不仁者，此五脏之气绝于内也。内外气绝者，死不治。 18、师曰：热在上焦者，因咳为肺痿；热在中焦者，为腹坚；热在下焦者，则尿血，或为淋秘不通。大肠有寒者，多鹜溏；有热者，便肠垢。小肠有寒者，其人下重便脓血；有热者，必痔。 19、问曰：三焦竭，何谓也？师曰：上焦受中焦之气，中焦未和，不能消谷，故上焦竭者，必善噫；下焦承中焦之气，中气未和，谷气不行，故下焦竭者，必遗溺失便。 20、问曰：病有积、有聚、有谷气，何谓也？ 师曰：积者，藏病也，终不移处；聚者，腑病也，发作有时，展转移痛，谷气者，胁下痛，按之则愈，愈而复发，为馨气。 诸积之脉，沉细附骨在寸口，积在胸中； 微出寸口，积在喉中； 在关者，积在脐旁； 上关上，积在心下； 微出下关，积在少腹。 在尺中，积在气冲； 脉出左，积在左； 脉出右，积在右； 脉左右俱出，积在中央；各以其部处之。', '2024-12-06T07:23:39.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GyqBRPJNca3', 1, '{"title":"温病脉证并治第六","description":"<p>1、温病有三：曰春温、曰秋温、曰冬温。此皆发于伏气，夏则病暑，而不病温。冬伤于寒，其气伏于少阴，至春乃发为温病，名曰春温。</p><p>2、夏伤于湿，其气伏于太阴，至秋燥乃大行，发为温病，名曰秋温。</p><p>3、气不当至而至，初冬乃大寒，燥以内收，其气伏于厥阴，冬至后，天应寒而反温，发为温病，名曰冬温。</p><p>4、春秋病温，此其常，冬时病温，此其变。冬时应寒而反大温，此非其时而蓄其气，及时不病，至春乃发，名曰大温。此由冬不藏精，气失其正，春时阳气外发，二气相搏为病则重，医又不晓病源为治，乃误尸气流传，遂以成疫。</p><p>5、病春温，其气在上，头痛，咽干，发热，目眩，甚则谵语，脉弦而急，$f{小柴胡加黄连牡丹汤}主之。</p><p>6、病秋温，其气在中，发热，口渴，腹中热痛，下利便脓血，脉大而短涩，$f{地黄知母黄连阿胶汤}主之；不便脓血者，$f{白虎汤}主之。</p><p>7、病冬温，其气在下，发热，腹痛引少腹，夜半咽中干痛，脉沉实，时而大数，$f{石膏黄连黄芩甘草汤}主之；不大便六七日者，$f{大黄黄芩地黄牡丹汤}主之。</p><p>8、病温，头痛，面赤，发热，手足拘急，脉浮弦而数，名曰风温，$f{黄连黄芩栀子牡丹芍药汤}主之。</p><p>9、病温，其人素有湿，发热唇焦，下利，腹中热痛，脉大而数，名曰湿温，$f{猪苓加黄连牡丹汤}主之。</p><p>10、病温，舌赤，咽干，心中烦热，脉急数，上寸口者，温邪干心也，$f{黄连黄芩阿胶甘草汤}主之。</p><p>11、病温，口渴，咳嗽，衄不止，脉浮而数大，此温邪乘肺也，$f{黄芩石膏杏子甘草汤}主之。</p><p>12、病温，发热，腰以下有水气，甚煮取三升，少腹热痛，小便赤数，脉急而数下尺中者，此温邪移肾也，$f{地黄黄柏秦皮茯苓泽泻汤}主之。</p><p>13、病大温，发热头晕，目眩，齿枯，唇焦，谵语，不省人事，面色乍青乍赤，脉急大而数者，$f{大黄香蒲汤}主之；若喉闭难下咽者，针少商令出血；若脉乍疏乍数，目内陷者，死。</p><p>14、温病，下之大便溏，当自愈；若下之利不止者，必腹满，宜$f{茯苓白术甘草汤}主之。</p><p>15、风温者，因其人素有热，更伤于风，而为病也。脉浮弦而数，若头不痛者，$f{桂枝去桂加黄芩牡丹汤}主之。若伏气病温，误发其汗，则大热烦冤，唇焦，目赤，或衄，或吐，耳聋，脉大而数者，宜$f{白虎汤}；大实者，宜$n{承气}辈；若至十余日则入于里，宜$f{黄连阿胶汤}。何以知其入里？以脉沉而数，心烦不卧，故知也。</p><p>16、病温，治不得法，留久移于三焦，其在上焦，则舌蹇，神昏，宜$f{栀子汤}；其在中焦，则腹痛而利，利后腹痛，唇口干燥，宜$f{白虎加地黄汤}；其在下焦，从腰以下热，齿黑，咽干，宜$f{百合地黄牡丹皮半夏茯苓汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010008,"no":8}}', '2024-12-06T07:24:17.000Z', '2024-12-06T07:24:17.000Z', '2024-12-06T07:24:17.000Z', '1、温病有三：曰春温、曰秋温、曰冬温。此皆发于伏气，夏则病暑，而不病温。冬伤于寒，其气伏于少阴，至春乃发为温病，名曰春温。 2、夏伤于湿，其气伏于太阴，至秋燥乃大行，发为温病，名曰秋温。 3、气不当至而至，初冬乃大寒，燥以内收，其气伏于厥阴，冬至后，天应寒而反温，发为温病，名曰冬温。 4、春秋病温，此其常，冬时病温，此其变。冬时应寒而反大温，此非其时而蓄其气，及时不病，至春乃发，名曰大温。此由冬不藏精，气失其正，春时阳气外发，二气相搏为病则重，医又不晓病源为治，乃误尸气流传，遂以成疫。 5、病春温，其气在上，头痛，咽干，发热，目眩，甚则谵语，脉弦而急，$f{小柴胡加黄连牡丹汤}主之。 6、病秋温，其气在中，发热，口渴，腹中热痛，下利便脓血，脉大而短涩，$f{地黄知母黄连阿胶汤}主之；不便脓血者，$f{白虎汤}主之。 7、病冬温，其气在下，发热，腹痛引少腹，夜半咽中干痛，脉沉实，时而大数，$f{石膏黄连黄芩甘草汤}主之；不大便六七日者，$f{大黄黄芩地黄牡丹汤}主之。 8、病温，头痛，面赤，发热，手足拘急，脉浮弦而数，名曰风温，$f{黄连黄芩栀子牡丹芍药汤}主之。 9、病温，其人素有湿，发热唇焦，下利，腹中热痛，脉大而数，名曰湿温，$f{猪苓加黄连牡丹汤}主之。 10、病温，舌赤，咽干，心中烦热，脉急数，上寸口者，温邪干心也，$f{黄连黄芩阿胶甘草汤}主之。 11、病温，口渴，咳嗽，衄不止，脉浮而数大，此温邪乘肺也，$f{黄芩石膏杏子甘草汤}主之。 12、病温，发热，腰以下有水气，甚煮取三升，少腹热痛，小便赤数，脉急而数下尺中者，此温邪移肾也，$f{地黄黄柏秦皮茯苓泽泻汤}主之。 13、病大温，发热头晕，目眩，齿枯，唇焦，谵语，不省人事，面色乍青乍赤，脉急大而数者，$f{大黄香蒲汤}主之；若喉闭难下咽者，针少商令出血；若脉乍疏乍数，目内陷者，死。 14、温病，下之大便溏，当自愈；若下之利不止者，必腹满，宜$f{茯苓白术甘草汤}主之。 15、风温者，因其人素有热，更伤于风，而为病也。脉浮弦而数，若头不痛者，$f{桂枝去桂加黄芩牡丹汤}主之。若伏气病温，误发其汗，则大热烦冤，唇焦，目赤，或衄，或吐，耳聋，脉大而数者，宜$f{白虎汤}；大实者，宜$n{承气}辈；若至十余日则入于里，宜$f{黄连阿胶汤}。何以知其入里？以脉沉而数，心烦不卧，故知也。 16、病温，治不得法，留久移于三焦，其在上焦，则舌蹇，神昏，宜$f{栀子汤}；其在中焦，则腹痛而利，利后腹痛，唇口干燥，宜$f{白虎加地黄汤}；其在下焦，从腰以下热，齿黑，咽干，宜$f{百合地黄牡丹皮半夏茯苓汤}。', '2024-12-06T07:24:17.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V3oXNm4Y5uu', 1, '{"title":"伤暑脉证并治第七","description":"<p>1、伤暑肺先受之，肺为气府，暑伤元气，寸口脉弱，口渴，汗出，神昏，气短，$f{竹叶石膏汤}主之。</p><p>2、伤暑，发热，汗出，口渴，脉浮而大，名曰中暍，$f{白虎加人参黄连阿胶汤}主之。</p><p>3、伤暑，汗出已，发热，烦躁，声嘶，脉反浮数者，此为肺液伤，$f{百合地黄加牡蛎汤}主之。</p><p>4、伤暑，心下有水气，汗出，咳嗽，渴欲饮水，水入则吐，脉弱而滑，$f{栝蒌茯苓汤}主之。</p><p>5、伤暑，发热，无汗，水行皮中故也，脉必浮而滑，先以热水灌之，令汗出，后以$f{竹茹半夏汤}与之。</p><p>6、太阳中热者，暍是也。其人汗出，恶寒，身热而渴，$f{白虎加人参汤}主之。</p><p>7、太阳中暍，身热，疼重，而脉微弱者，以夏月伤冷水，水行皮中所致也，$f{猪苓加人参汤}主之；一物$f{瓜蒂汤}亦主之。</p><p>8、凡病暑者，当汗出，不汗出者，必发热，发热者，必不汗出也，不可发汗，发汗则发热，烦躁，失声，此为肺液枯，息高气贲者，不治。</p><p>9、伤暑，夜卧不安，烦躁，谵语，舌赤，脉数，此为暑邪干心也，$f{黄连半夏石膏甘草汤}主之。</p><p>10、太阳中暍，发热，恶寒，身重疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷；小有劳身即热；口开，前板齿燥；若发汗，则恶寒甚；加温针，则发热甚，数下之，则淋甚；$f{白虎加桂枝人参芍药汤}主之。</p><p>11、伤暑，脉弱，口渴，大汗出，头晕者，$f{人参石膏汤}主之。</p><p>12、伤暑者，头不痛，头痛者风也，头重者湿也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010009,"no":9}}', '2024-12-06T07:24:37.000Z', '2024-12-06T07:24:37.000Z', '2024-12-06T07:24:37.000Z', '1、伤暑肺先受之，肺为气府，暑伤元气，寸口脉弱，口渴，汗出，神昏，气短，$f{竹叶石膏汤}主之。 2、伤暑，发热，汗出，口渴，脉浮而大，名曰中暍，$f{白虎加人参黄连阿胶汤}主之。 3、伤暑，汗出已，发热，烦躁，声嘶，脉反浮数者，此为肺液伤，$f{百合地黄加牡蛎汤}主之。 4、伤暑，心下有水气，汗出，咳嗽，渴欲饮水，水入则吐，脉弱而滑，$f{栝蒌茯苓汤}主之。 5、伤暑，发热，无汗，水行皮中故也，脉必浮而滑，先以热水灌之，令汗出，后以$f{竹茹半夏汤}与之。 6、太阳中热者，暍是也。其人汗出，恶寒，身热而渴，$f{白虎加人参汤}主之。 7、太阳中暍，身热，疼重，而脉微弱者，以夏月伤冷水，水行皮中所致也，$f{猪苓加人参汤}主之；一物$f{瓜蒂汤}亦主之。 8、凡病暑者，当汗出，不汗出者，必发热，发热者，必不汗出也，不可发汗，发汗则发热，烦躁，失声，此为肺液枯，息高气贲者，不治。 9、伤暑，夜卧不安，烦躁，谵语，舌赤，脉数，此为暑邪干心也，$f{黄连半夏石膏甘草汤}主之。 10、太阳中暍，发热，恶寒，身重疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷；小有劳身即热；口开，前板齿燥；若发汗，则恶寒甚；加温针，则发热甚，数下之，则淋甚；$f{白虎加桂枝人参芍药汤}主之。 11、伤暑，脉弱，口渴，大汗出，头晕者，$f{人参石膏汤}主之。 12、伤暑者，头不痛，头痛者风也，头重者湿也。', '2024-12-06T07:24:37.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IME7cq10zI4', 1, '{"title":"热病脉证并治第八","description":"<p>1、热之为病，有外至，有内生。外至可移，内有定处，不循经序，舍于所合，与温相似，根本异源，传经化热，伏气变温，医多不晓，认为一体，如此杀人，莫可穷极。为子条记，传与后贤。</p><p>2、热病，面赤，口烂，心中痛，欲呕，脉洪而数，此热邪干心也，$f{黄连黄芩泻心汤}主之。</p><p>3、热病，身热，左胁痛，甚则狂言乱语，脉弦而数，此热邪乘肝也，$f{黄连黄芩半夏猪胆汁汤}主之。</p><p>4、热病，腹中痛，不可按，不能俯仰，大便难，脉数而大，此热邪乘脾也，$f{大黄厚朴甘草汤}主之。</p><p>5、热病，口渴，喘，嗽，痛引胸中，不得太息，脉短而数，此热邪乘肺也，$f{黄连石膏半夏甘草汤}主之。</p><p>6、热病，咽中干，腰痛，足热，脉沉而数，此热邪移肾也，$f{地黄黄柏黄连半夏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010010,"no":10}}', '2024-12-06T07:24:54.000Z', '2024-12-06T07:24:54.000Z', '2024-12-06T07:24:54.000Z', '1、热之为病，有外至，有内生。外至可移，内有定处，不循经序，舍于所合，与温相似，根本异源，传经化热，伏气变温，医多不晓，认为一体，如此杀人，莫可穷极。为子条记，传与后贤。 2、热病，面赤，口烂，心中痛，欲呕，脉洪而数，此热邪干心也，$f{黄连黄芩泻心汤}主之。 3、热病，身热，左胁痛，甚则狂言乱语，脉弦而数，此热邪乘肝也，$f{黄连黄芩半夏猪胆汁汤}主之。 4、热病，腹中痛，不可按，不能俯仰，大便难，脉数而大，此热邪乘脾也，$f{大黄厚朴甘草汤}主之。 5、热病，口渴，喘，嗽，痛引胸中，不得太息，脉短而数，此热邪乘肺也，$f{黄连石膏半夏甘草汤}主之。 6、热病，咽中干，腰痛，足热，脉沉而数，此热邪移肾也，$f{地黄黄柏黄连半夏汤}主之。', '2024-12-06T07:24:54.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mN0iZDj3yl7', 1, '{"title":"湿病脉证并治第九","description":"<p>1、湿气为病，内外上下，四处流行，随邪变化，各具病形，按法诊治，勿失纪纲。湿气在上，中于雾露，头痛，项强，两额疼痛，脉浮而涩者，$f{黄芪桂枝茯苓细辛汤}主之。</p><p>2、湿气在下，中于水冷，从腰以下重，两足肿，脉沉而涩者，$f{桂枝茯苓白术细辛汤}主之。</p><p>3、湿气在外，因风相搏，流于经络，骨节烦疼，卧不欲食，脉浮缓，按之涩，$f{桂枝汤}微发其汗，令风湿俱去；若恶寒，身体疼痛，四肢不仁，脉浮而细紧，此为寒气，并$f{桂枝麻黄各半汤}主之。</p><p>4、湿气在内，与脾相搏，发为中满；胃寒相将，变为泄泻。中满宜$f{白术茯苓厚朴汤}；泄泻宜$f{理中汤}；若上干肺，发为肺寒，宜$f{小青龙汤}；下移肾，发为淋漓，宜$f{五苓散}；流于肌肉，发为黄肿，宜$f{麻黄茯苓汤}；若流于经络，与热气相乘，则发痈脓；脾胃素寒，与湿久留，发为水饮，与燥相搏，发为痰饮，治属饮家。</p><p>5、太阳病，关节疼痛而烦，脉沉而细者，此名湿痹；湿痹之候，其人小便不利，大便反快，但当利其小便。</p><p>6、湿家之为病，一身尽疼，发热，身色如熏黄。</p><p>7、湿家，其人但头汗出，背强，欲得被覆向火，若下之早，则哕，胸满，小便不利，舌上滑苔者，以丹田有热，胸中有寒，渴欲得水，而不能饮，口燥烦也。</p><p>8、湿家下之，额上汗出，微喘，小便利者死；若下利不止者亦死。</p><p>9、问曰：风湿相搏，一身尽疼，法当汗出而解，值天阴雨不止，医云此可发汗，汗之病不愈者何也？</p>\n<p></p>\n<p>     师曰：发其汗，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，发其汗，但微微似欲汗出者，风湿俱去也。</p><p>10、湿家病，身上尽疼痛，发热，面黄而喘，头痛，鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故$f{鼻塞}，纳药鼻中，则愈。</p><p>11、湿家，身烦疼，可与$f{麻黄加术汤}发其汗为宜，慎不可以火攻之。</p><p>12、病者一身尽疼，发热，日晡所剧者，此名风湿。此病伤于汗出当风，或久伤取冷所致也，可与$f{麻黄杏仁薏苡甘草汤}。</p><p>13、风湿，脉浮，身重，汗出，恶风者，$f{防己黄芪汤}主之。</p><p>14、伤寒八九日，风湿相搏，不能自转侧，不呕，不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利者，$f{白术附子汤}主之。</p><p>15、风湿相搏，骨节疼烦，掣痛，不得屈伸，近之则痛剧，汗出，短气，小便不利，恶风，不欲去衣，或身微肿者，$f{甘草附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010011,"no":11}}', '2024-12-06T07:25:15.000Z', '2024-12-06T07:25:15.000Z', '2024-12-06T07:25:15.000Z', '1、湿气为病，内外上下，四处流行，随邪变化，各具病形，按法诊治，勿失纪纲。湿气在上，中于雾露，头痛，项强，两额疼痛，脉浮而涩者，$f{黄芪桂枝茯苓细辛汤}主之。 2、湿气在下，中于水冷，从腰以下重，两足肿，脉沉而涩者，$f{桂枝茯苓白术细辛汤}主之。 3、湿气在外，因风相搏，流于经络，骨节烦疼，卧不欲食，脉浮缓，按之涩，$f{桂枝汤}微发其汗，令风湿俱去；若恶寒，身体疼痛，四肢不仁，脉浮而细紧，此为寒气，并$f{桂枝麻黄各半汤}主之。 4、湿气在内，与脾相搏，发为中满；胃寒相将，变为泄泻。中满宜$f{白术茯苓厚朴汤}；泄泻宜$f{理中汤}；若上干肺，发为肺寒，宜$f{小青龙汤}；下移肾，发为淋漓，宜$f{五苓散}；流于肌肉，发为黄肿，宜$f{麻黄茯苓汤}；若流于经络，与热气相乘，则发痈脓；脾胃素寒，与湿久留，发为水饮，与燥相搏，发为痰饮，治属饮家。 5、太阳病，关节疼痛而烦，脉沉而细者，此名湿痹；湿痹之候，其人小便不利，大便反快，但当利其小便。 6、湿家之为病，一身尽疼，发热，身色如熏黄。 7、湿家，其人但头汗出，背强，欲得被覆向火，若下之早，则哕，胸满，小便不利，舌上滑苔者，以丹田有热，胸中有寒，渴欲得水，而不能饮，口燥烦也。 8、湿家下之，额上汗出，微喘，小便利者死；若下利不止者亦死。 9、问曰：风湿相搏，一身尽疼，法当汗出而解，值天阴雨不止，医云此可发汗，汗之病不愈者何也？ 师曰：发其汗，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，发其汗，但微微似欲汗出者，风湿俱去也。 10、湿家病，身上尽疼痛，发热，面黄而喘，头痛，鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故$f{鼻塞}，纳药鼻中，则愈。 11、湿家，身烦疼，可与$f{麻黄加术汤}发其汗为宜，慎不可以火攻之。 12、病者一身尽疼，发热，日晡所剧者，此名风湿。此病伤于汗出当风，或久伤取冷所致也，可与$f{麻黄杏仁薏苡甘草汤}。 13、风湿，脉浮，身重，汗出，恶风者，$f{防己黄芪汤}主之。 14、伤寒八九日，风湿相搏，不能自转侧，不呕，不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利者，$f{白术附子汤}主之。 15、风湿相搏，骨节疼烦，掣痛，不得屈伸，近之则痛剧，汗出，短气，小便不利，恶风，不欲去衣，或身微肿者，$f{甘草附子汤}主之。', '2024-12-06T07:25:15.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B72k8bHIXIB', 1, '{"title":"伤燥病脉证并治第十","description":"<p>1、伤燥，肺先受之，出则大肠受之，移传五脏，病各异形，分别诊治，消息脉经。</p><p>2、燥病，口渴，咽干，喘，咳，胸满痛甚则唾血，脉浮短而急，此燥邪干肺也，$f{竹叶石膏杏子甘草汤}主之；若移于大肠，则大便难，口渴，欲饮热，脉急大，在下者，$f{麻仁白蜜煎}主之。</p><p>3、燥病，口烂，气上逆，胸中痛，脉大而涩，此燥邪乘心也，$f{栀子连翘甘草栝蒌汤}主之。</p><p>4、燥病，目赤，困苦，咽干，胁下痛，脉弦而数，此燥邪乘肝也，$f{黄芩牡丹皮栝蒌半夏枳实汤}主之。</p><p>5、燥病，色黄，腹中痛不可按，大便难，脉数而滑，此燥邪乘脾也，$f{白虎汤}主之。</p><p>6、燥病，咽干，喉痛，少腹急痛，小便赤，脉沉而急，此燥邪移肾也，$f{地黄黄柏茯苓栝蒌汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010012,"no":12}}', '2024-12-06T07:25:35.000Z', '2024-12-06T07:25:35.000Z', '2024-12-06T07:25:35.000Z', '1、伤燥，肺先受之，出则大肠受之，移传五脏，病各异形，分别诊治，消息脉经。 2、燥病，口渴，咽干，喘，咳，胸满痛甚则唾血，脉浮短而急，此燥邪干肺也，$f{竹叶石膏杏子甘草汤}主之；若移于大肠，则大便难，口渴，欲饮热，脉急大，在下者，$f{麻仁白蜜煎}主之。 3、燥病，口烂，气上逆，胸中痛，脉大而涩，此燥邪乘心也，$f{栀子连翘甘草栝蒌汤}主之。 4、燥病，目赤，困苦，咽干，胁下痛，脉弦而数，此燥邪乘肝也，$f{黄芩牡丹皮栝蒌半夏枳实汤}主之。 5、燥病，色黄，腹中痛不可按，大便难，脉数而滑，此燥邪乘脾也，$f{白虎汤}主之。 6、燥病，咽干，喉痛，少腹急痛，小便赤，脉沉而急，此燥邪移肾也，$f{地黄黄柏茯苓栝蒌汤}主之。', '2024-12-06T07:25:35.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CdcX5CUj52l', 1, '{"title":"伤风病脉证并治第十一","description":"<p>1、风为百病之长，中于面，则下阳明，甚则入脾；中于项，则下太阳，甚则入肾；中于侧，则下少阳，甚则入肝；病变不一，慎毋失焉。</p><p>2、风病，头痛，多汗，恶风，腋下痛，不可转侧，脉浮弦而数，此风邪干肝也，$f{小柴胡汤}主之；若流于腑，则困苦，呕逆，腹胀，善太息，$f{柴胡枳实芍药甘草汤}主之。</p><p>3、风病，胸中痛，胁支满，膺背肩胛间痛，嗌干，善噫，咽肿，喉痹，脉浮洪而数，此风邪乘心也，$f{黄连黄芩麦冬桔梗甘草汤}主之。</p><p>4、风病，四肢懈惰，体重，不能胜衣，胁下痛引肩背，脉浮而弦涩，此风邪乘脾也，$f{桂枝去桂加茯苓白术汤}主之；若流于腑，则腹满而胀，不嗜食，枳实厚朴白术甘草汤主之。</p><p>5、风病，咳而喘息有音，甚则唾血，嗌干，肩背痛，脉浮弦而数，此风邪乘肺也，$f{桔梗甘草枳实芍药汤}主之；若流于大肠，则大便燥结，或下血，桔梗甘草枳实芍药加地黄牡丹汤主之。</p><p>6、风病，面目浮肿，脊痛不能正立，隐曲不利，甚则骨痿，脉沉而弦，此风邪乘肾也，$f{柴胡桂枝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010013,"no":13}}', '2024-12-06T07:26:00.000Z', '2024-12-06T07:26:00.000Z', '2024-12-06T07:26:00.000Z', '1、风为百病之长，中于面，则下阳明，甚则入脾；中于项，则下太阳，甚则入肾；中于侧，则下少阳，甚则入肝；病变不一，慎毋失焉。 2、风病，头痛，多汗，恶风，腋下痛，不可转侧，脉浮弦而数，此风邪干肝也，$f{小柴胡汤}主之；若流于腑，则困苦，呕逆，腹胀，善太息，$f{柴胡枳实芍药甘草汤}主之。 3、风病，胸中痛，胁支满，膺背肩胛间痛，嗌干，善噫，咽肿，喉痹，脉浮洪而数，此风邪乘心也，$f{黄连黄芩麦冬桔梗甘草汤}主之。 4、风病，四肢懈惰，体重，不能胜衣，胁下痛引肩背，脉浮而弦涩，此风邪乘脾也，$f{桂枝去桂加茯苓白术汤}主之；若流于腑，则腹满而胀，不嗜食，枳实厚朴白术甘草汤主之。 5、风病，咳而喘息有音，甚则唾血，嗌干，肩背痛，脉浮弦而数，此风邪乘肺也，$f{桔梗甘草枳实芍药汤}主之；若流于大肠，则大便燥结，或下血，桔梗甘草枳实芍药加地黄牡丹汤主之。 6、风病，面目浮肿，脊痛不能正立，隐曲不利，甚则骨痿，脉沉而弦，此风邪乘肾也，$f{柴胡桂枝汤}主之。', '2024-12-06T07:26:00.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M43hMFfNOo1', 1, '{"title":"寒病脉证并治第十二","description":"<p>1、寒之为病，肾先受之，其客于五脏之间，脉引而痛；若客于八虚之室，则恶血住留，积久不去，变而成着，可不慎焉！</p>\n<p></p>\n<p>    寒病，骨痛，阴痹，腹胀，腰痛，大便难，肩背颈项引痛，脉沉而迟，此寒邪干肾也，$f{桂枝加葛根汤}主之；其着也则两腘痛，$f{甘草干姜茯苓白术汤}主之。</p><p>2、寒病，两胁中痛，寒中行善掣节，逆则头痛，耳聋，脉弦而沉迟，此寒邪乘肝也，$f{小柴胡汤}主之；其着也，则两腋急痛，不能转侧，$f{柴胡黄芩芍药半夏甘草汤}主之。</p><p>3、寒病，胸胁支满，膺背肩胛间痛，甚则喜悲，时发眩，仆而不知人，此寒邪乘心也，$f{通脉四逆汤}主之；其着也，则肘外痛，臂不能伸，$f{甘草泻心汤}主之。</p><p>4、寒病，腹满肠鸣，食不化，飧泄，甚则足痿不收，脉迟而涩，此寒邪乘脾也，$f{理中汤}主之；其着也，则髀枢强痛，不能屈伸，$f{枳实白术茯苓甘草汤}主之。</p><p>5、寒病，喘，咳，少气，不能报息，口唾涎沫，耳聋，嗌干，此寒邪乘肺也，脉沉而迟者，$f{甘草干姜汤}主之；其着也，则肘内痛，转侧不便，$f{枳实橘皮桔梗半夏生姜甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010014,"no":14}}', '2024-12-06T07:26:28.000Z', '2024-12-06T07:26:28.000Z', '2024-12-06T07:26:28.000Z', '1、寒之为病，肾先受之，其客于五脏之间，脉引而痛；若客于八虚之室，则恶血住留，积久不去，变而成着，可不慎焉！ 寒病，骨痛，阴痹，腹胀，腰痛，大便难，肩背颈项引痛，脉沉而迟，此寒邪干肾也，$f{桂枝加葛根汤}主之；其着也则两腘痛，$f{甘草干姜茯苓白术汤}主之。 2、寒病，两胁中痛，寒中行善掣节，逆则头痛，耳聋，脉弦而沉迟，此寒邪乘肝也，$f{小柴胡汤}主之；其着也，则两腋急痛，不能转侧，$f{柴胡黄芩芍药半夏甘草汤}主之。 3、寒病，胸胁支满，膺背肩胛间痛，甚则喜悲，时发眩，仆而不知人，此寒邪乘心也，$f{通脉四逆汤}主之；其着也，则肘外痛，臂不能伸，$f{甘草泻心汤}主之。 4、寒病，腹满肠鸣，食不化，飧泄，甚则足痿不收，脉迟而涩，此寒邪乘脾也，$f{理中汤}主之；其着也，则髀枢强痛，不能屈伸，$f{枳实白术茯苓甘草汤}主之。 5、寒病，喘，咳，少气，不能报息，口唾涎沫，耳聋，嗌干，此寒邪乘肺也，脉沉而迟者，$f{甘草干姜汤}主之；其着也，则肘内痛，转侧不便，$f{枳实橘皮桔梗半夏生姜甘草汤}主之。', '2024-12-06T07:26:28.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rx41G0NS51e', 1, '{"title":"辨太阳病脉证并治上","description":"<p>1、太阳之为病，脉浮，头项强痛而恶寒。</p><p>2、太阳病，发热，汗出，恶风，脉缓者，名为中风。</p><p>3、太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名曰伤寒。</p><p>4、伤寒一日，太阳受之，脉若静者为不传；颇欲吐，若躁烦，脉数急者，此为传也。</p><p>5、伤寒二三日，阳明、少阳证不见者，此为不传也。</p><p>6、太阳病，发热而渴，不恶寒者，为温病。若发汗已，身灼热者，名曰风温。风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，鼻息必鼾，语言难出。若被下者，小便不利，直视，失溲；若被火者，微发黄色，剧则如惊痫，时瘛疭；若火熏之，一逆尚引日，再逆促命期。</p><p>7、病有发热恶寒者，发于阳也；无热恶寒者，发于阴也。发于阳者七日愈，发于阴者六日愈，以阳数七，阴数六故也。</p><p>8、太阳病，头痛至七日以上自愈者，以行其经尽故也。若欲作再经者，针足阳明，使经不传则愈。</p><p>9、太阳病欲解时，从巳至未上。</p><p>10、风家表解而不了了者，十二日愈。</p><p>11、病人身大热，反欲得衣者，热在皮肤，寒在骨髓也。</p><p>12、病人身大寒，反不欲近衣者，寒在皮肤，热在骨髓也。</p><p>13、太阳中风，阳浮而阴弱。阳浮者热自发，阴弱者汗自出。啬啬恶寒，淅淅恶风，翕翕发热，鼻鸣干呕者，$f{桂枝汤}主之。</p><p>14、太阳病，头痛，发热，汗出，恶风，$f{桂枝汤}主之。</p><p>15、太阳病，项背强几几，及汗出恶风者，$f{桂枝加葛根汤}主之。</p><p>16、太阳病，下之后，其气上冲者，可与$f{桂枝汤}。方用前法。若不上冲者，不可与之。</p><p>17、太阳病三日，已发汗，若吐，若下，若温针，仍不解者，此为坏病，桂枝不可与也。观其脉证，知犯何逆，随证治之。</p><p>18、$f{桂枝汤}本为解肌，若其人脉浮紧，发热，汗不出者，不可与也。常须识此，勿令误也。若酒客病，亦不可与$f{桂枝汤}，得之必呕，以酒客不喜甘故也。</p><p>19、喘家作，$f{桂枝汤}$n{加厚朴杏子}与之佳。</p><p>20、凡服$f{桂枝汤}吐者，其后必吐脓血也。</p><p>21、太阳病，发汗，遂漏不止，其人恶风，小便难，四肢微急，难以屈伸者，$f{桂枝加附子汤}主之。</p><p>22、太阳病，下之后，脉促，胸满者，$f{桂枝去芍药汤}主之。</p><p>23、太阳病，下之后，其人恶寒者，$f{桂枝去芍药加附子汤}主之。</p><p>24、太阳病，得之八九日，如疟状，发热恶寒，热多寒少，其人不呕，清便欲自可，一日二三度发，脉微缓者，为欲愈也。脉微而恶寒，此阴阳俱虚，不可更发汗、更吐下也。面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜$f{桂枝麻黄各半汤}。</p><p>25、太阳病，初服$f{桂枝汤}，反烦不解者，先刺风府、风池，却与$f{桂枝汤}。</p><p>26、太阳病，服$f{桂枝汤}后，大汗出，脉洪大者，与$f{白虎汤}；若形如疟，一日再发者，宜$f{桂枝二麻黄一汤}。</p><p>27、太阳病，服$f{桂枝汤}后，大汗出，大烦渴，脉洪大者，$f{白虎加人参汤}主之。</p><p>28、太阳病，发热恶寒，热多寒少，脉微弱者，此无阳也，不可发汗，脉浮大者，宜$f{桂枝二越婢一汤}方。</p><p>29、太阳病，服$f{桂枝汤}，或下之，仍头项强痛，翕翕发热，无汗，心下满，微痛，小便不利者，$f{桂枝去桂加茯苓白术汤}主之。</p><p>30、伤寒，脉浮，自汗出，小便数，心烦，微恶寒，脚挛急，反与$f{桂枝汤}欲攻其表，此误也。得之便厥，咽中干，烦燥，吐逆者，作$f{甘草干姜汤}与之，以复其阳。若厥愈，足温者，更作$f{芍药甘草汤}与之，其脚即伸。若胃气不和，谵语者，少与$f{调胃承气汤}。若重发汗，复加烧针者，$f{四逆汤}主之。</p><p>31、问曰：太阳病，其证备，按桂枝法治之而增剧，厥逆，咽中干，烦躁，吐逆，谵语，其故何也？</p>\n<p>  </p>\n<p>       师曰：此阳旦证，不可攻也，寸口脉浮，浮则风，亦为虚，风则生热，虚则挛急。误攻其表煮取三升，去滓，温服一升，日三服汗出亡阳，汗多则液枯，液枯则筋挛，阳明内结则烦躁谵语，用甘草干姜以复其阳，芍药甘草以救液，调胃承气以止其谵语，此坏病之治必随脉证也。</p><p>32、阳旦证，发热不潮，汗出，咽干，昏睡不安，夜半反静者，宜$f{地黄半夏牡蛎酸枣仁汤}主之；若口渴，烦躁，小便赤，谵语者，$f{竹叶石膏黄芩泽泻半夏甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010015,"no":15}}', '2024-12-06T07:27:05.000Z', '2024-12-06T07:27:05.000Z', '2024-12-06T07:27:05.000Z', '1、太阳之为病，脉浮，头项强痛而恶寒。 2、太阳病，发热，汗出，恶风，脉缓者，名为中风。 3、太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名曰伤寒。 4、伤寒一日，太阳受之，脉若静者为不传；颇欲吐，若躁烦，脉数急者，此为传也。 5、伤寒二三日，阳明、少阳证不见者，此为不传也。 6、太阳病，发热而渴，不恶寒者，为温病。若发汗已，身灼热者，名曰风温。风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，鼻息必鼾，语言难出。若被下者，小便不利，直视，失溲；若被火者，微发黄色，剧则如惊痫，时瘛疭；若火熏之，一逆尚引日，再逆促命期。 7、病有发热恶寒者，发于阳也；无热恶寒者，发于阴也。发于阳者七日愈，发于阴者六日愈，以阳数七，阴数六故也。 8、太阳病，头痛至七日以上自愈者，以行其经尽故也。若欲作再经者，针足阳明，使经不传则愈。 9、太阳病欲解时，从巳至未上。 10、风家表解而不了了者，十二日愈。 11、病人身大热，反欲得衣者，热在皮肤，寒在骨髓也。 12、病人身大寒，反不欲近衣者，寒在皮肤，热在骨髓也。 13、太阳中风，阳浮而阴弱。阳浮者热自发，阴弱者汗自出。啬啬恶寒，淅淅恶风，翕翕发热，鼻鸣干呕者，$f{桂枝汤}主之。 14、太阳病，头痛，发热，汗出，恶风，$f{桂枝汤}主之。 15、太阳病，项背强几几，及汗出恶风者，$f{桂枝加葛根汤}主之。 16、太阳病，下之后，其气上冲者，可与$f{桂枝汤}。方用前法。若不上冲者，不可与之。 17、太阳病三日，已发汗，若吐，若下，若温针，仍不解者，此为坏病，桂枝不可与也。观其脉证，知犯何逆，随证治之。 18、$f{桂枝汤}本为解肌，若其人脉浮紧，发热，汗不出者，不可与也。常须识此，勿令误也。若酒客病，亦不可与$f{桂枝汤}，得之必呕，以酒客不喜甘故也。 19、喘家作，$f{桂枝汤}$n{加厚朴杏子}与之佳。 20、凡服$f{桂枝汤}吐者，其后必吐脓血也。 21、太阳病，发汗，遂漏不止，其人恶风，小便难，四肢微急，难以屈伸者，$f{桂枝加附子汤}主之。 22、太阳病，下之后，脉促，胸满者，$f{桂枝去芍药汤}主之。 23、太阳病，下之后，其人恶寒者，$f{桂枝去芍药加附子汤}主之。 24、太阳病，得之八九日，如疟状，发热恶寒，热多寒少，其人不呕，清便欲自可，一日二三度发，脉微缓者，为欲愈也。脉微而恶寒，此阴阳俱虚，不可更发汗、更吐下也。面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜$f{桂枝麻黄各半汤}。 25、太阳病，初服$f{桂枝汤}，反烦不解者，先刺风府、风池，却与$f{桂枝汤}。 26、太阳病，服$f{桂枝汤}后，大汗出，脉洪大者，与$f{白虎汤}；若形如疟，一日再发者，宜$f{桂枝二麻黄一汤}。 27、太阳病，服$f{桂枝汤}后，大汗出，大烦渴，脉洪大者，$f{白虎加人参汤}主之。 28、太阳病，发热恶寒，热多寒少，脉微弱者，此无阳也，不可发汗，脉浮大者，宜$f{桂枝二越婢一汤}方。 29、太阳病，服$f{桂枝汤}，或下之，仍头项强痛，翕翕发热，无汗，心下满，微痛，小便不利者，$f{桂枝去桂加茯苓白术汤}主之。 30、伤寒，脉浮，自汗出，小便数，心烦，微恶寒，脚挛急，反与$f{桂枝汤}欲攻其表，此误也。得之便厥，咽中干，烦燥，吐逆者，作$f{甘草干姜汤}与之，以复其阳。若厥愈，足温者，更作$f{芍药甘草汤}与之，其脚即伸。若胃气不和，谵语者，少与$f{调胃承气汤}。若重发汗，复加烧针者，$f{四逆汤}主之。 31、问曰：太阳病，其证备，按桂枝法治之而增剧，厥逆，咽中干，烦躁，吐逆，谵语，其故何也？ 师曰：此阳旦证，不可攻也，寸口脉浮，浮则风，亦为虚，风则生热，虚则挛急。误攻其表煮取三升，去滓，温服一升，日三服汗出亡阳，汗多则液枯，液枯则筋挛，阳明内结则烦躁谵语，用甘草干姜以复其阳，芍药甘草以救液，调胃承气以止其谵语，此坏病之治必随脉证也。 32、阳旦证，发热不潮，汗出，咽干，昏睡不安，夜半反静者，宜$f{地黄半夏牡蛎酸枣仁汤}主之；若口渴，烦躁，小便赤，谵语者，$f{竹叶石膏黄芩泽泻半夏甘草汤}主之。', '2024-12-06T07:27:05.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VtBGNLOZPUA', 1, '{"title":"辨太阳病脉证并治中","description":"<p>33、太阳病，项背强几几，无汗，恶风者，$f{葛根汤}主之。</p><p>34、太阳与阳明合病者，必自下利，$f{葛根汤}主之。若不下利，但呕者，$f{葛根加半夏汤}主之。</p><p>35、太阳病，$n{桂枝}证，医反下之，利遂不止，脉促者，热未解也。喘而汗出者，$f{葛根黄连黄芩甘草汤}主之。</p><p>36、太阳病，头痛发热，身疼，腰痛，骨节疼痛，恶风，无汗而喘者，$f{麻黄汤}主之。</p><p>37、太阳与阳明合病，喘而胸满者，不可下，宜$f{麻黄汤}。</p><p>38、太阳病，十日已去，脉浮细而嗜卧者，外已解也，设胸满，胁痛，与$f{小柴胡汤}；脉但浮者，与$f{麻黄汤}。</p><p>39、太阳伤寒，脉浮紧，发热恶寒，身疼痛，不汗出而烦躁者，$f{大青龙汤}主之。若脉微弱，汗出恶风者，不可服之。服之则厥逆，筋惕肉（目闰），此为逆也。</p><p>40、太阳中风，脉浮缓，身不疼，但重，乍有轻时，无少阴证者，$f{大青龙汤}发之。</p><p>41、伤寒表不解，心下有水气，干呕发热而咳，或渴，或利，或噎，或小便不利，少腹满，或喘者，$f{小青龙汤}主之。</p><p>42、伤寒，心下有水气，咳而微喘，发热不渴。服汤已渴者，此寒去欲解也。$f{小青龙汤}主之。</p><p>43、太阳病，外证未解，脉浮弱者，当以汗解，宜$f{桂枝汤}。</p><p>44、太阳病，下之微喘者，表未解故也。$f{桂枝加厚朴杏子汤}主之。</p><p>45、太阳病，外证未解，不可下也，下之为逆。欲解外者，宜$f{桂枝汤}。</p><p>46、太阳病，先发汗不解，而复下之，脉浮者不愈。浮为在外，而反下之，故令不愈。今脉浮，故知在外，当须解外则愈，宜$f{桂枝汤}。</p><p>47、太阳病，脉浮紧，无汗，发热，身疼痛，八九日不解，表证仍在，此当发其汗。服药已，微除，其人发烦目瞑。剧者必衄，衄乃解，所以然者，阳气重故也。$f{麻黄汤}主之。</p><p>48、太阳病，脉浮紧，发热，身无汗，自衄者愈。</p><p>49、二阳并病，太阳初得病时，发其汗，汗先出不彻，因转属阳明，续自微汗出，不恶寒。若太阳病证不罢者，不可下，下之为逆，如此可小发其汗。设面色缘缘正赤者，阳气怫郁在表也，当解之、熏之；若发汗不彻，彻不足言，阳气怫郁不得越，当汗之不汗，则其人烦燥，不知痛处，乍在腹中，乍在四肢，按之不可得，更发汗则愈；若其人短气，但坐者，以汗出不彻故也，何以知汗出不彻？以脉涩故知之也。</p><p>50、脉浮紧者，法当汗出而解。若身重心悸者，不可发汗，须自汗出乃愈。所以然者，尺中脉微，此里虚也，须里实津液自和，便自汗出愈。</p><p>51、脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以然者，以荣气不足，血弱故也。</p><p>52、脉浮者，病在表，可发汗，宜$f{麻黄汤}。</p><p>53、脉浮而紧者，可发汗，宜$f{麻黄汤}。</p><p>54、病人常自汗出者，此为荣气和，卫气不谐也，所以然者，荣行脉中，卫行脉外，卫气不共荣气和谐故也。复发其汗则愈，宜$f{桂枝汤}。</p><p>55、病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜$f{桂枝汤}。</p><p>56、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之。</p><p>57、伤寒，不大便六七日，头痛有热者，与$n{承气汤}。其小便清者，知不在里，仍在表也，当须发汗，宜$f{桂枝汤}。</p><p>58、伤寒，发汗已解，半日许复烦，脉浮紧者，可更发汗，宜$f{桂枝汤}。</p><p>59、凡病若发汗、若吐、若下、若亡血、亡津液，阴阳自和者，必自愈。</p><p>60、大下之后，复下之，小便不利者，亡津液故也，勿治之，久久小便必自利。</p><p>61、大下之后，复发汗，其人必振寒，脉微细。所以然者，内外俱虚故也。</p><p>62、下之后，复发汗，昼日烦躁，不得眠，夜而安静，不呕不渴，无表证，脉沉而微，身无大热者，$f{干姜附子汤}主之。</p><p>63、发汗后，身疼痛，脉沉迟者，$f{桂枝去芍药加人参生姜汤}主之。</p><p>64、发汗若下后，不可更行$f{桂枝汤}。汗出而喘，无大热者，可与$f{麻黄杏仁甘草石膏汤}。</p><p>65、发汗过多，其叉手自冒心，心下悸欲得按者，$f{桂枝甘草汤}主之。</p><p>66、发汗后，其人脐下悸者，欲作奔豚也，$f{茯苓桂枝甘草大枣汤}主之。</p><p>67、奔豚病，从少腹上冲咽喉，发作欲死，复还止者，皆从惊恐得之。</p><p>68、奔豚，气上冲胸，腹痛，往来寒热，$f{奔豚汤}主之。</p><p>69、发汗后，腹胀满者，$f{厚朴生姜半夏甘草人参汤}主之。</p><p>70、伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，$f{茯苓桂枝白术甘草汤}主之。</p><p>71、发汗，病不解，反恶寒者，虚故也，$f{芍药甘草附子汤}主之。</p><p>72、发汗若下之，病仍不解，烦躁者，$f{茯苓四逆汤}主之。</p><p>73、发汗后，恶寒者，虚故也；不恶寒，但热者，实也。当和胃气，与$f{调胃承气汤}。</p><p>74、太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水，少少与之，令胃气和则愈。若脉浮，小便不利，微热消渴者，$f{五苓散}主之。</p><p>75、太阳病，发汗已，脉浮弦，烦渴者，$f{五苓散}主之。</p><p>76、伤寒汗出而渴，小便不利者，${五苓散}主之。不渴者，$f{茯苓甘草汤}主之。</p><p>77、中风发热，六七日不解而烦，有表里证，渴欲饮水，水入则吐者，名曰水逆。$f{五苓散}主之。</p><p>78、未持脉时，病人叉手自冒心，师因试教令咳而不咳者，此必两耳聋无所闻也。所以然者，以重发汗，虚故此。</p><p>79、发汗后，饮水多，必喘，以水灌之，亦喘。</p><p>80、发汗后，水药不得入口为逆，若更发汗，必吐下不止。</p><p>81、发汗后及吐下后，虚烦不得眠；若剧者，必反覆颠倒，心中懊憹，$f{栀子干姜汤}主之。若少气者，$f{栀子甘草豉汤}主之。若呕者，$f{栀子生姜豉汤}主之。</p><p>82、发汗，若下之，而烦热，胸中窒者，$f{栀子豉汤}主之。</p><p>83、伤寒五六日，大下之后，身热不去，心中结痛者，未欲解也，$f{栀子豉汤}主之。</p><p>84、伤寒下后，心烦、腹满、卧起不安者，$f{栀子厚朴枳实汤}主之。</p><p>85、伤寒，医以丸药大下之，身热不去，微烦者，$f{栀子干姜汤}主之。</p><p>86、凡用栀子汤，若病人大便旧微溏者，不可与之。</p><p>87、太阳病发汗，汗出不解，其人仍发热，心下悸，头眩，身（目闰）动，振振欲擗地者，$f{真武汤}主之。</p><p>88、咽喉干燥者，不可发汗。</p><p>89、淋家不可发汗，发汗必便血。</p><p>90、疮家虽身疼痛，不可发汗，发汗则痓。</p><p>91、衄家不可发汗，汗出必额上陷，脉急紧，直视不能目旬，不得眠。</p><p>92、亡血家，不可发汗，发汗则寒栗而振。</p><p>93、汗家重发汗，必恍惚心乱，小便已阴疼，与$f{禹余粮丸}。</p><p>94、病人有寒，复发汗，胃中冷，必吐逆。</p><p>95、伤寒，未发汗，而复下之，此为逆也；若先发汗，治不为逆。本先下之，而反汗之为逆；若先下之，治不为逆。</p><p>96、伤寒医下之，续得下利清谷不止，身疼痛者，急当救里；后身疼痛，清便自调者，急当救表。救里宜$f{四逆汤}；救表宜$f{桂枝汤}。</p><p>97、太阳病，先下而不愈，因复发汗，以此表里俱虚，其人因致冒，冒家汗自出愈，所以然者，表和故也，里未和然后复下之。</p><p>98、太阳病未解，脉阴阳俱微者，必先振栗汗出而解。但阳脉微者，先汗出而解；若阴脉实者，下之而解。若欲下之，宜$f{调胃承气汤}。</p><p>99、太阳病，发热汗出者，此为荣弱卫强，故使汗出，欲救邪风者，宜$f{桂枝汤}。</p><p>100、伤寒五六日，中风，往来寒热，胸胁苦满，嘿嘿不欲饮食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞鞕，或心下悸，小便不利，或不渴，身有微热，或咳者，与$f{小柴胡汤}主之。</p><p>101、血弱气尽，腠理开，邪气因入，与正气相搏，结于胁下，正邪纷争，往来寒热，休作有时，嘿嘿不欲饮食。脏腑相连，其痛必下，邪高痛下，故使呕也。$f{小柴胡汤}主之。服柴胡汤已，渴者，属阳明也，以法治之。</p><p>102、太阳病六七日，脉迟浮弱，恶风寒，手足温，医二三下之，不能食，胁下满痛，面目及身黄，颈项强，小便难者，与柴胡汤。后必下重，本渴而饮水呕者，柴胡不中与也。食谷者哕。</p><p>103、伤寒四五日，身热恶风，颈项强，胁下满，手足温而渴者，$f{小柴胡汤}主之。</p><p>104、伤寒，阳脉涩，阴脉弦，法当腹中急痛，先与$f{小建中汤}；不差者，与$f{小柴胡汤}。</p><p>105、伤寒与中风，有柴胡证，但见一证便是，不必悉具。凡柴胡汤病证而误下之，若柴胡证不罢者，复与柴胡汤，必蒸蒸而振，却复发热汗出而解。</p><p>106、伤寒二三日，心中悸而烦者，$f{小建中汤}主之。</p><p>107、太阳病，过经十余日，反二三下之，后四五日，柴胡证仍在者，先与$f{小柴胡汤}。呕不止，心下急，郁郁微烦者，为未解也，与$f{大柴胡汤}下之则愈。</p><p>108、伤寒十三日不解，胸胁满而呕，日晡所发潮热，已而微利。此本柴胡证，下之以不得利，今反利者，知医以丸药下之，非其治也。潮热者实也，宜先服$f{小柴胡汤}以解外，后以$f{柴胡加芒消汤}主之。</p><p>109、伤寒十三日，过经，谵语者，以有热也，当以汤下之。若小便利者，大便当鞕，而反下利，知医以丸药下之，非其治也。若自下利者，脉当微厥，今反和者，此为内实也，$f{调胃承气汤}主之。</p><p>110、太阳病不解，热结膀胱，其人如狂，血自下，下者愈。其外不解者，尚未可攻，当先解外。外解已，但少腹急结者，乃可攻之，宜$f{桃仁承气汤}。</p><p>111、伤寒八九日，下之，胸满烦惊，小便不利，谵语，一身尽重，不可转侧，$f{柴胡加龙骨牡蛎汤}主之。</p><p>112、伤寒，腹满，谵语，寸口脉浮而紧，关上弦者，此肝乘脾也，名曰纵，刺期门。</p><p>113、伤寒发热，啬啬恶寒，大渴欲饮水，其腹必满，自汗出，小便不寸口脉浮而涩，关上弦急者，此肝乘肺也，名曰横，刺期门。</p><p>114、太阳病二日，烦躁，反熨其背，而大汗出，火热入胃，胃中水竭，躁烦，必发谵语，十余日，振栗、自下利者，此为欲解也。若其汗从腰以下不得汗，欲小便不得，反呕，欲失溲，足下恶风，大便鞕，小便当数，而反不数又不多，大便已，头卓然而痛，其人足心必热，谷气下流故也。</p><p>115、太阳病中风，以火劫发汗，邪风被火热，血气流溢，失其常度，两阳相熏灼，其身发黄。阳盛则欲衄，阴虚小便难，阴阳俱虚竭，身体则枯燥。但头汗出，剂颈而还，腹满微喘，口干咽烂，或不大便，久则谵语，甚者至哕，手足躁扰，捻衣摸床，小便利者，其人可治。宜$f{人参地黄龙骨牡蛎茯苓汤}。</p><p>116、伤寒脉浮，医以火迫劫之，亡阳，必惊狂，起卧不安者，$f{桂枝去芍药加牡蛎龙骨救逆汤}主之。</p><p>117、形似伤寒，其脉不弦紧而弱。弱者必渴，被火必谵语。弱而发热、脉浮者，解之当汗出愈。</p><p>118、太阳病，以火熏之，不得汗，其人必躁，到经不解，必清血，名为火邪。</p><p>119、脉浮热甚，反以火灸之，此为实。实以虚治，因火而动，必咽燥唾血。</p><p>120、微数之脉，慎不可灸，因火为邪，则为烦逆，追虚逐实，血散脉中，火气虽微，内攻有力，焦骨伤筋，血难复也。</p><p>121、脉浮，宜以汗解，用火灸之，邪无从出，因火而盛，病从腰以下必重而痹，名火逆也。欲自解者，必当先烦，乃有汗而解。何以知之？脉浮故也。</p><p>122、烧针令其汗，针处被寒，核起而赤者，必发奔豚。气从少腹上冲心者，灸其核上各一壮，与$f{桂枝加桂汤}。</p><p>123、火逆，下之，因烧针烦躁者，$f{桂枝甘草龙骨牡蛎汤}主之。</p><p>124、太阳伤寒者，加温针，必惊也。</p><p>125、太阳病，当恶寒发热，今自汗出，反不恶寒发热，关上脉细数者，以医吐之过也。一二日吐之者，腹中饥，口不能食；三四日吐之者，不喜糜粥，欲食冷食，朝食暮吐，此为小逆；若不恶寒，又不欲近衣者，此为内烦；皆医吐之所致也。</p><p>126、病人脉数，数为热，当消谷，今引食而反吐者，此以发汗令阳气微，隔气虚，脉乃数也。数为客热，故不能消谷，以胃中虚冷故吐也。</p><p>127、太阳病，过经十余日，心中温温欲吐，胸中痛，大便反溏，腹微满，郁郁微烦。先其时，自极吐下者，与$f{调胃承气汤}。若不尔者，不可与之。若但欲呕，胸中痛，微溏者，此非柴胡证，所以然者，以呕故知极吐下也。</p><p>128、太阳病六七日，表证仍在，脉微而沉，反不结胸，其人发狂者，以热在下焦，少腹当鞕满，小便自利者，下血乃愈，所以然者，以太阳随经，瘀热在里故也。$f{抵当汤}主之。</p><p>129、太阳病，身黄脉沉结，少腹鞕，小便不利者，为无血也；小便自利，其人如狂者，血证谛也，$f{抵当汤}主之。</p><p>130、伤寒有热，少腹满，应小便不利；今反利者，为有血也，当下之，可不余药，宜$f{抵当丸}。</p><p>131、太阳病，小便利者，以饮水多，必心下悸。小便少者，必苦里急也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010016,"no":16}}', '2024-12-06T07:27:24.000Z', '2024-12-06T07:27:24.000Z', '2024-12-06T07:27:24.000Z', '33、太阳病，项背强几几，无汗，恶风者，$f{葛根汤}主之。 34、太阳与阳明合病者，必自下利，$f{葛根汤}主之。若不下利，但呕者，$f{葛根加半夏汤}主之。 35、太阳病，$n{桂枝}证，医反下之，利遂不止，脉促者，热未解也。喘而汗出者，$f{葛根黄连黄芩甘草汤}主之。 36、太阳病，头痛发热，身疼，腰痛，骨节疼痛，恶风，无汗而喘者，$f{麻黄汤}主之。 37、太阳与阳明合病，喘而胸满者，不可下，宜$f{麻黄汤}。 38、太阳病，十日已去，脉浮细而嗜卧者，外已解也，设胸满，胁痛，与$f{小柴胡汤}；脉但浮者，与$f{麻黄汤}。 39、太阳伤寒，脉浮紧，发热恶寒，身疼痛，不汗出而烦躁者，$f{大青龙汤}主之。若脉微弱，汗出恶风者，不可服之。服之则厥逆，筋惕肉（目闰），此为逆也。 40、太阳中风，脉浮缓，身不疼，但重，乍有轻时，无少阴证者，$f{大青龙汤}发之。 41、伤寒表不解，心下有水气，干呕发热而咳，或渴，或利，或噎，或小便不利，少腹满，或喘者，$f{小青龙汤}主之。 42、伤寒，心下有水气，咳而微喘，发热不渴。服汤已渴者，此寒去欲解也。$f{小青龙汤}主之。 43、太阳病，外证未解，脉浮弱者，当以汗解，宜$f{桂枝汤}。 44、太阳病，下之微喘者，表未解故也。$f{桂枝加厚朴杏子汤}主之。 45、太阳病，外证未解，不可下也，下之为逆。欲解外者，宜$f{桂枝汤}。 46、太阳病，先发汗不解，而复下之，脉浮者不愈。浮为在外，而反下之，故令不愈。今脉浮，故知在外，当须解外则愈，宜$f{桂枝汤}。 47、太阳病，脉浮紧，无汗，发热，身疼痛，八九日不解，表证仍在，此当发其汗。服药已，微除，其人发烦目瞑。剧者必衄，衄乃解，所以然者，阳气重故也。$f{麻黄汤}主之。 48、太阳病，脉浮紧，发热，身无汗，自衄者愈。 49、二阳并病，太阳初得病时，发其汗，汗先出不彻，因转属阳明，续自微汗出，不恶寒。若太阳病证不罢者，不可下，下之为逆，如此可小发其汗。设面色缘缘正赤者，阳气怫郁在表也，当解之、熏之；若发汗不彻，彻不足言，阳气怫郁不得越，当汗之不汗，则其人烦燥，不知痛处，乍在腹中，乍在四肢，按之不可得，更发汗则愈；若其人短气，但坐者，以汗出不彻故也，何以知汗出不彻？以脉涩故知之也。 50、脉浮紧者，法当汗出而解。若身重心悸者，不可发汗，须自汗出乃愈。所以然者，尺中脉微，此里虚也，须里实津液自和，便自汗出愈。 51、脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以然者，以荣气不足，血弱故也。 52、脉浮者，病在表，可发汗，宜$f{麻黄汤}。 53、脉浮而紧者，可发汗，宜$f{麻黄汤}。 54、病人常自汗出者，此为荣气和，卫气不谐也，所以然者，荣行脉中，卫行脉外，卫气不共荣气和谐故也。复发其汗则愈，宜$f{桂枝汤}。 55、病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜$f{桂枝汤}。 56、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之。 57、伤寒，不大便六七日，头痛有热者，与$n{承气汤}。其小便清者，知不在里，仍在表也，当须发汗，宜$f{桂枝汤}。 58、伤寒，发汗已解，半日许复烦，脉浮紧者，可更发汗，宜$f{桂枝汤}。 59、凡病若发汗、若吐、若下、若亡血、亡津液，阴阳自和者，必自愈。 60、大下之后，复下之，小便不利者，亡津液故也，勿治之，久久小便必自利。 61、大下之后，复发汗，其人必振寒，脉微细。所以然者，内外俱虚故也。 62、下之后，复发汗，昼日烦躁，不得眠，夜而安静，不呕不渴，无表证，脉沉而微，身无大热者，$f{干姜附子汤}主之。 63、发汗后，身疼痛，脉沉迟者，$f{桂枝去芍药加人参生姜汤}主之。 64、发汗若下后，不可更行$f{桂枝汤}。汗出而喘，无大热者，可与$f{麻黄杏仁甘草石膏汤}。 65、发汗过多，其叉手自冒心，心下悸欲得按者，$f{桂枝甘草汤}主之。 66、发汗后，其人脐下悸者，欲作奔豚也，$f{茯苓桂枝甘草大枣汤}主之。 67、奔豚病，从少腹上冲咽喉，发作欲死，复还止者，皆从惊恐得之。 68、奔豚，气上冲胸，腹痛，往来寒热，$f{奔豚汤}主之。 69、发汗后，腹胀满者，$f{厚朴生姜半夏甘草人参汤}主之。 70、伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，$f{茯苓桂枝白术甘草汤}主之。 71、发汗，病不解，反恶寒者，虚故也，$f{芍药甘草附子汤}主之。 72、发汗若下之，病仍不解，烦躁者，$f{茯苓四逆汤}主之。 73、发汗后，恶寒者，虚故也；不恶寒，但热者，实也。当和胃气，与$f{调胃承气汤}。 74、太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水，少少与之，令胃气和则愈。若脉浮，小便不利，微热消渴者，$f{五苓散}主之。 75、太阳病，发汗已，脉浮弦，烦渴者，$f{五苓散}主之。 76、伤寒汗出而渴，小便不利者，${五苓散}主之。不渴者，$f{茯苓甘草汤}主之。 77、中风发热，六七日不解而烦，有表里证，渴欲饮水，水入则吐者，名曰水逆。$f{五苓散}主之。 78、未持脉时，病人叉手自冒心，师因试教令咳而不咳者，此必两耳聋无所闻也。所以然者，以重发汗，虚故此。 79、发汗后，饮水多，必喘，以水灌之，亦喘。 80、发汗后，水药不得入口为逆，若更发汗，必吐下不止。 81、发汗后及吐下后，虚烦不得眠；若剧者，必反覆颠倒，心中懊憹，$f{栀子干姜汤}主之。若少气者，$f{栀子甘草豉汤}主之。若呕者，$f{栀子生姜豉汤}主之。 82、发汗，若下之，而烦热，胸中窒者，$f{栀子豉汤}主之。 83、伤寒五六日，大下之后，身热不去，心中结痛者，未欲解也，$f{栀子豉汤}主之。 84、伤寒下后，心烦、腹满、卧起不安者，$f{栀子厚朴枳实汤}主之。 85、伤寒，医以丸药大下之，身热不去，微烦者，$f{栀子干姜汤}主之。 86、凡用栀子汤，若病人大便旧微溏者，不可与之。 87、太阳病发汗，汗出不解，其人仍发热，心下悸，头眩，身（目闰）动，振振欲擗地者，$f{真武汤}主之。 88、咽喉干燥者，不可发汗。 89、淋家不可发汗，发汗必便血。 90、疮家虽身疼痛，不可发汗，发汗则痓。 91、衄家不可发汗，汗出必额上陷，脉急紧，直视不能目旬，不得眠。 92、亡血家，不可发汗，发汗则寒栗而振。 93、汗家重发汗，必恍惚心乱，小便已阴疼，与$f{禹余粮丸}。 94、病人有寒，复发汗，胃中冷，必吐逆。 95、伤寒，未发汗，而复下之，此为逆也；若先发汗，治不为逆。本先下之，而反汗之为逆；若先下之，治不为逆。 96、伤寒医下之，续得下利清谷不止，身疼痛者，急当救里；后身疼痛，清便自调者，急当救表。救里宜$f{四逆汤}；救表宜$f{桂枝汤}。 97、太阳病，先下而不愈，因复发汗，以此表里俱虚，其人因致冒，冒家汗自出愈，所以然者，表和故也，里未和然后复下之。 98、太阳病未解，脉阴阳俱微者，必先振栗汗出而解。但阳脉微者，先汗出而解；若阴脉实者，下之而解。若欲下之，宜$f{调胃承气汤}。 99、太阳病，发热汗出者，此为荣弱卫强，故使汗出，欲救邪风者，宜$f{桂枝汤}。 100、伤寒五六日，中风，往来寒热，胸胁苦满，嘿嘿不欲饮食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞鞕，或心下悸，小便不利，或不渴，身有微热，或咳者，与$f{小柴胡汤}主之。 101、血弱气尽，腠理开，邪气因入，与正气相搏，结于胁下，正邪纷争，往来寒热，休作有时，嘿嘿不欲饮食。脏腑相连，其痛必下，邪高痛下，故使呕也。$f{小柴胡汤}主之。服柴胡汤已，渴者，属阳明也，以法治之。 102、太阳病六七日，脉迟浮弱，恶风寒，手足温，医二三下之，不能食，胁下满痛，面目及身黄，颈项强，小便难者，与柴胡汤。后必下重，本渴而饮水呕者，柴胡不中与也。食谷者哕。 103、伤寒四五日，身热恶风，颈项强，胁下满，手足温而渴者，$f{小柴胡汤}主之。 104、伤寒，阳脉涩，阴脉弦，法当腹中急痛，先与$f{小建中汤}；不差者，与$f{小柴胡汤}。 105、伤寒与中风，有柴胡证，但见一证便是，不必悉具。凡柴胡汤病证而误下之，若柴胡证不罢者，复与柴胡汤，必蒸蒸而振，却复发热汗出而解。 106、伤寒二三日，心中悸而烦者，$f{小建中汤}主之。 107、太阳病，过经十余日，反二三下之，后四五日，柴胡证仍在者，先与$f{小柴胡汤}。呕不止，心下急，郁郁微烦者，为未解也，与$f{大柴胡汤}下之则愈。 108、伤寒十三日不解，胸胁满而呕，日晡所发潮热，已而微利。此本柴胡证，下之以不得利，今反利者，知医以丸药下之，非其治也。潮热者实也，宜先服$f{小柴胡汤}以解外，后以$f{柴胡加芒消汤}主之。 109、伤寒十三日，过经，谵语者，以有热也，当以汤下之。若小便利者，大便当鞕，而反下利，知医以丸药下之，非其治也。若自下利者，脉当微厥，今反和者，此为内实也，$f{调胃承气汤}主之。 110、太阳病不解，热结膀胱，其人如狂，血自下，下者愈。其外不解者，尚未可攻，当先解外。外解已，但少腹急结者，乃可攻之，宜$f{桃仁承气汤}。 111、伤寒八九日，下之，胸满烦惊，小便不利，谵语，一身尽重，不可转侧，$f{柴胡加龙骨牡蛎汤}主之。 112、伤寒，腹满，谵语，寸口脉浮而紧，关上弦者，此肝乘脾也，名曰纵，刺期门。 113、伤寒发热，啬啬恶寒，大渴欲饮水，其腹必满，自汗出，小便不寸口脉浮而涩，关上弦急者，此肝乘肺也，名曰横，刺期门。 114、太阳病二日，烦躁，反熨其背，而大汗出，火热入胃，胃中水竭，躁烦，必发谵语，十余日，振栗、自下利者，此为欲解也。若其汗从腰以下不得汗，欲小便不得，反呕，欲失溲，足下恶风，大便鞕，小便当数，而反不数又不多，大便已，头卓然而痛，其人足心必热，谷气下流故也。 115、太阳病中风，以火劫发汗，邪风被火热，血气流溢，失其常度，两阳相熏灼，其身发黄。阳盛则欲衄，阴虚小便难，阴阳俱虚竭，身体则枯燥。但头汗出，剂颈而还，腹满微喘，口干咽烂，或不大便，久则谵语，甚者至哕，手足躁扰，捻衣摸床，小便利者，其人可治。宜$f{人参地黄龙骨牡蛎茯苓汤}。 116、伤寒脉浮，医以火迫劫之，亡阳，必惊狂，起卧不安者，$f{桂枝去芍药加牡蛎龙骨救逆汤}主之。 117、形似伤寒，其脉不弦紧而弱。弱者必渴，被火必谵语。弱而发热、脉浮者，解之当汗出愈。 118、太阳病，以火熏之，不得汗，其人必躁，到经不解，必清血，名为火邪。 119、脉浮热甚，反以火灸之，此为实。实以虚治，因火而动，必咽燥唾血。 120、微数之脉，慎不可灸，因火为邪，则为烦逆，追虚逐实，血散脉中，火气虽微，内攻有力，焦骨伤筋，血难复也。 121、脉浮，宜以汗解，用火灸之，邪无从出，因火而盛，病从腰以下必重而痹，名火逆也。欲自解者，必当先烦，乃有汗而解。何以知之？脉浮故也。 122、烧针令其汗，针处被寒，核起而赤者，必发奔豚。气从少腹上冲心者，灸其核上各一壮，与$f{桂枝加桂汤}。 123、火逆，下之，因烧针烦躁者，$f{桂枝甘草龙骨牡蛎汤}主之。 124、太阳伤寒者，加温针，必惊也。 125、太阳病，当恶寒发热，今自汗出，反不恶寒发热，关上脉细数者，以医吐之过也。一二日吐之者，腹中饥，口不能食；三四日吐之者，不喜糜粥，欲食冷食，朝食暮吐，此为小逆；若不恶寒，又不欲近衣者，此为内烦；皆医吐之所致也。 126、病人脉数，数为热，当消谷，今引食而反吐者，此以发汗令阳气微，隔气虚，脉乃数也。数为客热，故不能消谷，以胃中虚冷故吐也。 127、太阳病，过经十余日，心中温温欲吐，胸中痛，大便反溏，腹微满，郁郁微烦。先其时，自极吐下者，与$f{调胃承气汤}。若不尔者，不可与之。若但欲呕，胸中痛，微溏者，此非柴胡证，所以然者，以呕故知极吐下也。 128、太阳病六七日，表证仍在，脉微而沉，反不结胸，其人发狂者，以热在下焦，少腹当鞕满，小便自利者，下血乃愈，所以然者，以太阳随经，瘀热在里故也。$f{抵当汤}主之。 129、太阳病，身黄脉沉结，少腹鞕，小便不利者，为无血也；小便自利，其人如狂者，血证谛也，$f{抵当汤}主之。 130、伤寒有热，少腹满，应小便不利；今反利者，为有血也，当下之，可不余药，宜$f{抵当丸}。 131、太阳病，小便利者，以饮水多，必心下悸。小便少者，必苦里急也。', '2024-12-06T07:27:24.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DwPMcet9QLd', 1, '{"title":"辨太阳病脉证并治下","description":"<p>132、问曰：病有脏结，有结胸，其状何如？</p>\n<p></p>\n<p>         师曰：寸脉浮，关脉小细沉紧者，名曰脏结也。按之痛，寸脉浮，关脉沉，名曰结胸也。</p><p>133、何谓脏结？</p>\n<p></p>\n<p>       师曰：脏结者，五脏各具，寒热攸分，宜求血分，虽有气结，皆血为之。假令肝脏结，则两胁痛而呕，脉沉弦而结者，宜$f{吴茱萸汤}。若发热不呕者，此为实，脉当沉弦而急，$f{桂枝当归牡丹皮桃仁枳实汤}主之。</p><p>134、心脏结，则心中痛，或在心下郁郁不乐，脉大而涩，$f{连翘阿胶半夏赤小豆汤}主之。若心中热痛而烦，脉大而弦急者，此为实也，$f{黄连阿胶半夏桃仁茯苓汤}主之。</p><p>135、肺脏结，胸中闭塞，喘，咳，善悲，脉短而涩，$f{百合贝母茯苓桔梗汤}主之。若咳而唾血，胸中痛，此为实，$f{葶苈括蒌桔梗牡丹汤}主之。</p><p>136、脾脏结，腹中满痛，按之如覆杯，甚则腹大而坚，脉沉而紧，$f{白术枳实桃仁干姜汤}主之。若腹中胀痛，不可按，大便初溏后鞕，转失（疑为矢）气者，此为实，$f{大黄厚朴枳实半夏甘草汤}主之。</p><p>137、肾脏结，少腹鞕，隐隐痛，按之如有核，小便乍清乍浊，脉沉细而结，宜$f{茯苓桂枝甘草大枣汤}。若小腹急痛，小便赤数者，此为实，宜$f{桂枝茯苓枳实芍药甘草汤}。</p><p>138、脏结，无阳证，不往来寒热，其人反静，舌上苔滑者，不可攻也；饮食如故，时时下利，舌上白苔滑者，为难治。</p><p>139、何谓结胸？师曰：病发于阳而反下之，热入于里，因作结胸。病发于阴，而早下之，因作痞。所以成结胸者，误下故也。</p><p>140、结胸病，头项强，如柔痉状者，下之则和，宜$f{大陷胸丸}。</p><p>141、结胸证，其脉浮大者，不可下，下之则死。</p><p>142、结胸证悉具，烦躁者，亦死。</p><p>143、太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，头痛发热，微盗汗出，而反恶寒者，表未解也，医反下之，动数变迟，膈内拒痛，胃中空虚，客气动膈，短气，躁烦，心中懊$n{憹[náo]}，阳气内陷，心下因鞕，则为结胸，$f{大陷胸汤}主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄。$f{五苓散}主之。</p><p>144、伤寒六七日，结胸热实，脉沉紧而实，心下痛，按之石鞕者，$f{大陷胸汤}主之。</p><p>145、伤寒十余日，热结在里，复往来寒热者，与$f{大柴胡汤}。</p><p>146、但结胸无大热者，此为水结在胸肋也，但头微汗出者，$f{大陷胸汤}主之。</p><p>147、太阳病，重发汗，而复下之，不大便五六日，舌上燥而渴，日晡所小有潮热，从心下至少腹鞕满而痛不可近者，$f{大陷胸汤}主之。</p><p>148、小结胸病，正在心下，按之则痛，脉浮滑者，$f{小陷胸汤}主之。</p><p>149、太阳病，二三日，不能卧，但欲起，心下必结，脉微弱者，此本有寒分也，反下之，若利止，必作结胸；未止者，此作协热利也。</p><p>150、太阳病，下之后，其脉促，不结胸者，此为欲解也；脉浮者，必结胸；脉紧者，必咽痛，脉弦者，必两胁拘急；脉细数者，头痛未止，脉沉紧者，必欲呕；脉沉滑者，协热利；脉浮滑者，必下血。</p><p>151、病在阳，应以汗解之，反以冷水潠之，若灌之，其热被劫不得去，弥更益烦，肉上粟起，意欲饮水，反不渴者，服$f{文蛤散}；若不差者，与$f{五苓散}。寒实结胸，无热证者，与$n{三物}$f{小陷胸汤}，$f{白散}亦可服。</p><p>152、太阳与少阳并病，头项强痛，或眩冒，时如结胸，心下痞鞕者，当刺大椎第一间、肺俞、肝俞，慎不可发汗，发汗则谵语，脉弦大，五日谵语不止，当刺期门。</p><p>153、妇人中风，发热恶风，经水适来，得之七八日，热除而脉迟身凉，胸胁下满，如结胸状，谵语者，此为热入血室也，当刺期门，随其实而泄之。</p><p>154、妇人中风，七八日，续得寒热，发作有时，经水适断者，此为热入血室，其血必结，故使如疟状，$f{小柴胡汤}主之。</p><p>155、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，无犯胃气及上二焦，必自愈。</p><p>156、伤寒六七日，发热微恶寒，支节烦疼，微呕，心下支结，外证未去者，$f{柴胡桂枝汤}主之。</p><p>157、伤寒五六日，已发汗而复下之，胸胁满，微结，小便不利，渴而不呕，但头汗出，往来寒热，心烦者，此为未解也，$f{柴胡桂枝干姜汤}主之。</p><p>158、伤寒五六日，头汗出，微恶寒，手足冷，心下满，口不欲食，大便鞕，脉细者，此为阳微结，必有表复有里也，脉沉者，亦在里也，汗出为阳微。假令纯阴结，不得复有外证，悉入在里，此为半在里半在外也，脉虽沉细，不得为少阴病，所以然者，阴不得有汗，今头汗出，故知非少阴也，可与$f{小柴胡汤}。设不了了者，得屎而解。</p><p>159、伤寒五六日，呕而发热者，$n{柴胡汤}证具，而以他药下之，$n{柴胡证}仍在者，复与$n{柴胡汤}，此虽已下之，不为逆，必蒸蒸而振，却发热汗出而解。若心下满而鞕痛者，此为结胸也，$f{大陷胸汤}主之，但满而不痛者，此为痞，$u{柴胡}不中与之，宜$f{半夏泻心汤}。</p><p>160、太阳少阳并病，而反下之，成结胸，心下必鞕，若下利不止，水浆不下，其人必烦。</p><p>161、脉浮而紧，而复下之，紧反入里，则作痞，按之自濡，但气痞耳；$f{小青龙汤}主之。</p><p>162、太阳中风，下利，呕逆，表解者，乃可攻之，若其人絷絷汗出，发作有时，头痛，心下痞满，引胁下痛，干呕短气，汗出不恶寒者，此表解里未和也，$f{十枣汤}主之。</p><p>163、太阳病，医发汗，遂发热恶寒，因复下之，心下痞，表里俱虚，阴阳气并竭，无阳则阴独，复加烧针，因胸烦，面色青黄，肤瞤者，难治，今色微黄，手足温者易愈。</p>\n<p></p><p> 164、心下痞，按之濡，其脉关上浮大者，$f{大黄黄连黄芩泻心汤}主之。 </p><p>165、心下痞，而复恶寒者，$f{附子泻心汤}主之。</p><p>166、本以下之，故心下痞，与泻心汤。痞不解，其人渴，而口燥烦，小便不利者，$f{五苓散}主之。</p><p>167、伤寒，汗出，解之后，胃中不和，心下痞鞕，干噫食臭，胁下有水气，腹中雷鸣，下利者，$f{生姜泻心汤}主之。</p><p>168、伤寒中风，医反下之，其人下利，日数十行，谷不化，腹中雷鸣，心下痞鞕而满，干呕，心烦不得安，医见心下痞，谓病不尽，复下之，其痞益甚，此非结热，但以胃中虚，客气上逆，故使鞕也，$f{甘草泻心汤}主之。</p><p>169、伤寒，服汤药下之，利不止，心下痞鞕，服泻心汤不已，复以他药下之，利益甚，医以理中与之，利仍不止，理中者，理中焦，此利在下焦故也，$f{赤石脂禹余粮汤}主之，复不止者，当利其小便。</p><p>170、伤寒吐下后，发汗，虚烦，脉甚微，八九日，心下痞鞕，胁下痛，气上冲咽喉，眩冒，经脉动惕者，久而成痿。</p><p>171、伤寒，发汗，若吐，若下，解后，心下痞鞕，噫气不除者，$f{旋覆代赭汤}主之。</p><p>172、太阳病，外证未除，而数下之，遂协热而利，利下不止，心下痞鞕，表里不解者，$f{桂枝人参汤}主之。</p><p>173、伤寒，大下后，复发汗，心下痞，恶寒者，表未解也，不可攻痞，当先解表，后攻其痞，解表宜$f{桂枝汤}；攻痞宜$f{大黄黄连黄芩泻心汤}。</p><p>174、伤寒发热，汗出不解，心下痞鞕，呕吐而不利者，$f{大柴胡汤}主之。</p><p>175、病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞鞕，气上咽喉，不得息者，此为胸有寒也，当吐之，宜$f{瓜蒂散}。</p><p>176、病胁下素有痞，连在脐旁，痛引少腹，入阴筋者，此名脏结，死。</p><p>177、伤寒，若吐，若下后，七八日不解，热结在里，表里俱热，时时恶风，大渴，舌上干燥而烦，欲饮水数升者，$f{白虎加人参汤}主之。</p><p>178、伤寒，无大热，口燥渴，心烦，背微恶寒者，$f{白虎加人参汤}主之。</p><p>179、伤寒，脉浮，发热，无汗，其表不解，当发汗，不可与$f{白虎汤}；渴欲饮，无表证者，$f{白虎加人参汤}主之。</p><p>180、太阳少阳并病，心下鞕，颈项强而眩者，当刺大椎、肺俞、肝俞，慎不可下也，下之则痉。</p><p>181、太阳与少阳合病，自下利者，与$f{黄芩汤}；若呕者，$f{黄芩加半夏生姜汤}主之。</p><p>182、伤寒，胸中有热，胃中有邪气，腹中痛，欲呕者，$f{黄连汤}主之。</p><p>183、伤寒，脉浮滑，此以里有热，表无寒也，$f{白虎汤}主之。</p><p>184、伤寒脉结促，心动悸者，$f{炙甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010017,"no":17}}', '2024-12-06T07:27:41.000Z', '2024-12-06T07:27:41.000Z', '2024-12-06T07:27:41.000Z', '132、问曰：病有脏结，有结胸，其状何如？ 师曰：寸脉浮，关脉小细沉紧者，名曰脏结也。按之痛，寸脉浮，关脉沉，名曰结胸也。 133、何谓脏结？ 师曰：脏结者，五脏各具，寒热攸分，宜求血分，虽有气结，皆血为之。假令肝脏结，则两胁痛而呕，脉沉弦而结者，宜$f{吴茱萸汤}。若发热不呕者，此为实，脉当沉弦而急，$f{桂枝当归牡丹皮桃仁枳实汤}主之。 134、心脏结，则心中痛，或在心下郁郁不乐，脉大而涩，$f{连翘阿胶半夏赤小豆汤}主之。若心中热痛而烦，脉大而弦急者，此为实也，$f{黄连阿胶半夏桃仁茯苓汤}主之。 135、肺脏结，胸中闭塞，喘，咳，善悲，脉短而涩，$f{百合贝母茯苓桔梗汤}主之。若咳而唾血，胸中痛，此为实，$f{葶苈括蒌桔梗牡丹汤}主之。 136、脾脏结，腹中满痛，按之如覆杯，甚则腹大而坚，脉沉而紧，$f{白术枳实桃仁干姜汤}主之。若腹中胀痛，不可按，大便初溏后鞕，转失（疑为矢）气者，此为实，$f{大黄厚朴枳实半夏甘草汤}主之。 137、肾脏结，少腹鞕，隐隐痛，按之如有核，小便乍清乍浊，脉沉细而结，宜$f{茯苓桂枝甘草大枣汤}。若小腹急痛，小便赤数者，此为实，宜$f{桂枝茯苓枳实芍药甘草汤}。 138、脏结，无阳证，不往来寒热，其人反静，舌上苔滑者，不可攻也；饮食如故，时时下利，舌上白苔滑者，为难治。 139、何谓结胸？师曰：病发于阳而反下之，热入于里，因作结胸。病发于阴，而早下之，因作痞。所以成结胸者，误下故也。 140、结胸病，头项强，如柔痉状者，下之则和，宜$f{大陷胸丸}。 141、结胸证，其脉浮大者，不可下，下之则死。 142、结胸证悉具，烦躁者，亦死。 143、太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，头痛发热，微盗汗出，而反恶寒者，表未解也，医反下之，动数变迟，膈内拒痛，胃中空虚，客气动膈，短气，躁烦，心中懊$n{憹[náo]}，阳气内陷，心下因鞕，则为结胸，$f{大陷胸汤}主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄。$f{五苓散}主之。 144、伤寒六七日，结胸热实，脉沉紧而实，心下痛，按之石鞕者，$f{大陷胸汤}主之。 145、伤寒十余日，热结在里，复往来寒热者，与$f{大柴胡汤}。 146、但结胸无大热者，此为水结在胸肋也，但头微汗出者，$f{大陷胸汤}主之。 147、太阳病，重发汗，而复下之，不大便五六日，舌上燥而渴，日晡所小有潮热，从心下至少腹鞕满而痛不可近者，$f{大陷胸汤}主之。 148、小结胸病，正在心下，按之则痛，脉浮滑者，$f{小陷胸汤}主之。 149、太阳病，二三日，不能卧，但欲起，心下必结，脉微弱者，此本有寒分也，反下之，若利止，必作结胸；未止者，此作协热利也。 150、太阳病，下之后，其脉促，不结胸者，此为欲解也；脉浮者，必结胸；脉紧者，必咽痛，脉弦者，必两胁拘急；脉细数者，头痛未止，脉沉紧者，必欲呕；脉沉滑者，协热利；脉浮滑者，必下血。 151、病在阳，应以汗解之，反以冷水潠之，若灌之，其热被劫不得去，弥更益烦，肉上粟起，意欲饮水，反不渴者，服$f{文蛤散}；若不差者，与$f{五苓散}。寒实结胸，无热证者，与$n{三物}$f{小陷胸汤}，$f{白散}亦可服。 152、太阳与少阳并病，头项强痛，或眩冒，时如结胸，心下痞鞕者，当刺大椎第一间、肺俞、肝俞，慎不可发汗，发汗则谵语，脉弦大，五日谵语不止，当刺期门。 153、妇人中风，发热恶风，经水适来，得之七八日，热除而脉迟身凉，胸胁下满，如结胸状，谵语者，此为热入血室也，当刺期门，随其实而泄之。 154、妇人中风，七八日，续得寒热，发作有时，经水适断者，此为热入血室，其血必结，故使如疟状，$f{小柴胡汤}主之。 155、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，无犯胃气及上二焦，必自愈。 156、伤寒六七日，发热微恶寒，支节烦疼，微呕，心下支结，外证未去者，$f{柴胡桂枝汤}主之。 157、伤寒五六日，已发汗而复下之，胸胁满，微结，小便不利，渴而不呕，但头汗出，往来寒热，心烦者，此为未解也，$f{柴胡桂枝干姜汤}主之。 158、伤寒五六日，头汗出，微恶寒，手足冷，心下满，口不欲食，大便鞕，脉细者，此为阳微结，必有表复有里也，脉沉者，亦在里也，汗出为阳微。假令纯阴结，不得复有外证，悉入在里，此为半在里半在外也，脉虽沉细，不得为少阴病，所以然者，阴不得有汗，今头汗出，故知非少阴也，可与$f{小柴胡汤}。设不了了者，得屎而解。 159、伤寒五六日，呕而发热者，$n{柴胡汤}证具，而以他药下之，$n{柴胡证}仍在者，复与$n{柴胡汤}，此虽已下之，不为逆，必蒸蒸而振，却发热汗出而解。若心下满而鞕痛者，此为结胸也，$f{大陷胸汤}主之，但满而不痛者，此为痞，$u{柴胡}不中与之，宜$f{半夏泻心汤}。 160、太阳少阳并病，而反下之，成结胸，心下必鞕，若下利不止，水浆不下，其人必烦。 161、脉浮而紧，而复下之，紧反入里，则作痞，按之自濡，但气痞耳；$f{小青龙汤}主之。 162、太阳中风，下利，呕逆，表解者，乃可攻之，若其人絷絷汗出，发作有时，头痛，心下痞满，引胁下痛，干呕短气，汗出不恶寒者，此表解里未和也，$f{十枣汤}主之。 163、太阳病，医发汗，遂发热恶寒，因复下之，心下痞，表里俱虚，阴阳气并竭，无阳则阴独，复加烧针，因胸烦，面色青黄，肤瞤者，难治，今色微黄，手足温者易愈。 164、心下痞，按之濡，其脉关上浮大者，$f{大黄黄连黄芩泻心汤}主之。 165、心下痞，而复恶寒者，$f{附子泻心汤}主之。 166、本以下之，故心下痞，与泻心汤。痞不解，其人渴，而口燥烦，小便不利者，$f{五苓散}主之。 167、伤寒，汗出，解之后，胃中不和，心下痞鞕，干噫食臭，胁下有水气，腹中雷鸣，下利者，$f{生姜泻心汤}主之。 168、伤寒中风，医反下之，其人下利，日数十行，谷不化，腹中雷鸣，心下痞鞕而满，干呕，心烦不得安，医见心下痞，谓病不尽，复下之，其痞益甚，此非结热，但以胃中虚，客气上逆，故使鞕也，$f{甘草泻心汤}主之。 169、伤寒，服汤药下之，利不止，心下痞鞕，服泻心汤不已，复以他药下之，利益甚，医以理中与之，利仍不止，理中者，理中焦，此利在下焦故也，$f{赤石脂禹余粮汤}主之，复不止者，当利其小便。 170、伤寒吐下后，发汗，虚烦，脉甚微，八九日，心下痞鞕，胁下痛，气上冲咽喉，眩冒，经脉动惕者，久而成痿。 171、伤寒，发汗，若吐，若下，解后，心下痞鞕，噫气不除者，$f{旋覆代赭汤}主之。 172、太阳病，外证未除，而数下之，遂协热而利，利下不止，心下痞鞕，表里不解者，$f{桂枝人参汤}主之。 173、伤寒，大下后，复发汗，心下痞，恶寒者，表未解也，不可攻痞，当先解表，后攻其痞，解表宜$f{桂枝汤}；攻痞宜$f{大黄黄连黄芩泻心汤}。 174、伤寒发热，汗出不解，心下痞鞕，呕吐而不利者，$f{大柴胡汤}主之。 175、病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞鞕，气上咽喉，不得息者，此为胸有寒也，当吐之，宜$f{瓜蒂散}。 176、病胁下素有痞，连在脐旁，痛引少腹，入阴筋者，此名脏结，死。 177、伤寒，若吐，若下后，七八日不解，热结在里，表里俱热，时时恶风，大渴，舌上干燥而烦，欲饮水数升者，$f{白虎加人参汤}主之。 178、伤寒，无大热，口燥渴，心烦，背微恶寒者，$f{白虎加人参汤}主之。 179、伤寒，脉浮，发热，无汗，其表不解，当发汗，不可与$f{白虎汤}；渴欲饮，无表证者，$f{白虎加人参汤}主之。 180、太阳少阳并病，心下鞕，颈项强而眩者，当刺大椎、肺俞、肝俞，慎不可下也，下之则痉。 181、太阳与少阳合病，自下利者，与$f{黄芩汤}；若呕者，$f{黄芩加半夏生姜汤}主之。 182、伤寒，胸中有热，胃中有邪气，腹中痛，欲呕者，$f{黄连汤}主之。 183、伤寒，脉浮滑，此以里有热，表无寒也，$f{白虎汤}主之。 184、伤寒脉结促，心动悸者，$f{炙甘草汤}主之。', '2024-12-06T07:27:41.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UFtAP4FnkSC', 1, '{"title":"辨阳明病脉证并治","description":"<p>185、问曰：病有太阳阳明，有正阳阳明，有少阳阳明，何谓也？答曰：太阳阳明者，脾约是也，正阳阳明者，胃家实是也；少阳阳明者，发汗，利小便已，胃中燥烦实，大便难是也。</p><p>186、阳明之为病，胃家实是也。</p><p>187、问曰：何缘得阳明病？</p>\n<p></p>\n<p>      答曰：太阳病若发汗，若下，若利小便，此亡津液，胃中干燥，因转属阳明，不更衣，内实，大便难者，此名阳明也。</p><p>188、问曰：阳明病外证云何？答曰：身热，汗自出，不恶寒，反恶热也。</p><p>189、问曰：病有得之一日，不发热而恶寒者，何也？</p>\n<p> </p>\n<p>        答曰：虽得之一日，恶寒将自罢，即自汗出而恶热也。</p><p>190、问曰：恶寒何故自罢？</p>\n<p></p>\n<p>        答曰：阳明居中，主土也，万物所归，无所复传，始虽恶寒，二日自止，此为阳明病也。</p><p>191、本太阳病，初得病时发其汗，汗先出不彻，因转属阳明也。</p><p>192、伤寒发热，无汗，呕不能食，而反汗出濈濈然者，是转属阳明也。</p><p>193、伤寒三日，阳明脉大者，此为不传也。</p><p>194、伤寒，脉浮而缓，手足自温者，是为系在太阴；太阴者，身当发黄，若小便自利者，不能发黄；至七八日，大便鞕者，为阳明病也。</p><p>195、伤寒转属阳明者，其人濈然微汗出也。</p><p>196、阳明中风，口苦，咽干，腹满，微喘，发热，恶风，脉浮而缓，若下之，则腹满，小便难也。</p><p>197、阳明病若能食，名中风；不能食，名中寒。</p><p>198、阳明病，若中寒者，不能食，小便不利，手足濈然汗出，此欲作固瘕，必大便初鞕后溏。所以然者，以胃中冷，水谷不别故也。</p><p>199、阳明病，初欲食，小便不利，犬便自调，其人骨节疼，翕翕然如有热状，奄然发狂，濈然汗出而解者，此水不胜谷气，与汗共并，脉小则愈。</p><p>200、阳明病，欲解时，从申至戌上。</p><p>201、阳明病，不能食，攻其热必哕，所以然者，其人本虚，胃中冷故也。</p><p>202、阳明病，脉迟，食难用饱，饱则微烦，头眩，必小便难，此欲作谷疸，虽下之，腹满如故。所以然者，脉迟故也。</p><p>203、阳明病，法多汗，反无汗，其身如虫行皮中状者，此以久虚故也。</p><p>204、阳明病，反无汗，而小便利，二三日呕而咳，手足厥者，必苦头痛；若不咳，不呕，手足不厥者，头不痛。</p><p>205、阳明病，但头眩，不恶寒，故能食；若咳者，其人必咽痛；不咳者，咽不痛。</p><p>206、阳明病，无汗，小便不利，心中懊憹者，身必发黄。</p><p>207、阳明病，被火，额上微汗出，而小便不利者，必发黄。</p><p>208、阳明病，脉浮而大者，必潮热，发作有时，但浮者，必自汗出。</p><p>209、阳明病，口燥，但欲漱水，不欲咽者，此必衄。</p><p>210、阳明病，本自汗出，医更重发汗，病已差，尚微烦不了了者，此必大便鞕故也。以亡津液，胃中干燥，故令大便鞕。当问其小便日几行，若本小便日三四行，今日再行，则知大便不久必出。所以然者，以小便数少，津液当还入胃中，故知不久必大便也。</p><p>211、伤寒呕多，虽有阳明证，不可攻之。</p><p>212、阳明证，心下鞕满者，不可攻之，攻之，利遂不止者死，利止者愈。</p><p>213、阳明证，眼合色赤，不可攻之，攻之必发热，色黄者，小便不利也。</p><p>214、阳明病，不吐，不下，心烦者，可与$f{调胃承气汤}。</p><p>215、阳明病，脉实，虽汗出，而不恶热者，其身必重，短气，腹满而喘，有潮热者，此外欲解可攻里也，手足濈然汗出者，此大便已鞕也，$f{大承气汤}主之；若汗多，微发热恶寒者，外未解也，其热不潮者，未可与承气汤；若腹大满不通者，可与$f{小承气汤}，微和胃气，勿令大泄下。</p><p>216、阳明病潮热，大便微鞕者，可以$f{大承气汤}；不鞕者不可与之。若不大便六七日，恐有燥屎，欲知之法，少与$f{小承气汤}；汤入腹中，转失气者，此有燥屎也，乃可攻之；若不转失气者，此但初头鞕，后必溏，不可攻之，攻之必胀满，不能食也，欲饮水者，与水则哕；其后发热者，必大便复鞕而少也，以$f{小承气汤}和之；不转失气者，慎不可攻也。</p><p>217、阳明病，实则谵语，虚则郑声，郑声者重语也，直视，谵浯，喘满者，死；下利者，亦死。</p><p>218、阳明病，发汗多，若重发汗，以亡其阳，谵语，脉短者，死；脉自和者，不死。</p><p>219、伤寒，若吐，若下后，不解，不大便五六日，上至十余日，日晡所发潮热，不恶寒，独语如见鬼状；若剧者，发则不识人，循衣摸床，惕而不安，微喘，直视；脉弦者生，涩者死；微者，但发热，谵语者，$f{大承气汤}主之</p><p>220、阳明病，其人多汗，以津夜外出，胃中燥，大便必鞕，鞕则谵语，$f{小承气汤}主之。</p><p>221、阳明病，谵语，发热潮，脉滑而疾者，$f{小承气汤}主之。</p><p>222、阳明病，服$n{承气汤}后，不转失气，明日又不大便，脉反微涩者，里虚也，为难治，不可更与$n{承气汤}也。</p><p>223、阳明病，谵语，有潮热，反不能食者，胃中必有燥屎五六枚也，若能食者，但鞕尔，宜$f{大承气汤}下之。</p><p>224、阳明病，下血，谵语者，此为热入血室，但头汗出者，刺期门，随其实而泻之，濈然汗出则愈。</p><p>225、阳明病，汗出，谵语者，以有燥屎在胃中，此为实也，须过经乃可下之；下之若早，语言必乱，以表虚里实故也，下之宜$f{大承气汤}。</p><p>226、伤寒四五日，脉沉而喘满，沉为在里，而反发其汗，津液越出，大便为难，表虚里实，久则谵语。</p><p>227、三阳合病，腹满，身重，难以转侧，口不仁面垢，若发汗则谵语，遗尿，下之，则手足逆冷，额上出汗，若自汗者，宜$f{白虎汤}。自利者，宜$f{葛根黄连黄芩甘草汤}。</p><p>228、二阳并病，太阳证罢，但发潮热，手足絷絷汗出，大便难而谵语者，下之则愈，宜$f{大承气汤}。</p><p>229、阳明病，脉浮而大，咽燥口苦，腹满而喘，发热汗出，不恶寒，反恶热，身重；若发汗，则躁，心愦愦反谵语；若加温针，必怵惕，烦躁，不得眠；若下之，则胃中空虚，客气动膈，心中懊憹，舌上苔者，$f{栀子豉汤}主之。</p><p>230、阳明病，渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。</p><p>231、阳明病，脉浮，发热，渴欲饮水，小便不利者，$f{猪苓汤}主之。</p><p>232、阳明病，汗出多而渴者，不可与$f{猪苓汤}，以汗多胃中燥，$f{猪苓汤}复利其小便故也。</p><p>233、阳明病，脉浮而迟，表热里寒，下利清谷者，$f{四逆汤}主之。</p><p>234、阳明病，胃中虚冷，不能食者，不可与水饮之，饮则必哕。</p><p>235、阳明病，脉浮，发热，口干，鼻燥，能食者，衄。</p><p>236、阳明病，下之，其外有热，手足温，不结胸，心中懊憹，饥不能食，但头汗出者，$f{栀子豉汤}主之</p><p>237、阳明病，发潮热，大便溏，小便自可，胸胁满不去者，与$f{小柴胡汤}。</p><p>238、阳明病，胁下鞕满，不大便而呕，舌上白苔者，可与$f{小柴胡汤}，上焦得通，津液得下，胃气因和，身濈然汗出而解也。</p><p>239、阳明中风，脉弦浮大，而短气，腹都满，胁下及心痛，久按之气不通，鼻干不得涕，嗜卧，一身及目悉黄，小便难，有潮热，时时哕，耳前后肿，刺之小差，外不解，病过十日，脉续浮者，与$f{小柴胡汤}；脉但浮，无余证者，与麻黄汤；若不尿，腹满加哕者，不治。</p><p>240、动作头痛，短气，有潮热者，属阳明也，$f{白蜜煎}主之。</p><p>241、阳明病，自汗出，若发汗，小便自利者，此为津液内竭，便虽鞕不可攻之，当须自欲大便，宜$f{蜜煎导}而通之，若$n{王瓜根}，及$f{大猪胆汁}，皆可为导。</p><p>242、阳明病，脉迟，汗出多，微恶寒者，表未解也，可发汗，宜$f{桂枝汤}。</p><p>243、阳明病，脉浮，无汗而喘者，发汗则愈，宜$f{麻黄汤}。</p><p>244、阳明病，发热汗出者，此为热越，不能发黄也，但头汗出，身无汗，剂颈而还，小便不利，渴引水浆者，此为瘀热在里，身必发黄，$f{茵陈蒿汤}主之。</p><p>245、阳明病，其人善忘者，必有蓄血，所以然者，本有久瘀血，故令善忘，屎虽鞕，大便反易，其色必黑，宜$f{抵当汤}下之。</p><p>246、阳明病，下之，心中懊憹而烦，胃中有燥屎者，可攻；腹微满，大便初鞕后溏者，不可攻之，若有燥屎者宜$f{大承气汤}。</p><p>247、病人不大便五六日，绕脐痛，烦躁，发作有时者，此有燥屎，故使不大便也。</p><p>248、病人烦热，汗出则解，又如疟状，丑晡所发热者，属阳明也；脉实者，宜下之；脉浮大者，宜发汗。下之与$f{大承气汤}；发汗宜$f{桂枝汤}。</p><p>249、大下后，六七日不大便，烦不解，腹满痛者，此有燥屎也，所以然者，本有宿食故也，宜$f{大承气汤}。</p><p>250、病人小便不和，大便乍难乍易，时有微热，喘息不能卧者，有燥屎也，宜${大承气汤}。</p><p>251、食谷欲呕者，属阳明也，$f{吴茱萸汤}主之。得汤反剧者，属上焦也，${小半夏汤}主之。</p><p>252、太阳病，寸缓，关浮，尺弱，其人发热汗出，复恶寒，不呕，但心下痞者，此以医下之。如其未下，病人不恶寒而渴者，此转属阳明也。小便数者，大便必鞕，不更衣十日，无所苦也，渴欲饮水者，少少与之，以法救之。渴而饮水多小便不利者，宜$f{五苓散}。</p><p>253、脉阳微而汗出少者，为自和；汗出多者，为太过；阳脉实，因发其汗，出多者，亦为太过，太过者，为阳绝于里，亡津液，大便因鞕也。</p><p>254、脉浮而芤，浮为阳，芤为阴，浮芤相搏，胃气生热，其阳则绝。</p><p>255、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮数相搏，大便则鞕，其脾为约，$f{麻子仁丸}主之。</p><p>256、太阳病二日，发汗不解，蒸蒸发热者，属阳明也，调$f{胃承气汤}主之。</p><p>257、伤寒吐后，腹胀满者，与$f{调胃承气汤}。</p><p>258、太阳病，若吐，若下，若发汗后，微烦，小便数，大便因鞕者，与${小承气汤}和之愈。</p><p>259、得病二三日，脉弱，无$n太阳柴胡}证，烦躁，心下鞕，至四五日，虽能食，以$f{小承气汤}少少与，微和之，令小安。至六日与$f{小承气汤}$q{一升}。若不大便六七日，小便少者，虽不大便，但初头鞕，后必溏，未定成鞕，攻之必溏，须小便利，屎定鞕，乃可攻之，宜$f{大承气汤}。</p><p>260、伤寒六七日，目中不了了，睛不和，无表里证，大便难，身微热者，此为实也，急下之，宜$f{大承气汤}。</p><p>261、阳明病，发热汗多者，急下之，宜$f{大承气汤}。</p><p>262、发汗，不解，腹满痛者，急下之，宜$f{大承气汤}。</p><p>263、腹满不减，减不足言，当下之，宜$f{大承气汤}。</p><p>264、阳明少阳合病，必下利，其脉不负者，为顺也；负者，失也。互相克责，名为负也。脉滑而数者，有宿食也，当下之，宜$f{大承气汤}。</p><p>265、病人无表里证，发热七八日，虽脉浮数者，可下之；假令已下，脉数不解，合热则消谷善饥，至六七日不大便者，有瘀血也，宜$f{抵当汤}；若脉数不解，而下利不止，必协热便脓血也。</p><p>266、伤寒，发汗已，身目为黄，所以然者，以寒湿在里，不解故也，不可汗也，当于寒湿中求之。</p><p>267、伤寒七八日，身黄如橘子色，小便不利，腹微满者，$f{茵陈蒿汤}主之。(</p><p>268、伤寒，身黄，发热者，$f{栀子柏皮汤}主之。</p><p>269、伤寒瘀热在里，其身必黄，$f{麻黄连轺赤小豆汤}主之。</p><p>270、阳明病，身热，不能食，食即头眩，心胸不安，久久发黄，此名谷疸，$f{茵陈蒿汤}主之。</p><p>271、阳明病，身热，发黄，心中懊憹，或热痛，因于酒食者，此名酒疸，$f{栀子大黄汤}主之。</p><p>272、阳明病，身黄，津液枯燥，色暗不明者，此热入于血分也，$f{猪膏发煎}主之。</p><p>273、黄疸，腹满，小便不利而赤，自汗出，此为表和里实，当下之，宜$f{大黄硝石汤}。</p><p>274、诸黄，腹痛而呕者，宜$f{大柴胡汤}。</p><p>275、黄病，小便色不变，自利，腹满而喘者，不可除热，除热必哕，哕者，$f{小半夏汤}主之。</p><p>276、诸黄家，但利其小便，$f{五苓散}加$u{茵陈蒿}主之；假令脉浮，当以汗解者，宜$f{桂枝加黄芪汤}。</p><p>277、诸黄，小便自利者，当以虚劳法，$f{小建中汤}主之。</p><p>278、阳明病，腹满，小便不利，舌萎黄燥，不得眠者，此属黄家。</p><p>279、黄疸病，当以十八日为期，治之十日以上瘥，反剧者，为难治。</p><p>280、夫病，脉沉，渴欲饮水，小便不利者，后必发黄。</p><p>281、趺阳脉微而弦，法当腹满，若不满者，必大便难，两胠疼痛，此为虚寒，当温之，宜$f{吴茱萸汤}。</p><p>282、夫病人腹痛绕脐，此为阳明风冷，谷气不行，若反下之，其气必冲，若不冲者，心下则痞，当温之，宜$f{理中汤}。</p><p>283、阳明病发热，十余日，脉浮而数，腹满，饮食如故者，$f{厚朴七物汤}主之。</p><p>284、阳明病，腹中切痛，雷鸣，逆满，呕吐者，此虚寒也，$f{附子粳米汤}主之。</p><p>285、阳明病，腹中寒痛，呕不能食，有物突起，如见头足，痛不可近者，$f{大建中汤}主之。</p><p>286、阳明病，腹满，胁下偏痛，发微热，其脉弦紧者，当以温药下之，宜$f{大黄附子细辛汤}。</p><p>287、问曰：阳明宿食何以别之？</p>\n<p></p>\n<p>          师曰：寸口脉浮而大，按之反涩，尺中亦微而涩，故知其有宿食也，$f{大承气汤}主之。</p><p>288、寸口脉数而滑者，此为有宿食也。</p><p>289、下利不欲食者，此为有宿食也。</p><p>290、脉紧如转索者，此为有宿食也。</p><p>291、脉紧，腹中痛，恶风寒者，此为有宿食也。</p><p>292、宿食在上脘者，法当吐之，宜$f{瓜蒂散}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010018,"no":18}}', '2024-12-06T07:28:03.000Z', '2024-12-06T07:28:03.000Z', '2024-12-06T07:28:03.000Z', '185、问曰：病有太阳阳明，有正阳阳明，有少阳阳明，何谓也？答曰：太阳阳明者，脾约是也，正阳阳明者，胃家实是也；少阳阳明者，发汗，利小便已，胃中燥烦实，大便难是也。 186、阳明之为病，胃家实是也。 187、问曰：何缘得阳明病？ 答曰：太阳病若发汗，若下，若利小便，此亡津液，胃中干燥，因转属阳明，不更衣，内实，大便难者，此名阳明也。 188、问曰：阳明病外证云何？答曰：身热，汗自出，不恶寒，反恶热也。 189、问曰：病有得之一日，不发热而恶寒者，何也？ 答曰：虽得之一日，恶寒将自罢，即自汗出而恶热也。 190、问曰：恶寒何故自罢？ 答曰：阳明居中，主土也，万物所归，无所复传，始虽恶寒，二日自止，此为阳明病也。 191、本太阳病，初得病时发其汗，汗先出不彻，因转属阳明也。 192、伤寒发热，无汗，呕不能食，而反汗出濈濈然者，是转属阳明也。 193、伤寒三日，阳明脉大者，此为不传也。 194、伤寒，脉浮而缓，手足自温者，是为系在太阴；太阴者，身当发黄，若小便自利者，不能发黄；至七八日，大便鞕者，为阳明病也。 195、伤寒转属阳明者，其人濈然微汗出也。 196、阳明中风，口苦，咽干，腹满，微喘，发热，恶风，脉浮而缓，若下之，则腹满，小便难也。 197、阳明病若能食，名中风；不能食，名中寒。 198、阳明病，若中寒者，不能食，小便不利，手足濈然汗出，此欲作固瘕，必大便初鞕后溏。所以然者，以胃中冷，水谷不别故也。 199、阳明病，初欲食，小便不利，犬便自调，其人骨节疼，翕翕然如有热状，奄然发狂，濈然汗出而解者，此水不胜谷气，与汗共并，脉小则愈。 200、阳明病，欲解时，从申至戌上。 201、阳明病，不能食，攻其热必哕，所以然者，其人本虚，胃中冷故也。 202、阳明病，脉迟，食难用饱，饱则微烦，头眩，必小便难，此欲作谷疸，虽下之，腹满如故。所以然者，脉迟故也。 203、阳明病，法多汗，反无汗，其身如虫行皮中状者，此以久虚故也。 204、阳明病，反无汗，而小便利，二三日呕而咳，手足厥者，必苦头痛；若不咳，不呕，手足不厥者，头不痛。 205、阳明病，但头眩，不恶寒，故能食；若咳者，其人必咽痛；不咳者，咽不痛。 206、阳明病，无汗，小便不利，心中懊憹者，身必发黄。 207、阳明病，被火，额上微汗出，而小便不利者，必发黄。 208、阳明病，脉浮而大者，必潮热，发作有时，但浮者，必自汗出。 209、阳明病，口燥，但欲漱水，不欲咽者，此必衄。 210、阳明病，本自汗出，医更重发汗，病已差，尚微烦不了了者，此必大便鞕故也。以亡津液，胃中干燥，故令大便鞕。当问其小便日几行，若本小便日三四行，今日再行，则知大便不久必出。所以然者，以小便数少，津液当还入胃中，故知不久必大便也。 211、伤寒呕多，虽有阳明证，不可攻之。 212、阳明证，心下鞕满者，不可攻之，攻之，利遂不止者死，利止者愈。 213、阳明证，眼合色赤，不可攻之，攻之必发热，色黄者，小便不利也。 214、阳明病，不吐，不下，心烦者，可与$f{调胃承气汤}。 215、阳明病，脉实，虽汗出，而不恶热者，其身必重，短气，腹满而喘，有潮热者，此外欲解可攻里也，手足濈然汗出者，此大便已鞕也，$f{大承气汤}主之；若汗多，微发热恶寒者，外未解也，其热不潮者，未可与承气汤；若腹大满不通者，可与$f{小承气汤}，微和胃气，勿令大泄下。 216、阳明病潮热，大便微鞕者，可以$f{大承气汤}；不鞕者不可与之。若不大便六七日，恐有燥屎，欲知之法，少与$f{小承气汤}；汤入腹中，转失气者，此有燥屎也，乃可攻之；若不转失气者，此但初头鞕，后必溏，不可攻之，攻之必胀满，不能食也，欲饮水者，与水则哕；其后发热者，必大便复鞕而少也，以$f{小承气汤}和之；不转失气者，慎不可攻也。 217、阳明病，实则谵语，虚则郑声，郑声者重语也，直视，谵浯，喘满者，死；下利者，亦死。 218、阳明病，发汗多，若重发汗，以亡其阳，谵语，脉短者，死；脉自和者，不死。 219、伤寒，若吐，若下后，不解，不大便五六日，上至十余日，日晡所发潮热，不恶寒，独语如见鬼状；若剧者，发则不识人，循衣摸床，惕而不安，微喘，直视；脉弦者生，涩者死；微者，但发热，谵语者，$f{大承气汤}主之 220、阳明病，其人多汗，以津夜外出，胃中燥，大便必鞕，鞕则谵语，$f{小承气汤}主之。 221、阳明病，谵语，发热潮，脉滑而疾者，$f{小承气汤}主之。 222、阳明病，服$n{承气汤}后，不转失气，明日又不大便，脉反微涩者，里虚也，为难治，不可更与$n{承气汤}也。 223、阳明病，谵语，有潮热，反不能食者，胃中必有燥屎五六枚也，若能食者，但鞕尔，宜$f{大承气汤}下之。 224、阳明病，下血，谵语者，此为热入血室，但头汗出者，刺期门，随其实而泻之，濈然汗出则愈。 225、阳明病，汗出，谵语者，以有燥屎在胃中，此为实也，须过经乃可下之；下之若早，语言必乱，以表虚里实故也，下之宜$f{大承气汤}。 226、伤寒四五日，脉沉而喘满，沉为在里，而反发其汗，津液越出，大便为难，表虚里实，久则谵语。 227、三阳合病，腹满，身重，难以转侧，口不仁面垢，若发汗则谵语，遗尿，下之，则手足逆冷，额上出汗，若自汗者，宜$f{白虎汤}。自利者，宜$f{葛根黄连黄芩甘草汤}。 228、二阳并病，太阳证罢，但发潮热，手足絷絷汗出，大便难而谵语者，下之则愈，宜$f{大承气汤}。 229、阳明病，脉浮而大，咽燥口苦，腹满而喘，发热汗出，不恶寒，反恶热，身重；若发汗，则躁，心愦愦反谵语；若加温针，必怵惕，烦躁，不得眠；若下之，则胃中空虚，客气动膈，心中懊憹，舌上苔者，$f{栀子豉汤}主之。 230、阳明病，渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。 231、阳明病，脉浮，发热，渴欲饮水，小便不利者，$f{猪苓汤}主之。 232、阳明病，汗出多而渴者，不可与$f{猪苓汤}，以汗多胃中燥，$f{猪苓汤}复利其小便故也。 233、阳明病，脉浮而迟，表热里寒，下利清谷者，$f{四逆汤}主之。 234、阳明病，胃中虚冷，不能食者，不可与水饮之，饮则必哕。 235、阳明病，脉浮，发热，口干，鼻燥，能食者，衄。 236、阳明病，下之，其外有热，手足温，不结胸，心中懊憹，饥不能食，但头汗出者，$f{栀子豉汤}主之 237、阳明病，发潮热，大便溏，小便自可，胸胁满不去者，与$f{小柴胡汤}。 238、阳明病，胁下鞕满，不大便而呕，舌上白苔者，可与$f{小柴胡汤}，上焦得通，津液得下，胃气因和，身濈然汗出而解也。 239、阳明中风，脉弦浮大，而短气，腹都满，胁下及心痛，久按之气不通，鼻干不得涕，嗜卧，一身及目悉黄，小便难，有潮热，时时哕，耳前后肿，刺之小差，外不解，病过十日，脉续浮者，与$f{小柴胡汤}；脉但浮，无余证者，与麻黄汤；若不尿，腹满加哕者，不治。 240、动作头痛，短气，有潮热者，属阳明也，$f{白蜜煎}主之。 241、阳明病，自汗出，若发汗，小便自利者，此为津液内竭，便虽鞕不可攻之，当须自欲大便，宜$f{蜜煎导}而通之，若$n{王瓜根}，及$f{大猪胆汁}，皆可为导。 242、阳明病，脉迟，汗出多，微恶寒者，表未解也，可发汗，宜$f{桂枝汤}。 243、阳明病，脉浮，无汗而喘者，发汗则愈，宜$f{麻黄汤}。 244、阳明病，发热汗出者，此为热越，不能发黄也，但头汗出，身无汗，剂颈而还，小便不利，渴引水浆者，此为瘀热在里，身必发黄，$f{茵陈蒿汤}主之。 245、阳明病，其人善忘者，必有蓄血，所以然者，本有久瘀血，故令善忘，屎虽鞕，大便反易，其色必黑，宜$f{抵当汤}下之。 246、阳明病，下之，心中懊憹而烦，胃中有燥屎者，可攻；腹微满，大便初鞕后溏者，不可攻之，若有燥屎者宜$f{大承气汤}。 247、病人不大便五六日，绕脐痛，烦躁，发作有时者，此有燥屎，故使不大便也。 248、病人烦热，汗出则解，又如疟状，丑晡所发热者，属阳明也；脉实者，宜下之；脉浮大者，宜发汗。下之与$f{大承气汤}；发汗宜$f{桂枝汤}。 249、大下后，六七日不大便，烦不解，腹满痛者，此有燥屎也，所以然者，本有宿食故也，宜$f{大承气汤}。 250、病人小便不和，大便乍难乍易，时有微热，喘息不能卧者，有燥屎也，宜${大承气汤}。 251、食谷欲呕者，属阳明也，$f{吴茱萸汤}主之。得汤反剧者，属上焦也，${小半夏汤}主之。 252、太阳病，寸缓，关浮，尺弱，其人发热汗出，复恶寒，不呕，但心下痞者，此以医下之。如其未下，病人不恶寒而渴者，此转属阳明也。小便数者，大便必鞕，不更衣十日，无所苦也，渴欲饮水者，少少与之，以法救之。渴而饮水多小便不利者，宜$f{五苓散}。 253、脉阳微而汗出少者，为自和；汗出多者，为太过；阳脉实，因发其汗，出多者，亦为太过，太过者，为阳绝于里，亡津液，大便因鞕也。 254、脉浮而芤，浮为阳，芤为阴，浮芤相搏，胃气生热，其阳则绝。 255、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮数相搏，大便则鞕，其脾为约，$f{麻子仁丸}主之。 256、太阳病二日，发汗不解，蒸蒸发热者，属阳明也，调$f{胃承气汤}主之。 257、伤寒吐后，腹胀满者，与$f{调胃承气汤}。 258、太阳病，若吐，若下，若发汗后，微烦，小便数，大便因鞕者，与${小承气汤}和之愈。 259、得病二三日，脉弱，无$n太阳柴胡}证，烦躁，心下鞕，至四五日，虽能食，以$f{小承气汤}少少与，微和之，令小安。至六日与$f{小承气汤}$q{一升}。若不大便六七日，小便少者，虽不大便，但初头鞕，后必溏，未定成鞕，攻之必溏，须小便利，屎定鞕，乃可攻之，宜$f{大承气汤}。 260、伤寒六七日，目中不了了，睛不和，无表里证，大便难，身微热者，此为实也，急下之，宜$f{大承气汤}。 261、阳明病，发热汗多者，急下之，宜$f{大承气汤}。 262、发汗，不解，腹满痛者，急下之，宜$f{大承气汤}。 263、腹满不减，减不足言，当下之，宜$f{大承气汤}。 264、阳明少阳合病，必下利，其脉不负者，为顺也；负者，失也。互相克责，名为负也。脉滑而数者，有宿食也，当下之，宜$f{大承气汤}。 265、病人无表里证，发热七八日，虽脉浮数者，可下之；假令已下，脉数不解，合热则消谷善饥，至六七日不大便者，有瘀血也，宜$f{抵当汤}；若脉数不解，而下利不止，必协热便脓血也。 266、伤寒，发汗已，身目为黄，所以然者，以寒湿在里，不解故也，不可汗也，当于寒湿中求之。 267、伤寒七八日，身黄如橘子色，小便不利，腹微满者，$f{茵陈蒿汤}主之。( 268、伤寒，身黄，发热者，$f{栀子柏皮汤}主之。 269、伤寒瘀热在里，其身必黄，$f{麻黄连轺赤小豆汤}主之。 270、阳明病，身热，不能食，食即头眩，心胸不安，久久发黄，此名谷疸，$f{茵陈蒿汤}主之。 271、阳明病，身热，发黄，心中懊憹，或热痛，因于酒食者，此名酒疸，$f{栀子大黄汤}主之。 272、阳明病，身黄，津液枯燥，色暗不明者，此热入于血分也，$f{猪膏发煎}主之。 273、黄疸，腹满，小便不利而赤，自汗出，此为表和里实，当下之，宜$f{大黄硝石汤}。 274、诸黄，腹痛而呕者，宜$f{大柴胡汤}。 275、黄病，小便色不变，自利，腹满而喘者，不可除热，除热必哕，哕者，$f{小半夏汤}主之。 276、诸黄家，但利其小便，$f{五苓散}加$u{茵陈蒿}主之；假令脉浮，当以汗解者，宜$f{桂枝加黄芪汤}。 277、诸黄，小便自利者，当以虚劳法，$f{小建中汤}主之。 278、阳明病，腹满，小便不利，舌萎黄燥，不得眠者，此属黄家。 279、黄疸病，当以十八日为期，治之十日以上瘥，反剧者，为难治。 280、夫病，脉沉，渴欲饮水，小便不利者，后必发黄。 281、趺阳脉微而弦，法当腹满，若不满者，必大便难，两胠疼痛，此为虚寒，当温之，宜$f{吴茱萸汤}。 282、夫病人腹痛绕脐，此为阳明风冷，谷气不行，若反下之，其气必冲，若不冲者，心下则痞，当温之，宜$f{理中汤}。 283、阳明病发热，十余日，脉浮而数，腹满，饮食如故者，$f{厚朴七物汤}主之。 284、阳明病，腹中切痛，雷鸣，逆满，呕吐者，此虚寒也，$f{附子粳米汤}主之。 285、阳明病，腹中寒痛，呕不能食，有物突起，如见头足，痛不可近者，$f{大建中汤}主之。 286、阳明病，腹满，胁下偏痛，发微热，其脉弦紧者，当以温药下之，宜$f{大黄附子细辛汤}。 287、问曰：阳明宿食何以别之？ 师曰：寸口脉浮而大，按之反涩，尺中亦微而涩，故知其有宿食也，$f{大承气汤}主之。 288、寸口脉数而滑者，此为有宿食也。 289、下利不欲食者，此为有宿食也。 290、脉紧如转索者，此为有宿食也。 291、脉紧，腹中痛，恶风寒者，此为有宿食也。 292、宿食在上脘者，法当吐之，宜$f{瓜蒂散}。', '2024-12-06T07:28:03.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kw7bbKT09Yb', 1, '{"title":"辨少阳病脉证并治","description":"<p>293、少阳之为病，口苦，咽干，目眩是也。</p><p>294、少阳中风，两耳无所闻，目赤，胸中满而烦者，不可吐、下，吐、下则悸而惊。</p><p>295、伤寒，脉弦细，头痛，发热者，属少阳，不可发汗，汗则谵语，烦躁，此属胃不和也，和之则愈。</p><p>296、本太阳病，不解，转入少阳者，胁下鞕满，干呕不能食，往来寒热，脉沉弦者，不可吐、下，与$f{小柴胡汤}。</p><p>297、少阳病，气上逆，今胁下痛，甚则呕逆，此为胆气不降也，$f{柴胡芍药枳实甘草汤}主之。</p><p>298、若以吐、下，发汗，温针，谵语，$n{柴胡汤证}罢者，此为坏病，知犯何逆，以法救之，$n{柴胡汤}不中与也。</p><p>299、三阳合病，脉浮大，上关上，但欲眠睡，目合则汗，此上焦不通故也，宜$f{小柴胡汤}。</p><p>300、伤寒四五日，无大热，其人躁烦者，此为阳去入阴故也。</p><p>301、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕者，此为三阴不受邪也。</p><p>302、伤寒三日，少阳脉小者，为欲已也。</p><p>303、少阳病欲解时，从寅至辰上。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010019,"no":19}}', '2024-12-06T07:28:21.000Z', '2024-12-06T07:28:21.000Z', '2024-12-06T07:28:21.000Z', '293、少阳之为病，口苦，咽干，目眩是也。 294、少阳中风，两耳无所闻，目赤，胸中满而烦者，不可吐、下，吐、下则悸而惊。 295、伤寒，脉弦细，头痛，发热者，属少阳，不可发汗，汗则谵语，烦躁，此属胃不和也，和之则愈。 296、本太阳病，不解，转入少阳者，胁下鞕满，干呕不能食，往来寒热，脉沉弦者，不可吐、下，与$f{小柴胡汤}。 297、少阳病，气上逆，今胁下痛，甚则呕逆，此为胆气不降也，$f{柴胡芍药枳实甘草汤}主之。 298、若以吐、下，发汗，温针，谵语，$n{柴胡汤证}罢者，此为坏病，知犯何逆，以法救之，$n{柴胡汤}不中与也。 299、三阳合病，脉浮大，上关上，但欲眠睡，目合则汗，此上焦不通故也，宜$f{小柴胡汤}。 300、伤寒四五日，无大热，其人躁烦者，此为阳去入阴故也。 301、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕者，此为三阴不受邪也。 302、伤寒三日，少阳脉小者，为欲已也。 303、少阳病欲解时，从寅至辰上。', '2024-12-06T07:28:21.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XZHluCE3O7Q', 1, '{"title":"辨太阴病脉证并治","description":"<p>304、太阴之为病，腹满而吐，食不下，自利益甚，时腹自痛，若下之必胸下结鞕。</p><p>305、太阴中风，四肢烦疼，阳微阴涩而长者，为欲愈。</p><p>306、太阴病，脉浮者，可发汗，宜$f{桂枝汤}。</p><p>307、自利不渴者，属太阴，以其脏有寒故也，当温之，宜服$n{理中}、$n{四逆}辈。</p><p>308、伤寒，脉浮而缓，手足自温者，系在太阴。太阴当发身黄，若小便自利者，不能发黄。至七八日，虽暴烦，下利日十余行。必自止，以脾家实，腐秽当去故也。</p><p>309、本太阳病，医反下之，因尔腹满时痛者，属太阴也，$f{桂枝加芍药汤}主之；大实痛者，$f{桂枝加大黄汤}主之。</p><p>310、太阴病，脉弱，其人续自便利，设当行大黄芍药者，宜减之，以其人胃气弱，易动故也。</p><p>311、太阴病，大便反鞕，腹中胀满者，此脾气不转也，宜$f{白术枳实干姜白蜜汤}，若不胀满，反短气者，$f{黄芪五物汤加干姜半夏}主之。</p><p>312、太阴病，渴欲饮水，饮水即吐者，此为水在膈上，宜$f{半夏茯苓汤}。</p><p>313、太阴病，下利，口渴，脉虚而微数者，此津液伤也，宜$f{人参白术芍药甘草汤}。</p><p>314、太阴病，不下利、吐逆，但苦腹大而胀者，此脾气实也，$f{厚朴四物汤}主之。</p><p>315、太阴病，不吐、不满，但遗矢无度者，虚故也，$f{理中加黄芪汤}主之。</p><p>316、太阴病，欲吐不吐，下利时甚时疏，脉浮涩者，$f{桂枝去芍药加茯苓白术汤}主之。</p><p>317、太阴病，吐逆，腹中冷痛，雷鸣下利，脉沉紧者，$f{小柴胡加茯苓白术汤}主之。</p><p>318、太阴病，有宿食，脉滑而实者，可下之，宜承气辈，若大便溏者，宜$f{厚朴枳实白术甘草汤}。</p><p>319、太阴病欲解时，从亥至丑上。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010020,"no":20}}', '2024-12-06T07:28:39.000Z', '2024-12-06T07:28:39.000Z', '2024-12-06T07:28:39.000Z', '304、太阴之为病，腹满而吐，食不下，自利益甚，时腹自痛，若下之必胸下结鞕。 305、太阴中风，四肢烦疼，阳微阴涩而长者，为欲愈。 306、太阴病，脉浮者，可发汗，宜$f{桂枝汤}。 307、自利不渴者，属太阴，以其脏有寒故也，当温之，宜服$n{理中}、$n{四逆}辈。 308、伤寒，脉浮而缓，手足自温者，系在太阴。太阴当发身黄，若小便自利者，不能发黄。至七八日，虽暴烦，下利日十余行。必自止，以脾家实，腐秽当去故也。 309、本太阳病，医反下之，因尔腹满时痛者，属太阴也，$f{桂枝加芍药汤}主之；大实痛者，$f{桂枝加大黄汤}主之。 310、太阴病，脉弱，其人续自便利，设当行大黄芍药者，宜减之，以其人胃气弱，易动故也。 311、太阴病，大便反鞕，腹中胀满者，此脾气不转也，宜$f{白术枳实干姜白蜜汤}，若不胀满，反短气者，$f{黄芪五物汤加干姜半夏}主之。 312、太阴病，渴欲饮水，饮水即吐者，此为水在膈上，宜$f{半夏茯苓汤}。 313、太阴病，下利，口渴，脉虚而微数者，此津液伤也，宜$f{人参白术芍药甘草汤}。 314、太阴病，不下利、吐逆，但苦腹大而胀者，此脾气实也，$f{厚朴四物汤}主之。 315、太阴病，不吐、不满，但遗矢无度者，虚故也，$f{理中加黄芪汤}主之。 316、太阴病，欲吐不吐，下利时甚时疏，脉浮涩者，$f{桂枝去芍药加茯苓白术汤}主之。 317、太阴病，吐逆，腹中冷痛，雷鸣下利，脉沉紧者，$f{小柴胡加茯苓白术汤}主之。 318、太阴病，有宿食，脉滑而实者，可下之，宜承气辈，若大便溏者，宜$f{厚朴枳实白术甘草汤}。 319、太阴病欲解时，从亥至丑上。', '2024-12-06T07:28:39.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6c40chGIzw0', 1, '{"title":"辨少阴病脉证并治","description":"<p>320、少阴之为病，脉微细，但欲寐也。</p><p>321、少阴病，欲吐不吐，心烦，但欲寐，五六日，自利而渴者，属少阴也，虚，故饮水自救；若小便色白者，少阴病形悉具；小便白者，以下焦虚寒，不能制水，故令色白也。</p><p>322、病人脉阴阳俱紧，反汗出者，亡阳也；此属少阴，法当咽痛，而复吐、利。</p><p>323、少阴病咳而下利，语语者，被火劫故也，小便必难，以强责少阴汗也。</p><p>324、少阴病脉细沉数，病为在里，不可发汗。</p><p>325、少阴病脉微，不可发汗，亡阳故也；阳已虚，尺脉弱涩者，复不可下之。</p><p>326、少阴病脉紧，至七八日，自下利，脉暴微，手足反温，脉紧反去者，为欲解也，虽烦，下利，必自愈。</p><p>327、少阴病，下利，若利自止，恶寒而蜷卧，手足温者，可治。</p><p>328、少阴病，恶寒而蜷，时自烦，欲去衣被者，可治。</p><p>329、少阴中风，脉阳微阴浮者，为欲愈。</p><p>330、少阴病欲解时，从子至寅上。</p><p>331、少阴病，吐、利，手足不逆冷，反发热者，不死。脉不至者，灸少阴七壮。</p><p>332、少阴病八九日，一身手足尽热者，以热在膀胱，必便血也。</p><p>333、少阴病但厥，无汗，而强发之，必动其血，未知从何道而出，或从口鼻，或从耳出者，是名下厥上竭，为难治。</p><p>334、少阴病，恶寒，身蜷而利，手足逆冷者，不治。</p><p>335、少阴病，吐利，躁烦，四逆者，死。</p><p>336、少阴病，下利止，而头眩时时自冒者，死。</p><p>337、少阴病四逆，恶寒，而身蜷，脉不至，心烦而躁者，死。</p><p>338、少阴病，六七日，息高者，死。</p><p>339、少阴病，脉微细沉，但欲卧，汗出不烦，自欲吐，至五六日，自利，复烦躁不得卧寐者，死。</p><p>340、少阴病始得之，反发热，脉沉者，$f{麻黄附子细辛汤}主之。</p><p>341、少阴病，得之二三日，$f{麻黄附子甘草汤}微发汗，以二三日无里证，故微发汗也。</p><p>342、少阴病，得之二三日以上，心中烦，不得卧者，$f{黄连阿胶汤}主之。</p><p>343、少阴病，得之一二日，口中和，其背恶寒者，当灸之，$f{附子汤}主之。</p><p>344、少阴病，身体痛，手足寒，骨节痛，脉沉者，$f{附子汤}主之。</p><p>345、少阴病，脉微而弱，身痛如掣者，此荣卫不和故也，$f{当归四逆汤}主之。</p><p>346、少阴病下利便脓血者，$f{桃花汤}主之。</p><p>347、少阴病，二三日至四五日，腹痛，小便不利，下利不止，便脓血者，$f{桃花汤}主之。</p><p>348、少阴病，下利便脓血者，可刺足阳明。</p><p>349、少阴病，吐，利，手足逆冷，烦躁欲死者，$f{吴茱萸汤}主之。</p><p>350、少阴病，下利，咽痛，胸满，心烦者，$f{猪肤汤}主之。</p><p>351、少阴病，二三日咽中痛者，可与$f{甘草汤}；不差，与$f{桔梗汤}。</p><p>352、少阴病，咽中伤，生疮，痛引喉旁，不能语言，声不出者，$f{苦酒汤}主之。</p><p>353、少阴病，咽中痛，脉反浮者，$f{半夏散及汤}主之。</p><p>354、少阴病，下利，$f{白通汤}主之。</p><p>355、少阴病，下利，脉微者，与白通汤；利不止，厥逆无脉，干呕烦者，$f{白通加猪胆汁汤}主之；服汤后，脉暴出者死；微续者生。</p><p>356、少阴病二三日不已，至四五日，腹痛，小便不利，四肢沉重疼痛，自下利者，此为有水气，其人或咳，或小便不利，或下利，或呕者，$f{真武汤}主之。</p><p>357、少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面色赤，或腹痛，或干呕，或咽痛，或利止，脉不出者，$f{通脉四逆汤}主之。</p><p>358、少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，$f{四逆散}主之。</p><p>359、少阴病，下利六七日，咳而呕，渴，心烦不得眠者，$f{猪苓汤}主之。</p><p>360、少阴病，得之二三日，口燥咽干者，急下之，宜$f{大承气汤}。</p><p>361、少阴病，自利清水，色纯青，心下必痛，口干燥者，可下之，宜$f{大承气汤}。</p><p>362、少阴病，六七日，腹胀不大便者，急下之，宜$f{大承气汤}。</p><p>363、少阴病，脉沉者，急温之，宜$f{四逆汤}。</p><p>364、少阴病，饮食入口即吐，或心中温温欲吐，复不能吐，始得之，手足寒，脉弦迟者，此胸中实，不可下也，当吐之；若膈上有寒饮，干呕者，不可吐也，当温之，宜$f{四逆汤}。</p><p>365、少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010021,"no":21}}', '2024-12-06T07:28:55.000Z', '2024-12-06T07:28:55.000Z', '2024-12-06T07:28:55.000Z', '320、少阴之为病，脉微细，但欲寐也。 321、少阴病，欲吐不吐，心烦，但欲寐，五六日，自利而渴者，属少阴也，虚，故饮水自救；若小便色白者，少阴病形悉具；小便白者，以下焦虚寒，不能制水，故令色白也。 322、病人脉阴阳俱紧，反汗出者，亡阳也；此属少阴，法当咽痛，而复吐、利。 323、少阴病咳而下利，语语者，被火劫故也，小便必难，以强责少阴汗也。 324、少阴病脉细沉数，病为在里，不可发汗。 325、少阴病脉微，不可发汗，亡阳故也；阳已虚，尺脉弱涩者，复不可下之。 326、少阴病脉紧，至七八日，自下利，脉暴微，手足反温，脉紧反去者，为欲解也，虽烦，下利，必自愈。 327、少阴病，下利，若利自止，恶寒而蜷卧，手足温者，可治。 328、少阴病，恶寒而蜷，时自烦，欲去衣被者，可治。 329、少阴中风，脉阳微阴浮者，为欲愈。 330、少阴病欲解时，从子至寅上。 331、少阴病，吐、利，手足不逆冷，反发热者，不死。脉不至者，灸少阴七壮。 332、少阴病八九日，一身手足尽热者，以热在膀胱，必便血也。 333、少阴病但厥，无汗，而强发之，必动其血，未知从何道而出，或从口鼻，或从耳出者，是名下厥上竭，为难治。 334、少阴病，恶寒，身蜷而利，手足逆冷者，不治。 335、少阴病，吐利，躁烦，四逆者，死。 336、少阴病，下利止，而头眩时时自冒者，死。 337、少阴病四逆，恶寒，而身蜷，脉不至，心烦而躁者，死。 338、少阴病，六七日，息高者，死。 339、少阴病，脉微细沉，但欲卧，汗出不烦，自欲吐，至五六日，自利，复烦躁不得卧寐者，死。 340、少阴病始得之，反发热，脉沉者，$f{麻黄附子细辛汤}主之。 341、少阴病，得之二三日，$f{麻黄附子甘草汤}微发汗，以二三日无里证，故微发汗也。 342、少阴病，得之二三日以上，心中烦，不得卧者，$f{黄连阿胶汤}主之。 343、少阴病，得之一二日，口中和，其背恶寒者，当灸之，$f{附子汤}主之。 344、少阴病，身体痛，手足寒，骨节痛，脉沉者，$f{附子汤}主之。 345、少阴病，脉微而弱，身痛如掣者，此荣卫不和故也，$f{当归四逆汤}主之。 346、少阴病下利便脓血者，$f{桃花汤}主之。 347、少阴病，二三日至四五日，腹痛，小便不利，下利不止，便脓血者，$f{桃花汤}主之。 348、少阴病，下利便脓血者，可刺足阳明。 349、少阴病，吐，利，手足逆冷，烦躁欲死者，$f{吴茱萸汤}主之。 350、少阴病，下利，咽痛，胸满，心烦者，$f{猪肤汤}主之。 351、少阴病，二三日咽中痛者，可与$f{甘草汤}；不差，与$f{桔梗汤}。 352、少阴病，咽中伤，生疮，痛引喉旁，不能语言，声不出者，$f{苦酒汤}主之。 353、少阴病，咽中痛，脉反浮者，$f{半夏散及汤}主之。 354、少阴病，下利，$f{白通汤}主之。 355、少阴病，下利，脉微者，与白通汤；利不止，厥逆无脉，干呕烦者，$f{白通加猪胆汁汤}主之；服汤后，脉暴出者死；微续者生。 356、少阴病二三日不已，至四五日，腹痛，小便不利，四肢沉重疼痛，自下利者，此为有水气，其人或咳，或小便不利，或下利，或呕者，$f{真武汤}主之。 357、少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面色赤，或腹痛，或干呕，或咽痛，或利止，脉不出者，$f{通脉四逆汤}主之。 358、少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，$f{四逆散}主之。 359、少阴病，下利六七日，咳而呕，渴，心烦不得眠者，$f{猪苓汤}主之。 360、少阴病，得之二三日，口燥咽干者，急下之，宜$f{大承气汤}。 361、少阴病，自利清水，色纯青，心下必痛，口干燥者，可下之，宜$f{大承气汤}。 362、少阴病，六七日，腹胀不大便者，急下之，宜$f{大承气汤}。 363、少阴病，脉沉者，急温之，宜$f{四逆汤}。 364、少阴病，饮食入口即吐，或心中温温欲吐，复不能吐，始得之，手足寒，脉弦迟者，此胸中实，不可下也，当吐之；若膈上有寒饮，干呕者，不可吐也，当温之，宜$f{四逆汤}。 365、少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。', '2024-12-06T07:28:55.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FCG5O8QxL4a', 1, '{"title":"辨厥阴病脉证并治","description":"<p>365、少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。</p><p>367、厥阴中风，脉微浮，为欲愈；不浮，为未愈。</p><p>368、蹶阴欲解时，从丑至卯上。</p><p>369、厥阴病，渴欲饮水者，少少与之，愈。</p><p>370、诸四逆厥者，不可下之，虚家亦然。</p><p>371、伤寒先厥，后发热而利者，必自止；见厥，复利。</p><p>372、伤寒始发热六日，厥反九日而利；凡厥利者，当不能食，今反能食者，恐为除中；食以素饼，不发热者，知胃气尚在，必愈；恐暴热来出而复去也。后日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日亦为九日，与厥相应，故期之旦日夜半愈。后三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。</p><p>373、伤寒六七门，脉迟，而反与$f{黄芩汤}彻其热，脉迟为寒，今与$f{黄芩汤}复除其热，腹中应冷，今反能食，此名除中，必死。</p><p>374、伤寒，先厥后发热，下利必自止，而反汗出，咽中痛者，其喉为痹；发热，无汗，而利必自止；若不止，必便脓血，便脓血者，其喉不痹。</p><p>375、伤寒一二日，至四五日，厥者，必发热。前热者，后必厥；厥深者，热亦深；厥微者，热亦微；厥应下之，而反发汗者，必口伤烂赤。</p><p>376、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈；厥终不过五日，以热五日，知自愈。</p><p>377、凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。</p><p>378、伤寒，脉微而厥，至七八日，肤冷，其人躁，无暂安时者，此为脏厥，非蚘厥也。蚘厥者，其人当吐蚘，今病者静，而复时烦，此为脏寒，蚘上入其膈，故烦，须臾复止，得食而呕又烦者，蚘闻食臭出，其人当自吐蚘。蚘厥者，$f{乌梅丸}主之，又主久利。</p><p>379、伤寒，热少，微厥，指头寒，嘿嘿不欲食，烦躁，数日小便利色白者，此热除也，欲得食，其病为愈；若厥而呕，胸胁烦满者，其后必便血。</p><p>380、病者手足厥冷，不结胸，小腹满，按之痛者，此冷结在膀胱关元也。</p><p>381、伤寒发热四日，厥反三日，复热四日，厥少热多者，其病当愈；四日至七日，热不除者，必便脓血。</p><p>382、伤寒厥四日，热反三日，复厥五日，其病为进，寒多热少，阳气退，故为进也。</p><p>383、伤寒六七日，脉微，手足厥冷，烦躁，灸厥阴，厥不还者，死。</p><p>384、伤寒，发热，下利，厥逆，躁不得卧者，死。</p><p>385、伤寒，发热，下利至甚，厥不止者，死。</p><p>386、伤寒六七日不利，便发热而利，其人汗出不止者，死。有阴无阳故也。</p><p>387、伤寒五六日，不结胸，腹濡，脉虚，复厥者，不可下也，此为亡血，下之则死。</p><p>388、伤寒，发热而厥，七日，下利者，为难治。</p><p>389、伤寒，脉促，手足厥逆，不可灸之。</p><p>390、伤寒，脉滑而厥者，里有热也，$f{白虎汤}主之。</p><p>391、伤寒，手足厥逆，脉细欲绝者，$f{当归四逆加人参附子汤}主之；若其人内有久寒者，$f{当归四逆加吴茱萸生姜附子汤}主之。</p><p>392、大汗出，热不去，内拘急，四肢疼，复下利，厥逆，而恶寒者，$f{四逆汤}主之。</p><p>393、大汗，若大下利而厥逆冷者，$f{四逆汤}主之。</p><p>394、病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜$f{瓜蒂散}。</p><p>395、伤寒，厥而心下悸者，宜先治水，当服$f{茯苓甘草汤}，却治其厥，不尔水渍入胃，必作利也。</p><p>396、伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，咽喉不利，唾脓血，泄利不止者，为难治，$f{人参附子汤}主之；不差，复以$f{人参干姜汤}与之。</p><p>397、伤寒四五日，腹中痛，若转气下趋少腹者，此欲自利也。</p><p>398、伤寒，本自寒下，医复吐、下之，寒格，更逆吐、下，$f{麻黄升麻汤}主之；若食入口即吐，$f{干姜黄芩黄连人参汤}主之。</p><p>399、下利，有微热而渴，脉弱者，令自愈。</p><p>400、下利，脉数有微热，汗出者，为欲愈，脉紧者，为未解。</p><p>401、下利，手足厥逆，无脉者，灸之不温，若脉不还，反微喘者，死。少阴负趺阳者，为顺也。</p><p>402、下利，寸脉反浮数，尺中自涩者，必圊脓血，$f{柏叶阿胶汤}主之。</p><p>403、下利清谷，不可攻表；汗出，必胀满。</p><p>404、下利，脉沉弦者，下重也；脉大者，为未止；脉微弱数者，为欲自止，虽发热，不死。</p><p>405、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，必郁冒，汗出而解，病人必微厥，所以然者，其面戴阳下虚故也。</p><p>406、下利，脉数而渴者，令自愈，设不差，必清脓血，以有热故也。</p><p>407、下利后，脉绝，手足厥冷，啐时脉还，手足温者，生，脉不还者，死。</p><p>408、伤寒，下利日十余行，脉反实者，死。</p><p>409、下利清谷，里寒外热，汗出而厥者，$f{通脉四逆汤}主之。</p><p>410、热利下重者，$f{白头翁汤}主之。</p><p>411、下利，其人虚极者，$f{白头翁加阿胶甘草汤}主之。</p><p>412、下利，腹胀满，身体疼痛者，先温其里，乃攻其表，温里宜$f{四逆汤}；攻表宜$f{桂枝汤}。</p><p>413、下利，欲饮水者，以有热故也，$f{白头翁汤}主之。</p><p>414、下利，谵语者，有燥屎也，宜$f{小承气汤}。</p><p>415、下利后，更烦，按之心下濡者，为虚烦也，宜$f{栀子豉汤}。</p><p>416、下利，腹痛，若胸痛者，$f{紫参汤}主之。</p><p>417、气利，$f{诃黎勒散}主之。</p><p>418、呕家，有痈脓者，不可治呕，脓尽自愈。</p><p>419、呕而胸满者，$f{吴茱萸汤}主之。</p><p>420、干呕，吐涎沫，头痛者，$f{吴茱萸汤}主之。</p><p>421、呕而发热者，$f{小柴胡汤}主之。</p><p>422、呕而脉弱，小便复利，身有微热，见厥者，难治，$f{四逆汤}主之。</p><p>423、干呕，吐逆，吐涎沫，$f{半夏干姜散}主之。</p><p>424、伤寒，大吐大下之，极虚，复极汗者，以其人外气怫郁，复与之水，以发其汗，因得哕，所以然者，胃中寒冷故也。</p><p>425、伤寒，哕而腹满，视其前后，知何部下利，利之则愈。</p><p>426、病人胸中似喘不喘，似呕不呕，似哕不哕，彻心中愦愦然无奈者，$f{生姜半夏汤}主之。</p><p>427、干呕，哕，若手足厥者，$f{橘皮汤}主之。</p><p>428、哕逆，其人虚者，$f{橘皮竹茹汤}主之。</p><p>429、诸呕谷不得下者，$f{小半夏汤}主之。</p><p>430、便脓血，相传为病，此名疫利。其原因，于夏而发，于秋热燥相搏，逐伤气血，流于肠问，其后乃重，脉洪变量，$f{黄连茯苓汤}主之。</p><p>431、病人呕，吐涎沫，心痛，若腹痛发作有时，其脉反洪大者，此虫之为病也，$f{甘草粉蜜汤}主之。</p><p>433、寒疝，腹中痛，若胁痛里急者，$f{当归生姜羊肉汤}主之。</p><p>434、寒疝，腹中痛，手足不仁，若逆冷，若身疼痛，灸刺诸药不能治者，$f{乌头桂枝汤}主之。</p><p>435、病人睪丸，偏有大小，时有上下，此为狐疝，宜先刺厥阴之俞，后与$f{蜘蛛散}。</p><p>436、寸口脉浮而迟，浮则为虚，迟则为劳；虚则卫气不足，劳则荣气竭。</p><p>437、趺阳脉浮而数，浮则为气，数则消谷而大坚，气盛则溲数，溲数则坚，坚数相搏，即为消渴。</p><p>438、消渴，小便多，饮一斗，小便亦一斗者，$f{肾气丸}主之。</p><p>439、消渴，脉浮有微热，小便不利者，$f{五苓散}主之。</p><p>441、消渴，欲得水而食饮不休者，$f{文蛤汤}主之。</p><p>442、小便痛閟，下如粟状，少腹弦急，痛引脐中，其名曰淋，此热结在下焦也，$f{小柴胡加茯苓汤}主之。</p>\n<p>  </p>\n<p>          $a{  “閟”}：$v{音bì，通“闭”}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010022,"no":22}}', '2024-12-06T07:29:10.000Z', '2024-12-06T07:29:10.000Z', '2024-12-06T07:29:10.000Z', '365、少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。 367、厥阴中风，脉微浮，为欲愈；不浮，为未愈。 368、蹶阴欲解时，从丑至卯上。 369、厥阴病，渴欲饮水者，少少与之，愈。 370、诸四逆厥者，不可下之，虚家亦然。 371、伤寒先厥，后发热而利者，必自止；见厥，复利。 372、伤寒始发热六日，厥反九日而利；凡厥利者，当不能食，今反能食者，恐为除中；食以素饼，不发热者，知胃气尚在，必愈；恐暴热来出而复去也。后日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日亦为九日，与厥相应，故期之旦日夜半愈。后三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。 373、伤寒六七门，脉迟，而反与$f{黄芩汤}彻其热，脉迟为寒，今与$f{黄芩汤}复除其热，腹中应冷，今反能食，此名除中，必死。 374、伤寒，先厥后发热，下利必自止，而反汗出，咽中痛者，其喉为痹；发热，无汗，而利必自止；若不止，必便脓血，便脓血者，其喉不痹。 375、伤寒一二日，至四五日，厥者，必发热。前热者，后必厥；厥深者，热亦深；厥微者，热亦微；厥应下之，而反发汗者，必口伤烂赤。 376、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈；厥终不过五日，以热五日，知自愈。 377、凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。 378、伤寒，脉微而厥，至七八日，肤冷，其人躁，无暂安时者，此为脏厥，非蚘厥也。蚘厥者，其人当吐蚘，今病者静，而复时烦，此为脏寒，蚘上入其膈，故烦，须臾复止，得食而呕又烦者，蚘闻食臭出，其人当自吐蚘。蚘厥者，$f{乌梅丸}主之，又主久利。 379、伤寒，热少，微厥，指头寒，嘿嘿不欲食，烦躁，数日小便利色白者，此热除也，欲得食，其病为愈；若厥而呕，胸胁烦满者，其后必便血。 380、病者手足厥冷，不结胸，小腹满，按之痛者，此冷结在膀胱关元也。 381、伤寒发热四日，厥反三日，复热四日，厥少热多者，其病当愈；四日至七日，热不除者，必便脓血。 382、伤寒厥四日，热反三日，复厥五日，其病为进，寒多热少，阳气退，故为进也。 383、伤寒六七日，脉微，手足厥冷，烦躁，灸厥阴，厥不还者，死。 384、伤寒，发热，下利，厥逆，躁不得卧者，死。 385、伤寒，发热，下利至甚，厥不止者，死。 386、伤寒六七日不利，便发热而利，其人汗出不止者，死。有阴无阳故也。 387、伤寒五六日，不结胸，腹濡，脉虚，复厥者，不可下也，此为亡血，下之则死。 388、伤寒，发热而厥，七日，下利者，为难治。 389、伤寒，脉促，手足厥逆，不可灸之。 390、伤寒，脉滑而厥者，里有热也，$f{白虎汤}主之。 391、伤寒，手足厥逆，脉细欲绝者，$f{当归四逆加人参附子汤}主之；若其人内有久寒者，$f{当归四逆加吴茱萸生姜附子汤}主之。 392、大汗出，热不去，内拘急，四肢疼，复下利，厥逆，而恶寒者，$f{四逆汤}主之。 393、大汗，若大下利而厥逆冷者，$f{四逆汤}主之。 394、病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜$f{瓜蒂散}。 395、伤寒，厥而心下悸者，宜先治水，当服$f{茯苓甘草汤}，却治其厥，不尔水渍入胃，必作利也。 396、伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，咽喉不利，唾脓血，泄利不止者，为难治，$f{人参附子汤}主之；不差，复以$f{人参干姜汤}与之。 397、伤寒四五日，腹中痛，若转气下趋少腹者，此欲自利也。 398、伤寒，本自寒下，医复吐、下之，寒格，更逆吐、下，$f{麻黄升麻汤}主之；若食入口即吐，$f{干姜黄芩黄连人参汤}主之。 399、下利，有微热而渴，脉弱者，令自愈。 400、下利，脉数有微热，汗出者，为欲愈，脉紧者，为未解。 401、下利，手足厥逆，无脉者，灸之不温，若脉不还，反微喘者，死。少阴负趺阳者，为顺也。 402、下利，寸脉反浮数，尺中自涩者，必圊脓血，$f{柏叶阿胶汤}主之。 403、下利清谷，不可攻表；汗出，必胀满。 404、下利，脉沉弦者，下重也；脉大者，为未止；脉微弱数者，为欲自止，虽发热，不死。 405、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，必郁冒，汗出而解，病人必微厥，所以然者，其面戴阳下虚故也。 406、下利，脉数而渴者，令自愈，设不差，必清脓血，以有热故也。 407、下利后，脉绝，手足厥冷，啐时脉还，手足温者，生，脉不还者，死。 408、伤寒，下利日十余行，脉反实者，死。 409、下利清谷，里寒外热，汗出而厥者，$f{通脉四逆汤}主之。 410、热利下重者，$f{白头翁汤}主之。 411、下利，其人虚极者，$f{白头翁加阿胶甘草汤}主之。 412、下利，腹胀满，身体疼痛者，先温其里，乃攻其表，温里宜$f{四逆汤}；攻表宜$f{桂枝汤}。 413、下利，欲饮水者，以有热故也，$f{白头翁汤}主之。 414、下利，谵语者，有燥屎也，宜$f{小承气汤}。 415、下利后，更烦，按之心下濡者，为虚烦也，宜$f{栀子豉汤}。 416、下利，腹痛，若胸痛者，$f{紫参汤}主之。 417、气利，$f{诃黎勒散}主之。 418、呕家，有痈脓者，不可治呕，脓尽自愈。 419、呕而胸满者，$f{吴茱萸汤}主之。 420、干呕，吐涎沫，头痛者，$f{吴茱萸汤}主之。 421、呕而发热者，$f{小柴胡汤}主之。 422、呕而脉弱，小便复利，身有微热，见厥者，难治，$f{四逆汤}主之。 423、干呕，吐逆，吐涎沫，$f{半夏干姜散}主之。 424、伤寒，大吐大下之，极虚，复极汗者，以其人外气怫郁，复与之水，以发其汗，因得哕，所以然者，胃中寒冷故也。 425、伤寒，哕而腹满，视其前后，知何部下利，利之则愈。 426、病人胸中似喘不喘，似呕不呕，似哕不哕，彻心中愦愦然无奈者，$f{生姜半夏汤}主之。 427、干呕，哕，若手足厥者，$f{橘皮汤}主之。 428、哕逆，其人虚者，$f{橘皮竹茹汤}主之。 429、诸呕谷不得下者，$f{小半夏汤}主之。 430、便脓血，相传为病，此名疫利。其原因，于夏而发，于秋热燥相搏，逐伤气血，流于肠问，其后乃重，脉洪变量，$f{黄连茯苓汤}主之。 431、病人呕，吐涎沫，心痛，若腹痛发作有时，其脉反洪大者，此虫之为病也，$f{甘草粉蜜汤}主之。 433、寒疝，腹中痛，若胁痛里急者，$f{当归生姜羊肉汤}主之。 434、寒疝，腹中痛，手足不仁，若逆冷，若身疼痛，灸刺诸药不能治者，$f{乌头桂枝汤}主之。 435、病人睪丸，偏有大小，时有上下，此为狐疝，宜先刺厥阴之俞，后与$f{蜘蛛散}。 436、寸口脉浮而迟，浮则为虚，迟则为劳；虚则卫气不足，劳则荣气竭。 437、趺阳脉浮而数，浮则为气，数则消谷而大坚，气盛则溲数，溲数则坚，坚数相搏，即为消渴。 438、消渴，小便多，饮一斗，小便亦一斗者，$f{肾气丸}主之。 439、消渴，脉浮有微热，小便不利者，$f{五苓散}主之。 441、消渴，欲得水而食饮不休者，$f{文蛤汤}主之。 442、小便痛閟，下如粟状，少腹弦急，痛引脐中，其名曰淋，此热结在下焦也，$f{小柴胡加茯苓汤}主之。 $a{ “閟”}：$v{音bì，通“闭”}。', '2024-12-06T07:29:10.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ivl1mj3EGPu', 1, '{"title":"辨霍乱吐利病脉证并治","description":"<p>1、问曰：病有霍乱者何？答曰：呕吐而利，此名霍乱。</p><p>2、师曰：霍乱属太阴，霍乱必吐利，吐利不必尽霍乱。霍乱者，由寒热杂合混乱于中也。热气上逆故吐，寒气下注故利，其有饮食不节，壅滞于中上者，竟上则吐，下者，竟下则利，此名吐利，非霍乱也。</p><p>3、问曰：病有发热，头痛，身疼，恶寒，吐利者，此属何病？</p>\n<p></p>\n<p>            答曰：此非霍乱，霍乱自吐下，今恶寒，身疼，复更发热，故知非霍乱也。</p><p>4、霍乱呕、吐、下利，无寒热，脉濡弱者，$f{理中汤}主之。</p><p>5、先吐，后利，腹中满痛，无寒热，脉濡弱而涩者，此宿食也，$f{白术茯苓半夏枳实汤}主之。</p><p>6、胸中满，欲吐不吐，下利时疏，无寒热，腹中绞痛，寸口脉弱而结者，此宿食在上故也，宜$f{瓜蒂散}。</p><p>7、霍乱呕、吐，下利清谷，手足厥冷，脉沉而迟者，$f{四逆汤}主之。</p><p>8、吐、利，发热，脉濡弱而大者，$f{白术石膏半夏干姜汤}主之。</p><p>9、呕吐甚则蚘出，下利时密时疏，身微热，手足厥冷，面色青，脉沉弦而紧者，$f{四逆加吴茱萸黄连汤}主之。</p><p>10、霍乱吐、利，口渴，汗出，短气，脉弱而濡者，$f{理中加人参括蒌根汤}主之。</p><p>11、饮水即吐，食谷则利，脉迟而弱者，$f{理中加附子汤}主之。</p><p>12、腹中胀满而痛，时时上下，痛气上则吐，痛气下则利，脉濡而涩者，$f{理中汤}主之。</p><p>13、霍乱证，有虚实，因其人本有虚实，证随本变故也，虚者脉濡而弱，宜$f{理中汤}；实者脉急而促，宜$f{葛根黄连黄芩甘草汤}。</p><p>14、霍乱，转筋，必先其时已有寒邪留于筋间，伤其荣气，随证而发，脉当濡弱，反见弦急厥逆者，$f{理中加附子汤}主之。</p><p>15、霍乱，已，头痛，发热，身疼痛，热多，欲饮水者，$f{五苓散}主之；寒多，不饮水者，${理中丸}主之。</p><p>16、伤寒其脉微涩者，本是霍乱，今是伤寒，却四五日，至阴经上，若转入阴者，必利；若欲似大便，而反失气，仍不利者，此属阳明也，便必鞕，十三日愈。所以然者，经尽故也。</p><p>17、下利后，便当鞕，鞕则能食者，愈；今反不能食，到后经中，颇能食，复过一经亦能食，过之一日当愈，不愈者，不属阳明也。</p><p>18、伤寒脉微而复利，利自止者，亡血也，$f{四逆加人参汤}主之。</p><p>19、吐、利止，而身痛不休者，当消息和解其外，宜$f{桂枝汤}。</p><p>20、吐、利，汗出，发热，恶寒，四肢拘急，手足厥冷者，$f{四逆汤}主之。</p><p>21、既吐且利，小便复利而大汗出，下利清谷，内寒外热，脉微欲绝者，$f{四逆汤}主之。</p><p>22、吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，$f{通脉四逆加猪胆汁汤}主之。</p><p>23、吐、利后，汗出，脉平，小烦者，以新虚不胜谷气故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010023,"no":23}}', '2024-12-06T07:29:26.000Z', '2024-12-06T07:29:26.000Z', '2024-12-06T07:29:26.000Z', '1、问曰：病有霍乱者何？答曰：呕吐而利，此名霍乱。 2、师曰：霍乱属太阴，霍乱必吐利，吐利不必尽霍乱。霍乱者，由寒热杂合混乱于中也。热气上逆故吐，寒气下注故利，其有饮食不节，壅滞于中上者，竟上则吐，下者，竟下则利，此名吐利，非霍乱也。 3、问曰：病有发热，头痛，身疼，恶寒，吐利者，此属何病？ 答曰：此非霍乱，霍乱自吐下，今恶寒，身疼，复更发热，故知非霍乱也。 4、霍乱呕、吐、下利，无寒热，脉濡弱者，$f{理中汤}主之。 5、先吐，后利，腹中满痛，无寒热，脉濡弱而涩者，此宿食也，$f{白术茯苓半夏枳实汤}主之。 6、胸中满，欲吐不吐，下利时疏，无寒热，腹中绞痛，寸口脉弱而结者，此宿食在上故也，宜$f{瓜蒂散}。 7、霍乱呕、吐，下利清谷，手足厥冷，脉沉而迟者，$f{四逆汤}主之。 8、吐、利，发热，脉濡弱而大者，$f{白术石膏半夏干姜汤}主之。 9、呕吐甚则蚘出，下利时密时疏，身微热，手足厥冷，面色青，脉沉弦而紧者，$f{四逆加吴茱萸黄连汤}主之。 10、霍乱吐、利，口渴，汗出，短气，脉弱而濡者，$f{理中加人参括蒌根汤}主之。 11、饮水即吐，食谷则利，脉迟而弱者，$f{理中加附子汤}主之。 12、腹中胀满而痛，时时上下，痛气上则吐，痛气下则利，脉濡而涩者，$f{理中汤}主之。 13、霍乱证，有虚实，因其人本有虚实，证随本变故也，虚者脉濡而弱，宜$f{理中汤}；实者脉急而促，宜$f{葛根黄连黄芩甘草汤}。 14、霍乱，转筋，必先其时已有寒邪留于筋间，伤其荣气，随证而发，脉当濡弱，反见弦急厥逆者，$f{理中加附子汤}主之。 15、霍乱，已，头痛，发热，身疼痛，热多，欲饮水者，$f{五苓散}主之；寒多，不饮水者，${理中丸}主之。 16、伤寒其脉微涩者，本是霍乱，今是伤寒，却四五日，至阴经上，若转入阴者，必利；若欲似大便，而反失气，仍不利者，此属阳明也，便必鞕，十三日愈。所以然者，经尽故也。 17、下利后，便当鞕，鞕则能食者，愈；今反不能食，到后经中，颇能食，复过一经亦能食，过之一日当愈，不愈者，不属阳明也。 18、伤寒脉微而复利，利自止者，亡血也，$f{四逆加人参汤}主之。 19、吐、利止，而身痛不休者，当消息和解其外，宜$f{桂枝汤}。 20、吐、利，汗出，发热，恶寒，四肢拘急，手足厥冷者，$f{四逆汤}主之。 21、既吐且利，小便复利而大汗出，下利清谷，内寒外热，脉微欲绝者，$f{四逆汤}主之。 22、吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，$f{通脉四逆加猪胆汁汤}主之。 23、吐、利后，汗出，脉平，小烦者，以新虚不胜谷气故也。', '2024-12-06T07:29:26.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kBNKud90m4z', 1, '{"title":"辨痉阴阳易差后病脉证并治","description":"<p>1、太阳病，发热，无汗，而恶寒者，若脉沉迟，名刚痉。</p><p>2、太阳病，发热，汗出，不恶寒者，若脉浮数，名柔痉。</p><p>3、太阳病，发热，脉沉而细者，名曰痉，为难治。</p><p>4、太阳病，发汗太多，因致痉。</p><p>5、风病，下之则痉，复发汗，必拘急。</p><p>6、疮家，不可发汗，汗出则痉。</p><p>7、病者身热足寒，颈项强急，恶寒，时头热，面赤目赤，独头动摇，卒口噤，背反张者，痉病也。若发其汗，寒湿相得，其表益虚，则恶寒甚，发其汗已，其脉如蛇，暴脉长大者，为欲解；其脉如故，及伏弦者，为未解。</p><p>8、夫痉脉，按之紧如弦，直上下行。</p><p>9、痉病，有灸疮者，难治。</p><p>10、太阳病，其证备，身体强几几然，脉反沉迟，此为痉，$f{栝蒌桂枝汤}主之。</p><p>11、太阳病，无汗，而小便反少，气上冲胸，口噤不得语，欲作刚痉者，$f{葛根汤}主之。</p><p>12、痉病，手足厥冷，发热间作，唇青目陷，脉沉弦者，风邪入厥阴也，$f{桂枝加附子当归细辛人参干姜汤}主之。</p><p>13、痉病，本属太阳，若发热，汗出，脉弦而实者，转属阳明也，宜$n{承气}辈与之。</p><p>14、痉病，胸满，口噤，卧不着席，脚挛急，必介齿，宜$f{大承气汤}。</p><p>15、伤寒阴阳易之为病，其人身体重，少气，少腹里急，或引阴中拘挛，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，$f{烧裩散}主之。</p><p>16、大病差后，劳复者，$f{枳实栀子豉汤}主之；若有宿食者，加$u{大黄}$w{如博棋子大五六枚}。</p><p>17、伤寒差已后，更发热者，$f{小柴胡汤}主之；脉浮者，以汗解之；脉沉实者，以下解之。</p><p>18、大病差后，从腰以下有水气者，$f{牡蛎泽泻散}主之。</p><p>19、大病差后，喜唾，久不了了，胸上有寒也，当以丸药温之，宜$f{理中丸}。</p><p>20、伤寒解后，虚赢少气，气逆欲吐者，$f{竹叶石膏汤}主之。</p><p>21、大病已解，而日暮微烦者，以病新差，人强与谷，脾胃之气尚弱，不能消谷，故令微烦，损谷则愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010024,"no":24}}', '2024-12-06T07:29:42.000Z', '2024-12-06T07:29:42.000Z', '2024-12-06T07:29:42.000Z', '1、太阳病，发热，无汗，而恶寒者，若脉沉迟，名刚痉。 2、太阳病，发热，汗出，不恶寒者，若脉浮数，名柔痉。 3、太阳病，发热，脉沉而细者，名曰痉，为难治。 4、太阳病，发汗太多，因致痉。 5、风病，下之则痉，复发汗，必拘急。 6、疮家，不可发汗，汗出则痉。 7、病者身热足寒，颈项强急，恶寒，时头热，面赤目赤，独头动摇，卒口噤，背反张者，痉病也。若发其汗，寒湿相得，其表益虚，则恶寒甚，发其汗已，其脉如蛇，暴脉长大者，为欲解；其脉如故，及伏弦者，为未解。 8、夫痉脉，按之紧如弦，直上下行。 9、痉病，有灸疮者，难治。 10、太阳病，其证备，身体强几几然，脉反沉迟，此为痉，$f{栝蒌桂枝汤}主之。 11、太阳病，无汗，而小便反少，气上冲胸，口噤不得语，欲作刚痉者，$f{葛根汤}主之。 12、痉病，手足厥冷，发热间作，唇青目陷，脉沉弦者，风邪入厥阴也，$f{桂枝加附子当归细辛人参干姜汤}主之。 13、痉病，本属太阳，若发热，汗出，脉弦而实者，转属阳明也，宜$n{承气}辈与之。 14、痉病，胸满，口噤，卧不着席，脚挛急，必介齿，宜$f{大承气汤}。 15、伤寒阴阳易之为病，其人身体重，少气，少腹里急，或引阴中拘挛，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，$f{烧裩散}主之。 16、大病差后，劳复者，$f{枳实栀子豉汤}主之；若有宿食者，加$u{大黄}$w{如博棋子大五六枚}。 17、伤寒差已后，更发热者，$f{小柴胡汤}主之；脉浮者，以汗解之；脉沉实者，以下解之。 18、大病差后，从腰以下有水气者，$f{牡蛎泽泻散}主之。 19、大病差后，喜唾，久不了了，胸上有寒也，当以丸药温之，宜$f{理中丸}。 20、伤寒解后，虚赢少气，气逆欲吐者，$f{竹叶石膏汤}主之。 21、大病已解，而日暮微烦者，以病新差，人强与谷，脾胃之气尚弱，不能消谷，故令微烦，损谷则愈。', '2024-12-06T07:29:42.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ay62bNVdQvD', 1, '{"title":"辨百合狐惑阴阳毒病脉证并治","description":"<p>1、百合病者，百脉一宗，悉致其病也，意欲食，复不能食，常默默，欲卧不能卧，欲行不能行，饮食或有美时，或有不欲闻食臭时，如寒无寒，如热无热，口苦，小便赤，诸药不能治，得药则剧吐利，如有神灵者，身形如和，其脉微数，每溺时头痛者，六十日乃愈。若溺时头不痛，淅淅然者，四十日愈。若溺时快然，但头眩者，二十日愈。其证或未病而预见，或病四五日始见，或病至二十日，或一月后见者；各随其证，依法治之。</p><p>2、百合病，见于发汗之后者，$f{百合知母汤}主之。</p><p>3、百合病，见于下之后者，$f{百合滑石代赭汤}主之。</p><p>4、百合病，见于吐之后者，$f{百合鸡子黄汤}主之。</p><p>5、百合病，不经发汗、吐下，病形如初者，$f{百合地黄汤}主之。</p><p>6、百合病，一月不解，变成渴者，$f{百合洗方主}之；不差，$f{括蒌牡蛎散}主之。</p><p>7、百合病，变发热者，$f{百合滑石散}主之。</p><p>8、百合病，见于阴者，以阳法救之；见于阳者，以阴法救之；见阳攻阴，复发其汗，此为逆，见阴攻阳，乃复下之，此亦为逆。</p><p>9、狐惑之为病，状如伤寒，默默欲眠，目不得闭，卧起不安。蚀于喉为惑，蚀于阴为狐，不欲饮食，恶闻食臭，其面目乍赤，乍黑，乍白，蚀于上部则声嗄，$f{甘草泻心汤}主之；蚀于下部则咽干，$f{苦参汤}洗之；蚀于肛者，$u{雄黄}薰之。 </p>\n<p>    </p>\n<p>另：$a{雄黄}应该是$f{雄黄散}</p><p>10、病者脉数，无热微烦，默默但欲卧，汗出，初得之三四日，目赤如鸠眼，七八日，目四眦黑，若能食者，脓已成也，$f{赤豆当归散}主之。</p><p>11、阳毒之为病，面赤斑斑如锦纹，咽喉痛，唾脓血，五日可治，七日不可治，$f{升麻鳖甲汤}主之。</p><p>12、阴毒之为病，面目青，身痛如被杖，咽喉痛，五日可治；七日不可治；$f{升麻鳖甲汤去雄黄蜀椒}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010025,"no":25}}', '2024-12-06T07:29:58.000Z', '2024-12-06T07:29:58.000Z', '2024-12-06T07:29:58.000Z', '1、百合病者，百脉一宗，悉致其病也，意欲食，复不能食，常默默，欲卧不能卧，欲行不能行，饮食或有美时，或有不欲闻食臭时，如寒无寒，如热无热，口苦，小便赤，诸药不能治，得药则剧吐利，如有神灵者，身形如和，其脉微数，每溺时头痛者，六十日乃愈。若溺时头不痛，淅淅然者，四十日愈。若溺时快然，但头眩者，二十日愈。其证或未病而预见，或病四五日始见，或病至二十日，或一月后见者；各随其证，依法治之。 2、百合病，见于发汗之后者，$f{百合知母汤}主之。 3、百合病，见于下之后者，$f{百合滑石代赭汤}主之。 4、百合病，见于吐之后者，$f{百合鸡子黄汤}主之。 5、百合病，不经发汗、吐下，病形如初者，$f{百合地黄汤}主之。 6、百合病，一月不解，变成渴者，$f{百合洗方主}之；不差，$f{括蒌牡蛎散}主之。 7、百合病，变发热者，$f{百合滑石散}主之。 8、百合病，见于阴者，以阳法救之；见于阳者，以阴法救之；见阳攻阴，复发其汗，此为逆，见阴攻阳，乃复下之，此亦为逆。 9、狐惑之为病，状如伤寒，默默欲眠，目不得闭，卧起不安。蚀于喉为惑，蚀于阴为狐，不欲饮食，恶闻食臭，其面目乍赤，乍黑，乍白，蚀于上部则声嗄，$f{甘草泻心汤}主之；蚀于下部则咽干，$f{苦参汤}洗之；蚀于肛者，$u{雄黄}薰之。 另：$a{雄黄}应该是$f{雄黄散} 10、病者脉数，无热微烦，默默但欲卧，汗出，初得之三四日，目赤如鸠眼，七八日，目四眦黑，若能食者，脓已成也，$f{赤豆当归散}主之。 11、阳毒之为病，面赤斑斑如锦纹，咽喉痛，唾脓血，五日可治，七日不可治，$f{升麻鳖甲汤}主之。 12、阴毒之为病，面目青，身痛如被杖，咽喉痛，五日可治；七日不可治；$f{升麻鳖甲汤去雄黄蜀椒}主之。', '2024-12-06T07:29:58.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N18NIzeqEiz', 1, '{"title":"辨疟病脉证并治","description":"<p>1、师曰：疟病其脉弦数者，热多寒少；</p>\n<p>                其脉弦迟者，寒多热少。</p>\n<p>                脉弦而小紧者，可下之；</p>\n<p>                弦迟者，可温之，</p>\n<p>                弦紧者，可汗之，针之，灸之；</p>\n<p>                浮大者，可吐之；</p>\n<p>                弦数者，风发也，当于少阳中求之。</p><p>2、问曰：疟病以月一发者，当以十五日愈，甚者当月尽解，如其不差，当云何?</p>\n<p></p>\n<p>           师曰：此结为症瘕，必有疟母，急治之，宜鳖甲煎丸。</p><p>3、师曰：阴气孤绝，阳气独发，则热而少气烦悗，手足热而欲呕，此名疸疟，$f{白虎加桂枝人参汤}主之。</p><p>4、疟病，其脉如平，身无寒，但热，骨节疼烦，时作呕，此名温疟，宜$f{白虎加桂枝汤}。</p><p>5、疟病，多寒，或但寒不热者，此名牡疟，$f{蜀漆散}主之，$f{柴胡桂姜汤}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010026,"no":26}}', '2024-12-06T07:30:13.000Z', '2024-12-06T07:30:13.000Z', '2024-12-06T07:30:13.000Z', '1、师曰：疟病其脉弦数者，热多寒少； 其脉弦迟者，寒多热少。 脉弦而小紧者，可下之； 弦迟者，可温之， 弦紧者，可汗之，针之，灸之； 浮大者，可吐之； 弦数者，风发也，当于少阳中求之。 2、问曰：疟病以月一发者，当以十五日愈，甚者当月尽解，如其不差，当云何? 师曰：此结为症瘕，必有疟母，急治之，宜鳖甲煎丸。 3、师曰：阴气孤绝，阳气独发，则热而少气烦悗，手足热而欲呕，此名疸疟，$f{白虎加桂枝人参汤}主之。 4、疟病，其脉如平，身无寒，但热，骨节疼烦，时作呕，此名温疟，宜$f{白虎加桂枝汤}。 5、疟病，多寒，或但寒不热者，此名牡疟，$f{蜀漆散}主之，$f{柴胡桂姜汤}亦主之。', '2024-12-06T07:30:13.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PyUWgHiFRAt', 1, '{"title":"辨血痹虚劳病脉证并治","description":"<p>1、问曰：血痹之病，从何得之？</p>\n<p></p>\n<p>          师曰：夫尊荣之人，骨弱，肌肤盛，重因疲劳，汗出，卧不时动摇，加被微风，遂得之。但以脉寸口微涩，关上小紧，宜针引阳气，令脉和，紧去则愈。</p><p>2、血痹，阴阳俱微，或寸口关上微，尺中小紧，外证身体不仁，如风痹状，$f{黄芪桂枝五物汤}主之。</p><p>3、男子平人，脉大为劳，极虚亦为劳。</p><p>4、男子面色薄者，主渴及亡血，卒喘悸，脉浮者，里虚也。</p><p>5、男子脉虚沉弦，无寒热，短气，里急，小便不利，面色白，时目瞑兼衄，少腹满，此为劳使之然。</p><p>6、劳之为病，其脉浮大，手足烦，春夏剧，秋冬差，阴寒精自出，酸削不能行。</p><p>7、男子脉浮弱涩，为无子，精气清冷。</p><p>8、失精家，少阴脉弦急，阴头寒，目眩，发落，脉极虚芤迟者，为清谷亡血失精；脉得诸芤动微紧者，男子则失精，女子则梦交，$f{桂枝龙骨牡蛎汤}主之。$f{天雄散}亦主之。</p><p>9、男子平人，脉虚弱细微者，喜盗汗也。</p><p>10、人年五六十，其脉大者，病痹，挟背行；若肠鸣，马刀挟瘿者，皆为劳得之也。其脉小沉迟者，病脱气，疾行则喘渴；手足逆寒者，亦劳之为病也。</p><p>11、虚劳里急，悸衄，腹中痛，梦失精，四肢酸疼，手足烦热，咽干口燥者，$f{小建中汤}主之。</p><p>12、虚劳里急，诸不足者，${黄芪建中汤}主之。</p><p>13、虚劳，腰痛，少腹拘急，小便不利者，$f{肾气丸}主之。</p><p>14、虚劳虚烦不得眠，$f{酸枣仁汤}主之。</p><p>15、五劳虚极，赢瘦腹满，不能饮食，食伤，忧伤，饮伤，房室伤，饥伤，劳伤，经络荣卫气伤，内有干血，肌肤甲错，两目黯黑，缓中补虚，$f{大黄䗪虫丸}主之。</p><p>16、女劳，膀胱急，少腹满，身尽黄，额上黑，足下热，其腹胀如水状，大便溏而黑，胸满者，难治，$f{硝石矾石散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010027,"no":27}}', '2024-12-06T07:30:32.000Z', '2024-12-06T07:30:32.000Z', '2024-12-06T07:30:32.000Z', '1、问曰：血痹之病，从何得之？ 师曰：夫尊荣之人，骨弱，肌肤盛，重因疲劳，汗出，卧不时动摇，加被微风，遂得之。但以脉寸口微涩，关上小紧，宜针引阳气，令脉和，紧去则愈。 2、血痹，阴阳俱微，或寸口关上微，尺中小紧，外证身体不仁，如风痹状，$f{黄芪桂枝五物汤}主之。 3、男子平人，脉大为劳，极虚亦为劳。 4、男子面色薄者，主渴及亡血，卒喘悸，脉浮者，里虚也。 5、男子脉虚沉弦，无寒热，短气，里急，小便不利，面色白，时目瞑兼衄，少腹满，此为劳使之然。 6、劳之为病，其脉浮大，手足烦，春夏剧，秋冬差，阴寒精自出，酸削不能行。 7、男子脉浮弱涩，为无子，精气清冷。 8、失精家，少阴脉弦急，阴头寒，目眩，发落，脉极虚芤迟者，为清谷亡血失精；脉得诸芤动微紧者，男子则失精，女子则梦交，$f{桂枝龙骨牡蛎汤}主之。$f{天雄散}亦主之。 9、男子平人，脉虚弱细微者，喜盗汗也。 10、人年五六十，其脉大者，病痹，挟背行；若肠鸣，马刀挟瘿者，皆为劳得之也。其脉小沉迟者，病脱气，疾行则喘渴；手足逆寒者，亦劳之为病也。 11、虚劳里急，悸衄，腹中痛，梦失精，四肢酸疼，手足烦热，咽干口燥者，$f{小建中汤}主之。 12、虚劳里急，诸不足者，${黄芪建中汤}主之。 13、虚劳，腰痛，少腹拘急，小便不利者，$f{肾气丸}主之。 14、虚劳虚烦不得眠，$f{酸枣仁汤}主之。 15、五劳虚极，赢瘦腹满，不能饮食，食伤，忧伤，饮伤，房室伤，饥伤，劳伤，经络荣卫气伤，内有干血，肌肤甲错，两目黯黑，缓中补虚，$f{大黄䗪虫丸}主之。 16、女劳，膀胱急，少腹满，身尽黄，额上黑，足下热，其腹胀如水状，大便溏而黑，胸满者，难治，$f{硝石矾石散}主之。', '2024-12-06T07:30:32.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z8BIBJV0eq2', 1, '{"title":"辨咳嗽水饮黄汗历节病脉证并治","description":"<p>1、师曰：咳嗽发于肺，不专属于肺病也。五脏，六腑，感受客邪，皆能致咳。所以然者，邪气上逆，必干于肺，肺为气动，发声为咳，欲知其源，必察脉息，为子条记，传与后贤。</p><p>2、肺咳，脉短而涩。假令浮而涩，知受风邪；紧短而涩，知受寒邪；数短而涩，知受热邪；急短而涩，知受燥邪；濡短而涩，知受湿邪。此肺咳之因也。其状则喘息有音，甚则唾血。</p><p>3、心咳，脉大而散。假令浮大而散，知受风邪，紧大而散，知受寒邪；数大而散，知受热邪；急大而散，知受燥邪；濡大而散，知受湿邪；此心咳之因也。其状则心痛，喉中介介如梗，甚则咽肿，喉痹。</p><p>4、肝咳，脉弦而涩。假令浮弦而涩，知受风邪；弦紧而涩，知受寒邪；弦数而涩，知受热邪；弦急而涩，知受燥邪；弦濡而涩，知受湿邪；此肝咳之因也。其状则两胁下痛，甚则不可以转，转则两胠下满。</p><p>5、脾咳，脉濡而涩。假令浮濡而涩，知受风邪；沉濡而涩，知受寒邪；数濡而涩，知受热邪；急濡而涩，知受燥邪；迟濡而涩，知受湿邪；此脾咳之因也。其状则右肋下痛，隐隐引背，甚则不可以动，动则咳剧。</p><p>6、肾咳，脉沉而濡。假令沉弦而濡，知受风邪；沉紧而濡，知受寒邪；沉数而濡，知受热邪；沉急而濡，知受燥邪；沉滞而濡，知受湿邪；此肾咳之因也。其状则肩背相引而痛，甚则咳涎。</p><p>7、肺咳不已，则流于大肠，脉与肺同，其状则咳而遗矢也。</p><p>8、心咳不已，则流于小肠，脉与心同，其状则咳而失气，气与咳俱失也。</p><p>9、肝咳不已，则流于胆，脉与肝同，其状则呕苦汁也。</p><p>10、脾咳不已，则流于胃，脉与脾同，其状则呕，呕甚则长虫出也。</p><p>11、肾咳不已，则流于膀胱，脉与肾同，其状则咳而遗溺也。</p><p>12、久咳不已，则移于三焦，脉随证易，其状则咳而腹满，不欲食饮也。</p><p>13、咳而有饮者，咳不得卧，卧则气急，此为实咳，不能言，言则气短，此为虚咳，病多端，治各异法，谨守其道，庶可万全。</p><p>14、咳家其脉弦者，此为有水，$f{十枣汤}主之。</p><p>15、咳而气逆，喉中作水鸡声者，$f{射干麻黄汤}主之。</p><p>16、咳逆上气，时唾浊痰，但坐不得眠者，$f{皂荚丸}主之。</p><p>17、咳而脉浮者，$f{厚朴麻黄汤}主之。</p><p>18、咳而脉沉者，$f{泽漆汤}主之。</p><p>19、咳而上气，咽喉不利，脉数者，$f{麦门冬汤}主之。</p><p>20、咳逆倚息，不得卧，脉浮弦者，$f{小青龙汤}主之。</p><p>21、咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓，如米粥者，此为肺痈，$f{桔梗汤}主之。</p><p>22、咳而气喘，目如脱状，脉浮大者，此为肺胀，$f{越婢加半夏汤}主之；$f{小青龙加石膏汤}亦主之。</p><p>23、咳而气逆，喘鸣，迫塞胸满而胀，一身面目浮肿，鼻出清涕，不闻香臭，此为肺胀，$f{葶苈大枣泻肺汤}主之。</p><p>24、似咳非咳，唾多涎沫，其人不渴，此为肺冷，$f{甘草干姜汤}主之。</p><p>25、咳而唾涎沫不止，咽燥，口渴，其脉浮细而数者，此为肺痿，$f{炙甘草汤}主之。</p><p>26、问曰：饮病奈何？师曰：饮病有四：曰痰饮，曰悬饮，曰溢饮，曰支饮。其人素盛今瘦，水走肠间，沥沥有声，为痰饮，水流胁下，咳唾引痛，为悬饮；水归四肢，当汗不汗，身体疼重，为溢饮；水停膈下，咳逆倚息，短气不得卧，其形如肿，为支饮。</p><p>27、水在心，则心下坚筑，短气，恶水不欲饮；水在肺，必吐涎沫，欲饮水；水在脾，则少气身重；水在肝，则胁下支满，嚏则胁痛；水在肾，则心下悸。</p><p>28、心下有留饮，其人必背寒冷如掌大，咳则肋下痛引缺盆。</p><p>29、胸中有留饮，其人必短气而渴，四肢历节痛。</p><p>30、夫平人食少饮多，水停心下，久久成病，甚者则悸，微者短气，脉双弦者寒也，脉偏弦者饮也。</p><p>31、夫短气有微饮者，当从小便去之。</p><p>32、病者脉伏，其人欲自利，利反快，虽利，心下续坚满，此为留饮，$f{甘遂半夏汤}主之。</p><p>33、心下有痰饮，胸胁支满，目眩，脉沉弦者，$f{茯苓桂枝白术甘草汤}主之。</p><p>34、悬饮内痛，脉沉而弦者，$f{十枣汤}主之。</p><p>35、病溢饮者，当发其汗，$f{大青龙汤}主之，$f{小青龙汤}亦主之。</p><p>36、膈间支饮，其人喘满，心下痞坚，面色黧黑，其脉沉紧，得之数十日，医吐下之不愈者，$f{木防已汤}主之；不差，$f{木防已去石膏加茯苓芒硝汤}主之。</p><p>37、心下有支饮，其人苦冒眩，$f{泽泻汤}主之。</p><p>38、支饮，胸满者，$f{厚朴大黄汤}主之。</p><p>39、支饮，不得息，$f{葶苈大枣泻肺汤}主之。</p><p>40、支饮，口不渴，作呕者，或吐水者，$f{小半夏汤}主之。</p><p>41、腹满，口舌干燥，肠间有水气者，$f{防已椒目葶苈大黄丸}主之。</p><p>42、膈间有水气，呕、吐、眩、悸者，$f{小半夏加茯苓汤}主之。</p><p>43、病人脐下悸，吐涎沫而头眩者，此有水也，$f{五苓散}主之。</p><p>44、师曰：病有风水，有皮水，有正水，有石水，有黄汗。</p>\n<p></p>\n<p>           风水其脉自浮，其证骨节疼痛，恶风。</p>\n<p>           皮水其脉亦浮，其证尉肿，按之没指，不恶风，腹如鼓，不渴，当发其汗。</p>\n<p>           正水其脉沉迟，其证为喘。</p>\n<p>           石水其脉自沉，其证腹满不喘，当利其小便。</p>\n<p>           黄汗其脉沉迟，其证发热，胸满，四肢头面肿，久不愈，必致痈脓。</p><p>45、脉浮而洪，浮则为风，洪则为气。风气相搏，风强则为瘾疹，身体为痒，痒者为泻风，久为痂癞。气强则为水，难以俯仰，身体洪肿，汗出乃愈。恶风则虚，此为风水，不恶风者，小便通利，上焦有寒，其口多涎，此为黄汗。</p><p>46、寸口脉沉滑者，中有水气，面目肿大有热，名曰风水。其人之目窠上微肿，如蚕新卧起状，其颈脉动，时时咳，按其手足上，陷而不起者，亦曰风水。</p><p>47、太阳病，脉浮而紧，法当骨节疼痛，今反不痛，体重而酸，其人不渴，此为风水，</p>\n<p>       汗出即愈，恶寒者此为极虚，发汗得之。渴而不恶寒者，此为皮水。</p>\n<p>       身肿而冷，状如周痹，胸中窒，不能食，反聚痛，躁不得眠，此为黄汗。</p>\n<p>       痛在骨节，咳而喘不渴者，此为正水，其状如肿，发汗则愈。然诸病此者若渴而下利，小便数者，皆不可发汗，但当利其小便。</p><p>48、心水为病，其身重而少气，不得卧，烦躁，阴肿。</p><p>49、肝水为病，其腹大，不能自转侧，胁下痛，津液微生，小便续通。</p><p>50、肺水为病，其身肿，小便难，时时鸭溏。</p><p>51、脾水为病，其腹大，四肢苦重，津液不生，但苦少气，小便难。</p><p>52、肾水为病，其腹大，脐肿，腰痛，不得溺，阴下湿如牛鼻上汗，其足逆冷，面反瘦。</p><p>53、诸有水者，腰以下肿，当利小便；腰以上肿，当发汗乃愈。</p><p>54、寸口脉沉而迟，沉则为水，迟则为寒，寒水相搏，脾气衰则骛溏，胃气衰则身肿，名曰水分。</p><p>55、少阳脉卑，少阴脉细，男子则小便不利；妇人则经水不利；名曰血分。</p><p>56、妇人经水，前断后病水者，名曰血分，此病难治；先病水，后经水断，名曰水分，此病易治，水去则经自下也。</p><p>57、寸口脉沉而数，数则为出，沉则为入，出为阳实，入为阴结，趺阳脉微而弦，微则无胃气，弦则不得息；少阴脉沉而滑，沉为在里，滑则为实，沉滑相搏，血结胞门，其瘕不泻，经络不通，名曰血分。</p><p>58、问曰：病者苦水，面目身体皆肿，四肢亦肿，小便不利，脉之，不言水，反言胸中痛，气上冲咽状如炙肉，当感咳喘，审如师言，其脉何类？师曰：寸口脉沉而紧，沉为水，紧为寒，沉紧相搏，结在关元，始时尚微，年盛不觉，阳衰之后，荣卫相干，阳损阴盛，结寒微动，肾气上冲，咽喉塞噎，胁下急痛，医以为留饮而大下之，沉紧不去，其病不除，复重吐之，胃家虚烦，咽燥欲饮水，小便不利，水谷不化，面目手足浮肿，又与葶苈下水，当时如小差，食饮过度，肿复如前，胸胁苦痛，象若奔豚，其水扬溢，则咳喘逆，当先攻其冲气令止，乃治其咳，咳止，喘自差，先治新病，水当在后。</p><p>59、水之为病，其脉沉小者，属少阴为石水；沉迟者，属少阴为正水；浮而恶风者，为风水，属太阳，浮而不恶风者，为皮水，属太阳；虚肿者，属气分，发其汗即已，脉沉者，$f{麻黄附子甘草汤}主之；脉浮者，$f{麻黄加术汤}主之。</p><p>60、风水，脉浮，身重，汗出，恶风者，$f{防已黄芪汤}主之。</p><p>61、风水，恶风，一身悉肿，脉浮不渴，续自汗出，无大热者，$f{越婢汤}主之。</p><p>62、皮水，四肢肿，水气在皮肤中，四肢聂聂动者，$f{防已茯苓汤}主之。</p><p>63、里水，一身面目黄肿，其脉沉，小便不利，$f{甘草麻黄汤}主之；$f{越婢加术汤}亦主之。</p><p>64、问曰：黄汗之为病，身体肿，若重汗出而发热口渴，状如风水，汗沾衣，色正黄如柏汁，脉自沉，从何得之？</p>\n<p></p>\n<p>       师曰：以汗出入水中浴，水从汗孔入得之，宜$f{黄芪芍药桂枝汤}。</p><p>65、黄汗之病，两胫自冷，假令发热，此属历节，食已汗出，暮常盗汗，此荣气热也；若汗出已，反发热者，久久身必甲错；若发热不止者，久久必生恶疮；若身重，汗出已辙，轻者，久久身必瞤，瞤即胸痛；又从腰以上汗出，以下无汗，腰臗弛痛，如有物在皮中状，剧则不能食，身疼重，烦躁，小便不利，此为黄汗，$f{桂枝加黄芪汤}主之。</p><p>66、寸口脉沉而弱，沉即主骨，弱即主筋，沉即为肾，弱即为肝，汗出入水中，如水伤心，历节痛，黄汗出，故曰历节。</p><p>67、味酸则伤筋，筋伤则缓，名曰泄，咸则伤骨，骨伤则痿，名曰枯，枯泄相搏，名曰断泄。荣气不通，卫不独行，荣卫俱微，三焦无御，四属断绝，身体赢瘦，独足肿大，黄汗出，两胫热，便为历节。</p><p>68、少阴，脉浮而弱，弱则血不足，浮则为风，风血相搏，即疼痛如掣。</p><p>69、肥盛之人，脉涩小，短气，自汗出，历节疼，不可屈伸，此皆饮酒汗出当风所致也。</p><p>70、诸肢节疼痛，身体赢瘦，脚肿如脱，头眩短气，温温欲吐者，$f{桂枝芍药知母甘草汤}主之。</p><p>71、病历节，疼痛，不可屈伸，脉沉弱者，$f{乌头麻黄黄芪芍药甘草汤}主之。</p><p>72、病历节，疼痛，两足肿，大小便不利，脉沉紧者，$f{甘草麻黄汤}主之；脉沉而细数者，$f{越婢加术汤}主之。</p><p>73、师曰：寸口脉迟而涩，迟则为寒，涩为血不足，趺阳脉微而迟，微则为气，迟则为寒，胃气不足，则手足逆冷，荣卫不利，则腹满肠鸣相逐，气转膀胱，荣卫俱劳。阳气不通即身冷，阴气不通即骨疼，阳前通则恶寒，阴前通则痹不仁，阴阳相得，其气乃行，大气一转，寒气乃散，实则失气，虚则遗溺，名曰气分。</p><p>74、气分，心下坚，大如盘，边如旋杯，$f{桂枝甘草麻黄生姜大枣细辛附子汤}主之。</p><p>75、水饮，心下坚，大如盘，边如旋杯，$f{枳实白术汤}主之。</p><p>76、小便不利，其人有水气，若渴者，$f{括蒌瞿麦薯蓣丸}主之。</p><p>77、小便不利，其人有水气在血分者，$f{滑石乱发白鱼散}主之；$f{茯苓白术戎盐汤}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010028,"no":28}}', '2024-12-06T07:30:53.000Z', '2024-12-06T07:30:53.000Z', '2024-12-06T07:30:53.000Z', '1、师曰：咳嗽发于肺，不专属于肺病也。五脏，六腑，感受客邪，皆能致咳。所以然者，邪气上逆，必干于肺，肺为气动，发声为咳，欲知其源，必察脉息，为子条记，传与后贤。 2、肺咳，脉短而涩。假令浮而涩，知受风邪；紧短而涩，知受寒邪；数短而涩，知受热邪；急短而涩，知受燥邪；濡短而涩，知受湿邪。此肺咳之因也。其状则喘息有音，甚则唾血。 3、心咳，脉大而散。假令浮大而散，知受风邪，紧大而散，知受寒邪；数大而散，知受热邪；急大而散，知受燥邪；濡大而散，知受湿邪；此心咳之因也。其状则心痛，喉中介介如梗，甚则咽肿，喉痹。 4、肝咳，脉弦而涩。假令浮弦而涩，知受风邪；弦紧而涩，知受寒邪；弦数而涩，知受热邪；弦急而涩，知受燥邪；弦濡而涩，知受湿邪；此肝咳之因也。其状则两胁下痛，甚则不可以转，转则两胠下满。 5、脾咳，脉濡而涩。假令浮濡而涩，知受风邪；沉濡而涩，知受寒邪；数濡而涩，知受热邪；急濡而涩，知受燥邪；迟濡而涩，知受湿邪；此脾咳之因也。其状则右肋下痛，隐隐引背，甚则不可以动，动则咳剧。 6、肾咳，脉沉而濡。假令沉弦而濡，知受风邪；沉紧而濡，知受寒邪；沉数而濡，知受热邪；沉急而濡，知受燥邪；沉滞而濡，知受湿邪；此肾咳之因也。其状则肩背相引而痛，甚则咳涎。 7、肺咳不已，则流于大肠，脉与肺同，其状则咳而遗矢也。 8、心咳不已，则流于小肠，脉与心同，其状则咳而失气，气与咳俱失也。 9、肝咳不已，则流于胆，脉与肝同，其状则呕苦汁也。 10、脾咳不已，则流于胃，脉与脾同，其状则呕，呕甚则长虫出也。 11、肾咳不已，则流于膀胱，脉与肾同，其状则咳而遗溺也。 12、久咳不已，则移于三焦，脉随证易，其状则咳而腹满，不欲食饮也。 13、咳而有饮者，咳不得卧，卧则气急，此为实咳，不能言，言则气短，此为虚咳，病多端，治各异法，谨守其道，庶可万全。 14、咳家其脉弦者，此为有水，$f{十枣汤}主之。 15、咳而气逆，喉中作水鸡声者，$f{射干麻黄汤}主之。 16、咳逆上气，时唾浊痰，但坐不得眠者，$f{皂荚丸}主之。 17、咳而脉浮者，$f{厚朴麻黄汤}主之。 18、咳而脉沉者，$f{泽漆汤}主之。 19、咳而上气，咽喉不利，脉数者，$f{麦门冬汤}主之。 20、咳逆倚息，不得卧，脉浮弦者，$f{小青龙汤}主之。 21、咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓，如米粥者，此为肺痈，$f{桔梗汤}主之。 22、咳而气喘，目如脱状，脉浮大者，此为肺胀，$f{越婢加半夏汤}主之；$f{小青龙加石膏汤}亦主之。 23、咳而气逆，喘鸣，迫塞胸满而胀，一身面目浮肿，鼻出清涕，不闻香臭，此为肺胀，$f{葶苈大枣泻肺汤}主之。 24、似咳非咳，唾多涎沫，其人不渴，此为肺冷，$f{甘草干姜汤}主之。 25、咳而唾涎沫不止，咽燥，口渴，其脉浮细而数者，此为肺痿，$f{炙甘草汤}主之。 26、问曰：饮病奈何？师曰：饮病有四：曰痰饮，曰悬饮，曰溢饮，曰支饮。其人素盛今瘦，水走肠间，沥沥有声，为痰饮，水流胁下，咳唾引痛，为悬饮；水归四肢，当汗不汗，身体疼重，为溢饮；水停膈下，咳逆倚息，短气不得卧，其形如肿，为支饮。 27、水在心，则心下坚筑，短气，恶水不欲饮；水在肺，必吐涎沫，欲饮水；水在脾，则少气身重；水在肝，则胁下支满，嚏则胁痛；水在肾，则心下悸。 28、心下有留饮，其人必背寒冷如掌大，咳则肋下痛引缺盆。 29、胸中有留饮，其人必短气而渴，四肢历节痛。 30、夫平人食少饮多，水停心下，久久成病，甚者则悸，微者短气，脉双弦者寒也，脉偏弦者饮也。 31、夫短气有微饮者，当从小便去之。 32、病者脉伏，其人欲自利，利反快，虽利，心下续坚满，此为留饮，$f{甘遂半夏汤}主之。 33、心下有痰饮，胸胁支满，目眩，脉沉弦者，$f{茯苓桂枝白术甘草汤}主之。 34、悬饮内痛，脉沉而弦者，$f{十枣汤}主之。 35、病溢饮者，当发其汗，$f{大青龙汤}主之，$f{小青龙汤}亦主之。 36、膈间支饮，其人喘满，心下痞坚，面色黧黑，其脉沉紧，得之数十日，医吐下之不愈者，$f{木防已汤}主之；不差，$f{木防已去石膏加茯苓芒硝汤}主之。 37、心下有支饮，其人苦冒眩，$f{泽泻汤}主之。 38、支饮，胸满者，$f{厚朴大黄汤}主之。 39、支饮，不得息，$f{葶苈大枣泻肺汤}主之。 40、支饮，口不渴，作呕者，或吐水者，$f{小半夏汤}主之。 41、腹满，口舌干燥，肠间有水气者，$f{防已椒目葶苈大黄丸}主之。 42、膈间有水气，呕、吐、眩、悸者，$f{小半夏加茯苓汤}主之。 43、病人脐下悸，吐涎沫而头眩者，此有水也，$f{五苓散}主之。 44、师曰：病有风水，有皮水，有正水，有石水，有黄汗。 风水其脉自浮，其证骨节疼痛，恶风。 皮水其脉亦浮，其证尉肿，按之没指，不恶风，腹如鼓，不渴，当发其汗。 正水其脉沉迟，其证为喘。 石水其脉自沉，其证腹满不喘，当利其小便。 黄汗其脉沉迟，其证发热，胸满，四肢头面肿，久不愈，必致痈脓。 45、脉浮而洪，浮则为风，洪则为气。风气相搏，风强则为瘾疹，身体为痒，痒者为泻风，久为痂癞。气强则为水，难以俯仰，身体洪肿，汗出乃愈。恶风则虚，此为风水，不恶风者，小便通利，上焦有寒，其口多涎，此为黄汗。 46、寸口脉沉滑者，中有水气，面目肿大有热，名曰风水。其人之目窠上微肿，如蚕新卧起状，其颈脉动，时时咳，按其手足上，陷而不起者，亦曰风水。 47、太阳病，脉浮而紧，法当骨节疼痛，今反不痛，体重而酸，其人不渴，此为风水， 汗出即愈，恶寒者此为极虚，发汗得之。渴而不恶寒者，此为皮水。 身肿而冷，状如周痹，胸中窒，不能食，反聚痛，躁不得眠，此为黄汗。 痛在骨节，咳而喘不渴者，此为正水，其状如肿，发汗则愈。然诸病此者若渴而下利，小便数者，皆不可发汗，但当利其小便。 48、心水为病，其身重而少气，不得卧，烦躁，阴肿。 49、肝水为病，其腹大，不能自转侧，胁下痛，津液微生，小便续通。 50、肺水为病，其身肿，小便难，时时鸭溏。 51、脾水为病，其腹大，四肢苦重，津液不生，但苦少气，小便难。 52、肾水为病，其腹大，脐肿，腰痛，不得溺，阴下湿如牛鼻上汗，其足逆冷，面反瘦。 53、诸有水者，腰以下肿，当利小便；腰以上肿，当发汗乃愈。 54、寸口脉沉而迟，沉则为水，迟则为寒，寒水相搏，脾气衰则骛溏，胃气衰则身肿，名曰水分。 55、少阳脉卑，少阴脉细，男子则小便不利；妇人则经水不利；名曰血分。 56、妇人经水，前断后病水者，名曰血分，此病难治；先病水，后经水断，名曰水分，此病易治，水去则经自下也。 57、寸口脉沉而数，数则为出，沉则为入，出为阳实，入为阴结，趺阳脉微而弦，微则无胃气，弦则不得息；少阴脉沉而滑，沉为在里，滑则为实，沉滑相搏，血结胞门，其瘕不泻，经络不通，名曰血分。 58、问曰：病者苦水，面目身体皆肿，四肢亦肿，小便不利，脉之，不言水，反言胸中痛，气上冲咽状如炙肉，当感咳喘，审如师言，其脉何类？师曰：寸口脉沉而紧，沉为水，紧为寒，沉紧相搏，结在关元，始时尚微，年盛不觉，阳衰之后，荣卫相干，阳损阴盛，结寒微动，肾气上冲，咽喉塞噎，胁下急痛，医以为留饮而大下之，沉紧不去，其病不除，复重吐之，胃家虚烦，咽燥欲饮水，小便不利，水谷不化，面目手足浮肿，又与葶苈下水，当时如小差，食饮过度，肿复如前，胸胁苦痛，象若奔豚，其水扬溢，则咳喘逆，当先攻其冲气令止，乃治其咳，咳止，喘自差，先治新病，水当在后。 59、水之为病，其脉沉小者，属少阴为石水；沉迟者，属少阴为正水；浮而恶风者，为风水，属太阳，浮而不恶风者，为皮水，属太阳；虚肿者，属气分，发其汗即已，脉沉者，$f{麻黄附子甘草汤}主之；脉浮者，$f{麻黄加术汤}主之。 60、风水，脉浮，身重，汗出，恶风者，$f{防已黄芪汤}主之。 61、风水，恶风，一身悉肿，脉浮不渴，续自汗出，无大热者，$f{越婢汤}主之。 62、皮水，四肢肿，水气在皮肤中，四肢聂聂动者，$f{防已茯苓汤}主之。 63、里水，一身面目黄肿，其脉沉，小便不利，$f{甘草麻黄汤}主之；$f{越婢加术汤}亦主之。 64、问曰：黄汗之为病，身体肿，若重汗出而发热口渴，状如风水，汗沾衣，色正黄如柏汁，脉自沉，从何得之？ 师曰：以汗出入水中浴，水从汗孔入得之，宜$f{黄芪芍药桂枝汤}。 65、黄汗之病，两胫自冷，假令发热，此属历节，食已汗出，暮常盗汗，此荣气热也；若汗出已，反发热者，久久身必甲错；若发热不止者，久久必生恶疮；若身重，汗出已辙，轻者，久久身必瞤，瞤即胸痛；又从腰以上汗出，以下无汗，腰臗弛痛，如有物在皮中状，剧则不能食，身疼重，烦躁，小便不利，此为黄汗，$f{桂枝加黄芪汤}主之。 66、寸口脉沉而弱，沉即主骨，弱即主筋，沉即为肾，弱即为肝，汗出入水中，如水伤心，历节痛，黄汗出，故曰历节。 67、味酸则伤筋，筋伤则缓，名曰泄，咸则伤骨，骨伤则痿，名曰枯，枯泄相搏，名曰断泄。荣气不通，卫不独行，荣卫俱微，三焦无御，四属断绝，身体赢瘦，独足肿大，黄汗出，两胫热，便为历节。 68、少阴，脉浮而弱，弱则血不足，浮则为风，风血相搏，即疼痛如掣。 69、肥盛之人，脉涩小，短气，自汗出，历节疼，不可屈伸，此皆饮酒汗出当风所致也。 70、诸肢节疼痛，身体赢瘦，脚肿如脱，头眩短气，温温欲吐者，$f{桂枝芍药知母甘草汤}主之。 71、病历节，疼痛，不可屈伸，脉沉弱者，$f{乌头麻黄黄芪芍药甘草汤}主之。 72、病历节，疼痛，两足肿，大小便不利，脉沉紧者，$f{甘草麻黄汤}主之；脉沉而细数者，$f{越婢加术汤}主之。 73、师曰：寸口脉迟而涩，迟则为寒，涩为血不足，趺阳脉微而迟，微则为气，迟则为寒，胃气不足，则手足逆冷，荣卫不利，则腹满肠鸣相逐，气转膀胱，荣卫俱劳。阳气不通即身冷，阴气不通即骨疼，阳前通则恶寒，阴前通则痹不仁，阴阳相得，其气乃行，大气一转，寒气乃散，实则失气，虚则遗溺，名曰气分。 74、气分，心下坚，大如盘，边如旋杯，$f{桂枝甘草麻黄生姜大枣细辛附子汤}主之。 75、水饮，心下坚，大如盘，边如旋杯，$f{枳实白术汤}主之。 76、小便不利，其人有水气，若渴者，$f{括蒌瞿麦薯蓣丸}主之。 77、小便不利，其人有水气在血分者，$f{滑石乱发白鱼散}主之；$f{茯苓白术戎盐汤}亦主之。', '2024-12-06T07:30:53.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q71IeKIPLgK', 1, '{"title":"辨瘀血吐衄下血疮痈病脉证并治","description":"<p>1、病人胸满、唇痿、舌青、口燥，但欲嗽水，不欲咽，无寒热，脉微大来迟，腹不满，其言我满，此为有瘀血。</p><p>2、病人如有热状，烦满，口干燥而渴，其脉反无热，此为阴伏，是瘀血也，当下之，宜$f{下瘀血汤}。</p><p>3、膈间停留瘀血，若吐血色黑者，$f{桔梗汤}主之。</p><p>4、吐血不止者，$f{柏叶汤}主之；$f{黄土汤}亦主之。</p><p>5、心气不足，吐血，若衄血者，$f{泻心汤}主之。</p><p>6、下血，先便而后血者，此远血也，$f{黄土汤}主之。</p><p>7、下血，先血而便者，此近血也，$f{赤豆当归散}主之。</p><p>8、师曰：病人面无色，无寒热，脉沉弦者，必衄血；脉浮而弱，按之则绝者，必下血，烦而咳者，必吐血。</p><p>9、从春至夏衄血者，属太阳也；从秋至冬衄血者，属阳明也。</p><p>10、尺脉浮，目睛晕黄者，衄未止也；黄去睛慧了者，知衄已止。</p><p>11、问曰：寸口脉微浮而涩，法当亡血，若汗出，设不汗出者云何？</p>\n<p></p>\n<p>           师曰：若身有疮，被刀斧所伤，亡血故也，此名金疮；无脓者，$f{王不留行散}主之；有脓者，$f{排脓散}主之，$f{排脓汤}亦主之。</p><p>12、浸淫疮，从口流向四肢者，可治，从四肢流来入口者，不可治。</p><p>13、浸淫疮，$f{黄连粉}主之。</p><p>14、诸脉浮数，法当发热，而反洒浙恶寒，若有痛处，当发其痈。</p><p>15、师曰：诸痈肿者，欲知有脓无脓？以手掩肿上，热者，为有脓；不热者，为无脓也。</p><p>16、肠痈之为病，其身甲错，腹皮急，按之濡，如肿状，腹无积聚，身无热，脉数，此为肠内有痈也，$f{薏苡附子败酱散}主之。</p><p>17、少腹肿痞，按之即痛如淋，小便自调，时时发热，自汗出，复恶寒，此为肠外有痈也；其脉沉紧者，脓未成也，下之当有血；脉洪数者，脓已成也，可下之，$f{大黄牡丹汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010029,"no":29}}', '2024-12-06T07:31:11.000Z', '2024-12-06T07:31:11.000Z', '2024-12-06T07:31:11.000Z', '1、病人胸满、唇痿、舌青、口燥，但欲嗽水，不欲咽，无寒热，脉微大来迟，腹不满，其言我满，此为有瘀血。 2、病人如有热状，烦满，口干燥而渴，其脉反无热，此为阴伏，是瘀血也，当下之，宜$f{下瘀血汤}。 3、膈间停留瘀血，若吐血色黑者，$f{桔梗汤}主之。 4、吐血不止者，$f{柏叶汤}主之；$f{黄土汤}亦主之。 5、心气不足，吐血，若衄血者，$f{泻心汤}主之。 6、下血，先便而后血者，此远血也，$f{黄土汤}主之。 7、下血，先血而便者，此近血也，$f{赤豆当归散}主之。 8、师曰：病人面无色，无寒热，脉沉弦者，必衄血；脉浮而弱，按之则绝者，必下血，烦而咳者，必吐血。 9、从春至夏衄血者，属太阳也；从秋至冬衄血者，属阳明也。 10、尺脉浮，目睛晕黄者，衄未止也；黄去睛慧了者，知衄已止。 11、问曰：寸口脉微浮而涩，法当亡血，若汗出，设不汗出者云何？ 师曰：若身有疮，被刀斧所伤，亡血故也，此名金疮；无脓者，$f{王不留行散}主之；有脓者，$f{排脓散}主之，$f{排脓汤}亦主之。 12、浸淫疮，从口流向四肢者，可治，从四肢流来入口者，不可治。 13、浸淫疮，$f{黄连粉}主之。 14、诸脉浮数，法当发热，而反洒浙恶寒，若有痛处，当发其痈。 15、师曰：诸痈肿者，欲知有脓无脓？以手掩肿上，热者，为有脓；不热者，为无脓也。 16、肠痈之为病，其身甲错，腹皮急，按之濡，如肿状，腹无积聚，身无热，脉数，此为肠内有痈也，$f{薏苡附子败酱散}主之。 17、少腹肿痞，按之即痛如淋，小便自调，时时发热，自汗出，复恶寒，此为肠外有痈也；其脉沉紧者，脓未成也，下之当有血；脉洪数者，脓已成也，可下之，$f{大黄牡丹汤}主之。', '2024-12-06T07:31:11.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SKF0QSVG4Eo', 1, '{"title":"辨胸痹病脉证并治","description":"<p>1、师曰：夫脉当取太过不及，阳微阴弦，即胸痹而痛；所以然者，责其极虚也，今阳虚，知在上焦，胸痹而痛者，以其脉弦故也。</p><p>2、平人无寒热，胸痹，短气不足以息者，实也。</p><p>3、胸痹，喘、息、咳、唾，胸背痛，寸脉沉迟，关上小紧数者，$f{括蒌薤白白酒汤}主之。</p><p>4、胸痹不得卧，心痛彻背者，$f{括蒌薤白半夏汤}主之。</p><p>5、胸痹，心中痞，留气结在胸，胸满，胁下逆抢心者，枳实薤白桂枝厚朴括蒌汤主之；$f{桂枝人参汤}亦主之。</p><p>6、胸痹，胸中气塞，或短气者，此胸中有水气也，$f{茯苓杏仁甘草汤}主之；$f{橘皮枳实生姜汤}亦主之。</p><p>7、胸痹，时缓时急者，$f{薏苡附子散}主之。</p><p>8、胸痹，心中悬痛者，$f{桂枝生姜枳实汤}主之。</p><p>9、胸痹，胸痛彻背，背痛彻胸者，$f{乌头赤石脂丸}主之。</p><p>10、胸痹，其人常欲蹈，其胸上先未苦时，但欲饮热者，$f{旋覆花汤}主之。</p><p>11、胸痹，心下悸者，责其有痰也，$f{半夏麻黄丸}主之。</p><p>12、胸痹，心下痛，或有恶血积冷者，$f{九痛丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010030,"no":30}}', '2024-12-06T07:31:36.000Z', '2024-12-06T07:31:36.000Z', '2024-12-06T07:31:36.000Z', '1、师曰：夫脉当取太过不及，阳微阴弦，即胸痹而痛；所以然者，责其极虚也，今阳虚，知在上焦，胸痹而痛者，以其脉弦故也。 2、平人无寒热，胸痹，短气不足以息者，实也。 3、胸痹，喘、息、咳、唾，胸背痛，寸脉沉迟，关上小紧数者，$f{括蒌薤白白酒汤}主之。 4、胸痹不得卧，心痛彻背者，$f{括蒌薤白半夏汤}主之。 5、胸痹，心中痞，留气结在胸，胸满，胁下逆抢心者，枳实薤白桂枝厚朴括蒌汤主之；$f{桂枝人参汤}亦主之。 6、胸痹，胸中气塞，或短气者，此胸中有水气也，$f{茯苓杏仁甘草汤}主之；$f{橘皮枳实生姜汤}亦主之。 7、胸痹，时缓时急者，$f{薏苡附子散}主之。 8、胸痹，心中悬痛者，$f{桂枝生姜枳实汤}主之。 9、胸痹，胸痛彻背，背痛彻胸者，$f{乌头赤石脂丸}主之。 10、胸痹，其人常欲蹈，其胸上先未苦时，但欲饮热者，$f{旋覆花汤}主之。 11、胸痹，心下悸者，责其有痰也，$f{半夏麻黄丸}主之。 12、胸痹，心下痛，或有恶血积冷者，$f{九痛丸}主之。', '2024-12-06T07:31:36.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qQPCJTZga3G', 1, '{"title":"辨妇人各病脉证并治","description":"<p>1、师曰：妇人得平脉，阴脉小弱，其人呕，不能食，无寒热，此为妊娠，$f{桂枝汤}主之；于法六十日当有此证；设有医治逆者，却一月；加吐下者，则绝之。</p><p>2、妇人宿有症病，经断未及三月，而得漏下不止，胎动在脐上者，此为症痼害；妊娠六月动者，前三月经水利时胎也；下血者，断后三月衄也；所以血不止者，其症不去故也，当下其症，$f{桂枝茯苓丸}主之。</p><p>3、妇人怀孕六七月，脉弦，发热，其胎愈胀，腹痛，恶寒，少腹如扇，所以然者，子藏开故也，当以$f{附子汤}温之。</p><p>4、师曰：妇人有漏下者；有半产后续下血都不绝者；假令妊娠腹中痛者，此为胞阻，$f{胶艾汤}主之。</p><p>5、妇人怀妊，腹中疞痛，$f{当归芍药散}主之。</p><p>6、妊娠，呕吐不止，$f{干姜人参半夏丸}主之。</p><p>7、妊娠，小便难，饮食如故，$f{当归贝母苦参丸}主之。</p><p>8、妊娠，有水气，小便不利，洒淅恶寒，起即头眩，$f{葵子茯苓散}主之。</p><p>9、妇人妊娠，身无他病，宜常服$f{当归散}，则临产不难，产后亦免生他病。</p><p>10、妊娠，身有寒湿，或腹痛，或心烦，心痛，不能饮食，其胎跃跃动者，宜养之，$f{白术散}主之。</p><p>12、问曰：新产妇人有三病，一者病痉，二者郁冒，三者大便难，何谓也？</p>\n<p></p>\n<p>         师曰：新产血虚多汗出，喜中风，故令病痉；亡血，复汗，寒多，故令郁冒；亡津液胃燥，故大便难。</p><p>13、产妇郁冒，其脉微弱，呕不能食，大便反坚，但头汗出。所以然者，血虚而厥，厥则必冒，冒家欲解，必大汗出；以血虚下厥，孤阳上出，故头汗出也。所以产妇喜汗出者，亡阴血虚，阳气独盛，故当汗出，阴阳乃复；大便坚，呕不能食者，$f{小柴胡汤}主之。</p><p>14、郁冒病解，能食，七八日更发热者，此为胃实，$f{大承气汤}主之。</p><p>15、产后腹中疞痛，若虚寒不足者，$f{当归生姜羊肉汤}主之。</p><p>16、产后腹痛，烦满不得卧，不可下也，宜$f{枳实芍药散}和之。</p><p>17、师曰：产后腹痛，法当以$f{枳实芍药散}；假令不愈，必腹中有瘀血着脐下也，$f{下瘀血汤}主之。</p><p>18、产后七八日，无太阳证，少腹坚痛，此恶露不尽也；若不大便，烦躁，发热，脉微实者，宜和之；若日晡所烦躁，食则谵语，至夜即愈者，$f{大承气汤}主之。</p><p>19、产后中风，数十日不解，头痛，恶寒，发热，心下满，干呕，续自微汗出，$f{小柴胡汤}主之。</p><p>20、产后中风，发热，面赤，头痛，汗出而喘，脉弦数者，$f{竹叶汤}主之。</p><p>21、产后烦乱，呕逆，无外证者，此乳中虚也，$f{竹皮大丸}主之。</p><p>22、产后下利，脉虚极者，$f{白头翁加甘草阿胶汤}主之。</p><p>23、妇人咽中如有炙脔者，$f{半夏厚朴茯苓生姜汤}主之。</p><p>24、妇人脏燥，悲伤欲哭，数欠伸，象如神灵所作者，$f{甘草小麦大枣汤}主之。</p><p>25、妇人吐涎沫，医反下之，心下即痞，当先治其吐涎沫，后治其痞，治吐宜$f{桔梗甘草茯苓泽泻汤}；治痞宜$f{泻心汤}。</p><p>26、妇人之病，因虚积冷结，为诸经水断绝，血结胞门。或绕脐疼痛，状如寒疝；或痛在关元，肌若鱼鳞；或阴中掣痛，少腹恶寒；或引腰脊，或下气街；此皆带下。万病一言，察其寒、热、虚、实、紧、弦、行其针药，各探其源，子当辨记，勿谓不然。</p><p>27、问曰：妇人年五十所，病下血数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥，何也？</p>\n<p></p>\n<p>       师曰：此病属带下，何以知之？曾经半产，瘀血在少腹不去，故唇口干燥也，$f{温经汤}主之。</p><p>28、经水不利，少腹满痛，或一月再经者，$f{王瓜根散}主之。阴肿者，亦主之。</p><p>29、妇人半产若漏下者，$f{旋覆花汤}主之；脉虚弱者，$f{黄芪当归汤}主之。</p><p>30、妇人陷经，漏下色黑如块者，$f{胶姜汤}主之。</p><p>31、妇人少腹满，如敦状，小便微难而不渴，或经后产后者，此为水与血俱结在血室也，$f{大黄甘遂阿胶汤}主之。</p><p>32、妇人时腹痛，经水时行时止，止而复行者，$f{抵当汤}主之。</p><p>33、妇人经水闭，脏坚癖，下白物不止，此中有干血也，$f{矾石丸}主之。</p><p>34、妇人六十二种风证，腹中气血如刺痛者，$f{红蓝花酒}主之。</p><p>35、妇人腹中诸病痛者，$f{当归芍药散}主之；$f{小建中汤}亦主之；</p><p>36、问曰：妇人病，饮食如故，烦热不得卧，而反倚息者，何也？</p>\n<p></p>\n<p>          师曰：此名转胞，不得溺也，以胞系了戾，故致此病，但利小便则愈，$f{肾气丸}主之。</p><p>37、妇人阴寒，$f{蛇床子散}主之。</p><p>38、少阴脉滑而数者，阴中疮也，蚀烂者，$f{狼牙汤}主之。</p><p>39、胃气下泄，阴吹而喧，如失气者，此谷道实也，$f{猪膏发煎}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","section":10010031,"no":31}}', '2024-12-06T07:31:45.000Z', '2024-12-06T07:31:45.000Z', '2024-12-06T07:31:45.000Z', '1、师曰：妇人得平脉，阴脉小弱，其人呕，不能食，无寒热，此为妊娠，$f{桂枝汤}主之；于法六十日当有此证；设有医治逆者，却一月；加吐下者，则绝之。 2、妇人宿有症病，经断未及三月，而得漏下不止，胎动在脐上者，此为症痼害；妊娠六月动者，前三月经水利时胎也；下血者，断后三月衄也；所以血不止者，其症不去故也，当下其症，$f{桂枝茯苓丸}主之。 3、妇人怀孕六七月，脉弦，发热，其胎愈胀，腹痛，恶寒，少腹如扇，所以然者，子藏开故也，当以$f{附子汤}温之。 4、师曰：妇人有漏下者；有半产后续下血都不绝者；假令妊娠腹中痛者，此为胞阻，$f{胶艾汤}主之。 5、妇人怀妊，腹中疞痛，$f{当归芍药散}主之。 6、妊娠，呕吐不止，$f{干姜人参半夏丸}主之。 7、妊娠，小便难，饮食如故，$f{当归贝母苦参丸}主之。 8、妊娠，有水气，小便不利，洒淅恶寒，起即头眩，$f{葵子茯苓散}主之。 9、妇人妊娠，身无他病，宜常服$f{当归散}，则临产不难，产后亦免生他病。 10、妊娠，身有寒湿，或腹痛，或心烦，心痛，不能饮食，其胎跃跃动者，宜养之，$f{白术散}主之。 12、问曰：新产妇人有三病，一者病痉，二者郁冒，三者大便难，何谓也？ 师曰：新产血虚多汗出，喜中风，故令病痉；亡血，复汗，寒多，故令郁冒；亡津液胃燥，故大便难。 13、产妇郁冒，其脉微弱，呕不能食，大便反坚，但头汗出。所以然者，血虚而厥，厥则必冒，冒家欲解，必大汗出；以血虚下厥，孤阳上出，故头汗出也。所以产妇喜汗出者，亡阴血虚，阳气独盛，故当汗出，阴阳乃复；大便坚，呕不能食者，$f{小柴胡汤}主之。 14、郁冒病解，能食，七八日更发热者，此为胃实，$f{大承气汤}主之。 15、产后腹中疞痛，若虚寒不足者，$f{当归生姜羊肉汤}主之。 16、产后腹痛，烦满不得卧，不可下也，宜$f{枳实芍药散}和之。 17、师曰：产后腹痛，法当以$f{枳实芍药散}；假令不愈，必腹中有瘀血着脐下也，$f{下瘀血汤}主之。 18、产后七八日，无太阳证，少腹坚痛，此恶露不尽也；若不大便，烦躁，发热，脉微实者，宜和之；若日晡所烦躁，食则谵语，至夜即愈者，$f{大承气汤}主之。 19、产后中风，数十日不解，头痛，恶寒，发热，心下满，干呕，续自微汗出，$f{小柴胡汤}主之。 20、产后中风，发热，面赤，头痛，汗出而喘，脉弦数者，$f{竹叶汤}主之。 21、产后烦乱，呕逆，无外证者，此乳中虚也，$f{竹皮大丸}主之。 22、产后下利，脉虚极者，$f{白头翁加甘草阿胶汤}主之。 23、妇人咽中如有炙脔者，$f{半夏厚朴茯苓生姜汤}主之。 24、妇人脏燥，悲伤欲哭，数欠伸，象如神灵所作者，$f{甘草小麦大枣汤}主之。 25、妇人吐涎沫，医反下之，心下即痞，当先治其吐涎沫，后治其痞，治吐宜$f{桔梗甘草茯苓泽泻汤}；治痞宜$f{泻心汤}。 26、妇人之病，因虚积冷结，为诸经水断绝，血结胞门。或绕脐疼痛，状如寒疝；或痛在关元，肌若鱼鳞；或阴中掣痛，少腹恶寒；或引腰脊，或下气街；此皆带下。万病一言，察其寒、热、虚、实、紧、弦、行其针药，各探其源，子当辨记，勿谓不然。 27、问曰：妇人年五十所，病下血数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥，何也？ 师曰：此病属带下，何以知之？曾经半产，瘀血在少腹不去，故唇口干燥也，$f{温经汤}主之。 28、经水不利，少腹满痛，或一月再经者，$f{王瓜根散}主之。阴肿者，亦主之。 29、妇人半产若漏下者，$f{旋覆花汤}主之；脉虚弱者，$f{黄芪当归汤}主之。 30、妇人陷经，漏下色黑如块者，$f{胶姜汤}主之。 31、妇人少腹满，如敦状，小便微难而不渴，或经后产后者，此为水与血俱结在血室也，$f{大黄甘遂阿胶汤}主之。 32、妇人时腹痛，经水时行时止，止而复行者，$f{抵当汤}主之。 33、妇人经水闭，脏坚癖，下白物不止，此中有干血也，$f{矾石丸}主之。 34、妇人六十二种风证，腹中气血如刺痛者，$f{红蓝花酒}主之。 35、妇人腹中诸病痛者，$f{当归芍药散}主之；$f{小建中汤}亦主之； 36、问曰：妇人病，饮食如故，烦热不得卧，而反倚息者，何也？ 师曰：此名转胞，不得溺也，以胞系了戾，故致此病，但利小便则愈，$f{肾气丸}主之。 37、妇人阴寒，$f{蛇床子散}主之。 38、少阴脉滑而数者，阴中疮也，蚀烂者，$f{狼牙汤}主之。 39、胃气下泄，阴吹而喧，如失气者，此谷道实也，$f{猪膏发煎}主之。', '2024-12-06T07:31:45.000Z', 1, NULL, '5IGM9t76quT', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G8p8ju2wawz', 4, '{"title":"1","description":"<p>       论曰：余每览越人入虢之诊，望齐侯之色，未尝不慨然叹其才秀也。怪当今居世之士，曾不留神医药，精究方术，上以疗君亲之疾，下以救贫贱之厄，中以保身长全，以养其生，但竞逐荣势，企踵权豪，孜孜汲汲，惟名利是务，崇饰其末，忽弃其本，华其外，而悴其内，皮之不存，毛将安附焉。卒然遭邪风之气，婴非常之疾，患及祸至，而方震栗，降志屈节，钦望巫祝，告穷归天，束手受败，賫百年之寿命，持至贵之重器，委付凡医，恣其所措，咄嗟呜呼！厥身已毙，神明消灭，变为异物，幽潜重泉，徒为啼泣，痛夫！举世昏迷，莫能觉悟，不惜其命，若是轻生，彼何荣势之足云哉！而进不能爱人知人，退不能爱身知己，遇灾值祸，身居厄地，蒙蒙昧昧，憃若游魂。哀乎！趋势之士，驰竞浮华，不固根本，忘躯徇物，危若冰谷，至于是也。余宗族素多，向余二百，建安纪元以来，犹未十稔，其死亡者，三分有二，伤寒十居其七。感往昔之沦丧，伤横夭之莫救，乃勤求古训，博采众方，撰用《$m{素问}》、《$m{九卷}》、《$m{八十一难}》、《$m{阴阳大论}》、《$m{胎胪药录}》，并平脉辨证，为《$m{伤寒杂病论}》合十六卷，虽未能尽愈诸病，庶可以见病知源，若能寻余所集，思过半矣。夫天布五行，以运万类，人禀五常，以有五脏，经络府俞，阴阳会通，玄冥幽微，变化难极，自非才高识妙，岂能探其理致哉！上古有$n{神农、黄帝、歧伯、伯高、雷公、少俞、少师、仲文}，中世有$m{长桑、扁鹊，汉有公乘阳庆及仓公}，下此以往，未之闻也。观今之医，不念思求经旨，以演其所知，各承家技，终始顺旧，省疾问病，务在口给。相对须臾，便处汤药，按寸不及尺，握手不及足，人迎趺阳，三部不参，动数发息，不满五十，短期未知决诊，九候曾无仿佛，明堂阙庭，尽不见察，所谓窥管而已。夫欲视死别生，实为难矣。</p>\n<p></p>\n<p>      孔子云：生而知之者上，学则亚之，多闻博识，知之次也。余宿尚方术，请事斯语。</p>\n<p></p>\n<p> 汉长沙太守南阳张机序</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T07:39:37.000Z', '2024-12-06T07:39:37.000Z', '2024-12-06T07:39:37.000Z', '论曰：余每览越人入虢之诊，望齐侯之色，未尝不慨然叹其才秀也。怪当今居世之士，曾不留神医药，精究方术，上以疗君亲之疾，下以救贫贱之厄，中以保身长全，以养其生，但竞逐荣势，企踵权豪，孜孜汲汲，惟名利是务，崇饰其末，忽弃其本，华其外，而悴其内，皮之不存，毛将安附焉。卒然遭邪风之气，婴非常之疾，患及祸至，而方震栗，降志屈节，钦望巫祝，告穷归天，束手受败，賫百年之寿命，持至贵之重器，委付凡医，恣其所措，咄嗟呜呼！厥身已毙，神明消灭，变为异物，幽潜重泉，徒为啼泣，痛夫！举世昏迷，莫能觉悟，不惜其命，若是轻生，彼何荣势之足云哉！而进不能爱人知人，退不能爱身知己，遇灾值祸，身居厄地，蒙蒙昧昧，憃若游魂。哀乎！趋势之士，驰竞浮华，不固根本，忘躯徇物，危若冰谷，至于是也。余宗族素多，向余二百，建安纪元以来，犹未十稔，其死亡者，三分有二，伤寒十居其七。感往昔之沦丧，伤横夭之莫救，乃勤求古训，博采众方，撰用《$m{素问}》、《$m{九卷}》、《$m{八十一难}》、《$m{阴阳大论}》、《$m{胎胪药录}》，并平脉辨证，为《$m{伤寒杂病论}》合十六卷，虽未能尽愈诸病，庶可以见病知源，若能寻余所集，思过半矣。夫天布五行，以运万类，人禀五常，以有五脏，经络府俞，阴阳会通，玄冥幽微，变化难极，自非才高识妙，岂能探其理致哉！上古有$n{神农、黄帝、歧伯、伯高、雷公、少俞、少师、仲文}，中世有$m{长桑、扁鹊，汉有公乘阳庆及仓公}，下此以往，未之闻也。观今之医，不念思求经旨，以演其所知，各承家技，终始顺旧，省疾问病，务在口给。相对须臾，便处汤药，按寸不及尺，握手不及足，人迎趺阳，三部不参，动数发息，不满五十，短期未知决诊，九候曾无仿佛，明堂阙庭，尽不见察，所谓窥管而已。夫欲视死别生，实为难矣。 孔子云：生而知之者上，学则亚之，多闻博识，知之次也。余宿尚方术，请事斯语。 汉长沙太守南阳张机序', '2024-12-06T07:39:37.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FH7C1pOgiiZ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mzr6Kzn51cj', 4, '{"title":"1","description":"<p>        余闻吾师$n{张绍祖}先生之言曰：“吾家伤寒一书，相传共有一十三稿，每成一稿，传抄殆遍城邑，兹所存者为第十二稿，余者或为族人所秘，或付劫灰，不外是矣；叔和所得相传为第七次稿，与吾所脏者较，其间阙如固多，编次亦不相类，或为叔和所篡乱，或疑为宋人所增删，聚讼纷如，各执其说；然考晋时尚无刊本，犹是传抄，唐末宋初始易传抄为刊刻，遂称易简，以此言之，则坊间所刊者，不但非汉时之原稿，恐亦非叔和之原稿也。</p>\n<p></p>\n<p>       ”余聆训之下，始亦疑之，及读至伤寒例一卷，见其于可汗不可汗，可吐不可吐，可下不可下法，尽载其中，于六经已具之条为并不重引，法律谨严，始知坊间所刻之辨可汗不可汗，可吐不可吐，可下不可下，以及发汗 吐下后各卷，盖后人以读书之法，错杂其间，而未计及编书之法固不如是也，不然孔氏之徒，问仁者众，问政者繁，何不各类其类，而惮烦若此耶!吾师讳学正，自言为仲氏四十六世孙，自晋以后迁徙不一，其高祖复初公，自岭南复迁原籍，寄居光州，遂聚族焉。</p>\n<p>       吾师虽承家学，不以医名，亦不轻出此书以三示人，余得之受业者，殆有天焉。</p>\n<p>      余宿好方术，得针灸之学于永川邓师宪章公，后随侍先严游宦岭南，与吾师同寅，朝夕相过从，见余手执宋本伤寒论，笑问曰：“亦嗜此乎？”时余年仅弱冠，答曰：“非敢云嗜，尚未得其要领，正寻绎耳。”师曰：“子既好学，复知针灸，可以读伤寒论矣，吾有世传抄本伤寒杂病论十六卷，向不示人，得人不传，恐成坠绪。”遂历言此书颠末，及吾师家世滔滔不倦。先严促余曰：“速下拜。”于是即席拜之，得师事焉。今罗生哲初为吾邑知名人士，从习针灸历有年所，颇能好余之所好，余亦以所得者尽授之，余不负吾师，罗生亦必不负余，故特序其原起，罗生其志之，罗生其勉之。</p>\n<p></p>\n<p>       光绪二十年岁次甲午三月桂林左盛德序</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T07:51:53.000Z', '2024-12-06T07:51:53.000Z', '2024-12-06T07:51:53.000Z', '余闻吾师$n{张绍祖}先生之言曰：“吾家伤寒一书，相传共有一十三稿，每成一稿，传抄殆遍城邑，兹所存者为第十二稿，余者或为族人所秘，或付劫灰，不外是矣；叔和所得相传为第七次稿，与吾所脏者较，其间阙如固多，编次亦不相类，或为叔和所篡乱，或疑为宋人所增删，聚讼纷如，各执其说；然考晋时尚无刊本，犹是传抄，唐末宋初始易传抄为刊刻，遂称易简，以此言之，则坊间所刊者，不但非汉时之原稿，恐亦非叔和之原稿也。 ”余聆训之下，始亦疑之，及读至伤寒例一卷，见其于可汗不可汗，可吐不可吐，可下不可下法，尽载其中，于六经已具之条为并不重引，法律谨严，始知坊间所刻之辨可汗不可汗，可吐不可吐，可下不可下，以及发汗 吐下后各卷，盖后人以读书之法，错杂其间，而未计及编书之法固不如是也，不然孔氏之徒，问仁者众，问政者繁，何不各类其类，而惮烦若此耶!吾师讳学正，自言为仲氏四十六世孙，自晋以后迁徙不一，其高祖复初公，自岭南复迁原籍，寄居光州，遂聚族焉。 吾师虽承家学，不以医名，亦不轻出此书以三示人，余得之受业者，殆有天焉。 余宿好方术，得针灸之学于永川邓师宪章公，后随侍先严游宦岭南，与吾师同寅，朝夕相过从，见余手执宋本伤寒论，笑问曰：“亦嗜此乎？”时余年仅弱冠，答曰：“非敢云嗜，尚未得其要领，正寻绎耳。”师曰：“子既好学，复知针灸，可以读伤寒论矣，吾有世传抄本伤寒杂病论十六卷，向不示人，得人不传，恐成坠绪。”遂历言此书颠末，及吾师家世滔滔不倦。先严促余曰：“速下拜。”于是即席拜之，得师事焉。今罗生哲初为吾邑知名人士，从习针灸历有年所，颇能好余之所好，余亦以所得者尽授之，余不负吾师，罗生亦必不负余，故特序其原起，罗生其志之，罗生其勉之。 光绪二十年岁次甲午三月桂林左盛德序', '2024-12-06T07:51:53.000Z', 1, NULL, '5IGM9t76quT', 'section', 'oGwKvnSkJP1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nV5dKwWhtBc', 4, '{"title":"1","description":"<p>1、问曰：脉何以知气血脏腑之诊也？</p>\n<p> </p>\n<p>    师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。气独胜者，则脉强；血独盛者，则脉滑；气偏衰者，则脉微；血偏衰者，则脉涩；气血和者，则脉缓；气血平者，则脉平；气血乱者，则脉乱；气血脱者，则脉绝；阳迫气血，则脉数；阴阻气血，则脉迟；若感于邪，气血扰动，脉随变化，变化无穷，气血使之；病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:24:36.000Z', '2024-12-06T09:24:36.000Z', '2024-12-06T09:24:36.000Z', '1、问曰：脉何以知气血脏腑之诊也？ 师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。气独胜者，则脉强；血独盛者，则脉滑；气偏衰者，则脉微；血偏衰者，则脉涩；气血和者，则脉缓；气血平者，则脉平；气血乱者，则脉乱；气血脱者，则脉绝；阳迫气血，则脉数；阴阻气血，则脉迟；若感于邪，气血扰动，脉随变化，变化无穷，气血使之；病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。', '2024-12-06T09:24:36.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uGQiWtkN0FN', 4, '{"title":"2","description":"<p>2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。</p>\n<p></p>\n<p>       师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000302,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:24:36.000Z', '2024-12-06T09:24:36.000Z', '2024-12-06T09:24:36.000Z', '2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。 师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。', '2024-12-06T09:24:36.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1yhQTu61Bwt', 4, '{"title":"3","description":"<p>3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000303,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2W1BGA8Tzdi', 4, '{"title":"4","description":"<p>4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000304,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q41hTzQa42b', 4, '{"title":"5","description":"<p>5、问曰：经说，脉有三菽、六菽重者，何谓也？</p>\n<p></p>\n<p>     师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000305,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '5、问曰：经说，脉有三菽、六菽重者，何谓也？ 师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sW8XkVPJSmV', 4, '{"title":"6","description":"<p>6、问曰：东方肝脉，其形何似？</p>\n<p>      师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000306,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '6、问曰：东方肝脉，其形何似？ 师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OwES1r9rRk3', 4, '{"title":"7、南方心脉，其形何似","description":"<p>7、南方心脉，其形何似？</p>\n<p> </p>\n<p>      师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000307,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '7、南方心脉，其形何似？ 师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FsdVbnF7ehw', 4, '{"title":"8、西方肺脉，其形何似","description":"<p>8、西方肺脉，其形何似？</p>\n<p></p>\n<p>      师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000308,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '8、西方肺脉，其形何似？ 师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H7vLzQjqvXZ', 4, '{"title":"9、北方肾脉其形何似","description":"<p>9、北方肾脉其形何似？</p>\n<p></p>\n<p>     师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000309,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '9、北方肾脉其形何似？ 师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uDoZM9HHpiB', 4, '{"title":"10","description":"<p>10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000310,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0tr3l7UHuUP', 4, '{"title":"11","description":"<p>11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000311,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qMeu3oGSfdF', 4, '{"title":"12","description":"<p>12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。</p>\n<p></p>\n<p>        师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000312,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。 师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HY24NRkizf7', 4, '{"title":"13","description":"<p>13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000313,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lFzCUQmxvHS', 4, '{"title":"14","description":"<p>14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000314,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TTGkdYrx8fk', 4, '{"title":"15","description":"<p>15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000315,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QMarOMc8se9', 4, '{"title":"16","description":"<p>16、色白者，病在肺与大肠；假令身色白，明堂色微黑者，生；赤者，死；黄赤者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000316,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '16、色白者，病在肺与大肠；假令身色白，明堂色微黑者，生；赤者，死；黄赤者，半死半生也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sPRkOqVuK26', 4, '{"title":"17","description":"<p>17、色黑者，病在肾与膀胱；假令身色黑，明堂色微青者，生；黄者，死；黄赤者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000317,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '17、色黑者，病在肾与膀胱；假令身色黑，明堂色微青者，生；黄者，死；黄赤者，半死半生也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uz2rEzMM1JM', 4, '{"title":"18","description":"<p>18、阙庭脉色青而沉细，推之不移者，病在肝；青而浮大，推之随转者，病在胆。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000318,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '18、阙庭脉色青而沉细，推之不移者，病在肝；青而浮大，推之随转者，病在胆。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ojOyXwhz7LL', 4, '{"title":"19","description":"<p>19、阙庭脉色赤而沉细，推之参差不齐者，病在心；赤而横弋，推之愈赤者，病在小肠。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000319,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '19、阙庭脉色赤而沉细，推之参差不齐者，病在心；赤而横弋，推之愈赤者，病在小肠。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j8lG91h8bOi', 4, '{"title":"20","description":"<p>20、阙庭脉色黄，推之如水停留者，病在脾；如水急流者，病在胃。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000320,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '20、阙庭脉色黄，推之如水停留者，病在脾；如水急流者，病在胃。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dJ1HfT4oHOF', 4, '{"title":"21","description":"<p>21、阙庭脉色青白，推之久不还者，病在肺；推之即至者，病在大肠。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000321,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '21、阙庭脉色青白，推之久不还者，病在肺；推之即至者，病在大肠。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('arc7rvAZvZD', 4, '{"title":"22","description":"<p>22、阙庭脉色青黑直下睛明，推之不变者，病在肾；推之即至者，病在膀胱。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000322,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '22、阙庭脉色青黑直下睛明，推之不变者，病在肾；推之即至者，病在膀胱。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j1ZgH5FK96y', 4, '{"title":"23","description":"<p>23、明堂阙庭色不见，推之色青紫者，病在中焦有积；推之明于水者，病在上焦有饮；推之黑赤参差者，病在下焦有寒热。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000323,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '23、明堂阙庭色不见，推之色青紫者，病在中焦有积；推之明于水者，病在上焦有饮；推之黑赤参差者，病在下焦有寒热。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FAqeUxdFHV1', 4, '{"title":"24","description":"<p>24、问曰：色有内外，何以别之？师曰：一望而知者，谓之外；在明堂阙庭，推而见之者，谓之内。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000324,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '24、问曰：色有内外，何以别之？师曰：一望而知者，谓之外；在明堂阙庭，推而见之者，谓之内。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FfzacHHv0Ep', 4, '{"title":"25","description":"<p>25、病暴至者，先形于色，不见于脉；病久发者，先见于脉，不形于色；病入于脏，无余证者，见于脉，不形于色；病痼疾者，见于脉，不形于色也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000325,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '25、病暴至者，先形于色，不见于脉；病久发者，先见于脉，不形于色；病入于脏，无余证者，见于脉，不形于色；病痼疾者，见于脉，不形于色也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a08KWL5VcLI', 4, '{"title":"26","description":"<p>26、问曰：色有生死，何谓也？</p>\n<p></p>\n<p>       师曰：假令色黄如蟹腹者，生；如枳实者，死；有气则生，无气则死，余色仿此。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000326,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '26、问曰：色有生死，何谓也？ 师曰：假令色黄如蟹腹者，生；如枳实者，死；有气则生，无气则死，余色仿此。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9f0Zw9ik6aQ', 4, '{"title":"27","description":"<p>27、师曰：人秉五常，有五脏，五脏发五声，宫、商、角、征、羽是也；五声在人，各具一体；假令人本声角变商声者，为金克木，至秋当死；变宫、征、羽皆病，以本声不可变故也。</p>\n<p> </p>\n<p>       人本声宫变角声者，为本克土，至春当死；变商、征、羽皆病。 </p>\n<p></p>\n<p>       人本声商变征声者，为火克金，至夏当死；变宫、角、羽皆病。</p>\n<p></p>\n<p>       人本声征变羽声者，为水克火，至冬当死；变角、宫、商皆病。</p>\n<p></p>\n<p>       人本声羽变宫声者，为土克水，至长夏当死；变角、商、征皆病。</p>\n<p></p>\n<p>       以上所言，皆人不病而声先病者，初变可治，变成难瘳；词声之妙，差在毫厘，本不易晓，若病至发声则易知也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000327,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '2024-12-06T09:35:32.000Z', '27、师曰：人秉五常，有五脏，五脏发五声，宫、商、角、征、羽是也；五声在人，各具一体；假令人本声角变商声者，为金克木，至秋当死；变宫、征、羽皆病，以本声不可变故也。 人本声宫变角声者，为本克土，至春当死；变商、征、羽皆病。 人本声商变征声者，为火克金，至夏当死；变宫、角、羽皆病。 人本声征变羽声者，为水克火，至冬当死；变角、宫、商皆病。 人本声羽变宫声者，为土克水，至长夏当死；变角、商、征皆病。 以上所言，皆人不病而声先病者，初变可治，变成难瘳；词声之妙，差在毫厘，本不易晓，若病至发声则易知也。', '2024-12-06T09:35:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fRhlc8FvPex', 4, '{"title":"28","description":"<p>28、师曰：持脉，病人欠者，无病也。脉之，呻者，病也。言迟者，风也。摇头言者，里痛也。行迟者，表强也。坐而伏者，短气也。坐而下一脚者，腰痛也。里实护腹，如怀卵物者，心痛也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000328,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '28、师曰：持脉，病人欠者，无病也。脉之，呻者，病也。言迟者，风也。摇头言者，里痛也。行迟者，表强也。坐而伏者，短气也。坐而下一脚者，腰痛也。里实护腹，如怀卵物者，心痛也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RcBGZE5uXas', 4, '{"title":"29","description":"<p>29、病人长叹声，出高入卑者，病在上焦；出卑入高者，病在下焦；出入急促者，病在中焦有痛处；声唧唧而叹者，身体疼痛；问之不欲语，语先泪下者，必有忧郁；问之不语，泪下不止者，必有隐衷；问之不语，数问之而微笑者，必有隐疾。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000329,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '29、病人长叹声，出高入卑者，病在上焦；出卑入高者，病在下焦；出入急促者，病在中焦有痛处；声唧唧而叹者，身体疼痛；问之不欲语，语先泪下者，必有忧郁；问之不语，泪下不止者，必有隐衷；问之不语，数问之而微笑者，必有隐疾。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z4V6qzt0LPq', 4, '{"title":"30","description":"<p>30、实则谵语，虚则郑声；假令言出声卑者，为气虚；言出声高者，为气实；欲言手按胸中者，胸中满痛；欲言手按腹者，腹中满痛；欲言声不出者，咽中肿痛。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000330,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '30、实则谵语，虚则郑声；假令言出声卑者，为气虚；言出声高者，为气实；欲言手按胸中者，胸中满痛；欲言手按腹者，腹中满痛；欲言声不出者，咽中肿痛。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tvVDXsfGeyG', 4, '{"title":"31","description":"<p>31、师曰：脉病人不病，名曰行尸，以无王气，卒眩仆，不识人者，短命则死。人病脉不病，名曰内虚，以少谷神，虽困无苦。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000331,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '31、师曰：脉病人不病，名曰行尸，以无王气，卒眩仆，不识人者，短命则死。人病脉不病，名曰内虚，以少谷神，虽困无苦。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oISUawLq50i', 4, '{"title":"32","description":"<p>32、师曰：脉，肥人责浮，瘦人责沉。肥人当沉，今反浮；瘦人当浮，今反沉，故责之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000332,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '32、师曰：脉，肥人责浮，瘦人责沉。肥人当沉，今反浮；瘦人当浮，今反沉，故责之。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2GJ8iDOE1qf', 4, '{"title":"33","description":"<p>33、师曰：呼吸者，脉之头也。初持脉来疾去迟，此出疾入迟，名曰内虚外实也。初持脉，来迟去疾，此出迟入疾，名曰内实外虚也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000333,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '33、师曰：呼吸者，脉之头也。初持脉来疾去迟，此出疾入迟，名曰内虚外实也。初持脉，来迟去疾，此出迟入疾，名曰内实外虚也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GFmvOUujI4v', 4, '{"title":"34、寸口卫气盛，名曰高；荣气盛，名曰章；高章相搏，名曰纲","description":"<p>34、寸口卫气盛，名曰高；荣气盛，名曰章；高章相搏，名曰纲。卫气弱，名曰惵；荣气弱，名曰卑；惵卑相搏，名曰损。卫气和，名曰缓；荣气和，名曰迟；迟缓相搏，名曰沉。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000334,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '34、寸口卫气盛，名曰高；荣气盛，名曰章；高章相搏，名曰纲。卫气弱，名曰惵；荣气弱，名曰卑；惵卑相搏，名曰损。卫气和，名曰缓；荣气和，名曰迟；迟缓相搏，名曰沉。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uQ4Mw32RiWB', 4, '{"title":"35","description":"<p>35、阳脉浮大而濡，阴脉浮大而濡，阴脉与阳脉同等者，名曰缓也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000335,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '35、阳脉浮大而濡，阴脉浮大而濡，阴脉与阳脉同等者，名曰缓也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('97MXM3f4lkt', 4, '{"title":"36","description":"<p>36、问曰：二月得毛浮脉，何以处言至秋当死。</p>\n<p></p>\n<p>       师曰：二月之时，脉当濡弱，反得毛浮者，故知至秋死。二月肝用事，肝属木，脉应濡弱，反得毛浮者，是肺脉也。肺属金，金来克木，故知至秋死。他皆仿此。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000336,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '36、问曰：二月得毛浮脉，何以处言至秋当死。 师曰：二月之时，脉当濡弱，反得毛浮者，故知至秋死。二月肝用事，肝属木，脉应濡弱，反得毛浮者，是肺脉也。肺属金，金来克木，故知至秋死。他皆仿此。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3L7sLhRrnft', 4, '{"title":"37","description":"<p>37、师曰：立夏得洪大脉是其本位。其人病身体苦疼重者，须发其汗。若明日身不疼不重者，不须发汗。若汗濈濈自出者，明日便解矣。何以言之？立夏脉洪大是其时脉，故使然也。四时仿此。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000337,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '37、师曰：立夏得洪大脉是其本位。其人病身体苦疼重者，须发其汗。若明日身不疼不重者，不须发汗。若汗濈濈自出者，明日便解矣。何以言之？立夏脉洪大是其时脉，故使然也。四时仿此。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AiEo1AYadXJ', 4, '{"title":"38","description":"<p>38、问曰：凡病欲知何时得，何时愈，何以知之？</p>\n<p></p>\n<p>       师曰：假令夜半得病者，明日日中愈；日中得病者，夜半愈。何以言之？日中得病，夜半愈者，以阳得阴则解也。夜半得病，明日日中愈者，以阴得阳则解也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000338,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '38、问曰：凡病欲知何时得，何时愈，何以知之？ 师曰：假令夜半得病者，明日日中愈；日中得病者，夜半愈。何以言之？日中得病，夜半愈者，以阳得阴则解也。夜半得病，明日日中愈者，以阴得阳则解也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8m52o721cZR', 4, '{"title":"39","description":"<p>39、问曰：脉病欲知愈未愈者，何以别之？</p>\n<p>     </p>\n<p>      答曰：寸口、关上、尺中三处，大、小、浮、沉、迟、数同等，虽有寒热不解者，此脉阴阳为和平，虽剧当愈。师曰：寸脉下不至关，为阳绝；尺脉上不至关，为阴绝。此皆不治，决死也。若计其余命生死之期，期以月节克之也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000339,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '39、问曰：脉病欲知愈未愈者，何以别之？ 答曰：寸口、关上、尺中三处，大、小、浮、沉、迟、数同等，虽有寒热不解者，此脉阴阳为和平，虽剧当愈。师曰：寸脉下不至关，为阳绝；尺脉上不至关，为阴绝。此皆不治，决死也。若计其余命生死之期，期以月节克之也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mJqJElfQaIR', 4, '{"title":"40","description":"<p>40、脉浮者在前，其病在表；浮者在后，其病在里；假令濡而上鱼际者，宗气泄也；孤而下尺中者，精不脏也；若乍高乍卑，乍升乍坠，为难治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000340,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '40、脉浮者在前，其病在表；浮者在后，其病在里；假令濡而上鱼际者，宗气泄也；孤而下尺中者，精不脏也；若乍高乍卑，乍升乍坠，为难治。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KyqTRyVvZMl', 4, '{"title":"41","description":"<p>41、寸口脉缓而迟，缓则阳气长，其色鲜，其颜光，其声商，毛发长；迟则阴气盛，骨髓生，血满，肌肉紧薄鲜鞕。阴阳相抱，荣卫俱行，刚柔相得，名曰强也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000341,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '41、寸口脉缓而迟，缓则阳气长，其色鲜，其颜光，其声商，毛发长；迟则阴气盛，骨髓生，血满，肌肉紧薄鲜鞕。阴阳相抱，荣卫俱行，刚柔相得，名曰强也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O2QrZTLVNtp', 4, '{"title":"42、寸口脉浮为在表，沉为在里，数为在腑，迟为在脏","description":"<p>42、寸口脉浮为在表，沉为在里，数为在腑，迟为在脏。假令脉迟，此为在脏也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000342,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '42、寸口脉浮为在表，沉为在里，数为在腑，迟为在脏。假令脉迟，此为在脏也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4wGPVj9BY9E', 4, '{"title":"43、寸口脉浮而紧，浮则为风，紧则为寒","description":"<p>43、寸口脉浮而紧，浮则为风，紧则为寒。风则伤卫，寒则伤荣。荣卫俱病，骨节烦疼，当发其汗也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000343,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '43、寸口脉浮而紧，浮则为风，紧则为寒。风则伤卫，寒则伤荣。荣卫俱病，骨节烦疼，当发其汗也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bxd1qZ9O5nM', 4, '{"title":"44","description":"<p>44、寸口脉浮而数，浮为风，数为热，风为虚，虚为寒，风虚相搏，则洒淅恶寒也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000344,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '44、寸口脉浮而数，浮为风，数为热，风为虚，虚为寒，风虚相搏，则洒淅恶寒也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sBczKR0gTrM', 4, '{"title":"45","description":"<p>45、问曰：病有洒淅恶寒而复发热者何也？</p>\n<p></p>\n<p>       师曰：阴脉不足，阳往从之；阳脉不足，阴往乘之也。何谓阳脉不足？师曰：假令寸口脉微，名曰阳不足，阴气上入阳中，则洒淅恶寒也，何谓阴不足？师曰：假令尺脉弱，名曰阴不足，阳气下陷入阴中，则发热也。阴脉弱者，则血虚。血虚则筋急也。其脉涩者，荣气微也。其脉浮而汗出如流珠者，卫气衰也。荣气微者，加烧针，则血留不行，更发热而躁烦也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000345,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '45、问曰：病有洒淅恶寒而复发热者何也？ 师曰：阴脉不足，阳往从之；阳脉不足，阴往乘之也。何谓阳脉不足？师曰：假令寸口脉微，名曰阳不足，阴气上入阳中，则洒淅恶寒也，何谓阴不足？师曰：假令尺脉弱，名曰阴不足，阳气下陷入阴中，则发热也。阴脉弱者，则血虚。血虚则筋急也。其脉涩者，荣气微也。其脉浮而汗出如流珠者，卫气衰也。荣气微者，加烧针，则血留不行，更发热而躁烦也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FyNOz0RD4zI', 4, '{"title":"46、寸口脉阴阳俱紧者，法当清邪中于上焦，浊邪中于下焦","description":"<p>46、寸口脉阴阳俱紧者，法当清邪中于上焦，浊邪中于下焦。清邪中于上，名曰洁也；浊邪中于下，名曰浑也，阴中于邪，必内栗也，表气微虚，里气不守，故使邪中于阴也。阳中于邪，必发热、头痛、项强、颈挛、腰痛、胫酸，所谓阳中雾露之气，故曰清邪中上。浊邪中下，阴气为栗，足膝逆冷，便溺妄出，表气微虚，里气微急，三焦相混，内外不通，上焦怫郁，脏气相熏，口烂食断也。中焦不治，胃气上冲，脾气不转，胃中为浊，荣卫不通，血凝不流。若胃气前通者，小便赤黄，与热相搏，因热作使，游于经络，出入脏腑，热气所过，则为痈脓。若阴气前通者，阳气厥微，阴无所使，客气内入，嚏而出之，声嗢咽塞，寒厥相追，为热所拥，血凝自下，状如豚肝，阴阳俱厥，脾气弧弱，五液注下，下焦不阖，清便下重，令便数难，脐筑湫痛，命将难全。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000346,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '46、寸口脉阴阳俱紧者，法当清邪中于上焦，浊邪中于下焦。清邪中于上，名曰洁也；浊邪中于下，名曰浑也，阴中于邪，必内栗也，表气微虚，里气不守，故使邪中于阴也。阳中于邪，必发热、头痛、项强、颈挛、腰痛、胫酸，所谓阳中雾露之气，故曰清邪中上。浊邪中下，阴气为栗，足膝逆冷，便溺妄出，表气微虚，里气微急，三焦相混，内外不通，上焦怫郁，脏气相熏，口烂食断也。中焦不治，胃气上冲，脾气不转，胃中为浊，荣卫不通，血凝不流。若胃气前通者，小便赤黄，与热相搏，因热作使，游于经络，出入脏腑，热气所过，则为痈脓。若阴气前通者，阳气厥微，阴无所使，客气内入，嚏而出之，声嗢咽塞，寒厥相追，为热所拥，血凝自下，状如豚肝，阴阳俱厥，脾气弧弱，五液注下，下焦不阖，清便下重，令便数难，脐筑湫痛，命将难全。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Yh31VnLT0h8', 4, '{"title":"47","description":"<p>47、寸口脉阴阳俱紧者，口中气出，唇口干燥，蜷卧足冷，鼻中涕出，舌上胎滑，勿妄治也。到七日以来，其人微发热，手足温者，此为欲解；或到八日以上，反大发热者，此为难治。设使恶寒者，必欲呕也；腹内痛者，必欲利也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000347,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '47、寸口脉阴阳俱紧者，口中气出，唇口干燥，蜷卧足冷，鼻中涕出，舌上胎滑，勿妄治也。到七日以来，其人微发热，手足温者，此为欲解；或到八日以上，反大发热者，此为难治。设使恶寒者，必欲呕也；腹内痛者，必欲利也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IWXVphsvbey', 4, '{"title":"48","description":"<p>48、寸口脉阴阳俱紧，至于吐利，其脉独不解，紧去人安，此为欲解。若脉迟至六七日，不欲食，此为晚发，水停故也，为未解；食自可者，为欲解。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000348,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '48、寸口脉阴阳俱紧，至于吐利，其脉独不解，紧去人安，此为欲解。若脉迟至六七日，不欲食，此为晚发，水停故也，为未解；食自可者，为欲解。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dd8CMjCum3c', 4, '{"title":"49、寸口脉浮而大，有热，心下反鞕，属脏者攻之，不令发汗","description":"<p>49、寸口脉浮而大，有热，心下反鞕，属脏者攻之，不令发汗。属腑者不令溲数。溲数则大便鞕，汗多则热甚，脉迟者尚未可攻也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000349,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '49、寸口脉浮而大，有热，心下反鞕，属脏者攻之，不令发汗。属腑者不令溲数。溲数则大便鞕，汗多则热甚，脉迟者尚未可攻也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('erozoJxJPna', 4, '{"title":"50","description":"<p>50、问曰：病有战而汗出，因得解者，何也？</p>\n<p></p>\n<p>       师曰：脉浮而紧，按之反芤，此为本虚，故当战而汗出也。其人本虚，是以发战。以脉浮紧，故当汗出而解也。若脉浮数，按之不芤，此人本不虚；若欲自解，但汗出耳，不发战也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000350,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '50、问曰：病有战而汗出，因得解者，何也？ 师曰：脉浮而紧，按之反芤，此为本虚，故当战而汗出也。其人本虚，是以发战。以脉浮紧，故当汗出而解也。若脉浮数，按之不芤，此人本不虚；若欲自解，但汗出耳，不发战也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rJdTCBSWOGd', 4, '{"title":"51","description":"<p>51、问曰：病有不战而汗出解者何也？师曰：脉大而浮数，故不战汗出而解也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000351,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '51、问曰：病有不战而汗出解者何也？师曰：脉大而浮数，故不战汗出而解也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bEX95VQd9KI', 4, '{"title":"52","description":"<p>52、问曰：病有不战不汗出而解者，何也？</p>\n<p></p>\n<p>       答曰：其脉自微，此以曾发汗、若吐、若下、若亡血，以内无津液，此阴阳自和，必自愈，故不战不汗出而解也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000352,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '52、问曰：病有不战不汗出而解者，何也？ 答曰：其脉自微，此以曾发汗、若吐、若下、若亡血，以内无津液，此阴阳自和，必自愈，故不战不汗出而解也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g1zPyfSAAlk', 4, '{"title":"53","description":"<p>53、问曰：伤寒三日，脉浮数而微，病人身凉和者，何也？</p>\n<p></p>\n<p>        师曰：此为欲解也。解以夜半。浮而解者，濈然汗出也；数而解者，必能食也；微而解者，必大汗出也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000353,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '53、问曰：伤寒三日，脉浮数而微，病人身凉和者，何也？ 师曰：此为欲解也。解以夜半。浮而解者，濈然汗出也；数而解者，必能食也；微而解者，必大汗出也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d44CXQOgv8x', 4, '{"title":"54、脉浮而迟，面热赤而战惕者，六七日当汗出而解","description":"<p>54、脉浮而迟，面热赤而战惕者，六七日当汗出而解。反发热者差迟。迟为无阳，不能作汗，其身必痒也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000354,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '54、脉浮而迟，面热赤而战惕者，六七日当汗出而解。反发热者差迟。迟为无阳，不能作汗，其身必痒也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8VRwqU5T3Vg', 4, '{"title":"55","description":"<p>55、病六七日，手足三部脉皆至，大烦而口噤不能言，其人躁扰者，未欲解也。若脉和，其人不烦，目重，睑内际黄者，此欲解也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000355,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '55、病六七日，手足三部脉皆至，大烦而口噤不能言，其人躁扰者，未欲解也。若脉和，其人不烦，目重，睑内际黄者，此欲解也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ebGZrIblcnV', 4, '{"title":"56","description":"<p>56、师曰：伏气之病，以意候之，今月之内，欲知伏气。假令旧有伏气，当须脉之。若脉微弱者，当喉中痛似伤，非喉痹也，病人云实咽中痛。虽尔，今复宜下之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000356,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '56、师曰：伏气之病，以意候之，今月之内，欲知伏气。假令旧有伏气，当须脉之。若脉微弱者，当喉中痛似伤，非喉痹也，病人云实咽中痛。虽尔，今复宜下之。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HFGwlF0h68o', 4, '{"title":"57","description":"<p>57、师曰：病家人请云病人苦发热，身体疼，病人自卧，师到，诊其脉，沉而迟者，知其瘥也；何以知之？凡表有病者，脉当浮大，今反沉迟故知愈也；假令病人云腹内卒痛，病人自坐，师到，脉之，浮而大者，知其瘥也；凡里有病者，脉当沉细，今反浮大，故知愈也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000357,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '57、师曰：病家人请云病人苦发热，身体疼，病人自卧，师到，诊其脉，沉而迟者，知其瘥也；何以知之？凡表有病者，脉当浮大，今反沉迟故知愈也；假令病人云腹内卒痛，病人自坐，师到，脉之，浮而大者，知其瘥也；凡里有病者，脉当沉细，今反浮大，故知愈也。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RpPDViAcXmv', 4, '{"title":"58","description":"<p>58、师曰：病家人来请云，病人发热，烦极。明日师到，病人向壁卧，此热已去也。设令脉不和，处言已愈。设令向壁卧，闻师到，不惊起而盼视，若三言三止，脉之，咽唾者，此诈病也。设令脉自和，处言此病大重，当须服吐下药，针灸数十百处，乃愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000358,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '58、师曰：病家人来请云，病人发热，烦极。明日师到，病人向壁卧，此热已去也。设令脉不和，处言已愈。设令向壁卧，闻师到，不惊起而盼视，若三言三止，脉之，咽唾者，此诈病也。设令脉自和，处言此病大重，当须服吐下药，针灸数十百处，乃愈。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TWm0ZQ7dXFn', 4, '{"title":"59","description":"<p>59、问曰：脉有灾怪，何谓也？师曰：假令人病，脉得太阳，与形证相应，因为作汤。比还送汤如食顷，病人乃大吐，若下利，腹中痛。</p>\n<p>     </p>\n<p>        师曰：我前来不见此证，今乃变异，是名灾怪。又问曰：何缘得此吐利？师曰：或有旧时服药，今乃发作，故名灾怪耳。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000359,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '2024-12-07T00:35:52.000Z', '59、问曰：脉有灾怪，何谓也？师曰：假令人病，脉得太阳，与形证相应，因为作汤。比还送汤如食顷，病人乃大吐，若下利，腹中痛。 师曰：我前来不见此证，今乃变异，是名灾怪。又问曰：何缘得此吐利？师曰：或有旧时服药，今乃发作，故名灾怪耳。', '2024-12-07T00:35:52.000Z', 1, NULL, '5IGM9t76quT', 'section', 'TYCTSYUPQh5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IUu5Gp4jJf2', 4, '{"title":"1","description":"<p>1、问曰：脉何以知气血脏腑之诊也？</p>\n<p></p>\n<p>      师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。</p>\n<p></p>\n<p>      气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。</p>\n<p></p>\n<p>      气独胜者，则脉强；血独盛者，则脉滑；</p>\n<p></p>\n<p>      气偏衰者，则脉微；血偏衰者，则脉涩；</p>\n<p></p>\n<p>     气血和者，则脉缓；气血平者，则脉平；</p>\n<p></p>\n<p>     气血乱者，则脉乱；气血脱者，则脉绝；</p>\n<p></p>\n<p>     阳迫气血，则脉数；阴阻气血，则脉迟；</p>\n<p></p>\n<p>    若感于邪，气血扰动，脉随变化，变化无穷，气血使之；</p>\n<p></p>\n<p>    病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000401,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '1、问曰：脉何以知气血脏腑之诊也？ 师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。 气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。 气独胜者，则脉强；血独盛者，则脉滑； 气偏衰者，则脉微；血偏衰者，则脉涩； 气血和者，则脉缓；气血平者，则脉平； 气血乱者，则脉乱；气血脱者，则脉绝； 阳迫气血，则脉数；阴阻气血，则脉迟； 若感于邪，气血扰动，脉随变化，变化无穷，气血使之； 病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R2Ixj77f5h8', 4, '{"title":"2","description":"<p>2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。</p>\n<p> </p>\n<p>        师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000402,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。 师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3qSCxKJcFgO', 4, '{"title":"3","description":"<p>3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000403,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5BACIxLk9yJ', 4, '{"title":"4","description":"<p>4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000404,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W8fsl5GiRlw', 4, '{"title":"5","description":"<p>5、问曰：经说，脉有三菽、六菽重者，何谓也？</p>\n<p></p>\n<p>      师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000405,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '5、问曰：经说，脉有三菽、六菽重者，何谓也？ 师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Waf3X9BFMWL', 4, '{"title":"6","description":"<p>6、问曰：东方肝脉，其形何似？</p>\n<p></p>\n<p>      师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000406,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '6、问曰：东方肝脉，其形何似？ 师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8vmXi6Mi5na', 4, '{"title":"7、南方心脉，其形何似","description":"<p>7、南方心脉，其形何似？</p>\n<p></p>\n<p>     师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000407,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '7、南方心脉，其形何似？ 师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SzO52XDN1EI', 4, '{"title":"8、西方肺脉，其形何似","description":"<p>8、西方肺脉，其形何似？</p>\n<p></p>\n<p>      师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000408,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '8、西方肺脉，其形何似？ 师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OS5v09n6pTD', 4, '{"title":"9、北方肾脉其形何似","description":"<p>9、北方肾脉其形何似？</p>\n<p></p>\n<p>      师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000409,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '9、北方肾脉其形何似？ 师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XghzOco9OsN', 4, '{"title":"10","description":"<p>10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000410,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GoQ8mMn9o1n', 4, '{"title":"11","description":"<p>11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000411,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IvtS298N3I1', 4, '{"title":"12","description":"<p>12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。</p>\n<p></p>\n<p>        师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000412,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。 师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ltnoCYjqNrh', 4, '{"title":"13","description":"<p>13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000413,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ALM2INC02Rf', 4, '{"title":"14","description":"<p>14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000414,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wfwiR5gUY2I', 4, '{"title":"15","description":"<p>15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000415,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ueEwAVrSK5Z', 4, '{"title":"16","description":"<p>16、色白者，病在肺与大肠；假令身色白，明堂色微黑者，生；赤者，死；黄赤者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000416,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '16、色白者，病在肺与大肠；假令身色白，明堂色微黑者，生；赤者，死；黄赤者，半死半生也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tZQo4ZCm4pB', 4, '{"title":"17","description":"<p>17、色黑者，病在肾与膀胱；假令身色黑，明堂色微青者，生；黄者，死；黄赤者，半死半生也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000417,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '17、色黑者，病在肾与膀胱；假令身色黑，明堂色微青者，生；黄者，死；黄赤者，半死半生也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('adlCsV72OCd', 4, '{"title":"18","description":"<p>18、阙庭脉色青而沉细，推之不移者，病在肝；青而浮大，推之随转者，病在胆。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000418,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '18、阙庭脉色青而沉细，推之不移者，病在肝；青而浮大，推之随转者，病在胆。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WNkcjMmoZzI', 4, '{"title":"19","description":"<p>19、阙庭脉色赤而沉细，推之参差不齐者，病在心；赤而横弋，推之愈赤者，病在小肠。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000419,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '19、阙庭脉色赤而沉细，推之参差不齐者，病在心；赤而横弋，推之愈赤者，病在小肠。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E2qyh7LD2v3', 4, '{"title":"20","description":"<p>20、阙庭脉色黄，推之如水停留者，病在脾；如水急流者，病在胃。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000420,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '20、阙庭脉色黄，推之如水停留者，病在脾；如水急流者，病在胃。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('toQUUyCnkLH', 4, '{"title":"21","description":"<p>21、阙庭脉色青白，推之久不还者，病在肺；推之即至者，病在大肠。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000421,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '21、阙庭脉色青白，推之久不还者，病在肺；推之即至者，病在大肠。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oS3UJtFhp2A', 4, '{"title":"22","description":"<p>22、阙庭脉色青黑直下睛明，推之不变者，病在肾；推之即至者，病在膀胱。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000422,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '22、阙庭脉色青黑直下睛明，推之不变者，病在肾；推之即至者，病在膀胱。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b4RpXmHm6Nx', 4, '{"title":"23","description":"<p>23、明堂阙庭色不见，推之色青紫者，病在中焦有积；推之明于水者，病在上焦有饮；推之黑赤参差者，病在下焦有寒热。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000423,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '23、明堂阙庭色不见，推之色青紫者，病在中焦有积；推之明于水者，病在上焦有饮；推之黑赤参差者，病在下焦有寒热。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0PhzNCcB1Ty', 4, '{"title":"24","description":"<p>24、问曰：色有内外，何以别之？</p>\n<p></p>\n<p>       师曰：一望而知者，谓之外；在明堂阙庭，推而见之者，谓之内。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000424,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '24、问曰：色有内外，何以别之？ 师曰：一望而知者，谓之外；在明堂阙庭，推而见之者，谓之内。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8mSTN7EneI2', 4, '{"title":"25","description":"<p>25、病暴至者，先形于色，不见于脉；病久发者，先见于脉，不形于色；病入于脏，无余证者，见于脉，不形于色；病痼疾者，见于脉，不形于色也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000425,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '25、病暴至者，先形于色，不见于脉；病久发者，先见于脉，不形于色；病入于脏，无余证者，见于脉，不形于色；病痼疾者，见于脉，不形于色也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('azA2NDrlVsh', 4, '{"title":"26","description":"<p>26、问曰：色有生死，何谓也？</p>\n<p>           </p>\n<p>       师曰：假令色黄如蟹腹者，生；如枳实者，死；有气则生，无气则死，余色仿此。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000426,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '26、问曰：色有生死，何谓也？ 师曰：假令色黄如蟹腹者，生；如枳实者，死；有气则生，无气则死，余色仿此。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ts8AMaFm5bD', 4, '{"title":"27","description":"<p>27、师曰：人秉五常，有五脏，五脏发五声，宫、商、角、征、羽是也；五声在人，各具一体；假令人本声角变商声者，为金克木，至秋当死；变宫、征、羽皆病，以本声不可变故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000427,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '27、师曰：人秉五常，有五脏，五脏发五声，宫、商、角、征、羽是也；五声在人，各具一体；假令人本声角变商声者，为金克木，至秋当死；变宫、征、羽皆病，以本声不可变故也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PS45gnXHthc', 4, '{"title":"28","description":"<p>28、人本声宫变角声者，为本克土，至春当死；变商、征、羽皆病。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000428,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '28、人本声宫变角声者，为本克土，至春当死；变商、征、羽皆病。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
