INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('enphOcdtUQL', 4, '{"title":"30","description":"<p>30、人本声征变羽声者，为水克火，至冬当死；变角、宫、商皆病。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000430,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '30、人本声征变羽声者，为水克火，至冬当死；变角、宫、商皆病。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K5bfZcLgdgH', 4, '{"title":"31","description":"<p>31、人本声羽变宫声者，为土克水，至长夏当死；变角、商、征皆病。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000431,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '31、人本声羽变宫声者，为土克水，至长夏当死；变角、商、征皆病。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0D8StvgnR5x', 4, '{"title":"32","description":"<p>32、问曰：脉有阴阳，何谓也？</p>\n<p></p>\n<p>        师曰：凡脉大、浮、数、动、滑，此名阳也；凡脉沉、涩、迟、弦、微，此名阴也，凡阴病见阳脉者生，阳病见阴脉者死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000432,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '32、问曰：脉有阴阳，何谓也？ 师曰：凡脉大、浮、数、动、滑，此名阳也；凡脉沉、涩、迟、弦、微，此名阴也，凡阴病见阳脉者生，阳病见阴脉者死。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jpm86cFtjHq', 4, '{"title":"33","description":"<p>33、阴阳相搏名曰动，阳动则汗出，阴动则发热，形冷恶寒者，此三焦伤也。若脉数见于关上，上下无头尾如豆大，厥厥然动摇者，名曰动也。脉来缓，时一止复来者，名曰结。脉来数，时一止复来者，名曰促。脉阳盛则促，阴盛则结，此皆病脉。又脉来动而中止，更来小数，中有还者反动，名曰结阴也；脉来动而中止，不能自还，因而复动者，名曰代阴也；得此脉者，必难治。脉阴阳俱促，当病血，为实；阴阳俱结，当亡血，为虚；假令促上寸口者，当吐血，或衄；下尺中者，当下血；若乍促乍结为难治。脉数者，久数不止，止则邪结，正气不能复，却结于脏；故邪气浮之，与皮毛相得脉数者，不可下，下之，必烦利不止。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000433,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '33、阴阳相搏名曰动，阳动则汗出，阴动则发热，形冷恶寒者，此三焦伤也。若脉数见于关上，上下无头尾如豆大，厥厥然动摇者，名曰动也。脉来缓，时一止复来者，名曰结。脉来数，时一止复来者，名曰促。脉阳盛则促，阴盛则结，此皆病脉。又脉来动而中止，更来小数，中有还者反动，名曰结阴也；脉来动而中止，不能自还，因而复动者，名曰代阴也；得此脉者，必难治。脉阴阳俱促，当病血，为实；阴阳俱结，当亡血，为虚；假令促上寸口者，当吐血，或衄；下尺中者，当下血；若乍促乍结为难治。脉数者，久数不止，止则邪结，正气不能复，却结于脏；故邪气浮之，与皮毛相得脉数者，不可下，下之，必烦利不止。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9wV1v6X7JCQ', 4, '{"title":"34","description":"<p>34、问曰：脉有阳结阴结者，何以别之？师曰：其脉浮而数，能食，不大便者，此为实，名曰阳结也，期十七日当剧。其脉沉而迟，不能食，身体重，大便反鞕，名曰阴结也。期十四日当剧。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000434,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '34、问曰：脉有阳结阴结者，何以别之？师曰：其脉浮而数，能食，不大便者，此为实，名曰阳结也，期十七日当剧。其脉沉而迟，不能食，身体重，大便反鞕，名曰阴结也。期十四日当剧。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IaEcbiVieQW', 4, '{"title":"35、脉蔼蔼，如车盖者，名曰阳结也","description":"<p>35、脉蔼蔼，如车盖者，名曰阳结也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000435,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '35、脉蔼蔼，如车盖者，名曰阳结也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
