INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3ObP3aF9QlC', 4, '{"title":"37、脉瞥瞥，如羹上肥者，阳气微也","description":"<p>37、脉瞥瞥，如羹上肥者，阳气微也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000437,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '37、脉瞥瞥，如羹上肥者，阳气微也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EW6VKUQa7Oy', 4, '{"title":"38、脉萦萦，如蜘蛛丝者，阴气衰也","description":"<p>38、脉萦萦，如蜘蛛丝者，阴气衰也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000438,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '38、脉萦萦，如蜘蛛丝者，阴气衰也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mmoCTjQ1Z5x', 4, '{"title":"39、脉绵绵，如泻漆之绝者，亡其血也","description":"<p>39、脉绵绵，如泻漆之绝者，亡其血也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000439,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '39、脉绵绵，如泻漆之绝者，亡其血也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qnhM1hgEQSY', 4, '{"title":"40","description":"<p>40、问曰：脉有残贼，何谓也？</p>\n<p></p>\n<p>      师曰：脉有弦、紧、浮、滑、沉、涩，此六脉，名曰残贼，能为诸脉作病也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000440,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '40、问曰：脉有残贼，何谓也？ 师曰：脉有弦、紧、浮、滑、沉、涩，此六脉，名曰残贼，能为诸脉作病也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4crFMZmxWbB', 4, '{"title":"41","description":"<p>41、问曰：脉有相乘、有纵、有横、有逆、有顺，何也？师曰：水行乘火，金行乘木，名曰纵；火行乘水，木行乘金，名曰横；水行乘金，火行乘木，名曰逆；金行乘水，木行乘火，名曰顺也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000441,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '41、问曰：脉有相乘、有纵、有横、有逆、有顺，何也？师曰：水行乘火，金行乘木，名曰纵；火行乘水，木行乘金，名曰横；水行乘金，火行乘木，名曰逆；金行乘水，木行乘火，名曰顺也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kTMfqitIprR', 4, '{"title":"42","description":"<p>42、问曰：濡弱何以反适十一头？</p>\n<p></p>\n<p>        师曰：五脏六腑相乘故令十一。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000442,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '42、问曰：濡弱何以反适十一头？ 师曰：五脏六腑相乘故令十一。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('02gDh7fJRHj', 4, '{"title":"43、脉阴阳俱弦，无寒热，为病饮","description":"<p>43、脉阴阳俱弦，无寒热，为病饮。在浮部，饮在皮肤；在中部，饮在经络；在沉部，饮在肌肉；若寸口弦，饮在上焦；关上弦，饮在中焦；尺中弦，饮在下焦。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000443,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '43、脉阴阳俱弦，无寒热，为病饮。在浮部，饮在皮肤；在中部，饮在经络；在沉部，饮在肌肉；若寸口弦，饮在上焦；关上弦，饮在中焦；尺中弦，饮在下焦。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('leSt6YK2hqh', 4, '{"title":"44、脉弦而紧者，名曰革也","description":"<p>44、脉弦而紧者，名曰革也。弦者状如弓弦，按之不移也。紧者如转索无常也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000444,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '44、脉弦而紧者，名曰革也。弦者状如弓弦，按之不移也。紧者如转索无常也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8K2TZuM5aDK', 4, '{"title":"45、脉弦而大，弦则为减，大则为芤","description":"<p>45、脉弦而大，弦则为减，大则为芤。减则为寒，芤则为虚。寒虚相搏，此名为革。妇人则半产、漏下，男子则亡血、失精。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000445,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '45、脉弦而大，弦则为减，大则为芤。减则为寒，芤则为虚。寒虚相搏，此名为革。妇人则半产、漏下，男子则亡血、失精。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mlSKe3R0rBc', 4, '{"title":"46","description":"<p>46、问曰：曾为人所难，紧脉从何而来？</p>\n<p></p>\n<p>        师曰：假令亡汗、若吐，以肺里寒，故令脉紧也。假令咳者，坐饮冷水，故令脉紧也。假令下利，以胃中虚冷，故令脉紧也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000446,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '46、问曰：曾为人所难，紧脉从何而来？ 师曰：假令亡汗、若吐，以肺里寒，故令脉紧也。假令咳者，坐饮冷水，故令脉紧也。假令下利，以胃中虚冷，故令脉紧也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V8K6V5TTIpI', 4, '{"title":"47、寸口脉浮而紧，医反下之，此为大逆","description":"<p>47、寸口脉浮而紧，医反下之，此为大逆。浮则无血，紧则为寒，寒气相搏，则为肠鸣，医乃不知，而反饮冷水，令汗不出，水得寒气，冷必相搏，其人即饐。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000447,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '47、寸口脉浮而紧，医反下之，此为大逆。浮则无血，紧则为寒，寒气相搏，则为肠鸣，医乃不知，而反饮冷水，令汗不出，水得寒气，冷必相搏，其人即饐。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0XEkiGOd5Tc', 4, '{"title":"48、寸口脉微，尺脉紧，其人虚损多汗，知阴常在，绝不见阳也","description":"<p>48、寸口脉微，尺脉紧，其人虚损多汗，知阴常在，绝不见阳也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000448,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '48、寸口脉微，尺脉紧，其人虚损多汗，知阴常在，绝不见阳也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DN3HokOYne6', 4, '{"title":"49","description":"<p>49、寸口脉浮而大，浮为风虚，大为气强，风气相搏，必成隐疹，身体为痒。痒者名曰泄风，久久为痂癞。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000449,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '49、寸口脉浮而大，浮为风虚，大为气强，风气相搏，必成隐疹，身体为痒。痒者名曰泄风，久久为痂癞。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k9qkI1vrhfo', 4, '{"title":"50","description":"<p>50、寸口脉浮而大，浮为虚，大为实；在尺为关，在寸为格；关则不得小便，格则吐逆。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000450,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '50、寸口脉浮而大，浮为虚，大为实；在尺为关，在寸为格；关则不得小便，格则吐逆。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BYDeyu3Vcgh', 4, '{"title":"51、寸口脉微而涩，微者卫气不行，涩者荣气不逮","description":"<p>51、寸口脉微而涩，微者卫气不行，涩者荣气不逮。荣卫不能相将，三焦无所仰，身体痹不仁。荣气不足，则烦疼，口难言；卫气虚者，则恶寒数欠。三焦不归其部，上焦不归者，噫而酢吞；中焦不归者，不能消谷引食；下焦不归者，则遗溲。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000451,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '51、寸口脉微而涩，微者卫气不行，涩者荣气不逮。荣卫不能相将，三焦无所仰，身体痹不仁。荣气不足，则烦疼，口难言；卫气虚者，则恶寒数欠。三焦不归其部，上焦不归者，噫而酢吞；中焦不归者，不能消谷引食；下焦不归者，则遗溲。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iF97JAyKwzt', 4, '{"title":"52、寸口脉微而涩，微者卫气衰，涩者荣气不足","description":"<p>52、寸口脉微而涩，微者卫气衰，涩者荣气不足。卫气衰则面色黄；荣气不足则面色青。荣为根，卫为叶。荣卫俱微，则根叶枯槁，而寒栗咳逆，唾腥吐涎沫也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000452,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '52、寸口脉微而涩，微者卫气衰，涩者荣气不足。卫气衰则面色黄；荣气不足则面色青。荣为根，卫为叶。荣卫俱微，则根叶枯槁，而寒栗咳逆，唾腥吐涎沫也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mes2TAwnF7g', 4, '{"title":"53","description":"<p>53、寸口脉微而缓，微者卫气疏，疏则其肤空；缓者胃气实，实则谷消而水化也。谷入于胃，脉道乃行，水入于经，其血乃成。荣盛则其肤必疏，三焦绝经，名曰血崩。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000453,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '53、寸口脉微而缓，微者卫气疏，疏则其肤空；缓者胃气实，实则谷消而水化也。谷入于胃，脉道乃行，水入于经，其血乃成。荣盛则其肤必疏，三焦绝经，名曰血崩。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9YeQhihtsb2', 4, '{"title":"54","description":"<p>54、寸口脉弱而缓，弱者阳气不足，缓者胃气有余，噫而吞酸，食卒不下，气填于膈上也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000454,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '54、寸口脉弱而缓，弱者阳气不足，缓者胃气有余，噫而吞酸，食卒不下，气填于膈上也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Sf2XNJjmGb6', 4, '{"title":"55","description":"<p>55、寸口脉弱而迟，弱者卫气微，迟者荣中寒；荣为血，血寒则发热；卫为气，气微者心内饥，饥而虚满不能食也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000455,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '55、寸口脉弱而迟，弱者卫气微，迟者荣中寒；荣为血，血寒则发热；卫为气，气微者心内饥，饥而虚满不能食也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AHZAbEm9ly9', 4, '{"title":"56、寸口脉弱而涩，尺中浮大，无外证者，为病属内伤","description":"<p>56、寸口脉弱而涩，尺中浮大，无外证者，为病属内伤。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000456,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '56、寸口脉弱而涩，尺中浮大，无外证者，为病属内伤。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('92EGkqilGxG', 4, '{"title":"57、寸口脉弱而涩，尺中濡弱者，男子病失精，女子病赤白带下","description":"<p>57、寸口脉弱而涩，尺中濡弱者，男子病失精，女子病赤白带下。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000457,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '57、寸口脉弱而涩，尺中濡弱者，男子病失精，女子病赤白带下。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hku5lCWq0Fc', 4, '{"title":"58","description":"<p>58、寸口脉洪数，按之弦急者，当发瘾疹；假令脉浮数，按之反平者，为外毒；脉数大，按之弦直者，为内毒，宜升之，令其外出也；误攻则内陷，内陷则死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000458,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '58、寸口脉洪数，按之弦急者，当发瘾疹；假令脉浮数，按之反平者，为外毒；脉数大，按之弦直者，为内毒，宜升之，令其外出也；误攻则内陷，内陷则死。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5MqGRfS8UHM', 4, '{"title":"59","description":"<p>59、寸口脉洪数，按之急滑者，当发痈脓；发热者，暴出；无热者，久久必至也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000459,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '59、寸口脉洪数，按之急滑者，当发痈脓；发热者，暴出；无热者，久久必至也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H8F1XZa3G7s', 4, '{"title":"60","description":"<p>60、寸口脉浮滑，按之弦急者，当发内痈；咳嗽胸中痛为肺痈，当吐脓血；腹中掣痛为肠痈，当便脓血。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000460,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '60、寸口脉浮滑，按之弦急者，当发内痈；咳嗽胸中痛为肺痈，当吐脓血；腹中掣痛为肠痈，当便脓血。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pcj2qnGZS9p', 4, '{"title":"61","description":"<p>61、寸口脉大而涩，时一弦，无寒热，此为浸淫疮所致也；若加细数者，为难治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000461,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '61、寸口脉大而涩，时一弦，无寒热，此为浸淫疮所致也；若加细数者，为难治。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O1nlFPLJh6d', 4, '{"title":"62、趺阳脉紧而浮，浮为气，紧为寒","description":"<p>62、趺阳脉紧而浮，浮为气，紧为寒。浮为腹满，紧为绞痛。浮紧相搏，肠鸣而转，转即气动，隔气乃下。少阴脉不出，其阴肿大而虚也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000462,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '62、趺阳脉紧而浮，浮为气，紧为寒。浮为腹满，紧为绞痛。浮紧相搏，肠鸣而转，转即气动，隔气乃下。少阴脉不出，其阴肿大而虚也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y4y5wSnldfk', 4, '{"title":"63、趺阳脉微而紧，紧则为寒，微则为虚，微紧相搏，则为短气","description":"<p>63、趺阳脉微而紧，紧则为寒，微则为虚，微紧相搏，则为短气。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000463,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '63、趺阳脉微而紧，紧则为寒，微则为虚，微紧相搏，则为短气。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PR48piE3cFq', 4, '{"title":"64、趺阳脉大而紧者，当即下利，为难治","description":"<p>64、趺阳脉大而紧者，当即下利，为难治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000464,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '64、趺阳脉大而紧者，当即下利，为难治。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q3K92HXbTqk', 4, '{"title":"65","description":"<p>65、趺阳脉浮，浮则为虚，浮虚相搏，故令气饐，言胃气虚竭也；此为医咎，责虚取实，守空迫血；脉滑则为哕，脉浮鼻中燥者，必衄也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000465,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '65、趺阳脉浮，浮则为虚，浮虚相搏，故令气饐，言胃气虚竭也；此为医咎，责虚取实，守空迫血；脉滑则为哕，脉浮鼻中燥者，必衄也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xAGlnjGpRMB', 4, '{"title":"66、趺阳脉迟而缓，胃气如经也","description":"<p>66、趺阳脉迟而缓，胃气如经也。趺阳脉浮而数，浮则伤胃，数则动脾，此非本病，医特下之所为也。荣卫内陷，其数先微，脉反但浮，其人必大便鞕，气噫不除。何以言之？本以数脉动脾，其数先微，故知脾气不治，大便鞕，气噫不除。今脉反浮，其数改微，邪气独留，心中则饥，邪热不杀谷，潮热发渴，数脉当迟，缓病者则饥。数脉不时，则生恶疮也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000466,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '66、趺阳脉迟而缓，胃气如经也。趺阳脉浮而数，浮则伤胃，数则动脾，此非本病，医特下之所为也。荣卫内陷，其数先微，脉反但浮，其人必大便鞕，气噫不除。何以言之？本以数脉动脾，其数先微，故知脾气不治，大便鞕，气噫不除。今脉反浮，其数改微，邪气独留，心中则饥，邪热不杀谷，潮热发渴，数脉当迟，缓病者则饥。数脉不时，则生恶疮也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('erxID6ZHs4z', 4, '{"title":"67、趺阳脉浮而涩，少阴脉如经者，其病在脾，法当下利","description":"<p>67、趺阳脉浮而涩，少阴脉如经者，其病在脾，法当下利。何以知之？若脉浮大者，气实血虚也。今趺阳脉浮而涩，故知脾气不足，胃气虚也。以少阴脉弦，而沉才见，此为调脉，故称如经也。若反滑而数者，故知当屎脓也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000467,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '67、趺阳脉浮而涩，少阴脉如经者，其病在脾，法当下利。何以知之？若脉浮大者，气实血虚也。今趺阳脉浮而涩，故知脾气不足，胃气虚也。以少阴脉弦，而沉才见，此为调脉，故称如经也。若反滑而数者，故知当屎脓也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iZtz7EbF7a7', 4, '{"title":"68","description":"<p>68、趺阳脉浮而芤，浮者胃气虚，芤者荣气伤，其身体瘦，肌肉甲错，浮芤相搏，宗气衰微，四属断绝也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000468,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '68、趺阳脉浮而芤，浮者胃气虚，芤者荣气伤，其身体瘦，肌肉甲错，浮芤相搏，宗气衰微，四属断绝也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('33RH5xZ0kNI', 4, '{"title":"69","description":"<p>69、趺阳脉浮而大，浮为气实，大为血虚；血虚为无阴，孤阳独下阴部者，小便当赤而难，胞中当虚；今小便利，而大汗出，法应胃家当微；今反更实，津液四射，荣竭血尽，干烦而不眠，血薄肉消而成暴液；医复以毒药攻其胃，此为重虚，客阳去有期，必下如淤泥而死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000469,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '69、趺阳脉浮而大，浮为气实，大为血虚；血虚为无阴，孤阳独下阴部者，小便当赤而难，胞中当虚；今小便利，而大汗出，法应胃家当微；今反更实，津液四射，荣竭血尽，干烦而不眠，血薄肉消而成暴液；医复以毒药攻其胃，此为重虚，客阳去有期，必下如淤泥而死。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DSHcy8CD2AT', 4, '{"title":"70","description":"<p>70、问曰：翕奄沉名曰滑，何谓也？</p>\n<p></p>\n<p>        师曰：沉为纯阴，翕为正阳，阴阳和合，故令脉滑。关尺自平。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000470,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '70、问曰：翕奄沉名曰滑，何谓也？ 师曰：沉为纯阴，翕为正阳，阴阳和合，故令脉滑。关尺自平。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gGilMepnvAR', 4, '{"title":"71","description":"<p>71、趺阳脉微沉，食饮自平；少阴脉微滑，滑者紧之浮名也，此为阴实，其人必股内汗出，阴下湿也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000471,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '71、趺阳脉微沉，食饮自平；少阴脉微滑，滑者紧之浮名也，此为阴实，其人必股内汗出，阴下湿也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DgcdJERYq4z', 4, '{"title":"72","description":"<p>72、趺阳脉浮而滑，浮为阳，滑为实，阳实相搏，其脉数疾，卫气失度，浮滑之脉数疾，发热汗出者，此为不治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000472,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '72、趺阳脉浮而滑，浮为阳，滑为实，阳实相搏，其脉数疾，卫气失度，浮滑之脉数疾，发热汗出者，此为不治。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i44xag8ct7e', 4, '{"title":"73、趺阳脉滑而紧，滑者胃气实，紧者脾气强","description":"<p>73、趺阳脉滑而紧，滑者胃气实，紧者脾气强。持实击强，痛还自伤，以手把刃，坐作疮也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000473,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '73、趺阳脉滑而紧，滑者胃气实，紧者脾气强。持实击强，痛还自伤，以手把刃，坐作疮也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7RobmrUF83D', 4, '{"title":"74、趺阳脉沉而微，沉为实，数消谷；紧者，病难治","description":"<p>74、趺阳脉沉而微，沉为实，数消谷；紧者，病难治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000474,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '74、趺阳脉沉而微，沉为实，数消谷；紧者，病难治。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8BpBimUwMkQ', 4, '{"title":"75","description":"<p>75、趺阳脉伏而涩，伏则吐逆，水谷不化，涩则食不得入，名曰关格。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000475,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '75、趺阳脉伏而涩，伏则吐逆，水谷不化，涩则食不得入，名曰关格。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OH1zL8oOPYF', 4, '{"title":"76","description":"<p>76、师曰：病人脉微而涩者，此为医所病也。大发其汗，又数大下之，其人亡血，病当恶寒，后乃发热，无休止时，夏月盛热，欲着复衣，冬月盛寒，欲裸其身，所以然者，阳微则恶寒，阴弱则发热，此医发其汗，使阳气微，又大下之：令阴气弱，五月之时，阳气在表，胃中虚冷，以阳气内微，不能胜冷，故欲着复衣；十一月之时，阳气在里，胃中烦热，以阴气内弱，不能胜热，故欲裸其身。又阴脉迟涩，故知血亡也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000476,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '76、师曰：病人脉微而涩者，此为医所病也。大发其汗，又数大下之，其人亡血，病当恶寒，后乃发热，无休止时，夏月盛热，欲着复衣，冬月盛寒，欲裸其身，所以然者，阳微则恶寒，阴弱则发热，此医发其汗，使阳气微，又大下之：令阴气弱，五月之时，阳气在表，胃中虚冷，以阳气内微，不能胜冷，故欲着复衣；十一月之时，阳气在里，胃中烦热，以阴气内弱，不能胜热，故欲裸其身。又阴脉迟涩，故知血亡也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DWSHJtvUPOX', 4, '{"title":"77、少阴脉弱而涩，弱者微烦，涩者厥逆","description":"<p>77、少阴脉弱而涩，弱者微烦，涩者厥逆。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000477,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '77、少阴脉弱而涩，弱者微烦，涩者厥逆。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M2p45TlnRmF', 4, '{"title":"78、趺阳脉不出，脾不上下，身冷肤鞕","description":"<p>78、趺阳脉不出，脾不上下，身冷肤鞕。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000478,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '78、趺阳脉不出，脾不上下，身冷肤鞕。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s2nBdfIQ7jZ', 4, '{"title":"79","description":"<p>79、少阴脉不至，肾气微，少精血，奔气促迫，上入胸隔，宗气反聚，血结心下，阳气退下，热归阴股，与阴相动，令身不仁，此为尸厥。当刺期门、巨阙。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000479,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '79、少阴脉不至，肾气微，少精血，奔气促迫，上入胸隔，宗气反聚，血结心下，阳气退下，热归阴股，与阴相动，令身不仁，此为尸厥。当刺期门、巨阙。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R3YHDD6YPP5', 4, '{"title":"80","description":"<p>80、妊娠脉弦数而细，少腹痛，手心热，此为热结胞中，不先其时治之，必有产难。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000480,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '80、妊娠脉弦数而细，少腹痛，手心热，此为热结胞中，不先其时治之，必有产难。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TXzy6wqm8pG', 4, '{"title":"81","description":"<p>81、产后脉洪数，按之弦急，此为浊未下；若浊已下而脉如故者，此为魂脱，为难治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000481,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '81、产后脉洪数，按之弦急，此为浊未下；若浊已下而脉如故者，此为魂脱，为难治。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jCT46B0OKpU', 4, '{"title":"82","description":"<p>82、诸脉浮数，当发热而洒淅恶寒，若有痛处，饮食如常者，畜积有脓也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000482,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '82、诸脉浮数，当发热而洒淅恶寒，若有痛处，饮食如常者，畜积有脓也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a6IBdd3uGGt', 4, '{"title":"83","description":"<p>83、问曰：人恐怖者，其脉何状？</p>\n<p></p>\n<p>     师曰：脉形如循丝累累然，其面白脱色也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000483,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '83、问曰：人恐怖者，其脉何状？ 师曰：脉形如循丝累累然，其面白脱色也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Tp7uphWwZpi', 4, '{"title":"84","description":"<p>84、问曰：人不饮，其脉何类？</p>\n<p></p>\n<p>       师曰：脉自涩，唇口干燥也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000484,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '84、问曰：人不饮，其脉何类？ 师曰：脉自涩，唇口干燥也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MDQURrmelmP', 4, '{"title":"85","description":"<p>85、问曰：人愧者，其脉何类？</p>\n<p></p>\n<p>       师曰：脉浮而面色乍白乍赤也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000485,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '85、问曰：人愧者，其脉何类？ 师曰：脉浮而面色乍白乍赤也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qJG5rCiRGFB', 4, '{"title":"86","description":"<p>86、师曰：寸口诸微亡阳，诸濡亡血，诸弱发热，诸紧为寒。诸乘寒者则为厥，郁冒不仁，以胃无谷气，脾涩不通，口急不能言，战而栗也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000486,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '86、师曰：寸口诸微亡阳，诸濡亡血，诸弱发热，诸紧为寒。诸乘寒者则为厥，郁冒不仁，以胃无谷气，脾涩不通，口急不能言，战而栗也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EU8jfvrw9Ud', 4, '{"title":"87","description":"<p>87、师曰：发热则脉躁，恶寒则脉静，脉随证转者，为病疟。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000487,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '87、师曰：发热则脉躁，恶寒则脉静，脉随证转者，为病疟。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oQf36B11tDR', 4, '{"title":"88","description":"<p>88、师曰：伤寒，咳逆上气，其脉散者死，为其形损故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000488,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '88、师曰：伤寒，咳逆上气，其脉散者死，为其形损故也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HUfnHpMfUAH', 4, '{"title":"89","description":"<p>89、师曰：脉乍大乍小，乍静乍乱，见人惊恐者，为祟发于胆，气竭故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000489,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '89、师曰：脉乍大乍小，乍静乍乱，见人惊恐者，为祟发于胆，气竭故也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OZE03yZMvRK', 4, '{"title":"90","description":"<p>90、师曰：人脉皆无病，暴发重病，不省人事者，为厉鬼，治之以祝由，能言者可治，不言者死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000490,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '90、师曰：人脉皆无病，暴发重病，不省人事者，为厉鬼，治之以祝由，能言者可治，不言者死。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hOxVVqHzwR8', 4, '{"title":"91","description":"<p>91、师曰：脉浮而洪，身汗如油，喘而不休，水浆不下，形体不仁，乍静乍乱，此为命绝也。又未知何脏先受其灾。若汗出发润，喘不休者，此为肺先绝也。阳反独留，形体如烟熏，直视摇头者，此为心绝也。唇吻反青，四肢掣习者，此为肝绝也。环口黧黑，油汗发黄者，此为脾绝也。溲便遗失，狂言，目反直视者，此为肾绝也。又未知何脏阴阳前绝。若阳气前绝，阴气后竭者，其人死身色必青；阴气前绝，阳气后竭者，其人死，身色必赤，腋下温，心下热也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000491,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '91、师曰：脉浮而洪，身汗如油，喘而不休，水浆不下，形体不仁，乍静乍乱，此为命绝也。又未知何脏先受其灾。若汗出发润，喘不休者，此为肺先绝也。阳反独留，形体如烟熏，直视摇头者，此为心绝也。唇吻反青，四肢掣习者，此为肝绝也。环口黧黑，油汗发黄者，此为脾绝也。溲便遗失，狂言，目反直视者，此为肾绝也。又未知何脏阴阳前绝。若阳气前绝，阴气后竭者，其人死身色必青；阴气前绝，阳气后竭者，其人死，身色必赤，腋下温，心下热也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t5aP0ntmD7U', 4, '{"title":"92、奇经八脉不系于十二经，别有自行道路","description":"<p>92、奇经八脉不系于十二经，别有自行道路。其为病总于阴阳，其治法属十二经。假令督脉为病，脊背强，隐隐痛，脉当微浮而急，按之涩，治属太阳。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000492,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '92、奇经八脉不系于十二经，别有自行道路。其为病总于阴阳，其治法属十二经。假令督脉为病，脊背强，隐隐痛，脉当微浮而急，按之涩，治属太阳。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HJuvVvw3Lku', 4, '{"title":"93、任脉为病，其内结痛疝瘕，脉当沉而结，治属太阴","description":"<p>93、任脉为病，其内结痛疝瘕，脉当沉而结，治属太阴。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000493,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '93、任脉为病，其内结痛疝瘕，脉当沉而结，治属太阴。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
