INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Aprc6WZuXme', 4, '{"title":"96","description":"<p>96、阳跷为病，中于侧，气行于外，脉当弦急，按之缓，治属少阳。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000496,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '96、阳跷为病，中于侧，气行于外，脉当弦急，按之缓，治属少阳。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z0vTNJtySuv', 4, '{"title":"97","description":"<p>97、阴跷为病，中于侧，气行于内，脉当浮缓，按之微急而弦，治属厥阴。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000497,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '97、阴跷为病，中于侧，气行于内，脉当浮缓，按之微急而弦，治属厥阴。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X4uixMwWhqN', 4, '{"title":"98","description":"<p>98、阳维与诸阳会，其为病在脉外，发寒热，脉当浮而虚，治属气分。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000498,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '98、阳维与诸阳会，其为病在脉外，发寒热，脉当浮而虚，治属气分。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nSpiiBqbOwi', 4, '{"title":"99","description":"<p>99、阴维与诸阴交，其为病在脉中，心中痛，手心热，脉当弦而涩，治属血分。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000499,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '99、阴维与诸阴交，其为病在脉中，心中痛，手心热，脉当弦而涩，治属血分。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JE55HokDRwf', 4, '{"title":"100、阳维维于阳，阴维维于阴，为气血之别，使不拘于一经也","description":"<p>100、阳维维于阳，阴维维于阴，为气血之别，使不拘于一经也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000500,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '100、阳维维于阳，阴维维于阴，为气血之别，使不拘于一经也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Ns9d6V5O17', 4, '{"title":"101","description":"<p>101、奇经八脉之病，由各经受邪，久久移传，或劳伤所致，非暴发也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '101、奇经八脉之病，由各经受邪，久久移传，或劳伤所致，非暴发也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pk9bwHpMT1Q', 4, '{"title":"102","description":"<p>102、问曰：八脉内伤何以别之？</p>\n<p></p>\n<p>         师曰：督脉伤，柔柔不欲伸，不能久立，立则隐隐而胀；任脉伤，小便多，其色白浊；冲脉伤，时咳不休，有声无物，劳则；地喘；带脉伤，回身一周冷；阳跷伤，则身左不仁；阴跷伤，则身右不仁；阳维伤，则畏寒甚，皮常湿；阴维伤，则畏热甚，皮常枯。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000502,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '102、问曰：八脉内伤何以别之？ 师曰：督脉伤，柔柔不欲伸，不能久立，立则隐隐而胀；任脉伤，小便多，其色白浊；冲脉伤，时咳不休，有声无物，劳则；地喘；带脉伤，回身一周冷；阳跷伤，则身左不仁；阴跷伤，则身右不仁；阳维伤，则畏寒甚，皮常湿；阴维伤，则畏热甚，皮常枯。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gEyYvHIS85E', 4, '{"title":"103","description":"<p>103、问曰：八脉内伤其脉何似？</p>\n<p> </p>\n<p>        师曰：督脉伤，尺脉大而涩；任脉伤，关脉大而涩；冲脉伤，寸脉短而涩；带脉伤，脉沉迟而结；阳跷伤，脉时大而弦；阴跷伤，脉时细时弦；阳维伤，脉时缓时弦；阴维伤，脉时紧时涩。问曰：其治奈何？师曰：督脉伤，当补髓；任脉伤，当补精；冲脉伤，当补气；带脉伤，当补肾；阳跷伤，则益胆；阴跷伤，则补肝；阴维伤，则调卫；阴维伤，则养荣。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000503,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '103、问曰：八脉内伤其脉何似？ 师曰：督脉伤，尺脉大而涩；任脉伤，关脉大而涩；冲脉伤，寸脉短而涩；带脉伤，脉沉迟而结；阳跷伤，脉时大而弦；阴跷伤，脉时细时弦；阳维伤，脉时缓时弦；阴维伤，脉时紧时涩。问曰：其治奈何？师曰：督脉伤，当补髓；任脉伤，当补精；冲脉伤，当补气；带脉伤，当补肾；阳跷伤，则益胆；阴跷伤，则补肝；阴维伤，则调卫；阴维伤，则养荣。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7cvV70xO7wz', 4, '{"title":"104","description":"<p>104、问曰：其处方奈何？</p>\n<p></p>\n<p>         师曰：相体虚实，察病轻重，采取方法，权衡用之，则无失也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000504,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '2024-12-07T02:06:40.000Z', '104、问曰：其处方奈何？ 师曰：相体虚实，察病轻重，采取方法，权衡用之，则无失也。', '2024-12-07T02:06:40.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Okv1nb20qyT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KONQIRidc72', 4, '{"title":"1","description":"<p>1、问曰：六气主客何以别之？师曰：厥阴生少阴，少阴生少阳，少阳生太阴，太阴生阳明，阳明生太阳，太阳复生厥阴，周而复始，久久不变，年复一年，此名主气；厥阴生少阴，少阴生太阴，太阴生少阳，少阳生阳明，阳明生太阳，复生厥阴，周而复始，此名客气。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001005001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T11:03:50.000Z', '2024-12-07T11:03:50.000Z', '2024-12-07T11:03:50.000Z', '1、问曰：六气主客何以别之？师曰：厥阴生少阴，少阴生少阳，少阳生太阴，太阴生阳明，阳明生太阳，太阳复生厥阴，周而复始，久久不变，年复一年，此名主气；厥阴生少阴，少阴生太阴，太阴生少阳，少阳生阳明，阳明生太阳，复生厥阴，周而复始，此名客气。', '2024-12-07T11:03:50.000Z', 1, NULL, '5IGM9t76quT', 'section', 'I8vjThKe1JN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7SWihAUijr8', 4, '{"title":"2","description":"<p>2、问曰：其始终奈何？</p>\n<p></p>\n<p>      师曰：初气始于大寒，二气始于春分，三气始于小满，四气始于大暑，五气始于秋分，终气始于小雪，仍终于大寒，主客相同，其差各三十度也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001005002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T11:07:55.000Z', '2024-12-07T11:07:55.000Z', '2024-12-07T11:07:55.000Z', '2、问曰：其始终奈何？ 师曰：初气始于大寒，二气始于春分，三气始于小满，四气始于大暑，五气始于秋分，终气始于小雪，仍终于大寒，主客相同，其差各三十度也。', '2024-12-07T11:07:55.000Z', 1, NULL, '5IGM9t76quT', 'section', 'I8vjThKe1JN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EAdQA70sM0Q', 4, '{"title":"3","description":"<p>3、问曰：司天在泉奈何？</p>\n<p></p>\n<p>    师曰：此客气也。假如子午之年，少阴司天，阳明则为在泉，太阳为初气，厥阴为二气，司天为三气，太阴为四气，少阳为五气，在泉为终气；卯酉之年，阳明司天，少阴在泉，则初气太阴，二气少阳，三气阳明，四气太阳，五气厥阴，终气少阴；戌辰之年，太阳司天，太阴在泉；丑未之年，太阴司天，太阳在泉；寅申之年，少阳司天，厥阴在泉；巳亥之年，厥阴司天，少阳在泉；其余各气，以例推之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001005003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T11:07:55.000Z', '2024-12-07T11:07:55.000Z', '2024-12-07T11:07:55.000Z', '3、问曰：司天在泉奈何？ 师曰：此客气也。假如子午之年，少阴司天，阳明则为在泉，太阳为初气，厥阴为二气，司天为三气，太阴为四气，少阳为五气，在泉为终气；卯酉之年，阳明司天，少阴在泉，则初气太阴，二气少阳，三气阳明，四气太阳，五气厥阴，终气少阴；戌辰之年，太阳司天，太阴在泉；丑未之年，太阴司天，太阳在泉；寅申之年，少阳司天，厥阴在泉；巳亥之年，厥阴司天，少阳在泉；其余各气，以例推之。', '2024-12-07T11:07:55.000Z', 1, NULL, '5IGM9t76quT', 'section', 'I8vjThKe1JN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ijox8xacepS', 4, '{"title":"4","description":"<p>4、问曰：其为病也何如？</p>\n<p></p>\n<p>     师曰：亦有主客之分也；</p>\n<p></p>\n<p>    假如厥阴司天，主胜，则胸胁痛，舌难以言；客胜，则耳鸣，掉眩，甚则咳逆。</p>\n<p></p>\n<p>   少阴司天，主胜，则心热，烦躁，胁痛支满；客胜，则鼽嚏，颈项强，肩背瞀热，头痛，少气，发热，耳聋，目暝，甚则跗肿，血溢，疮，喑，喘咳。</p>\n<p></p>\n<p>   太阴司天，主胜，则胸腹满，食已而瞀；客胜，则首、面、跗肿，呼吸气喘。</p>\n<p></p>\n<p>   少阳司天，主胜，则胸满，咳逆，仰息，甚则有血，手热；客胜，则丹疹外发，及为丹熛，疮疡，呕逆，喉痹，头痛，嗌踵，耳聋，血溢，内为瘛疭。</p>\n<p></p>\n<p>   阳明司天，主胜，则清复内余，咳，衄，嗌塞，心膈中热，咳不止而白血出者死，金居少阳之位，客不胜主也。</p>\n<p></p>\n<p>   太阳司天，主胜，则喉嗌中鸣；客胜，则胸中不利，出清涕，感寒则咳也。</p>\n<p></p>\n<p>   厥阴主在泉，主胜，则筋骨徭并，腰腹时痛；客胜，则关节不利，内为痉强，外为不便。</p>\n<p></p>\n<p>  少阴在泉，主胜，则厥气上行，心痛发热，膈中众痹皆作，发于胠胁，魄汗不藏，四逆而起；客胜，则腰痛，尻、股、膝、髀、腨、胻、足病瞀热以酸，跗肿不能久立，溲便变。</p>\n<p></p>\n<p>   太阴在泉，主胜，则寒气逆满，食饮不下，甚则为疝；客胜，则足痿下肿，便溲不时，湿客下焦，发而濡泄，及为阴肿，隐曲之疾。</p>\n<p></p>\n<p>   少阳在泉，主胜，则热反上行，而客于心，心痛发热，格中而呕；客胜，则腰腹痛，而反恶寒，甚则下白溺白。</p>\n<p></p>\n<p>   阳明在泉，主胜，则腰重，腹痛，少腹生寒，下为鹜溏，寒厥于肠，上冲胸中，甚则喘满，不能久立；客胜，则清气动下，小腹坚满，而数便泄。</p>\n<p></p>\n<p>   太阳在泉，以水居水位，无所胜也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001005004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T11:07:55.000Z', '2024-12-07T11:07:55.000Z', '2024-12-07T11:07:55.000Z', '4、问曰：其为病也何如？ 师曰：亦有主客之分也； 假如厥阴司天，主胜，则胸胁痛，舌难以言；客胜，则耳鸣，掉眩，甚则咳逆。 少阴司天，主胜，则心热，烦躁，胁痛支满；客胜，则鼽嚏，颈项强，肩背瞀热，头痛，少气，发热，耳聋，目暝，甚则跗肿，血溢，疮，喑，喘咳。 太阴司天，主胜，则胸腹满，食已而瞀；客胜，则首、面、跗肿，呼吸气喘。 少阳司天，主胜，则胸满，咳逆，仰息，甚则有血，手热；客胜，则丹疹外发，及为丹熛，疮疡，呕逆，喉痹，头痛，嗌踵，耳聋，血溢，内为瘛疭。 阳明司天，主胜，则清复内余，咳，衄，嗌塞，心膈中热，咳不止而白血出者死，金居少阳之位，客不胜主也。 太阳司天，主胜，则喉嗌中鸣；客胜，则胸中不利，出清涕，感寒则咳也。 厥阴主在泉，主胜，则筋骨徭并，腰腹时痛；客胜，则关节不利，内为痉强，外为不便。 少阴在泉，主胜，则厥气上行，心痛发热，膈中众痹皆作，发于胠胁，魄汗不藏，四逆而起；客胜，则腰痛，尻、股、膝、髀、腨、胻、足病瞀热以酸，跗肿不能久立，溲便变。 太阴在泉，主胜，则寒气逆满，食饮不下，甚则为疝；客胜，则足痿下肿，便溲不时，湿客下焦，发而濡泄，及为阴肿，隐曲之疾。 少阳在泉，主胜，则热反上行，而客于心，心痛发热，格中而呕；客胜，则腰腹痛，而反恶寒，甚则下白溺白。 阳明在泉，主胜，则腰重，腹痛，少腹生寒，下为鹜溏，寒厥于肠，上冲胸中，甚则喘满，不能久立；客胜，则清气动下，小腹坚满，而数便泄。 太阳在泉，以水居水位，无所胜也。', '2024-12-07T11:07:55.000Z', 1, NULL, '5IGM9t76quT', 'section', 'I8vjThKe1JN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ir6MlbJlT26', 4, '{"title":"5","description":"<p>5、问曰：其胜复何如？</p>\n<p></p>\n<p>      师曰：有胜必有复，无胜则无复也；</p>\n<p></p>\n<p>      厥阴之胜，则病耳鸣，头眩，愦愦欲吐，胃膈如寒，胠胁气并，化而为热，小便黄赤，胃脘当心而痛，上及两胁，肠鸣，飧泄，少腹痛，注下赤白，甚则呕吐，膈不通；其复也，则少腹坚满，里急暴痛，厥心痛，汗发，呕吐，饮食不入，入而复出，筋骨掉眩清厥，甚则入脾，食痹而吐。</p>\n<p></p>\n<p>     少阴之胜，则病心下热，善饥，脐下气动，气游三焦，呕吐，躁烦，腹满而痛，溏泄赤沃；其复也，则燠热内作，烦躁，鼽嚏，少腹绞痛，嗌燥，气动于左上行于右，咳则皮肤痛，暴喑，心痛，郁冒不知人，洒淅恶寒振栗，谵妄，寒已而热，渴而欲饮，少气，骨痿，膈肠不便，外为浮肿，哕噫，痱疹，疮疡，痈疽，痤痔，甚则入肺，咳而鼻渊。</p>\n<p></p>\n<p>     太阴之胜，则火气内郁，疮疡于中，流散于外，病在胠胁甚则心痛热格，头痛，喉痹，项强，又或湿气内郁，寒迫下焦，少腹满，腰椎痛强，注泄，足下湿，头重，跗肿，足胫肿，饮发于中，跗肿于上；其复也，则体重，中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声，头项痛重，掉瘛尤甚，呕而密默，唾吐清液，甚则入肾，窃泄无度。</p>\n<p></p>\n<p>       少阳之胜，则病热客于胃，心烦而痛，目赤呕酸，善饥，耳痛，溺赤，善惊谵妄，暴热消烁，少腹痛，下沃赤白；其复也，枯燥，烦热，惊瘛，咳，衄，心热，烦躁，便数，憎风，厥气上行，面如浮埃，目乃瞤瘛，火气内发，上为口糜，呕逆，血溢，血泄，发而为疟，恶寒鼓栗，寒极反热，嗌络焦槁，渴饮水浆，色变黄赤，少气肺痿，化而为水，传为跗肿，甚则入肺，咳而血泄。</p>\n<p></p>\n<p>       阳明之胜，则清发于中，左胠胁痛，溏泄，内为嗌塞，外发颓疝，胸中不便，嗌而咳；其复也，则病生胠胁，气归于左，善太息，甚则心痛痞满，腹胀而泄，呕苦，咳哕烦心，病在膈中，甚则入肝，惊骇筋挛。</p>\n<p></p>\n<p>       太阳之胜，则病痔疟，发寒，厥人胃，则内生心痛，阴中乃疡，隐曲不利，亘引阴股筋肉拘苛，血脉凝泣，络满血变，或为血泄，皮肤否肿，腹满时减，热反上行，头项囟顶脑户中痛，目如脱，寒入下焦，则传为濡泄；其复也，则心胃生寒，胸膈不利，心痛痞满，头痛，善悲，时发眩仆，食减，腰椎反痛，屈伸不便，少腹控睪引腰脊上冲心，唾出清水，及为哕噫，甚则入心，善忘，善悲，寒复内余，则腰尻痛，屈伸不利，股胫足膝中痛。</p>\n<p></p>\n<p>      此六气为病，须谨识之，而弗失也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001005005,"note":"","videoMemo":"腨、胻、","fangList":[],"bieMing":""}}', '2024-12-07T02:36:09.000Z', '2024-12-07T02:36:09.000Z', '2024-12-07T02:36:09.000Z', '5、问曰：其胜复何如？ 师曰：有胜必有复，无胜则无复也； 厥阴之胜，则病耳鸣，头眩，愦愦欲吐，胃膈如寒，胠胁气并，化而为热，小便黄赤，胃脘当心而痛，上及两胁，肠鸣，飧泄，少腹痛，注下赤白，甚则呕吐，膈不通；其复也，则少腹坚满，里急暴痛，厥心痛，汗发，呕吐，饮食不入，入而复出，筋骨掉眩清厥，甚则入脾，食痹而吐。 少阴之胜，则病心下热，善饥，脐下气动，气游三焦，呕吐，躁烦，腹满而痛，溏泄赤沃；其复也，则燠热内作，烦躁，鼽嚏，少腹绞痛，嗌燥，气动于左上行于右，咳则皮肤痛，暴喑，心痛，郁冒不知人，洒淅恶寒振栗，谵妄，寒已而热，渴而欲饮，少气，骨痿，膈肠不便，外为浮肿，哕噫，痱疹，疮疡，痈疽，痤痔，甚则入肺，咳而鼻渊。 太阴之胜，则火气内郁，疮疡于中，流散于外，病在胠胁甚则心痛热格，头痛，喉痹，项强，又或湿气内郁，寒迫下焦，少腹满，腰椎痛强，注泄，足下湿，头重，跗肿，足胫肿，饮发于中，跗肿于上；其复也，则体重，中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声，头项痛重，掉瘛尤甚，呕而密默，唾吐清液，甚则入肾，窃泄无度。 少阳之胜，则病热客于胃，心烦而痛，目赤呕酸，善饥，耳痛，溺赤，善惊谵妄，暴热消烁，少腹痛，下沃赤白；其复也，枯燥，烦热，惊瘛，咳，衄，心热，烦躁，便数，憎风，厥气上行，面如浮埃，目乃瞤瘛，火气内发，上为口糜，呕逆，血溢，血泄，发而为疟，恶寒鼓栗，寒极反热，嗌络焦槁，渴饮水浆，色变黄赤，少气肺痿，化而为水，传为跗肿，甚则入肺，咳而血泄。 阳明之胜，则清发于中，左胠胁痛，溏泄，内为嗌塞，外发颓疝，胸中不便，嗌而咳；其复也，则病生胠胁，气归于左，善太息，甚则心痛痞满，腹胀而泄，呕苦，咳哕烦心，病在膈中，甚则入肝，惊骇筋挛。 太阳之胜，则病痔疟，发寒，厥人胃，则内生心痛，阴中乃疡，隐曲不利，亘引阴股筋肉拘苛，血脉凝泣，络满血变，或为血泄，皮肤否肿，腹满时减，热反上行，头项囟顶脑户中痛，目如脱，寒入下焦，则传为濡泄；其复也，则心胃生寒，胸膈不利，心痛痞满，头痛，善悲，时发眩仆，食减，腰椎反痛，屈伸不便，少腹控睪引腰脊上冲心，唾出清水，及为哕噫，甚则入心，善忘，善悲，寒复内余，则腰尻痛，屈伸不利，股胫足膝中痛。 此六气为病，须谨识之，而弗失也。', '2024-12-07T02:36:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 'I8vjThKe1JN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('seSdWcuQbS1', 4, '{"title":"6","description":"<p>6、师曰：子知六气，不知五运，未尽其道，今为子言，假如太阳司天，而运当甲己，夫甲己土运也，太阳寒水也，土能克水，太阳不能正其位也；又如厥阴司天，而逢乙庚金运；少阴少阳司天，而逢丙辛水运；太阴司天，而逢丁壬木运；阳明司天，而逢戊癸火运，其例同也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001005006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:36:09.000Z', '2024-12-07T02:36:09.000Z', '2024-12-07T02:36:09.000Z', '6、师曰：子知六气，不知五运，未尽其道，今为子言，假如太阳司天，而运当甲己，夫甲己土运也，太阳寒水也，土能克水，太阳不能正其位也；又如厥阴司天，而逢乙庚金运；少阴少阳司天，而逢丙辛水运；太阴司天，而逢丁壬木运；阳明司天，而逢戊癸火运，其例同也。', '2024-12-07T02:36:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 'I8vjThKe1JN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9FB1oFCdskw', 4, '{"title":"7","description":"<p>7、问曰：其治法奈何？</p>\n<p></p>\n<p>     师曰：风寒暑湿燥热各随其气，有假者反之，甚者从之，微者逆之，采取方法，慎毋乱也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001005007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T02:36:09.000Z', '2024-12-07T02:36:09.000Z', '2024-12-07T02:36:09.000Z', '7、问曰：其治法奈何？ 师曰：风寒暑湿燥热各随其气，有假者反之，甚者从之，微者逆之，采取方法，慎毋乱也。', '2024-12-07T02:36:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 'I8vjThKe1JN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aSjJwZ6IOh9', 4, '{"title":"1","description":"<p>1、</p>\n<p>四时八节二十四节气七十二候决病法：</p>\n<p>立春正月节斗指艮，雨水正月中斗指寅。</p>\n<p>惊蛰二月节斗指甲，春分二月中斗指卯。</p>\n<p>清明三月节斗指乙，谷雨三月中斗指辰。</p>\n<p>立夏四月节斗指巽，小满四月中斗指巳。</p>\n<p>芒种五月节斗指丙，夏至五月中斗指午。</p>\n<p>小暑六月节斗指丁，大暑六月中斗指未。</p>\n<p>立秋七月节斗指坤，处暑七月中斗指申。</p>\n<p>白露八月节斗指庚，秋分八月中斗指酉。</p>\n<p>寒露九月节斗指辛，霜降九月中斗指戌。</p>\n<p>立冬十月节斗指干，小雪十月中斗指亥。</p>\n<p>大雪十一月节斗指壬，冬至十一月中斗指子。</p>\n<p>小寒十二月节斗指癸，大寒十二月中斗指丑。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T03:49:05.000Z', '2024-12-07T03:49:05.000Z', '2024-12-07T03:49:05.000Z', '1、 四时八节二十四节气七十二候决病法： 立春正月节斗指艮，雨水正月中斗指寅。 惊蛰二月节斗指甲，春分二月中斗指卯。 清明三月节斗指乙，谷雨三月中斗指辰。 立夏四月节斗指巽，小满四月中斗指巳。 芒种五月节斗指丙，夏至五月中斗指午。 小暑六月节斗指丁，大暑六月中斗指未。 立秋七月节斗指坤，处暑七月中斗指申。 白露八月节斗指庚，秋分八月中斗指酉。 寒露九月节斗指辛，霜降九月中斗指戌。 立冬十月节斗指干，小雪十月中斗指亥。 大雪十一月节斗指壬，冬至十一月中斗指子。 小寒十二月节斗指癸，大寒十二月中斗指丑。', '2024-12-07T03:49:05.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oFqBfrTwmXT', 4, '{"title":"2","description":"<p>2、二十四节气，节有十二，中气有十二，五日为一候，气亦同，合有七十二候，决病生死，此须洞解也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T03:49:05.000Z', '2024-12-07T03:49:05.000Z', '2024-12-07T03:49:05.000Z', '2、二十四节气，节有十二，中气有十二，五日为一候，气亦同，合有七十二候，决病生死，此须洞解也。', '2024-12-07T03:49:05.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z5z3xNjx862', 4, '{"title":"3、阴阳大论云","description":"<p>3、阴阳大论云：春气温和，夏气暑热，秋气清凉，冬气冰冽，此则四时正气之序也。</p>\n<p></p>\n<p>    冬时严寒，万类深藏，君子周密，则不伤于寒。触冒之者，则名伤寒耳。其伤于四时之气，皆能为病。以伤寒为病者，以其最盛杀厉之气也。中而即病者，名曰伤寒；不即病，寒毒藏于肌肤，至春变为温病，至夏变为暑病。</p>\n<p>   暑病者，热极重于温也。是以辛苦之人，春夏多温热者，皆由冬时触寒所致，非时行之气也。凡时行者，春时应暖而反大寒；夏时应热而反大凉；秋时应凉而反大热；冬时应寒而反大温。此非其时而有其气，是以一岁之中，长幼之病多相似者，此则时行之气也。夫欲候知四时正气为病，及时行疫气之法，皆当按斗历占之。</p>\n<p>    九月霜降节后，宜渐寒，向冬大寒，至正月雨水节后宜解也。所以谓之雨水者，以冰雪解而为雨水故也。</p>\n<p>    至惊蛰二月节后，气渐和暖，向夏大热，至秋便凉。</p>\n<p>    从霜降以后，至春分以前，凡有触冒霜露，体中寒即病者，谓之伤寒也。</p>\n<p>    九月十月寒气尚微，为病则轻；十一月十二月寒冽已严，为病则重；正月二月寒渐将解，为病亦轻。此以冬时不调，适有伤寒之人即为病也。其冬有非节之暖者，名曰冬温。</p>\n<p>    冬温之毒，与伤寒大异，冬温复有先后，更相重沓，亦有轻重，为治不同，证如后章。</p>\n<p>    从立春节后，其中无暴大寒，又不冰雪；而有人壮热为病者，此属春时阳气，发其冬时伏寒，变为温病。</p>\n<p>    从春分以后，至秋分节前，天有暴寒者，皆为时行寒疫也。三月四月或有暴寒，其时阳气尚弱，为寒所折，病热犹轻；五月六月阳气已盛，为寒所折，病热则重；七月八月，阳气已衰，为寒所折，病热亦微。其病与温相似，但治有殊耳。</p>\n<p></p>\n<p>   十五日得一气，于四时之中，一时有六气，四六名为二十四气。然气候亦有应至仍不至，或有未应至而至者，或有至而太过者，皆成病气也。但天地动静，阴阳鼓击者，各正一气耳。是以彼春之暖，为夏之暑；彼秋之忿，为冬之怒。是故冬至之后，一阳爻升，一阴爻降也。</p>\n<p>    夏至之后，一阳气下，一阴气上也。斯则冬夏二至，阴阳合也；春秋二分，阴阳离也。阴阳交易，人变病焉。此君子春夏养阳，秋冬养阴，顺天地之刚柔也。小人触冒，必婴暴疹。须知毒烈之气，留在何经，必发何病，详而取之。是以春伤于风，夏必飧泄；夏伤于暑，秋必病疟；秋伤于湿，冬必咳嗽；</p>\n<p>   冬伤于寒，春必病温。此必然之道，可不审明之。伤寒之病，逐日浅深，以施方治。</p>\n<p></p>\n<p>   今世人伤寒，或始不早治，或治不对病，或日数久淹，困乃告医。医人又不依次第而治之，则不中病。皆宜临时消息制方，无不效也。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T03:49:05.000Z', '2024-12-07T03:49:05.000Z', '2024-12-07T03:49:05.000Z', '3、阴阳大论云：春气温和，夏气暑热，秋气清凉，冬气冰冽，此则四时正气之序也。 冬时严寒，万类深藏，君子周密，则不伤于寒。触冒之者，则名伤寒耳。其伤于四时之气，皆能为病。以伤寒为病者，以其最盛杀厉之气也。中而即病者，名曰伤寒；不即病，寒毒藏于肌肤，至春变为温病，至夏变为暑病。 暑病者，热极重于温也。是以辛苦之人，春夏多温热者，皆由冬时触寒所致，非时行之气也。凡时行者，春时应暖而反大寒；夏时应热而反大凉；秋时应凉而反大热；冬时应寒而反大温。此非其时而有其气，是以一岁之中，长幼之病多相似者，此则时行之气也。夫欲候知四时正气为病，及时行疫气之法，皆当按斗历占之。 九月霜降节后，宜渐寒，向冬大寒，至正月雨水节后宜解也。所以谓之雨水者，以冰雪解而为雨水故也。 至惊蛰二月节后，气渐和暖，向夏大热，至秋便凉。 从霜降以后，至春分以前，凡有触冒霜露，体中寒即病者，谓之伤寒也。 九月十月寒气尚微，为病则轻；十一月十二月寒冽已严，为病则重；正月二月寒渐将解，为病亦轻。此以冬时不调，适有伤寒之人即为病也。其冬有非节之暖者，名曰冬温。 冬温之毒，与伤寒大异，冬温复有先后，更相重沓，亦有轻重，为治不同，证如后章。 从立春节后，其中无暴大寒，又不冰雪；而有人壮热为病者，此属春时阳气，发其冬时伏寒，变为温病。 从春分以后，至秋分节前，天有暴寒者，皆为时行寒疫也。三月四月或有暴寒，其时阳气尚弱，为寒所折，病热犹轻；五月六月阳气已盛，为寒所折，病热则重；七月八月，阳气已衰，为寒所折，病热亦微。其病与温相似，但治有殊耳。 十五日得一气，于四时之中，一时有六气，四六名为二十四气。然气候亦有应至仍不至，或有未应至而至者，或有至而太过者，皆成病气也。但天地动静，阴阳鼓击者，各正一气耳。是以彼春之暖，为夏之暑；彼秋之忿，为冬之怒。是故冬至之后，一阳爻升，一阴爻降也。 夏至之后，一阳气下，一阴气上也。斯则冬夏二至，阴阳合也；春秋二分，阴阳离也。阴阳交易，人变病焉。此君子春夏养阳，秋冬养阴，顺天地之刚柔也。小人触冒，必婴暴疹。须知毒烈之气，留在何经，必发何病，详而取之。是以春伤于风，夏必飧泄；夏伤于暑，秋必病疟；秋伤于湿，冬必咳嗽； 冬伤于寒，春必病温。此必然之道，可不审明之。伤寒之病，逐日浅深，以施方治。 今世人伤寒，或始不早治，或治不对病，或日数久淹，困乃告医。医人又不依次第而治之，则不中病。皆宜临时消息制方，无不效也。', '2024-12-07T03:49:05.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LUhPSysxmZS', 4, '{"title":"4、又土地温凉，高下不同；物性刚柔，餐［注","description":"<p>4、又土地温凉，高下不同；物性刚柔，餐［注：桂本餐字为飧，似误］居亦异。是故黄帝兴四方之问，岐伯举四治之能，以训后贤，开其未悟。临病之工，宜须两审也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '4、又土地温凉，高下不同；物性刚柔，餐［注：桂本餐字为飧，似误］居亦异。是故黄帝兴四方之问，岐伯举四治之能，以训后贤，开其未悟。临病之工，宜须两审也。', '2024-12-07T04:00:57.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NsD97XRrodo', 4, '{"title":"5、凡伤于寒，传经则为病热，热虽甚，不死","description":"<p>5、凡伤于寒，传经则为病热，热虽甚，不死。若两感于寒而病者，多死。尺寸俱浮者，太阳受病也，当一二日发。以其脉上连风府，故头项痛，腰脊强。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '5、凡伤于寒，传经则为病热，热虽甚，不死。若两感于寒而病者，多死。尺寸俱浮者，太阳受病也，当一二日发。以其脉上连风府，故头项痛，腰脊强。', '2024-12-07T04:00:57.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BJS7FKAFfnV', 4, '{"title":"6、尺寸俱长者，阳明受病也，当二三日发","description":"<p>6、尺寸俱长者，阳明受病也，当二三日发。以其脉侠鼻、络于目，故身热、汗出、目疼、鼻干、不得卧。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '6、尺寸俱长者，阳明受病也，当二三日发。以其脉侠鼻、络于目，故身热、汗出、目疼、鼻干、不得卧。', '2024-12-07T04:00:57.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VRgyD758Qej', 4, '{"title":"7、尺寸俱弦者，少阳受病也，当三四日发","description":"<p>7、尺寸俱弦者，少阳受病也，当三四日发。以其脉循胁络于耳，故胸胁痛而耳聋。此三经受病，未入于腑者，皆可汗而已。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '7、尺寸俱弦者，少阳受病也，当三四日发。以其脉循胁络于耳，故胸胁痛而耳聋。此三经受病，未入于腑者，皆可汗而已。', '2024-12-07T04:00:57.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rs2paVewTqY', 4, '{"title":"8、尺寸俱沉濡者，太阴受病也，当四五日发","description":"<p>8、尺寸俱沉濡者，太阴受病也，当四五日发。以其脉布胃中，络于嗌，故腹满而嗌干。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '8、尺寸俱沉濡者，太阴受病也，当四五日发。以其脉布胃中，络于嗌，故腹满而嗌干。', '2024-12-07T04:00:57.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D54zKyl2LSA', 4, '{"title":"9、尺寸俱沉细者，少阴受病也，当五六日发","description":"<p>9、尺寸俱沉细者，少阴受病也，当五六日发。以其脉贯肾，络于肺，系舌本，故口燥舌干而渴。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '9、尺寸俱沉细者，少阴受病也，当五六日发。以其脉贯肾，络于肺，系舌本，故口燥舌干而渴。', '2024-12-07T04:00:57.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FvSIJXKd4ND', 4, '{"title":"10、尺寸俱弦微者，厥阴受病也，当六七日发","description":"<p>10、尺寸俱弦微者，厥阴受病也，当六七日发。以其脉循阴器、络于肝，故烦满而囊缩。此三经受病，己入于腑者，皆可下而已。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '10、尺寸俱弦微者，厥阴受病也，当六七日发。以其脉循阴器、络于肝，故烦满而囊缩。此三经受病，己入于腑者，皆可下而已。', '2024-12-07T04:00:57.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hEklYf13ivS', 4, '{"title":"11","description":"<p>11、伤寒传经在太阳，脉浮而急数，发热，无汗，烦躁，宜$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006011,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '11、伤寒传经在太阳，脉浮而急数，发热，无汗，烦躁，宜$f{麻黄汤}。', '2024-12-07T04:00:57.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E17Ipfor2tq', 4, '{"title":"12","description":"<p>12、传阳明，脉大而数，发热，汗出，口渴舌燥，宜$f{白虎汤}，不差与$n{承气汤}--$f{大承气汤}--$f{小承气汤}--$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006012,"note":"","videoMemo":"","fangList":["白虎汤","大承气汤","小承气汤","调胃承气汤"],"bieMing":""}}', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '2024-12-07T04:00:57.000Z', '12、传阳明，脉大而数，发热，汗出，口渴舌燥，宜$f{白虎汤}，不差与$n{承气汤}--$f{大承气汤}--$f{小承气汤}--$f{调胃承气汤}。', '2024-12-07T04:00:57.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TxrLgEHi9Ql', 4, '{"title":"13","description":"<p>13、传少阳，脉弦而急，口苦，咽干，头晕，目眩，往来寒热，热多寒少，宜$f{小柴胡汤}，不差与$f{大柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006013,"note":"","videoMemo":"","fangList":["小柴胡汤","大柴胡汤"],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '13、传少阳，脉弦而急，口苦，咽干，头晕，目眩，往来寒热，热多寒少，宜$f{小柴胡汤}，不差与$f{大柴胡汤}。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4OVayQJ3e1n', 4, '{"title":"14","description":"<p>14、传太阴，脉濡而大，发热，下利，口渴，腹中急痛，宜$f{茯苓白术厚朴石膏黄芩甘草汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006014,"note":"","videoMemo":"","fangList":["茯苓白术厚朴石膏黄芩甘草汤"],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '14、传太阴，脉濡而大，发热，下利，口渴，腹中急痛，宜$f{茯苓白术厚朴石膏黄芩甘草汤}。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gSQP6RJsHSj', 4, '{"title":"15","description":"<p>15、传少阴，脉沉细而数，手足时厥时热，咽中痛，小便难，宜$f{附子细辛黄连黄芩汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006015,"note":"","videoMemo":"","fangList":["附子细辛黄连黄芩汤"],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '15、传少阴，脉沉细而数，手足时厥时热，咽中痛，小便难，宜$f{附子细辛黄连黄芩汤}。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oJYW1n73AbH', 4, '{"title":"16","description":"<p>16、传厥阴，脉沉弦而急，发热时悚，心烦呕逆，宜$f{桂枝当归汤}，吐蛔者，宜$f{乌梅丸}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006016,"note":"","videoMemo":"","fangList":["桂枝当归汤","乌梅丸"],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '16、传厥阴，脉沉弦而急，发热时悚，心烦呕逆，宜$f{桂枝当归汤}，吐蛔者，宜$f{乌梅丸}。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8xW08yVm19H', 4, '{"title":"17、以上皆传经脉证并治之正法也","description":"<p>17、以上皆传经脉证并治之正法也。若入腑及脏为传经变病，治列后条。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '17、以上皆传经脉证并治之正法也。若入腑及脏为传经变病，治列后条。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aZppCKrMbuh', 4, '{"title":"18","description":"<p>18、若两感于寒者，一日太阳受之，即与少阴俱病，则头痛、口干、烦满而渴，脉时浮时沉，时数时细，$f{大青龙汤加附子}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006018,"note":"","videoMemo":"","fangList":["大青龙汤加附子"],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '18、若两感于寒者，一日太阳受之，即与少阴俱病，则头痛、口干、烦满而渴，脉时浮时沉，时数时细，$f{大青龙汤加附子}主之。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ku8ubTyOEcD', 4, '{"title":"19","description":"<p>19、二日阳明受之，即与太阴俱病，则腹满身热、不欲食、谵语，脉时高时卑，时强时弱，宜$f{大黄石膏茯苓白术枳实甘草汤}</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006019,"note":"","videoMemo":"","fangList":["大黄石膏茯苓白术枳实甘草汤"],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '19、二日阳明受之，即与太阴俱病，则腹满身热、不欲食、谵语，脉时高时卑，时强时弱，宜$f{大黄石膏茯苓白术枳实甘草汤}', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wYFLtU2157w', 4, '{"title":"20","description":"<p>20、三日少阳受之，即与厥阴俱病，则耳聋，囊缩而厥，水浆不入，脉乍弦乍急，乍细乍散，宜$f{当归附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006020,"note":"","videoMemo":"","fangList":["当归附子汤"],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '20、三日少阳受之，即与厥阴俱病，则耳聋，囊缩而厥，水浆不入，脉乍弦乍急，乍细乍散，宜$f{当归附子汤}主之。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sZpuit1n76C', 4, '{"title":"21、以上皆传经变病，多不可治，不知人者，六日死","description":"<p>21、以上皆传经变病，多不可治，不知人者，六日死。若三阴三阳、五脏六腑皆受病，则荣卫不行，脏腑不通而死矣。所谓两感于寒不免于死者，其在斯乎!其在斯乎!</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006021,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '21、以上皆传经变病，多不可治，不知人者，六日死。若三阴三阳、五脏六腑皆受病，则荣卫不行，脏腑不通而死矣。所谓两感于寒不免于死者，其在斯乎!其在斯乎!', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5AbkLcoGUcq', 4, '{"title":"22","description":"<p>22、若不加异气者，至七日太阳病衰，头痛少愈也；八日阳明病衰，身热少歇也；九日少阳病衰，耳聋微闻也；十日太阴病衰，腹减如故，则思饮食；十一日少阴病衰，渴止舌干，已而嚏；十二日厥阴病衰，囊纵，少腹微下，大气皆去，病人精神爽慧也。若过十三日以上不间，尺寸陷者，大危。若更感异气，变为他病者，当依坏病证法而治之。若脉阴阳俱盛，重感于寒者，变成温疟。阳脉浮滑，阴脉濡弱，更伤于风者，变为风温。阳脉洪数，阴脉实大，更遇温热者，变为温毒。温毒，病之最重者也。阳脉濡弱，阴脉弦紧，更遇温气者，变为温疫。以此冬伤于寒，发为温病，脉之变证，方治如说。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006022,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '22、若不加异气者，至七日太阳病衰，头痛少愈也；八日阳明病衰，身热少歇也；九日少阳病衰，耳聋微闻也；十日太阴病衰，腹减如故，则思饮食；十一日少阴病衰，渴止舌干，已而嚏；十二日厥阴病衰，囊纵，少腹微下，大气皆去，病人精神爽慧也。若过十三日以上不间，尺寸陷者，大危。若更感异气，变为他病者，当依坏病证法而治之。若脉阴阳俱盛，重感于寒者，变成温疟。阳脉浮滑，阴脉濡弱，更伤于风者，变为风温。阳脉洪数，阴脉实大，更遇温热者，变为温毒。温毒，病之最重者也。阳脉濡弱，阴脉弦紧，更遇温气者，变为温疫。以此冬伤于寒，发为温病，脉之变证，方治如说。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('StJuUY1DfsH', 4, '{"title":"23、凡人有疾，不时即治，隐忍冀差，以成痼疾","description":"<p>23、凡人有疾，不时即治，隐忍冀差，以成痼疾。小儿女子，益以滋甚。时气不和，便当早言，寻其邪由，及在腠理，以时治之，罕有不愈者。患人忍之，数日乃说，邪气入脏，则难为制。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006023,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '23、凡人有疾，不时即治，隐忍冀差，以成痼疾。小儿女子，益以滋甚。时气不和，便当早言，寻其邪由，及在腠理，以时治之，罕有不愈者。患人忍之，数日乃说，邪气入脏，则难为制。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xnMdJh5n4sG', 4, '{"title":"24","description":"<p>24、凡作汤药，不可避晨夕，觉病须臾，即宜便治，不等早晚，则易愈矣。如或差迟，病即传变，虽欲除治，必难为力。服药不如方法，纵意违师，不须治之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006024,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '24、凡作汤药，不可避晨夕，觉病须臾，即宜便治，不等早晚，则易愈矣。如或差迟，病即传变，虽欲除治，必难为力。服药不如方法，纵意违师，不须治之。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U8RBexf0O3i', 4, '{"title":"25、凡伤寒之病，多从风寒得之","description":"<p>25、凡伤寒之病，多从风寒得之。始表中风寒，入里则不消矣。未有温覆当而不消散者。不在证治，拟欲攻之，犹当先解表，乃可下之。若表未解，而内不消，必非大满，犹有寒热，则不可下。若表已解，而内不消，大满大实，腹坚，中有燥屎，自可除下之。虽四五日，数下之，不能为祸也。若不宜下，而便攻之，则内虚热入，协热遂利，烦躁诸变，不可胜数，轻者困笃，重者必死矣。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006025,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '25、凡伤寒之病，多从风寒得之。始表中风寒，入里则不消矣。未有温覆当而不消散者。不在证治，拟欲攻之，犹当先解表，乃可下之。若表未解，而内不消，必非大满，犹有寒热，则不可下。若表已解，而内不消，大满大实，腹坚，中有燥屎，自可除下之。虽四五日，数下之，不能为祸也。若不宜下，而便攻之，则内虚热入，协热遂利，烦躁诸变，不可胜数，轻者困笃，重者必死矣。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WWf6ABdNgxb', 4, '{"title":"26","description":"<p>26、夫阳盛阴虚，汗之则死，下之则愈；阳虚阴盛，汗之则愈，下之则死。如是，则神丹安可以误发，甘遂何可以妄攻？虚盛之治，相背千里，吉凶之机，应若影响，岂容易哉!况桂枝下咽，阳盛即毙；承气入胃，阴盛以亡，死生之要，在乎须臾，视身之尽，不暇计日。此阴阳虚实之交错，其候至微；发汗吐下之相反，其祸至速，而医术浅狭，懵然不知病源，为治乃误，使病者殒殁，自谓其分，至令冤魂塞于冥路，死尸盈于旷野，仁者鉴此，岂不痛欤！</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006026,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '26、夫阳盛阴虚，汗之则死，下之则愈；阳虚阴盛，汗之则愈，下之则死。如是，则神丹安可以误发，甘遂何可以妄攻？虚盛之治，相背千里，吉凶之机，应若影响，岂容易哉!况桂枝下咽，阳盛即毙；承气入胃，阴盛以亡，死生之要，在乎须臾，视身之尽，不暇计日。此阴阳虚实之交错，其候至微；发汗吐下之相反，其祸至速，而医术浅狭，懵然不知病源，为治乃误，使病者殒殁，自谓其分，至令冤魂塞于冥路，死尸盈于旷野，仁者鉴此，岂不痛欤！', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mvHVLVUufZN', 4, '{"title":"27","description":"<p>27、凡两感病俱作，治有先后，发表攻里，本自不同，而执迷用意者，乃云神丹甘遂合而饮之，且解其表，又除其里，言巧似是，其理实违。夫智者之举错也，常审以慎；愚者之动作也，必果而速。安危之变，岂可诡哉！世上之士，但务彼翕习之荣，而莫见此倾危之败，惟明者居然，能护其本，近取诸身，夫何远焉。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006027,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '27、凡两感病俱作，治有先后，发表攻里，本自不同，而执迷用意者，乃云神丹甘遂合而饮之，且解其表，又除其里，言巧似是，其理实违。夫智者之举错也，常审以慎；愚者之动作也，必果而速。安危之变，岂可诡哉！世上之士，但务彼翕习之荣，而莫见此倾危之败，惟明者居然，能护其本，近取诸身，夫何远焉。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R4vRmEVlKYD', 4, '{"title":"28","description":"<p>28、凡发汗，温暖汤药，其方虽言日三服，若病剧不解，当促其间，可半日中尽三服。若与病相阻，即使有所觉，病重病者一日一夜，当晬时观之，如服一剂，病证犹在，故当复作本汤服之。至有不能汗出，服三剂乃解；若汗不出者，死病也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006028,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '28、凡发汗，温暖汤药，其方虽言日三服，若病剧不解，当促其间，可半日中尽三服。若与病相阻，即使有所觉，病重病者一日一夜，当晬时观之，如服一剂，病证犹在，故当复作本汤服之。至有不能汗出，服三剂乃解；若汗不出者，死病也。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XB5F06oajFP', 4, '{"title":"29","description":"<p>29、凡得时气病，至五六日，而渴欲饮水，饮不能多，不当与也，何者？以腹中热尚少，不能消之，便更与人作病也。至七八日，大渴欲饮水者，犹当依证而与之。与之时常令不足，勿极意也。言能饮一斗，与五升。若饮而腹满，小便不利，若喘若哕。不可与之也。忽然大汗出，是为自愈也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006029,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '29、凡得时气病，至五六日，而渴欲饮水，饮不能多，不当与也，何者？以腹中热尚少，不能消之，便更与人作病也。至七八日，大渴欲饮水者，犹当依证而与之。与之时常令不足，勿极意也。言能饮一斗，与五升。若饮而腹满，小便不利，若喘若哕。不可与之也。忽然大汗出，是为自愈也。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EnjWaYKgjEo', 4, '{"title":"30、凡得病反能饮水，此为欲愈之病","description":"<p>30、凡得病反能饮水，此为欲愈之病。其不晓病者，但闻病饮水者自愈，小渴者乃强与饮之，因成其祸，不可复数也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006030,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '30、凡得病反能饮水，此为欲愈之病。其不晓病者，但闻病饮水者自愈，小渴者乃强与饮之，因成其祸，不可复数也。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ccq8SQ03wSm', 4, '{"title":"31","description":"<p>31、凡得病厥，脉动数，服汤更迟；脉浮大减小；初躁后静，此皆愈证也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006031,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '31、凡得病厥，脉动数，服汤更迟；脉浮大减小；初躁后静，此皆愈证也。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZyUgrgJXGZ2', 4, '{"title":"32、凡治温病，可刺五十九穴","description":"<p>32、凡治温病，可刺五十九穴。又身之穴，三百六十有五，其三十穴灸之有害；七十九穴刺之为灾，并中髓也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006032,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '32、凡治温病，可刺五十九穴。又身之穴，三百六十有五，其三十穴灸之有害；七十九穴刺之为灾，并中髓也。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k3HWFUXqOYj', 4, '{"title":"33、脉四损，三日死","description":"<p>33、脉四损，三日死。平人一息，病人脉一至，名曰四损。脉五损，一日死。平人二息，病人脉一至，名曰五损。脉六损，一时死。平人三息，病人脉一至，名曰六损。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006033,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '33、脉四损，三日死。平人一息，病人脉一至，名曰四损。脉五损，一日死。平人二息，病人脉一至，名曰五损。脉六损，一时死。平人三息，病人脉一至，名曰六损。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pAzdvkUQEzI', 4, '{"title":"34、四损，经气绝；五损，腑气绝；六损，脏气绝","description":"<p>34、四损，经气绝；五损，腑气绝；六损，脏气绝。真气不行于经曰经气绝；不行于腑，曰腑气绝；不行于脏，曰脏气绝；经气绝，则四肢不举；腑气绝，则不省人事；脏气绝，则一身尽冷。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006034,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '34、四损，经气绝；五损，腑气绝；六损，脏气绝。真气不行于经曰经气绝；不行于腑，曰腑气绝；不行于脏，曰脏气绝；经气绝，则四肢不举；腑气绝，则不省人事；脏气绝，则一身尽冷。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nd8aiHDcYuN', 4, '{"title":"35、脉盛身寒，得之伤寒；脉虚身热，得之伤暑","description":"<p>35、脉盛身寒，得之伤寒；脉虚身热，得之伤暑。脉阴阳俱盛，大汗出，下之不解者死。脉阴阳俱虚，热不止者死。脉至乍数乍疏者死。脉至如转索，按之不易者其日死。谵言妄语，身微热，脉浮大，手足温者生。逆冷，脉沉细者，不过一日死矣。此以前是伤寒热病证候也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006035,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '35、脉盛身寒，得之伤寒；脉虚身热，得之伤暑。脉阴阳俱盛，大汗出，下之不解者死。脉阴阳俱虚，热不止者死。脉至乍数乍疏者死。脉至如转索，按之不易者其日死。谵言妄语，身微热，脉浮大，手足温者生。逆冷，脉沉细者，不过一日死矣。此以前是伤寒热病证候也。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RYAUW1sNMo1', 4, '{"title":"36、脉濡而弱，弱反在关，濡反在巅，微反在上，涩反在下","description":"<p>36、脉濡而弱，弱反在关，濡反在巅，微反在上，涩反在下。微则阳气不足，涩则无血。阳气反微，中风汗出而反躁烦。涩则无血，厥而且寒。阳厥发汗，躁不得眠。阳微则不可下，下之则心下痞鞕。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006036,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '36、脉濡而弱，弱反在关，濡反在巅，微反在上，涩反在下。微则阳气不足，涩则无血。阳气反微，中风汗出而反躁烦。涩则无血，厥而且寒。阳厥发汗，躁不得眠。阳微则不可下，下之则心下痞鞕。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('77MFP6QuP7p', 4, '{"title":"37、动气在右，不可发汗，发汗则衄而渴，心苦烦，饮水即吐","description":"<p>37、动气在右，不可发汗，发汗则衄而渴，心苦烦，饮水即吐。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006037,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '37、动气在右，不可发汗，发汗则衄而渴，心苦烦，饮水即吐。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iLnKLeB2vN0', 4, '{"title":"38","description":"<p>38、动气在左，不可发汗，发汗则头眩，汗不止，则筋惕肉〖目闰〗。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006038,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '38、动气在左，不可发汗，发汗则头眩，汗不止，则筋惕肉〖目闰〗。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zjhEFNTIzp9', 4, '{"title":"39、动气在上，不可发汗，发汗则气上冲止于心下","description":"<p>39、动气在上，不可发汗，发汗则气上冲止于心下。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006039,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '39、动气在上，不可发汗，发汗则气上冲止于心下。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('acDgDRQmmyc', 4, '{"title":"40","description":"<p>40、动气在下，不可发汗，发汗则无汗可发，心中大烦，骨节疼痛，目眩恶寒，食则吐谷，气不得前。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006040,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '40、动气在下，不可发汗，发汗则无汗可发，心中大烦，骨节疼痛，目眩恶寒，食则吐谷，气不得前。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q6GfsS7gcQf', 4, '{"title":"41","description":"<p>41、咽中闭塞，不可发汗，发汗则吐血，气欲欲绝，手足厥冷，欲得蜷卧，不能自温。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006041,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '41、咽中闭塞，不可发汗，发汗则吐血，气欲欲绝，手足厥冷，欲得蜷卧，不能自温。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NdfNHh4sEgH', 4, '{"title":"42","description":"<p>42、诸脉得数动微弱者，不可发汗，发汗则大便难，腹中干，胃燥而烦，其形相象，根本异源。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006042,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '42、诸脉得数动微弱者，不可发汗，发汗则大便难，腹中干，胃燥而烦，其形相象，根本异源。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('69dIIWHXT2G', 4, '{"title":"43、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下","description":"<p>43、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，不可发汗，发汗则寒栗，不能自还。咳而发汗，其咳必剧，数吐涎沫，咽中必干，小便不利，心中饥烦，晬时而发，其形似疟，有寒无热，虚而寒栗，蜷而苦满，腹中复坚，命将难全。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006043,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '43、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，不可发汗，发汗则寒栗，不能自还。咳而发汗，其咳必剧，数吐涎沫，咽中必干，小便不利，心中饥烦，晬时而发，其形似疟，有寒无热，虚而寒栗，蜷而苦满，腹中复坚，命将难全。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VQnhFzYLsIK', 4, '{"title":"44、厥逆脉紧，不可发汗，发汗声乱、咽嘶、舌萎、声不得前","description":"<p>44、厥逆脉紧，不可发汗，发汗声乱、咽嘶、舌萎、声不得前。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006044,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '44、厥逆脉紧，不可发汗，发汗声乱、咽嘶、舌萎、声不得前。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
