INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H6bPzaR344Y', 4, '{"title":"46、凡发汗，欲令遍身漐漐微似汗，不可令如水流漓","description":"<p>46、凡发汗，欲令遍身漐漐微似汗，不可令如水流漓。若病不解，当重发汗；若汗多者，不得重发汗，亡阳故也。。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006046,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '46、凡发汗，欲令遍身漐漐微似汗，不可令如水流漓。若病不解，当重发汗；若汗多者，不得重发汗，亡阳故也。。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kyg2YGLJ5EO', 4, '{"title":"47、凡服汤发汗，中病便止，不必尽剂","description":"<p>47、凡服汤发汗，中病便止，不必尽剂。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006047,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '47、凡服汤发汗，中病便止，不必尽剂。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
