INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dMpssGOq2Wx', 4, '{"title":"50","description":"<p>50、凡病胸上诸实，胸中郁郁而痛，不能食，欲使人按之，而反有涎唾，下利十余行，其脉反涩，寸口脉微滑，此可吐之，吐之利则止。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006050,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '50、凡病胸上诸实，胸中郁郁而痛，不能食，欲使人按之，而反有涎唾，下利十余行，其脉反涩，寸口脉微滑，此可吐之，吐之利则止。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XL0iaW4mY9w', 4, '{"title":"51、宿食在上脘者，当吐之","description":"<p>51、宿食在上脘者，当吐之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006051,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '51、宿食在上脘者，当吐之。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xvH0YS2Tb3t', 4, '{"title":"52","description":"<p>52、动气在右，不可下之，下之则津液内竭，咽燥、鼻干、头眩、心悸也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006052,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '52、动气在右，不可下之，下之则津液内竭，咽燥、鼻干、头眩、心悸也。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4cVK1uoqxCk', 4, '{"title":"53、动气在左，不可下之","description":"<p>53、动气在左，不可下之。下之则腹内拘急，食饮不下，动气更剧。虽有身热，卧则欲蜷。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006053,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '53、动气在左，不可下之。下之则腹内拘急，食饮不下，动气更剧。虽有身热，卧则欲蜷。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iIgJe77QYmt', 4, '{"title":"54、动气在上，不可下之","description":"<p>54、动气在上，不可下之。下之则掌中热烦，身上浮冷，热汗自泄，欲得水自灌。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006054,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '54、动气在上，不可下之。下之则掌中热烦，身上浮冷，热汗自泄，欲得水自灌。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gn2IS4dq10m', 4, '{"title":"55、动气在下，不可下之","description":"<p>55、动气在下，不可下之。下之则腹胀满，卒起头眩，食则下利清谷，心下痞。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006055,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '55、动气在下，不可下之。下之则腹胀满，卒起头眩，食则下利清谷，心下痞。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('96bQA2EKeoD', 4, '{"title":"56、咽中闭寒，不可下之","description":"<p>56、咽中闭寒，不可下之。下之则上轻下重，水浆不下，卧则欲蜷，身急痛，下利日数十行。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006056,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '56、咽中闭寒，不可下之。下之则上轻下重，水浆不下，卧则欲蜷，身急痛，下利日数十行。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zdbD282Vb36', 4, '{"title":"57、诸外实者，不可下之","description":"<p>57、诸外实者，不可下之。下之则发微热，若亡脉厥者，当脐握热。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006057,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '57、诸外实者，不可下之。下之则发微热，若亡脉厥者，当脐握热。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WZv9SLrxgiP', 4, '{"title":"58、诸虚者，不可下之","description":"<p>58、诸虚者，不可下之。下之则大渴，求水者易愈，恶水者剧。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006058,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '58、诸虚者，不可下之。下之则大渴，求水者易愈，恶水者剧。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PsY1oZ2LgCu', 4, '{"title":"59、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下","description":"<p>59、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，虚者不可下也。微弦为咳，咳则吐涎，下之则咳止，而利因不休，利不休则胸中如虫啮，粥入则出，小便不利，两胁拘急，喘息为难，颈背相引，臂则不仁，极寒反汗出，身冷若冰，眼睛不慧，语言不休，而谷气多入，此为除中，口虽欲言，舌不得前。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006059,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '59、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，虚者不可下也。微弦为咳，咳则吐涎，下之则咳止，而利因不休，利不休则胸中如虫啮，粥入则出，小便不利，两胁拘急，喘息为难，颈背相引，臂则不仁，极寒反汗出，身冷若冰，眼睛不慧，语言不休，而谷气多入，此为除中，口虽欲言，舌不得前。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w5863Mybdfu', 4, '{"title":"60、脉濡而紧，濡则卫气微，紧则荣中寒","description":"<p>60、脉濡而紧，濡则卫气微，紧则荣中寒。阳微卫中风，发热而恶寒；荣紧胃气冷，微呕心内烦。医谓有大热，解肌而发汗，亡阳虚烦躁，心下苦痞坚。表里俱虚竭，卒起而头眩。客热在皮肤，怅怏不得眠。不知胃气冷，紧寒在关元。技巧无所施，汲水灌其身。客热应时罢，栗栗而振寒。重被而复之，汗出而冒巅。体惕而又振，小便为微难。寒气因水发，清谷不容闲。呕变反肠出，颠倒不得安。手足为微逆，身冷而内烦。迟欲从后救，安可复追还。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006060,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '60、脉濡而紧，濡则卫气微，紧则荣中寒。阳微卫中风，发热而恶寒；荣紧胃气冷，微呕心内烦。医谓有大热，解肌而发汗，亡阳虚烦躁，心下苦痞坚。表里俱虚竭，卒起而头眩。客热在皮肤，怅怏不得眠。不知胃气冷，紧寒在关元。技巧无所施，汲水灌其身。客热应时罢，栗栗而振寒。重被而复之，汗出而冒巅。体惕而又振，小便为微难。寒气因水发，清谷不容闲。呕变反肠出，颠倒不得安。手足为微逆，身冷而内烦。迟欲从后救，安可复追还。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G16oNHL7Zue', 4, '{"title":"61","description":"<p>61、脉浮而紧，浮则为风，紧则为寒；风则伤卫，寒则伤荣；荣卫俱病，骨节烦疼；当发其汗，而不可下也。。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006061,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '61、脉浮而紧，浮则为风，紧则为寒；风则伤卫，寒则伤荣；荣卫俱病，骨节烦疼；当发其汗，而不可下也。。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1TcyTDKzWl1', 4, '{"title":"62","description":"<p>62、脉浮而大，心下反鞕，有热，属脏者，攻之，不令发汗；属腑者，不令溲数。溲数则大便鞕，汗多则越甚，脉迟者，尚未可攻也。。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006062,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '62、脉浮而大，心下反鞕，有热，属脏者，攻之，不令发汗；属腑者，不令溲数。溲数则大便鞕，汗多则越甚，脉迟者，尚未可攻也。。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1oHM30GZJxt', 4, '{"title":"63、伤寒，脉阴阳俱紧，恶寒发热，则脉欲厥","description":"<p>63、伤寒，脉阴阳俱紧，恶寒发热，则脉欲厥。厥者，脉初来大，渐渐小，更来渐大，是其候也。如此者恶寒，甚者，翕翕汗出，喉中痛；若热多者，目赤脉多，睛不慧，医复发之，咽中则伤；若复下之，则两目闭，寒多便清谷，热多便脓血；若熏之，则身发黄；若熨之，则咽燥。若小便利者，可救之；小便难者，危殆也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006063,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '63、伤寒，脉阴阳俱紧，恶寒发热，则脉欲厥。厥者，脉初来大，渐渐小，更来渐大，是其候也。如此者恶寒，甚者，翕翕汗出，喉中痛；若热多者，目赤脉多，睛不慧，医复发之，咽中则伤；若复下之，则两目闭，寒多便清谷，热多便脓血；若熏之，则身发黄；若熨之，则咽燥。若小便利者，可救之；小便难者，危殆也。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n0grgS4zDw3', 4, '{"title":"64","description":"<p>64、伤寒发热，口中勃勃气出，头痛，目黄，衄不可制，阴阳俱虚，贪水者必呕，恶水者厥。若下之，则咽中生疮；假令手足温者，必下重便脓血。头痛目黄者，下之则目闭。贪水者，下之则脉厥，其声嘤嘤，咽喉塞，汗之则战栗；恶水者，下之则里冷，不嗜食，大便完谷出，汗之则口中伤，舌上白胎，烦躁，脉反数，不大便，六七日后必便血，小便不利也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006064,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '64、伤寒发热，口中勃勃气出，头痛，目黄，衄不可制，阴阳俱虚，贪水者必呕，恶水者厥。若下之，则咽中生疮；假令手足温者，必下重便脓血。头痛目黄者，下之则目闭。贪水者，下之则脉厥，其声嘤嘤，咽喉塞，汗之则战栗；恶水者，下之则里冷，不嗜食，大便完谷出，汗之则口中伤，舌上白胎，烦躁，脉反数，不大便，六七日后必便血，小便不利也。', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u6xB5M35a3Y', 4, '{"title":"65、凡服下汤，得利便止，不必尽剂","description":"<p>65、凡服下汤，得利便止，不必尽剂。此以前是汗吐下三法之大要也。若能于此例之外，更神而明之，斯道其庶几乎？</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001006065,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '2024-12-07T07:40:09.000Z', '65、凡服下汤，得利便止，不必尽剂。此以前是汗吐下三法之大要也。若能于此例之外，更神而明之，斯道其庶几乎？', '2024-12-07T07:40:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 's3kQvWS3zkF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TOVl6UMYeO5', 4, '{"title":"1","description":"<p>1、问曰：上工治未病，何也？</p>\n<p> </p>\n<p>      师曰：夫治未病者，见肝之病，知肝传脾，当先实脾，四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。夫肝之病，补用酸，助用焦苦，益用甘味之药调之。酸入肝，焦苦入心，甘入脾。脾能伤肾，肾气微弱，则水不行；水不行，则心火气盛，心火气盛则伤肺；肺被伤，则金气不行；金气不行，则肝气盛，肝必自愈。此治肝补脾之要妙也。肝虚则用此法，实则不可用之。经曰：勿虚虚，勿实实，补不足，损有余，是其义也。余脏准此。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '1、问曰：上工治未病，何也？ 师曰：夫治未病者，见肝之病，知肝传脾，当先实脾，四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。夫肝之病，补用酸，助用焦苦，益用甘味之药调之。酸入肝，焦苦入心，甘入脾。脾能伤肾，肾气微弱，则水不行；水不行，则心火气盛，心火气盛则伤肺；肺被伤，则金气不行；金气不行，则肝气盛，肝必自愈。此治肝补脾之要妙也。肝虚则用此法，实则不可用之。经曰：勿虚虚，勿实实，补不足，损有余，是其义也。余脏准此。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PaQVpDE4uPh', 4, '{"title":"2","description":"<p>2、夫人禀五常，因风气而生长，风气虽能生万物，亦能害万物，如水能浮舟，亦能覆舟。若五脏元真通畅，人即安和。客气邪风，中人多死。千般疢难，不越三条；</p>\n<p></p>\n<p>       一者，经络受邪，入于脏腑，为内所因也；</p>\n<p>      二者，四肢九窍，血脉相传，壅塞不通，为外皮肤所中也；</p>\n<p>      三者，房室、金刃、虫兽所伤。以此详之，病由都尽。若人能养慎，不令邪风干杵经络，适中经络，未流传脏腑，即医治之，四肢才觉重滞，即导引、吐纳、针灸、膏摩，勿令九窍闭塞；更能无犯王法、禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遗形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处，为血气所注；理者，是皮肤脏腑之纹理也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000702,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2、夫人禀五常，因风气而生长，风气虽能生万物，亦能害万物，如水能浮舟，亦能覆舟。若五脏元真通畅，人即安和。客气邪风，中人多死。千般疢难，不越三条； 一者，经络受邪，入于脏腑，为内所因也； 二者，四肢九窍，血脉相传，壅塞不通，为外皮肤所中也； 三者，房室、金刃、虫兽所伤。以此详之，病由都尽。若人能养慎，不令邪风干杵经络，适中经络，未流传脏腑，即医治之，四肢才觉重滞，即导引、吐纳、针灸、膏摩，勿令九窍闭塞；更能无犯王法、禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遗形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处，为血气所注；理者，是皮肤脏腑之纹理也。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H3WN4clKxeI', 4, '{"title":"3","description":"<p>3、问曰：病人有气色见于面部，愿闻其说。</p>\n<p></p>\n<p>      师曰：鼻头色青，腹中痛，苦冷者死。鼻头色微黑者，有水气；色黄者，胸上有寒；色白者，亡血也。设微赤非时者死。其目正圆者痉，不治。又色青为痛，色黑为劳，色赤为风，色黄者便难，色鲜明者有留饮。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000703,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '3、问曰：病人有气色见于面部，愿闻其说。 师曰：鼻头色青，腹中痛，苦冷者死。鼻头色微黑者，有水气；色黄者，胸上有寒；色白者，亡血也。设微赤非时者死。其目正圆者痉，不治。又色青为痛，色黑为劳，色赤为风，色黄者便难，色鲜明者有留饮。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1mcobf1Tykm', 4, '{"title":"4","description":"<p>4、师曰：语声寂寂然喜惊呼者，骨节间病；语声喑喑然不彻者，心膈间病；语声啾啾然细而长者，头中病。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000704,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '4、师曰：语声寂寂然喜惊呼者，骨节间病；语声喑喑然不彻者，心膈间病；语声啾啾然细而长者，头中病。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MpI37sE3W0b', 4, '{"title":"5","description":"<p>5、师曰：息摇肩者，心中坚，息引胸中上气者，咳；息张口短气者，肺痿唾沫。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000705,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '5、师曰：息摇肩者，心中坚，息引胸中上气者，咳；息张口短气者，肺痿唾沫。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vArmq6tOJ6V', 4, '{"title":"6","description":"<p>6、师曰：吸而微数者，其病在中焦，实也，当下之即愈，虚者不治。在上焦者，其吸促，在下焦者，其吸远，此皆难治。呼吸动摇振振者，不可治也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000706,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '6、师曰：吸而微数者，其病在中焦，实也，当下之即愈，虚者不治。在上焦者，其吸促，在下焦者，其吸远，此皆难治。呼吸动摇振振者，不可治也。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wYwwvZLnBjQ', 4, '{"title":"7","description":"<p>7、师曰：寸口脉动者，因其旺时而动，假令肝旺色青，四时各随其色。肝色青而反白，非其时也，色脉非时，法皆当病。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000707,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '7、师曰：寸口脉动者，因其旺时而动，假令肝旺色青，四时各随其色。肝色青而反白，非其时也，色脉非时，法皆当病。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mXAqGjoDGm2', 4, '{"title":"8","description":"<p>8、问曰：有未至而至，有至而不至，有至而不去，有至而太过，何谓也？师曰：冬至之后，甲子夜半少阳起，少阳之时，阳始生，天得温和。以未得甲子，天因温和，此末至而至也；以得甲子，而天犹未温和，此为至而不至也；以得甲子，而天大寒不解，此为至而不去也；以得甲子，而天温如盛夏五六月时，此为至而太过也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000708,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '8、问曰：有未至而至，有至而不至，有至而不去，有至而太过，何谓也？师曰：冬至之后，甲子夜半少阳起，少阳之时，阳始生，天得温和。以未得甲子，天因温和，此末至而至也；以得甲子，而天犹未温和，此为至而不至也；以得甲子，而天大寒不解，此为至而不去也；以得甲子，而天温如盛夏五六月时，此为至而太过也。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gz1jEVagvo1', 4, '{"title":"9","description":"<p>9、问曰：经云：“厥阳独行”，何谓也？</p>\n<p></p>\n<p>     师曰：此为有阳无阴，故称厥阳。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000709,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '9、问曰：经云：“厥阳独行”，何谓也？ 师曰：此为有阳无阴，故称厥阳。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vADmOS93lTt', 4, '{"title":"10","description":"<p>10、问曰：寸脉沉大而滑，沉则为实，滑则为气，实气相搏，血气入脏即死，入腑即愈，此为卒厥，何谓也？</p>\n<p></p>\n<p>        师曰：唇口青，身冷，为入藏，即死；身和，自汗出，为入腑，即愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000710,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '10、问曰：寸脉沉大而滑，沉则为实，滑则为气，实气相搏，血气入脏即死，入腑即愈，此为卒厥，何谓也？ 师曰：唇口青，身冷，为入藏，即死；身和，自汗出，为入腑，即愈。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mta0q1xEwam', 4, '{"title":"11","description":"<p>11、问曰：脉脱，入藏即死，入府即愈，何谓也？</p>\n<p></p>\n<p>        师曰：非为一病，百病皆然。譬如浸淫疮，从口流向四肢者可治，从四肢流来入口者不可治；病在外者可治，入里者即死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000711,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '11、问曰：脉脱，入藏即死，入府即愈，何谓也？ 师曰：非为一病，百病皆然。譬如浸淫疮，从口流向四肢者可治，从四肢流来入口者不可治；病在外者可治，入里者即死。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('glMDmIr2Ib3', 4, '{"title":"12","description":"<p>12、问曰：阳病十八何谓也？师曰：头项痛腰脊臂脚掣痛。阴病十八，何谓也？</p>\n<p></p>\n<p>        师曰：咳上气喘哕咽痛肠鸣胀满心痛拘急。脏病三十六，腑病三十六，合为一百八病；此外五劳、七伤、六极、妇人三十六病，不在其中。清邪居上，浊邪居下，大邪中表，小邪中里，谷饪之邪，从口入者，宿食也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000712,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '12、问曰：阳病十八何谓也？师曰：头项痛腰脊臂脚掣痛。阴病十八，何谓也？ 师曰：咳上气喘哕咽痛肠鸣胀满心痛拘急。脏病三十六，腑病三十六，合为一百八病；此外五劳、七伤、六极、妇人三十六病，不在其中。清邪居上，浊邪居下，大邪中表，小邪中里，谷饪之邪，从口入者，宿食也。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b6kcErKHTjF', 4, '{"title":"13","description":"<p>13、问曰：病有急当救里救表者，何谓也？</p>\n<p></p>\n<p>       师曰：病，医下之，续得下利清谷不止，身体疼痛者，急当救里；后身疼痛，清便自调者，急当救表也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000713,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '13、问曰：病有急当救里救表者，何谓也？ 师曰：病，医下之，续得下利清谷不止，身体疼痛者，急当救里；后身疼痛，清便自调者，急当救表也。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0BD53aUYfS2', 4, '{"title":"14、夫病痼疾加以卒病，当先治其卒病，后乃治其痼疾也","description":"<p>14、夫病痼疾加以卒病，当先治其卒病，后乃治其痼疾也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000714,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '14、夫病痼疾加以卒病，当先治其卒病，后乃治其痼疾也。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('33LCejl7QAU', 4, '{"title":"15","description":"<p>15、师曰：五藏病各有所得者愈，五藏病各有所恶，各随其所不喜为病。如病者素不喜食，而反暴思之，必发热也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000715,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '15、师曰：五藏病各有所得者愈，五藏病各有所恶，各随其所不喜为病。如病者素不喜食，而反暴思之，必发热也。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yGW229Q3ebO', 4, '{"title":"16、夫病在诸脏，欲攻，当随其所得而攻之，如渴者，与猪苓汤","description":"<p>16、夫病在诸脏，欲攻，当随其所得而攻之，如渴者，与猪苓汤。余仿此。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000716,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '16、夫病在诸脏，欲攻，当随其所得而攻之，如渴者，与猪苓汤。余仿此。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ciC89s4EoCz', 4, '{"title":"17、夫病者手足寒，上气脚缩，此六腑之气绝于外也","description":"<p>17、夫病者手足寒，上气脚缩，此六腑之气绝于外也。下利不禁，手足不仁者，此五脏之气绝于内也。内外气绝者，死不治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000717,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '17、夫病者手足寒，上气脚缩，此六腑之气绝于外也。下利不禁，手足不仁者，此五脏之气绝于内也。内外气绝者，死不治。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UHLXWvGHKEH', 4, '{"title":"18","description":"<p>18、师曰：热在上焦者，因咳为肺痿；热在中焦者，为腹坚；热在下焦者，则尿血，或为淋秘不通。大肠有寒者，多鹜溏；有热者，便肠垢。小肠有寒者，其人下重便脓血；有热者，必痔。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000718,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '18、师曰：热在上焦者，因咳为肺痿；热在中焦者，为腹坚；热在下焦者，则尿血，或为淋秘不通。大肠有寒者，多鹜溏；有热者，便肠垢。小肠有寒者，其人下重便脓血；有热者，必痔。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bKQZuHegBzs', 4, '{"title":"19","description":"<p>19、问曰：三焦竭，何谓也？师曰：上焦受中焦之气，中焦未和，不能消谷，故上焦竭者，必善噫；下焦承中焦之气，中气未和，谷气不行，故下焦竭者，必遗溺失便。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000719,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '19、问曰：三焦竭，何谓也？师曰：上焦受中焦之气，中焦未和，不能消谷，故上焦竭者，必善噫；下焦承中焦之气，中气未和，谷气不行，故下焦竭者，必遗溺失便。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mWPC6jJcIdX', 4, '{"title":"20","description":"<p>20、问曰：病有积、有聚、有谷气，何谓也？</p>\n<p></p>\n<p>     师曰：积者，藏病也，终不移处；聚者，腑病也，发作有时，展转移痛，谷气者，胁下痛，按之则愈，愈而复发，为馨气。</p>\n<p></p>\n<p>     诸积之脉，沉细附骨在寸口，积在胸中；</p>\n<p></p>\n<p>     微出寸口，积在喉中；</p>\n<p>     在关者，积在脐旁；</p>\n<p>     上关上，积在心下；</p>\n<p>     微出下关，积在少腹。</p>\n<p>     在尺中，积在气冲；</p>\n<p>     脉出左，积在左；</p>\n<p>     脉出右，积在右；</p>\n<p>     脉左右俱出，积在中央；各以其部处之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000720,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '2024-12-07T07:59:49.000Z', '20、问曰：病有积、有聚、有谷气，何谓也？ 师曰：积者，藏病也，终不移处；聚者，腑病也，发作有时，展转移痛，谷气者，胁下痛，按之则愈，愈而复发，为馨气。 诸积之脉，沉细附骨在寸口，积在胸中； 微出寸口，积在喉中； 在关者，积在脐旁； 上关上，积在心下； 微出下关，积在少腹。 在尺中，积在气冲； 脉出左，积在左； 脉出右，积在右； 脉左右俱出，积在中央；各以其部处之。', '2024-12-07T07:59:49.000Z', 1, NULL, '5IGM9t76quT', 'section', '1a2qOGIxrHw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FqBB82QEVuc', 4, '{"title":"1、温病有三","description":"<p>1、温病有三：曰春温、曰秋温、曰冬温。此皆发于伏气，夏则病暑，而不病温。冬伤于寒，其气伏于少阴，至春乃发为温病，名曰春温。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000801,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '1、温病有三：曰春温、曰秋温、曰冬温。此皆发于伏气，夏则病暑，而不病温。冬伤于寒，其气伏于少阴，至春乃发为温病，名曰春温。', '2024-12-07T08:14:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rva42DTCmDt', 4, '{"title":"2","description":"<p>2、夏伤于湿，其气伏于太阴，至秋燥乃大行，发为温病，名曰秋温。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000802,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '2、夏伤于湿，其气伏于太阴，至秋燥乃大行，发为温病，名曰秋温。', '2024-12-07T08:14:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z1zXmHRItlb', 4, '{"title":"3","description":"<p>3、气不当至而至，初冬乃大寒，燥以内收，其气伏于厥阴，冬至后，天应寒而反温，发为温病，名曰冬温。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000803,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '3、气不当至而至，初冬乃大寒，燥以内收，其气伏于厥阴，冬至后，天应寒而反温，发为温病，名曰冬温。', '2024-12-07T08:14:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RdPwLC1wEU7', 4, '{"title":"4、春秋病温，此其常，冬时病温，此其变","description":"<p>4、春秋病温，此其常，冬时病温，此其变。冬时应寒而反大温，此非其时而蓄其气，及时不病，至春乃发，名曰大温。此由冬不藏精，气失其正，春时阳气外发，二气相搏为病则重，医又不晓病源为治，乃误尸气流传，遂以成疫。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000804,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '4、春秋病温，此其常，冬时病温，此其变。冬时应寒而反大温，此非其时而蓄其气，及时不病，至春乃发，名曰大温。此由冬不藏精，气失其正，春时阳气外发，二气相搏为病则重，医又不晓病源为治，乃误尸气流传，遂以成疫。', '2024-12-07T08:14:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Uh1Uyw2Kd0b', 4, '{"title":"5","description":"<p>5、病春温，其气在上，头痛，咽干，发热，目眩，甚则谵语，脉弦而急，$f{小柴胡加黄连牡丹汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000805,"note":"","videoMemo":"","fangList":["小柴胡加黄连牡丹汤"],"bieMing":""}}', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '5、病春温，其气在上，头痛，咽干，发热，目眩，甚则谵语，脉弦而急，$f{小柴胡加黄连牡丹汤}主之。', '2024-12-07T08:14:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lg2ggA3uM5v', 4, '{"title":"6","description":"<p>6、病秋温，其气在中，发热，口渴，腹中热痛，下利便脓血，脉大而短涩，$f{地黄知母黄连阿胶汤}主之；不便脓血者，$f{白虎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000806,"note":"","videoMemo":"","fangList":["地黄知母黄连阿胶汤","白虎汤"],"bieMing":""}}', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '2024-12-07T08:14:29.000Z', '6、病秋温，其气在中，发热，口渴，腹中热痛，下利便脓血，脉大而短涩，$f{地黄知母黄连阿胶汤}主之；不便脓血者，$f{白虎汤}主之。', '2024-12-07T08:14:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xyPDJqpM4YI', 4, '{"title":"7","description":"<p>7、病冬温，其气在下，发热，腹痛引少腹，夜半咽中干痛，脉沉实，时而大数，$f{石膏黄连黄芩甘草汤}主之；不大便六七日者，$f{大黄黄芩地黄牡丹汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000807,"note":"","videoMemo":"","fangList":["石膏黄连黄芩甘草汤","大黄黄芩地黄牡丹汤"],"bieMing":""}}', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '7、病冬温，其气在下，发热，腹痛引少腹，夜半咽中干痛，脉沉实，时而大数，$f{石膏黄连黄芩甘草汤}主之；不大便六七日者，$f{大黄黄芩地黄牡丹汤}主之。', '2024-12-07T08:31:44.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PE517DgaFFD', 4, '{"title":"8","description":"<p>8、病温，头痛，面赤，发热，手足拘急，脉浮弦而数，名曰风温，$f{黄连黄芩栀子牡丹芍药汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000808,"note":"","videoMemo":"","fangList":["黄连黄芩栀子牡丹芍药汤"],"bieMing":""}}', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '8、病温，头痛，面赤，发热，手足拘急，脉浮弦而数，名曰风温，$f{黄连黄芩栀子牡丹芍药汤}主之。', '2024-12-07T08:31:44.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xjy5hbr4RPY', 4, '{"title":"9","description":"<p>9、病温，其人素有湿，发热唇焦，下利，腹中热痛，脉大而数，名曰湿温，$f{猪苓加黄连牡丹汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000809,"note":"","videoMemo":"","fangList":["猪苓加黄连牡丹汤"],"bieMing":""}}', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '9、病温，其人素有湿，发热唇焦，下利，腹中热痛，脉大而数，名曰湿温，$f{猪苓加黄连牡丹汤}主之。', '2024-12-07T08:31:44.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N3aoxh7WIy6', 4, '{"title":"10","description":"<p>10、病温，舌赤，咽干，心中烦热，脉急数，上寸口者，温邪干心也，$f{黄连黄芩阿胶甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000810,"note":"","videoMemo":"","fangList":["黄连黄芩阿胶甘草汤"],"bieMing":""}}', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '10、病温，舌赤，咽干，心中烦热，脉急数，上寸口者，温邪干心也，$f{黄连黄芩阿胶甘草汤}主之。', '2024-12-07T08:31:44.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2fuLpt4BDiN', 4, '{"title":"11","description":"<p>11、病温，口渴，咳嗽，衄不止，脉浮而数大，此温邪乘肺也，$f{黄芩石膏杏子甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000811,"note":"","videoMemo":"","fangList":["黄芩石膏杏子甘草汤"],"bieMing":""}}', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '11、病温，口渴，咳嗽，衄不止，脉浮而数大，此温邪乘肺也，$f{黄芩石膏杏子甘草汤}主之。', '2024-12-07T08:31:44.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cTTv3x2B62d', 4, '{"title":"12","description":"<p>12、病温，发热，腰以下有水气，甚煮取三升，少腹热痛，小便赤数，脉急而数下尺中者，此温邪移肾也，$f{地黄黄柏秦皮茯苓泽泻汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000812,"note":"","videoMemo":"","fangList":["地黄黄柏秦皮茯苓泽泻汤"],"bieMing":""}}', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '12、病温，发热，腰以下有水气，甚煮取三升，少腹热痛，小便赤数，脉急而数下尺中者，此温邪移肾也，$f{地黄黄柏秦皮茯苓泽泻汤}主之。', '2024-12-07T08:31:44.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
